def domain_sample_test_id(category, index):
    clean = re.sub(r"[^a-z0-9]+", "-", category.lower()).strip("-")
    return f"domain-sample-{clean}-{index:02d}"


def domain_sample_prompt_category(messages):
    query = latest_user_text(messages).strip()
    if not query:
        return ""
    for category, info in DOMAIN_SAMPLE_QUESTION_GROUPS.items():
        marker = category + ":"
        if not query.lower().startswith(marker.lower()):
            continue
        question = re.sub(r"\s+", " ", query[len(marker):].strip()).rstrip()
        for known_question in info.get("questions", ()):
            known = re.sub(r"\s+", " ", str(known_question).strip()).rstrip()
            if question.lower() == known.lower():
                return category
    return ""


def is_domain_sample_prompt(messages):
    return bool(domain_sample_prompt_category(messages))


