REASONING_TOOL_IDS = ["ast-grep", "tree-sitter-cli", "shellcheck", "hyperfine"]
CODE_QUALITY_TOOL_IDS = ["ruff", "pytest", "mypy"]
OPTIONAL_REASONING_TOOL_IDS = ["dspy", "lancedb", "mlx-lm"]


def json_line(handler, payload):
    if isinstance(payload, dict) and payload.get("type") == "status" and "runId" not in payload:
        run_id = safe_run_id(getattr(handler, "current_run_id", ""))
        if run_id:
            payload = {**payload, "runId": run_id}
    data = json.dumps(payload, separators=(",", ":")).encode("utf-8") + b"\n"
    handler.wfile.write(data)
    handler.wfile.flush()


def normalize_cwd_payload(value):
    seen = 0
    while seen < 6:
        seen += 1
        if isinstance(value, dict):
            value = value.get("cwd") or value.get("path") or value.get("value") or ""
            continue
        if isinstance(value, (list, tuple)):
            value = next(
                (
                    item
                    for item in value
                    if isinstance(item, (str, bytes, os.PathLike)) and str(item).strip()
                ),
                "",
            )
            continue
        if isinstance(value, (str, bytes, os.PathLike)):
            return value
        return ""
    return value if isinstance(value, (str, bytes, os.PathLike)) else ""


def safe_cwd(value):
    value = normalize_cwd_payload(value)
    candidate = Path(value or DEFAULT_CWD).expanduser()
    if candidate.exists() and candidate.is_dir():
        return str(candidate)
    return DEFAULT_CWD


def safe_choice(value, allowed, default):
    candidate = str(value or "").strip()
    if candidate in allowed:
        return candidate
    return default


def is_fast_mode(profile, reasoning_level):
    return profile == "local-fast" or reasoning_level == "low"


def default_reasoning_for_profile(profile):
    if profile == "local-fast":
        return "low"
    if profile in (LOCAL_REVIEW_PROFILES | {"local-research", "research-apply", "cloud-research"}):
        return "high"
    return DEFAULT_REASONING_LEVEL


def build_assistant_style_context(friendliness_level=None, humor_level=None, route=None):
    friendliness = safe_choice(
        friendliness_level,
        FRIENDLINESS_LEVELS,
        safe_choice(DEFAULT_FRIENDLINESS_LEVEL, FRIENDLINESS_LEVELS, "warm"),
    )
    humor = safe_choice(
        humor_level,
        HUMOR_LEVELS,
        safe_choice(DEFAULT_HUMOR_LEVEL, HUMOR_LEVELS, "light"),
    )
    lines = ["Assistant style:"]
    lines.extend(f"- {rule}" for rule in ASSISTANT_STYLE_RULES)

    friendliness_rules = {
        "focused": (
            "Friendliness setting: Focused. Be respectful, direct, and calm. Use fewer casual acknowledgements and keep personality subtle."
        ),
        "warm": (
            "Friendliness setting: Warm. Be personable and collaborative, like a capable teammate sitting beside Tinman."
        ),
        "high": (
            "Friendliness setting: High. Be openly friendly, encouraging, and conversational while still keeping the answer useful and concise."
        ),
    }
    humor_rules = {
        "off": (
            "Humor setting: Off. Do not make jokes or playful asides; keep the tone plain and professional."
        ),
        "light": (
            "Humor setting: Light. A small natural wink is okay when it fits, but never force it and never let it crowd the answer."
        ),
        "playful": (
            "Humor setting: Playful. Use occasional casual wit or a short playful aside when the topic is low-risk and it would feel natural."
        ),
    }
    lines.append(f"- {friendliness_rules[friendliness]}")
    lines.append(f"- {humor_rules[humor]}")
    lines.append("- Keep humor out of safety-critical, legal, medical, financial, printer-control, password, or precision troubleshooting answers.")
    role_style = response_role_style(route or {})
    lines.append(
        f"- Subject-matter posture: work as a {role_style.get('title', 'capable specialist')}. "
        f"{role_style.get('voice', 'Bring sound judgment in plain language.')}"
    )
    lines.append(
        "- Make each answer feel like a conversation with a well-prepared specialist: identify the real decision, make a clear recommendation or diagnosis, explain only the reasoning that earns confidence, and stay anchored to the user's actual constraints."
    )
    lines.append(
        "- Be precise about what is known, inferred, assumed, and still unverified. Do not perform certainty or hide uncertainty behind generic caveats."
    )
    lines.append(
        "- Adapt depth to the moment: answer simple questions simply, go deeper when the stakes or complexity warrant it, and ask one sharp clarification only when it would materially change the answer or action."
    )
    lines.append(
        "- Sound engaged rather than scripted. Vary acknowledgements and transitions naturally; do not repeat stock openings, formal labels, or the same closing pattern across turns."
    )
    lines.append(
        "- Respectfully disagree when the evidence points another way. Give the better path and the tradeoff instead of agreeing vaguely or burying the recommendation in options."
    )
    working_profile = working_profile_for_route(route or {})
    if working_profile:
        lines.append(
            "- A user-confirmed working profile is active for this project. Honor its objective, terminology, answer style, and constraints without extending it to another project or inferring new personal details."
        )
    if normalize_session_compass((route or {}).get("sessionCompass")):
        lines.append(
            "- An active session compass is attached to this thread. Use it to preserve continuity, but let the newest user request correct or replace stale context."
        )
    lines.append("")
    return "\n".join(lines)


def compact(text, limit=1400):
    text = " ".join(str(text or "").split())
    if len(text) > limit:
        return text[:limit].rstrip() + "..."
    return text


def safe_run_id(value):
    run_id = re.sub(r"[^A-Za-z0-9_.:-]", "", str(value or ""))[:96]
    return run_id


def prune_live_steering(now=None):
    now = now or time.time()
    with LIVE_STEERING_LOCK:
        stale = [
            run_id
            for run_id, state in LIVE_STEERING_BY_RUN.items()
            if now - float(state.get("updatedAt", 0) or 0) > LIVE_STEERING_TTL_SECONDS
        ]
        for run_id in stale:
            LIVE_STEERING_BY_RUN.pop(run_id, None)
        stale_active = [
            run_id
            for run_id, state in LIVE_ACTIVE_RUNS.items()
            if now - float(state.get("updatedAt", state.get("createdAt", 0)) or 0) > LIVE_STEERING_TTL_SECONDS
        ]
        for run_id in stale_active:
            LIVE_ACTIVE_RUNS.pop(run_id, None)
            LIVE_STEERING_BY_RUN.pop(run_id, None)


def register_live_run(run_id):
    run_id = safe_run_id(run_id)
    if not run_id:
        return ""
    now = time.time()
    prune_live_steering(now)
    with LIVE_STEERING_LOCK:
        LIVE_ACTIVE_RUNS[run_id] = {
            "createdAt": now,
            "updatedAt": now,
            "acceptsSteering": True,
        }
    return run_id


def close_live_steering_window(run_id):
    run_id = safe_run_id(run_id)
    if not run_id:
        return
    with LIVE_STEERING_LOCK:
        state = LIVE_ACTIVE_RUNS.get(run_id)
        if state:
            state["acceptsSteering"] = False
            state["updatedAt"] = time.time()


def unregister_live_run(run_id):
    run_id = safe_run_id(run_id)
    if not run_id:
        return
    with LIVE_STEERING_LOCK:
        LIVE_ACTIVE_RUNS.pop(run_id, None)
        LIVE_STEERING_BY_RUN.pop(run_id, None)


def add_live_steering(run_id, text):
    run_id = safe_run_id(run_id)
    note = compact(text, 1600)
    if not run_id:
        raise ValueError("Missing runId")
    if not note:
        raise ValueError("Missing steering text")
    now = time.time()
    prune_live_steering(now)
    with LIVE_STEERING_LOCK:
        active = LIVE_ACTIVE_RUNS.get(run_id) or {}
        if active.get("cancelled"):
            raise ValueError("That run has already been cancelled.")
        if not active or not active.get("acceptsSteering", False):
            raise ValueError("No active run is accepting steering right now.")
        active["updatedAt"] = now
        state = LIVE_STEERING_BY_RUN.setdefault(run_id, {"notes": [], "createdAt": now, "updatedAt": now})
        state["notes"].append({"text": note, "createdAt": now})
        state["notes"] = state["notes"][-12:]
        state["updatedAt"] = now
        return len(state["notes"])


def live_steering_receipt_payload(run_id, count):
    count = int(count or 0)
    return {
        "ok": True,
        "accepted": True,
        "runId": safe_run_id(run_id),
        "count": count,
        "message": f"Steering note accepted by the active run ({count} queued).",
    }


def cancel_live_run(run_id):
    run_id = safe_run_id(run_id)
    if not run_id:
        raise ValueError("Missing runId")
    now = time.time()
    prune_live_steering(now)
    with LIVE_STEERING_LOCK:
        active = LIVE_ACTIVE_RUNS.get(run_id)
        if not active:
            raise ValueError("No active run is available to cancel right now.")
        active["cancelled"] = True
        active["acceptsSteering"] = False
        active["updatedAt"] = now
        LIVE_STEERING_BY_RUN.pop(run_id, None)
    return run_id


def live_run_cancelled(run_id):
    run_id = safe_run_id(run_id)
    if not run_id:
        return False
    prune_live_steering()
    with LIVE_STEERING_LOCK:
        active = LIVE_ACTIVE_RUNS.get(run_id) or {}
        return bool(active.get("cancelled"))


def live_cancel_receipt_payload(run_id):
    return {
        "ok": True,
        "cancelled": True,
        "runId": safe_run_id(run_id),
        "message": "Cancellation requested for the active run.",
    }


def live_steering_notes(run_id):
    run_id = safe_run_id(run_id)
    if not run_id:
        return []
    prune_live_steering()
    with LIVE_STEERING_LOCK:
        state = LIVE_STEERING_BY_RUN.get(run_id) or {}
        return [str(item.get("text") or "").strip() for item in state.get("notes", []) if str(item.get("text") or "").strip()]


def live_run_accepts_steering(run_id):
    run_id = safe_run_id(run_id)
    if not run_id:
        return False
    prune_live_steering()
    with LIVE_STEERING_LOCK:
        active = LIVE_ACTIVE_RUNS.get(run_id) or {}
        return bool(active.get("acceptsSteering"))


def wait_for_live_steering_notes(run_id, grace_seconds=None):
    run_id = safe_run_id(run_id)
    if not run_id:
        return []
    notes = live_steering_notes(run_id)
    if notes:
        return notes
    grace = LIVE_STEERING_FINAL_GRACE_SECONDS if grace_seconds is None else max(0.0, float(grace_seconds or 0.0))
    deadline = time.time() + grace
    while time.time() < deadline:
        if not live_run_accepts_steering(run_id):
            return []
        remaining = max(0.0, deadline - time.time())
        time.sleep(min(LIVE_STEERING_FINAL_GRACE_POLL_SECONDS, remaining))
        notes = live_steering_notes(run_id)
        if notes:
            return notes
    with LIVE_STEERING_LOCK:
        state = LIVE_STEERING_BY_RUN.get(run_id) or {}
        notes = [str(item.get("text") or "").strip() for item in state.get("notes", []) if str(item.get("text") or "").strip()]
        active = LIVE_ACTIVE_RUNS.get(run_id)
        if notes:
            return notes
        if active:
            active["acceptsSteering"] = False
            active["updatedAt"] = time.time()
    return []


def finish_live_steering(run_id):
    run_id = safe_run_id(run_id)
    if not run_id:
        return
    with LIVE_STEERING_LOCK:
        LIVE_STEERING_BY_RUN.pop(run_id, None)


def redact_quality_text(text):
    redacted = str(text or "")
    redacted = re.sub(r"https?://\S+", "[source]", redacted)
    redacted = re.sub(r"\b(?:10|172\.(?:1[6-9]|2\d|3[0-1])|192\.168)\.\d{1,3}\.\d{1,3}\b", "[ip]", redacted)
    patterns = (
        r"(?i)\b(password|passwd|pwd)\s*[:=]\s*[^,\s;]+",
        r"(?i)\b(api[_-]?key|token|secret)\s*[:=]\s*[^,\s;]+",
        r"(?i)\b(bearer)\s+[A-Za-z0-9._~+/=-]+",
    )
    for pattern in patterns:
        redacted = re.sub(pattern, r"\1=[redacted]", redacted)
    return redacted


def load_quality_feedback(limit=200):
    if not QUALITY_FEEDBACK_PATH.exists():
        return []
    records = []
    try:
        for line in QUALITY_FEEDBACK_PATH.read_text(encoding="utf-8").splitlines():
            if not line.strip():
                continue
            try:
                item = json.loads(line)
            except json.JSONDecodeError:
                continue
            if isinstance(item, dict):
                records.append(item)
    except OSError:
        return []
    if limit and len(records) > limit:
        return records[-limit:]
    return records


def feedback_provenance(value):
    source = value if isinstance(value, dict) else {}
    raw = str(source.get("provenance") or source.get("feedbackProvenance") or "").strip().lower()
    if raw in {"test", "synthetic", "fixture", "rehearsal", "automation"}:
        return FEEDBACK_PROVENANCE_TEST
    if raw == FEEDBACK_PROVENANCE_HUMAN:
        return FEEDBACK_PROVENANCE_HUMAN
    if str(source.get("projectId") or "").strip().lower() in LEGACY_TEST_FEEDBACK_PROJECT_IDS:
        return FEEDBACK_PROVENANCE_TEST
    return FEEDBACK_PROVENANCE_HUMAN


def feedback_is_learning_eligible(record):
    return feedback_provenance(record) == FEEDBACK_PROVENANCE_HUMAN


def compact_string_list(values, limit=6, item_limit=140):
    if not isinstance(values, list):
        return []
    result = []
    for value in values:
        text = compact(redact_quality_text(value), item_limit)
        if text:
            result.append(text)
        if len(result) >= limit:
            break
    return result


def compact_objective_plan(plan):
    if not isinstance(plan, dict):
        return {}
    return {
        "objectiveType": compact(plan.get("objectiveType") or "", 80),
        "responseKind": compact(plan.get("responseKind") or "", 80),
        "target": compact(redact_quality_text(plan.get("target") or ""), 180),
        "action": compact(redact_quality_text(plan.get("action") or ""), 180),
        "evidenceNeed": compact(plan.get("evidenceNeed") or "", 80),
        "missingInputs": compact_string_list(plan.get("missingInputs"), limit=8, item_limit=120),
        "forbiddenAnswerFamilies": compact_string_list(plan.get("forbiddenAnswerFamilies"), limit=8, item_limit=120),
        "routeCandidates": compact_string_list(plan.get("routeCandidates"), limit=6, item_limit=100),
        "confidence": plan.get("confidence"),
    }


