FEEDBACK_DIAGNOSIS_THEME_MAP = {
    "wrong-objective": "misunderstood",
    "misunderstanding-clarification": "misunderstood",
    "missing-source-evidence": "missing-evidence",
    "missing-proof": "missing-evidence",
    "wrong-artifact-route": "wrong-expertise",
    "domain-expertise-routing": "wrong-expertise",
    "direct-answer-shape": "too-generic",
    "specificity-depth": "too-generic",
    "answer-length": "too-verbose",
    "conversation-tone": "tone",
}


def feedback_category_rule(value):
    key = str(value or "").strip().lower()
    rule = FEEDBACK_CATEGORY_RULES.get(key)
    return {"id": key, **rule} if rule else None


def feedback_category_for_record(record):
    record = record if isinstance(record, dict) else {}
    explicit = feedback_category_rule(record.get("feedbackCategory"))
    if explicit:
        return explicit.get("id"), "explicit"
    diagnosis = record.get("diagnosis") if isinstance(record.get("diagnosis"), dict) else {}
    failure_kind = str(diagnosis.get("failureKind") or "").strip().lower()
    derived = FEEDBACK_DIAGNOSIS_THEME_MAP.get(failure_kind, "")
    return derived, "derived" if derived else ""


def feedback_category_diagnosis(category, diagnosis=None):
    category = category if isinstance(category, dict) else {}
    diagnosis = diagnosis if isinstance(diagnosis, dict) else {}
    if not category:
        return diagnosis
    return {
        "failureKind": category.get("failureKind") or diagnosis.get("failureKind") or "answer-quality",
        "patchTarget": category.get("patchTarget") or diagnosis.get("patchTarget") or "response quality",
        "recommendation": category.get("lesson") or diagnosis.get("recommendation") or "Improve the response using the saved feedback lesson.",
        "nextAction": category.get("nextAction") or diagnosis.get("nextAction") or "Reproduce the prompt and verify the improved answer.",
        "safePatch": bool(diagnosis.get("safePatch")),
        "gaps": diagnosis.get("gaps", [])[:4] if isinstance(diagnosis.get("gaps"), list) else [],
    }


def objective_plan_from_feedback_payload(payload, route=None, messages=None):
    payload = payload if isinstance(payload, dict) else {}
    route = route if isinstance(route, dict) else {}
    messages = messages if isinstance(messages, list) else []
    plan = payload.get("objectivePlan") if isinstance(payload.get("objectivePlan"), dict) else {}
    if not plan and isinstance(route.get("objectivePlan"), dict):
        plan = route.get("objectivePlan") or {}
    if not plan:
        try:
            plan = build_interaction_objective_plan(messages, route, cwd=payload.get("cwd") or "")
        except Exception:
            plan = {}
    return compact_objective_plan(plan)


def interaction_feedback_failure_pattern(record):
    record = record if isinstance(record, dict) else {}
    rating = str(record.get("rating") or "").lower()
    diagnosis = record.get("diagnosis") if isinstance(record.get("diagnosis"), dict) else {}
    if rating == "good":
        return "reinforce-good-answer"
    failure_kind = compact(diagnosis.get("failureKind") or "", 80)
    if failure_kind:
        return failure_kind
    plan = record.get("objectivePlan") if isinstance(record.get("objectivePlan"), dict) else {}
    text = " ".join(
        str(record.get(key) or "").lower()
        for key in ("note", "prompt", "answer")
    )
    if any(term in text for term in ("canned", "programmed response", "same response", "template")):
        return "canned-response"
    if any(term in text for term in ("not what i asked", "misunderstood", "should have asked", "clarify")):
        return "misunderstanding-clarification"
    if plan.get("responseKind") == "clarify-before-answer":
        return "clarification-quality"
    if plan.get("evidenceNeed") in {"scientific-or-datasheet-evidence", "live-local-app-evidence"}:
        return "evidence-quality"
    return "answer-quality"


def interaction_feedback_ledger_entry(record):
    if not isinstance(record, dict):
        return None
    plan = record.get("objectivePlan") if isinstance(record.get("objectivePlan"), dict) else {}
    diagnosis = record.get("diagnosis") if isinstance(record.get("diagnosis"), dict) else {}
    composition = record.get("compositionStyle") if isinstance(record.get("compositionStyle"), dict) else {}
    director = record.get("interactionDirector") if isinstance(record.get("interactionDirector"), dict) else {}
    pre_send_review = record.get("preSendReview") if isinstance(record.get("preSendReview"), dict) else {}
    feedback_guidance = compact_feedback_guidance_receipt(record.get("feedbackGuidance"))
    rating = str(record.get("rating") or "").lower()
    failure_pattern = interaction_feedback_failure_pattern(record)
    return {
        "id": record.get("id") or hashlib.sha1(json.dumps(record, sort_keys=True, default=str).encode("utf-8")).hexdigest()[:16],
        "timestamp": record.get("timestamp") or time.time(),
        "rating": rating,
        "learningSignal": "reinforce" if rating == "good" else "repair",
        "projectId": record.get("projectId") or "general",
        "project": record.get("project") or "General Helper",
        "objectiveType": plan.get("objectiveType") or "",
        "responseKind": plan.get("responseKind") or "",
        "target": compact(redact_quality_text(plan.get("target") or ""), 180),
        "action": compact(redact_quality_text(plan.get("action") or ""), 180),
        "evidenceNeed": plan.get("evidenceNeed") or "",
        "missingInputs": compact_string_list(plan.get("missingInputs"), limit=8, item_limit=120),
        "forbiddenAnswerFamilies": compact_string_list(plan.get("forbiddenAnswerFamilies"), limit=8, item_limit=120),
        "failurePattern": failure_pattern,
        "feedbackCategory": compact(record.get("feedbackCategory") or "", 80),
        "interactionMode": compact(director.get("mode") or "", 60),
        "interactionAnswerShape": compact(director.get("answerShape") or "", 100),
        "preSendReviewStatus": compact(pre_send_review.get("status") or "", 40),
        "preSendReviewFlags": compact_string_list(pre_send_review.get("flags"), limit=6, item_limit=80),
        "feedbackGuidance": feedback_guidance,
        "patchTarget": compact(diagnosis.get("patchTarget") or "", 120),
        "prompt": compact(record.get("prompt") or "", 360),
        "note": compact(record.get("note") or "", 360),
        "answerExcerpt": compact(record.get("answer") or "", 520),
        "composition": {
            "mode": compact(composition.get("mode") or "", 80),
            "tone": compact(composition.get("tone") or "", 80),
            "structure": compact(composition.get("structure") or "", 80),
        },
    }


def store_interaction_feedback_learning(record):
    if not feedback_is_learning_eligible(record):
        return None
    entry = interaction_feedback_ledger_entry(record)
    if not entry:
        return None
    DATA_DIR.mkdir(parents=True, exist_ok=True)
    with INTERACTION_FEEDBACK_LEDGER_PATH.open("a", encoding="utf-8") as handle:
        handle.write(json.dumps(entry, separators=(",", ":")) + "\n")
    return entry


def load_interaction_feedback_ledger(limit=500):
    if not INTERACTION_FEEDBACK_LEDGER_PATH.exists():
        return []
    records = []
    try:
        for line in INTERACTION_FEEDBACK_LEDGER_PATH.read_text(encoding="utf-8").splitlines():
            if not line.strip():
                continue
            try:
                item = json.loads(line)
            except json.JSONDecodeError:
                continue
            if isinstance(item, dict):
                records.append(item)
    except OSError:
        return []
    if limit and len(records) > limit:
        return records[-limit:]
    return records


def interaction_feedback_summary(limit=8):
    records = load_interaction_feedback_ledger(limit=500)
    human_records = [item for item in records if feedback_is_learning_eligible(item)]
    test_count = len(records) - len(human_records)
    recent = list(reversed(human_records[-limit:]))
    return {
        "path": str(INTERACTION_FEEDBACK_LEDGER_PATH),
        "count": len(records),
        "humanCount": len(human_records),
        "testCount": test_count,
        "learningOutcomes": interaction_feedback_learning_outcomes(human_records, limit=limit),
        "recent": [
            {
                "id": item.get("id"),
                "rating": item.get("rating"),
                "learningSignal": item.get("learningSignal"),
                "projectId": item.get("projectId", "general"),
                "objectiveType": item.get("objectiveType", ""),
                "responseKind": item.get("responseKind", ""),
                "failurePattern": item.get("failurePattern", ""),
                "feedbackCategory": item.get("feedbackCategory", ""),
                "timestamp": item.get("timestamp"),
            }
            for item in recent
        ],
    }


def interaction_feedback_learning_categories(entry):
    """Return only canonical correction categories that can support an outcome observation."""
    entry = entry if isinstance(entry, dict) else {}
    rating = str(entry.get("rating") or "").lower()
    if rating == "fix":
        category, _ = feedback_category_for_record(entry)
        return [category] if feedback_category_rule(category) else []
    if rating != "good":
        return []
    receipt = compact_feedback_guidance_receipt(entry.get("feedbackGuidance"))
    return [
        item.get("category")
        for item in receipt.get("items") or []
        if item.get("kind") == "correction" and feedback_category_rule(item.get("category"))
    ]


def interaction_feedback_learning_outcome_signature(entry, category):
    entry = entry if isinstance(entry, dict) else {}
    parts = (
        entry.get("projectId") or "general",
        entry.get("objectiveType") or "unknown-objective",
        entry.get("responseKind") or "unknown-response",
        entry.get("evidenceNeed") or "no-evidence-need",
        category or "answer-quality",
    )
    key = "\n".join(compact(part, 120).lower() for part in parts)
    return hashlib.sha1(key.encode("utf-8")).hexdigest()[:16]


def interaction_feedback_learning_outcomes(records=None, limit=8):
    """Summarize observed post-repair positive signals without claiming causal effectiveness."""
    records = records if isinstance(records, list) else load_interaction_feedback_ledger(limit=500)
    buckets = {}
    for entry in records:
        if not isinstance(entry, dict) or not feedback_is_learning_eligible(entry):
            continue
        rating = str(entry.get("rating") or "").lower()
        if rating not in {"fix", "good"}:
            continue
        timestamp = float(entry.get("timestamp") or 0)
        for category in interaction_feedback_learning_categories(entry):
            signature = interaction_feedback_learning_outcome_signature(entry, category)
            rule = feedback_category_rule(category) or {}
            bucket = buckets.setdefault(
                signature,
                {
                    "signature": signature,
                    "category": category,
                    "label": rule.get("label") or "Response quality",
                    "objectiveType": compact(entry.get("objectiveType") or "", 80),
                    "responseKind": compact(entry.get("responseKind") or "", 80),
                    "repairTimestamps": [],
                    "validationTimestamps": [],
                },
            )
            if rating == "fix":
                bucket["repairTimestamps"].append(timestamp)
            else:
                bucket["validationTimestamps"].append(timestamp)

    patterns = []
    for bucket in buckets.values():
        repairs = sorted(timestamp for timestamp in bucket["repairTimestamps"] if timestamp)
        if not repairs:
            continue
        validations = sorted(timestamp for timestamp in bucket["validationTimestamps"] if timestamp)
        last_repair = repairs[-1]
        post_repair_validations = [timestamp for timestamp in validations if timestamp > last_repair]
        status = "validated" if post_repair_validations else "awaiting-validation"
        patterns.append(
            {
                "signature": bucket["signature"],
                "category": bucket["category"],
                "label": bucket["label"],
                "objectiveType": bucket["objectiveType"],
                "responseKind": bucket["responseKind"],
                "repairCount": len(repairs),
                "postRepairValidationCount": len(post_repair_validations),
                "recurring": len(repairs) > 1,
                "status": status,
                "lastRepairAt": last_repair,
                "lastValidationAt": post_repair_validations[-1] if post_repair_validations else None,
            }
        )
    patterns.sort(key=lambda item: (item.get("lastRepairAt") or 0, item.get("category") or ""), reverse=True)
    visible_patterns = patterns[:max(0, int(limit))] if limit is not None else patterns
    return {
        "repairSignalCount": sum(item["repairCount"] for item in patterns),
        "postRepairValidationSignalCount": sum(item["postRepairValidationCount"] for item in patterns),
        "validatedPatternCount": sum(item["status"] == "validated" for item in patterns),
        "awaitingValidationPatternCount": sum(item["status"] == "awaiting-validation" for item in patterns),
        "recurringPatternCount": sum(item["recurring"] for item in patterns),
        "patterns": visible_patterns,
    }


def score_interaction_feedback_entry(item, messages, route):
    route = route or {}
    plan = route.get("objectivePlan") if isinstance(route.get("objectivePlan"), dict) else {}
    if not plan:
        try:
            plan = build_interaction_objective_plan(messages, route)
        except Exception:
            plan = {}
    query = latest_user_text(messages).lower()
    terms = query_terms(messages)
    text = " ".join(
        str(item.get(key, "")).lower()
        for key in ("note", "prompt", "target", "action", "answerExcerpt", "failurePattern")
    )
    score = 0
    if item.get("projectId") and item.get("projectId") == route.get("projectId"):
        score += 10
    if item.get("objectiveType") and item.get("objectiveType") == plan.get("objectiveType"):
        score += 14
    if item.get("responseKind") and item.get("responseKind") == plan.get("responseKind"):
        score += 10
    if item.get("evidenceNeed") and item.get("evidenceNeed") == plan.get("evidenceNeed"):
        score += 5
    if item.get("rating") == "fix":
        score += 3
    for term in terms[:12]:
        if term and term in text:
            score += min(text.count(term), 4)
    if query and item.get("prompt") and compact(item.get("prompt", "").lower(), 120) in query:
        score += 6
    return score


def relevant_interaction_feedback(messages, route=None, limit=4):
    scored = []
    for item in load_interaction_feedback_ledger(limit=400):
        if not feedback_is_learning_eligible(item):
            continue
        score = score_interaction_feedback_entry(item, messages, route or {})
        if score > 0:
            scored.append((score, item))
    scored.sort(key=lambda pair: (pair[0], pair[1].get("timestamp", 0)), reverse=True)
    return [item for _, item in scored[:limit]]


def interaction_feedback_pattern_signature(entry):
    if not isinstance(entry, dict):
        return ""
    parts = [
        entry.get("projectId") or "general",
        entry.get("objectiveType") or "unknown-objective",
        entry.get("responseKind") or "unknown-response",
        entry.get("failurePattern") or "answer-quality",
        entry.get("evidenceNeed") or "no-evidence-need",
    ]
    key = "\n".join(compact(part, 120).lower() for part in parts)
    return hashlib.sha1(key.encode("utf-8")).hexdigest()[:16]


def interaction_forbidden_terms_from_families(families):
    terms = []
    family_map = {
        "cad-missing-geometry": ["not enough geometry", "fusion-ready cad", "mounting hole pattern", "overall envelope"],
        "generic-cad-missing-geometry": ["not enough geometry", "mounting hole pattern", "fusion-ready cad"],
        "fusion-ready-cad": ["fusion 360 script", "openscad model"],
        "cad-artifact": ["fusion 360 script", "openscad model", "stl file"],
        "local-research-dead-end": ["could not extract useful evidence", "local research found results"],
        "generic-annealing-process-advice": ["heating the part near", "polymer chains relax", "annealing process"],
        "formal-template-only": ["This is why:", "You should also consider:"],
        "generic-printer-profile": ["generic printer", "default profile"],
        "confident-guessed-answer": ["obviously", "just use", "no need to verify"],
    }
    for family in compact_string_list(families, limit=10, item_limit=120):
        terms.extend(family_map.get(family, [family.replace("-", " ")]))
    return normalize_test_terms(terms, limit=14)


def interaction_required_terms_for_pattern(pattern):
    objective = str(pattern.get("objectiveType") or "")
    response_kind = str(pattern.get("responseKind") or "")
    evidence_need = str(pattern.get("evidenceNeed") or "")
    required = []
    any_terms = []
    if objective == "local-ui-status-surface":
        any_terms.extend(("model health", "percent", "time remaining", "progress", "telemetry", "status"))
    elif objective == "scientific-materials-evidence":
        any_terms.extend(("evidence", "study", "data", "tested", "datasheet", "source"))
    elif objective == "missing-objective-details" or response_kind == "clarify-before-answer":
        any_terms.extend(("clarification", "what part", "which", "what failure mode", "before I"))
    elif objective == "behavior-guidance":
        any_terms.extend(("behavior", "guidance", "learn", "feedback", "canned"))
    elif evidence_need and evidence_need != "none":
        any_terms.extend((evidence_need.replace("-", " "), "verify", "evidence"))
    if response_kind in {"evidence-backed-direct-answer", "direct-materials-comparison"}:
        required.extend(("this is why",))
    return normalize_test_terms(required), normalize_test_terms(any_terms, limit=10)


def interaction_feedback_pattern_summary(entry, records=None, min_count=None):
    if not isinstance(entry, dict):
        return None
    if entry.get("learningSignal") != "repair" and entry.get("rating") != "fix":
        return None
    signature = interaction_feedback_pattern_signature(entry)
    if not signature:
        return None
    records = records if isinstance(records, list) else load_interaction_feedback_ledger(limit=600)
    matches = [
        item
        for item in records
        if isinstance(item, dict)
        and feedback_is_learning_eligible(item)
        and (item.get("learningSignal") == "repair" or item.get("rating") == "fix")
        and interaction_feedback_pattern_signature(item) == signature
    ]
    if not any(item.get("id") == entry.get("id") for item in matches):
        matches.append(entry)
    matches.sort(key=lambda item: float(item.get("timestamp") or 0), reverse=True)
    threshold = int(min_count if min_count is not None else INTERACTION_REGRESSION_MIN_COUNT)
    if len(matches) < max(1, threshold):
        return {
            "signature": signature,
            "count": len(matches),
            "threshold": threshold,
            "ready": False,
            "matches": matches,
        }
    latest = matches[0]
    forbidden = []
    for item in matches:
        forbidden.extend(item.get("forbiddenAnswerFamilies") if isinstance(item.get("forbiddenAnswerFamilies"), list) else [])
    forbidden = compact_string_list(forbidden, limit=12, item_limit=120)
    return {
        "signature": signature,
        "count": len(matches),
        "threshold": threshold,
        "ready": True,
        "matches": matches,
        "latest": latest,
        "projectId": latest.get("projectId") or "general",
        "project": latest.get("project") or "General Helper",
        "objectiveType": latest.get("objectiveType") or "",
        "responseKind": latest.get("responseKind") or "",
        "evidenceNeed": latest.get("evidenceNeed") or "",
        "failurePattern": latest.get("failurePattern") or "answer-quality",
        "forbiddenAnswerFamilies": forbidden,
    }


def interaction_feedback_regression_from_pattern(pattern):
    if not isinstance(pattern, dict) or not pattern.get("ready"):
        return None
    latest = pattern.get("latest") if isinstance(pattern.get("latest"), dict) else {}
    prompt = compact(latest.get("prompt") or "Answer this request with the learned interaction objective.", 700)
    required, any_terms = interaction_required_terms_for_pattern(pattern)
    forbidden = [
        "run failed",
        "no final message returned",
        "no response",
        "i do not have access",
        "i don't have access",
        "you can check it yourself",
    ]
    forbidden.extend(interaction_forbidden_terms_from_families(pattern.get("forbiddenAnswerFamilies") or []))
    objective = pattern.get("objectiveType") or "unknown-objective"
    response_kind = pattern.get("responseKind") or "unknown-response"
    name = compact(f"Interaction regression: {objective}/{response_kind}", 70)
    return {
        "id": f"interaction-pattern-{pattern.get('signature')}",
        "name": name,
        "group": "Interaction Learning",
        "prompt": prompt,
        "profile": "manager",
        "managerDepth": "fast",
        "webSearch": "live" if pattern.get("evidenceNeed") == "scientific-or-datasheet-evidence" else "disabled",
        "expectedProjectId": pattern.get("projectId") if pattern.get("projectId") != "general" else "",
        "expectedObjectiveType": objective if objective != "unknown-objective" else "",
        "expectedObjectiveResponseKind": response_kind if response_kind != "unknown-response" else "",
        "directAnswer": False,
        "directTerms": [],
        "requiredTerms": required,
        "anyTerms": any_terms,
        "forbiddenTerms": normalize_test_terms(forbidden, limit=16),
        "requiresSource": pattern.get("evidenceNeed") == "scientific-or-datasheet-evidence",
        "minAnalyticalScore": 76,
        "goal": compact(
            (
                f"Prevent repeated {pattern.get('failurePattern')} for objective "
                f"{objective}/{response_kind}; choose the objective before using an answer template."
            ),
            260,
        ),
        "source": "interaction-feedback-ledger",
        "interactionPatternSignature": pattern.get("signature"),
        "interactionPatternCount": int(pattern.get("count") or 0),
        "createdAt": time.time(),
    }


def maybe_upsert_interaction_feedback_regression(entry):
    pattern = interaction_feedback_pattern_summary(entry)
    if not pattern or not pattern.get("ready"):
        return None
    test = interaction_feedback_regression_from_pattern(pattern)
    if not test:
        return None
    return upsert_generated_golden_test(test)


