def interaction_feedback_regression_synthetic_check():
    messages = [{"role": "user", "text": "The Bambu H2D is printing; show percent complete and time remaining in Model Health."}]
    route = route_manager(messages, web_search="disabled")
    plan = route.get("objectivePlan") or build_interaction_objective_plan(messages, route)

    def sample_entry(index):
        record = {
            "id": f"synthetic-interaction-regression-{index}",
            "timestamp": index,
            "rating": "fix",
            "note": "The answer misunderstood a local UI status request and returned canned CAD missing-geometry text.",
            "prompt": latest_user_text(messages),
            "answer": "I can design the part, but I do not have enough geometry.",
            "projectId": route.get("projectId"),
            "project": route.get("project"),
            "objectivePlan": plan,
            "diagnosis": {
                "failureKind": "misunderstanding-clarification",
                "patchTarget": "objective planner and route classifier",
            },
        }
        return interaction_feedback_ledger_entry(record)

    entries = [sample_entry(1), sample_entry(2)]
    pattern = interaction_feedback_pattern_summary(entries[0], records=entries, min_count=2)
    regression = interaction_feedback_regression_from_pattern(pattern)
    forbidden = set((regression or {}).get("forbiddenTerms") or [])
    return bool(
        pattern
        and pattern.get("ready")
        and pattern.get("count") == 2
        and regression
        and regression.get("source") == "interaction-feedback-ledger"
        and regression.get("group") == "Interaction Learning"
        and regression.get("expectedProjectId") == "codex-cli-ui-local-agent"
        and regression.get("expectedObjectiveType") == "local-ui-status-surface"
        and regression.get("expectedObjectiveResponseKind") == "local-app-status-fix"
        and ("not enough geometry" in forbidden or "fusion-ready cad" in forbidden)
    )


