def load_response_examples():
    data = read_json(RESPONSE_EXAMPLES_PATH, {"version": 1, "items": []})
    if not isinstance(data, dict):
        data = {"version": 1, "items": []}
    items = data.get("items")
    data["items"] = items if isinstance(items, list) else []
    return data


def response_examples_summary(limit=8):
    data = load_response_examples()
    items = [item for item in data.get("items", []) if isinstance(item, dict)]
    built_in = default_response_examples()
    combined = [*built_in, *items]
    return {
        "path": str(RESPONSE_EXAMPLES_PATH),
        "builtInCount": len(built_in),
        "savedCount": len(items),
        "count": len(combined),
        "recent": list(reversed(items[-limit:])),
    }


def store_response_example_from_feedback(record):
    if not feedback_is_learning_eligible(record) or record.get("rating") != "good" or not record.get("answer"):
        return None
    plan = record.get("objectivePlan") if isinstance(record.get("objectivePlan"), dict) else {}
    item = {
        "id": f"good-{record.get('id')}",
        "createdAt": record.get("timestamp") or time.time(),
        "projectId": record.get("projectId") or "general",
        "objectiveType": compact(plan.get("objectiveType") or "", 80),
        "responseKind": compact(plan.get("responseKind") or "", 80),
        "title": compact(record.get("note") or record.get("prompt") or "Good Tinman-style answer", 120),
        "prompt": compact(record.get("prompt") or "", 700),
        "answerShape": compact(record.get("answer") or "", 1200),
        "lesson": compact(record.get("note") or "Tinman marked this answer good; preserve this answer shape for similar requests.", 500),
        "source": "good-feedback",
    }
    data = load_response_examples()
    items = [existing for existing in data.get("items", []) if existing.get("id") != item["id"]]
    items.append(item)
    data["items"] = items[-80:]
    data["updatedAt"] = time.time()
    write_json_atomic(RESPONSE_EXAMPLES_PATH, data)
    return item


def response_example_guidance_scope(item, route=None):
    """Keep saved positive examples inside the project or objective that made them useful."""
    item = item if isinstance(item, dict) else {}
    route = route if isinstance(route, dict) else {}
    if item.get("source") != "good-feedback":
        return "built-in"
    project_id = str(route.get("projectId") or "general")
    if item.get("projectId") == project_id:
        return "project"
    plan = route.get("objectivePlan") if isinstance(route.get("objectivePlan"), dict) else {}
    if item.get("objectiveType") and plan.get("objectiveType") and item.get("objectiveType") == plan.get("objectiveType"):
        return "objective"
    return "unrelated"


def relevant_response_examples(messages, route=None, limit=3):
    route = route or {}
    project_id = route.get("projectId") or "general"
    query = latest_user_text(messages).lower()
    combined = [*default_response_examples(), *load_response_examples().get("items", [])]
    scored = []
    for item in combined:
        if not isinstance(item, dict):
            continue
        scope = response_example_guidance_scope(item, route)
        if scope == "unrelated":
            continue
        score = 0
        if item.get("projectId") == project_id:
            score += 12
        elif scope == "objective":
            score += 10
        haystack = " ".join(
            str(item.get(key) or "").lower()
            for key in ("title", "prompt", "lesson", "answerShape")
        )
        for term in [term for term in re_words(query) if term not in STOP_WORDS][:12]:
            if term in haystack:
                score += 3
        if item.get("source") == "built-in":
            score += 2
        if score:
            scored.append((score, item))
    scored.sort(key=lambda pair: pair[0], reverse=True)
    return [item for _, item in scored[:limit]]


def record_quality_feedback(payload):
    route = payload.get("route") if isinstance(payload.get("route"), dict) else {}
    messages = payload.get("messages") if isinstance(payload.get("messages"), list) else []
    rating = safe_choice(payload.get("rating"), {"good", "fix"}, "fix")
    category = feedback_category_rule(payload.get("feedbackCategory")) if rating == "fix" else None
    note = compact(redact_quality_text(payload.get("note")), 700)
    if category and not note:
        note = compact(category.get("lesson") or "", 700)
    answer = compact(redact_quality_text(payload.get("answer")), 1800)
    prompt = compact(redact_quality_text(payload.get("prompt") or latest_user_text(messages)), 900)
    objective_plan = objective_plan_from_feedback_payload(payload, route, messages)
    composition_style = payload.get("compositionStyle") if isinstance(payload.get("compositionStyle"), dict) else {}
    interaction_director = payload.get("interactionDirector") if isinstance(payload.get("interactionDirector"), dict) else {}
    evidence_ledger = payload.get("evidenceLedger") if isinstance(payload.get("evidenceLedger"), list) else []
    evidence_claim_gate = payload.get("evidenceClaimGate") if isinstance(payload.get("evidenceClaimGate"), dict) else {}
    expertise_confidence = payload.get("expertiseConfidence") if isinstance(payload.get("expertiseConfidence"), dict) else {}
    response_composer = payload.get("responseComposer") if isinstance(payload.get("responseComposer"), dict) else {}
    pre_send_review = payload.get("preSendReview") if isinstance(payload.get("preSendReview"), dict) else {}
    feedback_guidance = compact_feedback_guidance_receipt(payload.get("feedbackGuidance"))
    provenance = feedback_provenance(payload)
    raw_diagnosis = payload.get("diagnosis") if isinstance(payload.get("diagnosis"), dict) else {}
    diagnosis = feedback_category_diagnosis(category, raw_diagnosis)
    derived_category = FEEDBACK_DIAGNOSIS_THEME_MAP.get(str(diagnosis.get("failureKind") or "").lower(), "")
    category_id = category.get("id") if category else derived_category
    category_source = "explicit" if category else "derived" if derived_category else ""
    now = time.time()
    record = {
        "id": hashlib.sha1(f"{now}:{rating}:{prompt}:{answer}".encode("utf-8")).hexdigest()[:16],
        "timestamp": now,
        "rating": rating,
        "provenance": provenance,
        "note": note,
        "prompt": prompt,
        "answer": answer,
        "projectId": str(route.get("projectId") or payload.get("projectId") or "general"),
        "project": str(route.get("project") or payload.get("project") or "General Helper"),
        "feedbackCategory": category_id,
        "feedbackCategorySource": category_source,
        "route": {
            "engine": route.get("engine"),
            "confidence": route.get("confidence"),
            "specialist": route.get("specialist"),
        },
        "objectivePlan": objective_plan,
        "compositionStyle": {
            "mode": compact(response_composer.get("mode") or composition_style.get("mode") or composition_style.get("name") or "", 80),
            "tone": compact(composition_style.get("tone") or "", 80),
            "structure": compact(response_composer.get("answerShape") or composition_style.get("structure") or "", 80),
        },
        "interactionDirector": {
            "mode": compact(interaction_director.get("mode") or response_composer.get("interactionMode") or "", 60),
            "answerShape": compact(interaction_director.get("answerShape") or response_composer.get("answerShape") or "", 100),
            "evidencePolicy": compact(interaction_director.get("evidencePolicy") or "", 120),
            "nextMovePolicy": compact(interaction_director.get("nextMovePolicy") or "", 120),
        },
        "evidenceLedger": [
            {
                "status": compact(item.get("status") or "", 40),
                "sourceType": compact(item.get("sourceType") or "", 60),
                "freshness": compact(item.get("freshness") or "", 40),
            }
            for item in evidence_ledger[:3]
            if isinstance(item, dict)
        ],
        "evidenceClaimGate": {
            "status": compact(evidence_claim_gate.get("status") or "", 40),
            "sourceType": compact(evidence_claim_gate.get("sourceType") or "", 60),
            "assertions": compact_string_list(evidence_claim_gate.get("assertions"), limit=4, item_limit=80),
        },
        "expertiseConfidence": {
            "level": compact(expertise_confidence.get("level") or "", 40),
            "sourceType": compact(expertise_confidence.get("sourceType") or "", 60),
            "interactionMode": compact(expertise_confidence.get("interactionMode") or "", 60),
        },
        "responseComposer": {
            "mode": compact(response_composer.get("mode") or "", 80),
            "answerShape": compact(response_composer.get("answerShape") or "", 100),
        },
        "preSendReview": {
            "status": compact(pre_send_review.get("status") or "", 40),
            "revisionApplied": bool(pre_send_review.get("revisionApplied")),
            "flags": compact_string_list(pre_send_review.get("flags"), limit=6, item_limit=80),
            "activeFeedbackCategories": compact_string_list(pre_send_review.get("activeFeedbackCategories"), limit=6, item_limit=80),
        },
        "feedbackGuidance": feedback_guidance,
    }
    if diagnosis:
        record["diagnosis"] = {
            "failureKind": compact(diagnosis.get("failureKind") or "", 80),
            "patchTarget": compact(diagnosis.get("patchTarget") or "", 120),
            "recommendation": compact(redact_quality_text(diagnosis.get("recommendation") or ""), 500),
            "nextAction": compact(redact_quality_text(diagnosis.get("nextAction") or ""), 360),
            "safePatch": bool(diagnosis.get("safePatch")),
            "gaps": diagnosis.get("gaps", [])[:4] if isinstance(diagnosis.get("gaps"), list) else [],
        }
    DATA_DIR.mkdir(parents=True, exist_ok=True)
    with QUALITY_FEEDBACK_PATH.open("a", encoding="utf-8") as handle:
        handle.write(json.dumps(record, separators=(",", ":")) + "\n")
    ledger_entry = store_interaction_feedback_learning(record)
    if ledger_entry:
        record["interactionLedger"] = ledger_entry
        interaction_regression = maybe_upsert_interaction_feedback_regression(ledger_entry)
        if interaction_regression:
            record["interactionRegression"] = interaction_regression
    store_response_example_from_feedback(record)
    return record


def quality_feedback_summary(limit=8):
    records = load_quality_feedback(limit=500)
    human_records = [item for item in records if feedback_is_learning_eligible(item)]
    test_count = len(records) - len(human_records)
    theme_counts = {}
    for item in human_records:
        category, _ = feedback_category_for_record(item)
        if category:
            theme_counts[category] = theme_counts.get(category, 0) + 1
    recent = list(reversed(human_records[-limit:]))
    return {
        "path": str(QUALITY_FEEDBACK_PATH),
        "count": len(records),
        "humanCount": len(human_records),
        "testCount": test_count,
        "themeCounts": theme_counts,
        "recent": [
            {
                "id": item.get("id"),
                "rating": item.get("rating"),
                "note": item.get("note", ""),
                "projectId": item.get("projectId", "general"),
                "timestamp": item.get("timestamp"),
            }
            for item in recent
        ],
    }


def feedback_provenance_p7_report():
    """Exercise feedback provenance in temporary storage before it affects live learning."""
    fixture = read_json(APP_DIR / "tests" / "feedback_provenance_p7_cases.json", {})
    cases = fixture.get("cases") if isinstance(fixture.get("cases"), list) else []
    if len(cases) < 3:
        return {"suite": fixture.get("suite") or "feedback-provenance-p7", "status": "fail", "caseCount": len(cases), "failedCount": 1, "cases": []}
    global DATA_DIR, QUALITY_FEEDBACK_PATH, INTERACTION_FEEDBACK_LEDGER_PATH, RESPONSE_EXAMPLES_PATH
    original_paths = {
        "DATA_DIR": DATA_DIR,
        "QUALITY_FEEDBACK_PATH": QUALITY_FEEDBACK_PATH,
        "INTERACTION_FEEDBACK_LEDGER_PATH": INTERACTION_FEEDBACK_LEDGER_PATH,
        "RESPONSE_EXAMPLES_PATH": RESPONSE_EXAMPLES_PATH,
    }
    results = []
    try:
        with tempfile.TemporaryDirectory(prefix="feedback-provenance-p7-") as tmp:
            root = Path(tmp)
            DATA_DIR = root
            QUALITY_FEEDBACK_PATH = root / "quality_feedback.jsonl"
            INTERACTION_FEEDBACK_LEDGER_PATH = root / "interaction_feedback_ledger.jsonl"
            RESPONSE_EXAMPLES_PATH = root / "response_examples.json"
            for case in cases:
                case = case if isinstance(case, dict) else {}
                case_id = str(case.get("id") or "unnamed")
                if case.get("kind") == "legacy":
                    actual = feedback_provenance({"projectId": case.get("projectId")})
                    results.append({"id": case_id, "provenance": actual, "passed": actual == case.get("expectedProvenance")})
                    continue
                before_ledger = len(load_interaction_feedback_ledger())
                before_examples = len(load_response_examples().get("items") or [])
                payload = {
                    "rating": "good",
                    "feedbackProvenance": case.get("feedbackProvenance"),
                    "note": "Shared feedback signal.",
                    "prompt": "Use the shared feedback signal in the next answer.",
                    "answer": "The answer is direct, specific, and grounded in the active request.",
                    "messages": [{"role": "user", "text": "Use the shared feedback signal in the next answer."}],
                    "route": {"projectId": "feedback-p7", "project": "Feedback P7"},
                }
                record = record_quality_feedback(payload)
                wrote_ledger = len(load_interaction_feedback_ledger()) > before_ledger
                wrote_example = len(load_response_examples().get("items") or []) > before_examples
                passed = (
                    record.get("provenance") == case.get("expectedProvenance")
                    and wrote_ledger == bool(case.get("expectsInteractionLearning"))
                    and wrote_example == bool(case.get("expectsResponseExample"))
                )
                results.append(
                    {
                        "id": case_id,
                        "provenance": record.get("provenance"),
                        "interactionLearning": wrote_ledger,
                        "responseExample": wrote_example,
                        "passed": passed,
                    }
                )
            relevant = relevant_quality_feedback(
                [{"role": "user", "text": "Use the shared feedback signal in the next answer."}],
                {"projectId": "feedback-p7"},
                limit=8,
            )
            summary = quality_feedback_summary()
            results.append(
                {
                    "id": "test-feedback-is-excluded-from-relevance-and-summary",
                    "relevantCount": len(relevant),
                    "humanCount": summary.get("humanCount"),
                    "testCount": summary.get("testCount"),
                    "passed": len(relevant) == 1 and summary.get("humanCount") == 1 and summary.get("testCount") == 1,
                }
            )
    finally:
        DATA_DIR = original_paths["DATA_DIR"]
        QUALITY_FEEDBACK_PATH = original_paths["QUALITY_FEEDBACK_PATH"]
        INTERACTION_FEEDBACK_LEDGER_PATH = original_paths["INTERACTION_FEEDBACK_LEDGER_PATH"]
        RESPONSE_EXAMPLES_PATH = original_paths["RESPONSE_EXAMPLES_PATH"]
    failed = [item for item in results if not item.get("passed")]
    return {
        "suite": fixture.get("suite") or "feedback-provenance-p7",
        "status": "pass" if not failed else "fail",
        "caseCount": len(results),
        "failedCount": len(failed),
        "cases": results,
    }


def feedback_provenance_p7_synthetic_check():
    return feedback_provenance_p7_report().get("status") == "pass"


def feedback_themes_p8_report():
    """Verify diagnosis-derived feedback themes without rewriting durable user records."""
    fixture = read_json(APP_DIR / "tests" / "feedback_themes_p8_cases.json", {})
    cases = fixture.get("cases") if isinstance(fixture.get("cases"), list) else []
    results = []
    for case in cases:
        case = case if isinstance(case, dict) else {}
