def feedback_traceability_p9_report():
    """Confirm recurring feedback themes retain explicit redacted regression scenarios."""
    fixture = read_json(APP_DIR / "tests" / "feedback_traceability_p9_cases.json", {})
    policy = fixture.get("policy") if isinstance(fixture.get("policy"), dict) else {}
    themes = policy.get("themes") if isinstance(policy.get("themes"), list) else []
    corpus = read_json(APP_DIR / "tests" / "conversation_quality_p2_cases.json", {})
    corpus_cases = corpus.get("cases") if isinstance(corpus.get("cases"), list) else []
    case_by_id = {
        str(case.get("id") or "").strip(): case
        for case in corpus_cases
        if isinstance(case, dict) and str(case.get("id") or "").strip()
    }
    summary = quality_feedback_summary(limit=0)
    live_theme_counts = summary.get("themeCounts") if isinstance(summary.get("themeCounts"), dict) else {}
    minimum_theme_count = max(1, int(policy.get("minimumThemeCount") or 1))
    minimum_scenario_count = max(1, int(policy.get("minimumScenarioCount") or 1))
    known_theme_ids = set(FEEDBACK_DIAGNOSIS_THEME_MAP.values())
    results = []
    for theme in themes:
        theme = theme if isinstance(theme, dict) else {}
        theme_id = str(theme.get("id") or "").strip()
        scenario_ids = [str(value).strip() for value in theme.get("scenarioIds") or [] if str(value).strip()]
        missing_scenarios = [scenario_id for scenario_id in scenario_ids if scenario_id not in case_by_id]
        duplicate_scenarios = len(scenario_ids) != len(set(scenario_ids))
        untagged_scenarios = [
            scenario_id
            for scenario_id in scenario_ids
            if theme_id and theme_id not in (case_by_id.get(scenario_id, {}).get("coverage") or [])
        ]
        minimum_signals = max(1, int(theme.get("minimumSignals") or 1))
        live_signal_count = int(live_theme_counts.get(theme_id) or 0)
        active = live_signal_count >= minimum_signals
        passed = (
            theme_id in known_theme_ids
            and len(scenario_ids) >= minimum_scenario_count
            and not duplicate_scenarios
            and not missing_scenarios
            and not untagged_scenarios
        )
        results.append(
            {
                "id": theme_id or "unnamed",
                "liveSignalCount": live_signal_count,
                "minimumSignals": minimum_signals,
                "active": active,
                "scenarioCount": len(scenario_ids),
                "missingScenarioIds": missing_scenarios,
                "untaggedScenarioIds": untagged_scenarios,
                "duplicateScenarioIds": duplicate_scenarios,
                "passed": passed,
            }
        )
    failed = [item for item in results if not item.get("passed")]
    configuration_valid = len(themes) >= minimum_theme_count
    return {
        "suite": fixture.get("suite") or "feedback-traceability-p9",
        "status": "pass" if configuration_valid and not failed else "fail",
        "caseCount": len(results),
        "failedCount": len(failed) + (0 if configuration_valid else 1),
        "minimumThemeCount": minimum_theme_count,
        "minimumScenarioCount": minimum_scenario_count,
        "humanFeedbackCount": int(summary.get("humanCount") or 0),
        "activeThemeCount": sum(1 for item in results if item.get("active")),
        "cases": results,
    }


