def feedback_guidance_receipt(messages, route=None, limit=4):
    """Expose the applied feedback lens without returning historical feedback text or identifiers."""
    items = []
    for item in distinct_quality_feedback_guidance(messages, route or {}, limit=limit):
        category, _ = feedback_category_for_record(item)
        rule = feedback_category_rule(category)
        rating = str(item.get("rating") or "").lower()
        items.append(
            {
                "category": category or "positive-example",
                "label": rule.get("label") if rule else "Positive example" if rating == "good" else "Response quality",
                "kind": "positive-example" if rating == "good" else "correction",
                "scope": feedback_guidance_scope(item, route),
            }
        )
    return {"count": len(items), "items": items}


def compact_feedback_guidance_receipt(value, limit=4):
    """Canonicalize a client-provided feedback receipt before retaining it with a rating."""
    raw_items = value.get("items") if isinstance(value, dict) and isinstance(value.get("items"), list) else []
    allowed_scopes = set(FEEDBACK_GUIDANCE_SCOPE_PRIORITY)
    items = []
    seen = set()
    for item in raw_items:
        item = item if isinstance(item, dict) else {}
        category = str(item.get("category") or "").strip().lower()
        rule = feedback_category_rule(category)
        if category == "positive-example":
            label = "Positive example"
            kind = "positive-example"
        elif rule:
            category = rule.get("id")
            label = rule.get("label") or "Response quality"
            kind = "correction"
        else:
            continue
        scope = str(item.get("scope") or "").strip().lower()
        if scope not in allowed_scopes:
            continue
        key = (category, kind, scope)
        if key in seen:
            continue
        seen.add(key)
        items.append({"category": category, "label": label, "kind": kind, "scope": scope})
        if len(items) >= max(1, int(limit)):
            break
    return {"count": len(items), "items": items}


