    """Verify ambiguous work gets one short question while known targets stay unblocked."""
    fixture = read_json(APP_DIR / "tests" / "clarification_quality_p21_cases.json", {})
    cases = fixture.get("cases") if isinstance(fixture.get("cases"), list) else []
    results = []
    for case in cases:
        case = case if isinstance(case, dict) else {}
        messages = case.get("messages") if isinstance(case.get("messages"), list) else []
        answer = understanding_clarification_direct_answer(messages)
        plan = build_interaction_objective_plan(messages, {})
        lower = answer.lower()
        words = re_words(answer)
        expects_empty = bool(case.get("expectEmpty"))
        required_terms = [str(term).lower() for term in case.get("requiredTerms") or [] if str(term).strip()]
        passed = (
            not answer
            if expects_empty
            else (
                answer.count("?") == 1
                and "\n" not in answer
                and len(words) <= int(case.get("maxWords") or 24)
                and all(term in lower for term in required_terms)
                and plan.get("responseKind") == case.get("expectedResponseKind")
            )
        )
        results.append(
            {
                "id": str(case.get("id") or "unnamed"),
                "wordCount": len(words),
                "questionCount": answer.count("?"),
                "responseKind": plan.get("responseKind") or "",
                "passed": passed,
            }
        )
    failed = [item for item in results if not item.get("passed")]
    return {
        "suite": fixture.get("suite") or "clarification-quality-p21",
        "status": "pass" if not failed else "fail",
        "caseCount": len(results),
        "failedCount": len(failed),
        "cases": results,
    }


