def agent_preference_direct_synthetic_check():
    first_messages = [{"role": "user", "text": "What would you like to be called brother?"}]
    first_route = route_manager(first_messages, requested_profile="manager", web_search="live")
    first_packet = general_direct_knowledge_answer(first_messages, first_route, web_search="live") or {}
    first_answer = first_packet.get("answer", "")
    standalone_correction_messages = [{"role": "user", "text": "That was a question about your preference"}]
    standalone_correction_route = route_manager(
        standalone_correction_messages, requested_profile="manager", web_search="live"
    )
    standalone_correction_packet = (
        general_direct_knowledge_answer(standalone_correction_messages, standalone_correction_route, web_search="live")
        or {}
    )
    standalone_correction_answer = standalone_correction_packet.get("answer", "")
    correction_messages = [
        *first_messages,
        {"role": "assistant", "text": "Local Research could not find free web results for that query."},
        {"role": "user", "text": "That was a question about your preference"},
    ]
    correction_route = route_manager(correction_messages, requested_profile="manager", web_search="live")
    correction_packet = general_direct_knowledge_answer(correction_messages, correction_route, web_search="live") or {}
    correction_answer = correction_packet.get("answer", "")
    understand_messages = [
        *correction_messages,
        {"role": "assistant", "text": correction_answer},
        {"role": "user", "text": "do you understand the question I am asking you?"},
    ]
    understand_route = route_manager(understand_messages, requested_profile="manager", web_search="live")
    understand_packet = general_direct_knowledge_answer(understand_messages, understand_route, web_search="live") or {}
    understand_answer = understand_packet.get("answer", "")
    combined = "\n".join([first_answer, standalone_correction_answer, correction_answer, understand_answer]).lower()
    return (
        first_packet.get("mode") == "agent-preference-direct-answer"
        and standalone_correction_packet.get("mode") == "agent-preference-direct-answer"
        and correction_packet.get("mode") == "agent-preference-direct-answer"
        and understand_packet.get("mode") == "agent-preference-direct-answer"
        and "local research could not find" not in combined
        and "this is why:" not in combined
        and "you should also consider:" not in combined
        and "codex" in combined
        and "preference question" in combined
        and "research" in combined
    )


