def auto_archive_validated_improvements():
    data = load_improvement_lab()
    items = data.get("items", [])
    now = time.time()
    changed = []
    for item in items:
        if not isinstance(item, dict) or item.get("status") == "archived":
            continue
        resolution = validated_improvement_resolution(item)
        if not resolution:
            continue
        reason, proof = resolution
        item["status"] = "archived"
        item["archivedAt"] = now
        item["resolvedAt"] = now
        item["resolution"] = reason
        item["resolutionProof"] = proof
        item["updatedAt"] = now
        changed.append(item.get("id"))
    if changed:
        data["updatedAt"] = now
        write_json_atomic(IMPROVEMENT_LAB_PATH, data)
    return {"archived": len(changed), "ids": changed}


def store_improvement_item(item):
    if not isinstance(item, dict):
        return None
    now = time.time()
    data = load_improvement_lab()
    items = data.get("items", [])
    item_id = item.get("id") or improvement_item_id(
        item.get("source", "manual"),
        item.get("type", "improvement"),
        item.get("title", ""),
        item.get("prompt", ""),
    )
    existing = next((candidate for candidate in items if candidate.get("id") == item_id), None)
    fields = {
        "id": item_id,
        "type": str(item.get("type") or "improvement"),
        "severity": safe_choice(item.get("severity"), {"critical", "high", "medium", "low"}, "medium"),
        "title": compact(redact_quality_text(item.get("title") or "Improvement"), 140),
        "source": compact(item.get("source") or "", 80),
        "projectId": str(item.get("projectId") or "general"),
        "project": compact(item.get("project") or "General Helper", 100),
        "prompt": compact(redact_quality_text(item.get("prompt") or ""), 700),
        "recommendation": compact(redact_quality_text(item.get("recommendation") or ""), 900),
        "nextAction": compact(redact_quality_text(item.get("nextAction") or ""), 500),
        "evidence": compact(redact_quality_text(item.get("evidence") or ""), 700),
    }
    if isinstance(item.get("diagnosis"), dict):
        diagnosis = item["diagnosis"]
        fields["diagnosis"] = {
            "failureKind": compact(diagnosis.get("failureKind") or "", 80),
            "patchTarget": compact(diagnosis.get("patchTarget") or "", 120),
            "recommendation": compact(redact_quality_text(diagnosis.get("recommendation") or ""), 500),
            "nextAction": compact(redact_quality_text(diagnosis.get("nextAction") or ""), 360),
            "safePatch": bool(diagnosis.get("safePatch")),
            "gaps": diagnosis.get("gaps", [])[:4] if isinstance(diagnosis.get("gaps"), list) else [],
        }
    if existing:
        status = safe_choice(existing.get("status"), {"open", "reviewed", "archived"}, "open")
        existing.update(fields)
        existing["status"] = "open" if item.get("reopen") else status
        existing["count"] = int(existing.get("count") or 1) + 1
        existing["updatedAt"] = now
        result = existing
    else:
        result = {
            **fields,
            "status": safe_choice(item.get("status"), {"open", "reviewed", "archived"}, "open"),
            "count": int(item.get("count") or 1),
            "createdAt": now,
            "updatedAt": now,
        }
        items.append(result)

    data["items"] = sorted(
        items,
        key=lambda candidate: (
            improvement_status_rank(candidate.get("status")),
            improvement_severity_rank(candidate.get("severity")),
            -float(candidate.get("updatedAt") or candidate.get("createdAt") or 0),
        ),
    )
    data["updatedAt"] = now
    write_json_atomic(IMPROVEMENT_LAB_PATH, data)
    return improvement_lab_item_summary(result)


def quality_feedback_improvement_item(record):
    if not isinstance(record, dict) or record.get("rating") != "fix":
        return None
    prompt = compact(record.get("prompt") or "", 260)
    note = compact(record.get("note") or "", 260)
    project_id = str(record.get("projectId") or "general")
    diagnosis = record.get("diagnosis") if isinstance(record.get("diagnosis"), dict) else {}
    failure_kind = compact(diagnosis.get("failureKind") or "answer-quality", 80)
    patch_target = compact(diagnosis.get("patchTarget") or "route, prompt, rubric, tool, or regression path", 120)
    if failure_kind == "misunderstanding-clarification" and not diagnosis.get("recommendation"):
        patch_target = "understanding clarification gate, route classifier, or feedback lesson retrieval"
    recommendation = (
        diagnosis.get("recommendation")
        or note
        or "Turn this feedback into a reusable answer rule, then rerun the same style of request as a regression check."
    )
    next_action = (
        diagnosis.get("nextAction")
        or "Create or update a golden prompt test and adjust the project playbook/rubric that produced the weak answer."
    )
    if failure_kind == "misunderstanding-clarification" and not diagnosis.get("nextAction"):
        next_action = "Reproduce the prompt, prove the app asks a focused clarification or answers the intended question, then add a live /api/run regression."
    return {
        "id": improvement_item_id("quality-feedback", record.get("id") or prompt or note),
        "type": "answer-quality",
        "severity": "high",
        "source": "Fix this feedback",
        "projectId": project_id,
        "project": record.get("project") or project_id.replace("-", " ").title(),
        "title": f"Repair {failure_kind}: {compact(prompt or project_id, 72)}",
        "prompt": prompt,
        "evidence": note or compact(record.get("answer") or "", 420),
        "recommendation": recommendation,
        "nextAction": f"{next_action} Patch target: {patch_target}.",
        "diagnosis": diagnosis,
    }


def record_improvement_from_feedback(record):
    item = quality_feedback_improvement_item(record)
    if not item:
        return None
    return store_improvement_item(item)


def golden_test_from_feedback_improvement(record, improvement):
    if not record or record.get("rating") != "fix" or not improvement:
        return None
    item = {
        **improvement,
        "prompt": record.get("prompt") or improvement.get("prompt"),
        "evidence": record.get("note") or improvement.get("evidence") or record.get("answer"),
        "recommendation": (
            record.get("note")
            or improvement.get("recommendation")
            or "Turn this Fix-this feedback into a reusable answer rule and regression check."
        ),
    }
    return upsert_generated_golden_test(generated_golden_test_from_improvement(item))


