def has_prior_substantive_context(messages):
    for message in reversed((messages or [])[:-1]):
        text = str(message.get("text") or "").strip()
        role = str(message.get("role", "")).lower()
        if text and role in {"user", "assistant"}:
            return True
    return False


def has_inline_target_reference(text):
    value = str(text or "")
    lower = value.lower()
    if text_has_any(lower, ("http://", "https://", "/users/", ".stl", ".step", ".stp", ".f3d", ".f3z", ".3mf", ".json", ".cfg", ".py", ".js", ".md")):
        return True
    if re.search(r"`[^`]{2,}`", value):
        return True
    return False


def understanding_clarification_direct_answer(messages, route=None):
    latest = latest_user_text(messages).strip()
    lower = latest.lower()
    if not latest:
        return ""
    if message_attachments(messages) or has_inline_target_reference(latest):
        return ""
    if has_prior_substantive_context(messages):
        return ""
    if is_behavior_guidance_message(messages) or is_agent_preference_question(messages):
        return ""
    if is_petcf_pctgcf_strength_comparison_question(messages) or is_petcf_annealing_strength_question(messages):
        return ""
    if text_has_any(lower, ("bambu h2d", "model health panel")) and text_has_any(lower, ("online", "printing", "offline", "showing")):
        return ""

    same_or_pronoun_action = (
        text_has_any(lower, ("same", "those settings", "these settings", "that setting", "other profile", "other printer", "other one"))
        and text_has_any(lower, ("do", "put", "copy", "apply", "change", "update", "move", "set", "make"))
    )
    if same_or_pronoun_action:
        return "What previous action should I repeat, and what exact target should receive it?"

    strength_action = (
        text_has_any(lower, ("make it stronger", "make this stronger", "make that stronger", "improve its strength", "improve the strength", "stronger design"))
        or (text_has_any(lower, ("stronger", "strengthen", "reinforce")) and text_has_any(lower, ("make", "improve", "fix", "redesign", "change")))
    )
    has_strength_target = text_has_any(
        lower,
        (
            "pet-cf",
            "pctg-cf",
            "bracket",
            "mount",
            "duct",
            "rotor",
            "blade",
            "profile",
            "printer",
            "part",
            "file",
            "model",
            "material",
        ),
    )
    if strength_action and not has_strength_target:
        return "Which part are we strengthening, and which failure mode matters most: bending, tensile load, impact, heat, layer split, or fatigue?"

    unresolved_referent_action = (
        text_has_any(lower, ("fix it", "fix this", "fix that", "change it", "change this", "update it", "update this", "move it", "open it", "delete it", "eject it", "register it", "configure them", "do it", "do this", "do that", "make it happen"))
        or re.fullmatch(r"(please\s+)?(fix|change|update|move|open|delete|eject|register|configure|post|run|apply|make|improve)\s+(it|this|that|them)(\s+.*)?", lower)
    )
    if unresolved_referent_action:
        route_matches = (route or {}).get("matched") if isinstance((route or {}).get("matched"), list) else []
        meaningful_route = any(item for item in route_matches if item not in {"general", "default", "same-action-missing-context"})
        if meaningful_route and len(re_words(lower)) >= 12:
            return ""
        return "What does `it`, `this`, or `that` refer to, and what result do you want?"

    return ""


