def score_quality_feedback(item, messages, route):
    query = latest_user_text(messages).lower()
    terms = query_terms(messages)
    text = " ".join(
        str(item.get(key, "")).lower()
        for key in ("note", "prompt", "answer", "project", "projectId")
    )
    score = 0
    if item.get("projectId") and item.get("projectId") == (route or {}).get("projectId"):
        score += 12
    if item.get("rating") == "fix":
        score += 4
    if item.get("rating") == "good" and item.get("note"):
        score += 2
    for term in terms:
        if term and term in text:
            score += min(text.count(term), 5)
    if query and item.get("prompt") and compact(item.get("prompt", "").lower(), 160) in query:
        score += 6
    return score


def relevant_quality_feedback(messages, route, limit=QUALITY_FEEDBACK_MAX_CONTEXT):
    scored = []
    for item in load_quality_feedback(limit=300):
        if not feedback_is_learning_eligible(item):
            continue
        score = score_quality_feedback(item, messages, route or {})
        if score > 0:
            scored.append((score, item))
    scored.sort(key=lambda pair: (pair[0], pair[1].get("timestamp", 0)), reverse=True)
    return [item for _, item in scored[:limit]]


GLOBAL_FEEDBACK_GUIDANCE_CATEGORIES = {"misunderstood", "too-generic", "too-verbose", "tone"}
FEEDBACK_GUIDANCE_SCOPE_PRIORITY = {
    "project": 4,
    "objective": 3,
    "global": 2,
    "unscoped": 1,
    "unrelated": 0,
}


def feedback_guidance_scope(item, route=None):
    """Allow reusable conversation lessons to travel, but keep domain corrections in scope."""
    item = item if isinstance(item, dict) else {}
    route = route or {}
    category, _ = feedback_category_for_record(item)
    if category in GLOBAL_FEEDBACK_GUIDANCE_CATEGORIES:
        return "global"
    current_project = str(route.get("projectId") or "").strip()
    feedback_project = str(item.get("projectId") or "").strip()
    if current_project and feedback_project and current_project == feedback_project:
        return "project"
    current_plan = route.get("objectivePlan") if isinstance(route.get("objectivePlan"), dict) else {}
    feedback_plan = item.get("objectivePlan") if isinstance(item.get("objectivePlan"), dict) else {}
    current_objective_type = current_plan.get("objectiveType")
    feedback_objective_type = feedback_plan.get("objectiveType") or item.get("objectiveType")
    matches_objective = (
        current_objective_type
        and feedback_objective_type
        and current_objective_type == feedback_objective_type
    )
    if matches_objective:
        return "objective"
    if not current_project and not current_plan:
        return "unscoped"
    return "unrelated"


def distinct_quality_feedback_guidance(messages, route=None, limit=4):
    """Keep response prompts focused on distinct feedback lessons, not repeated corrections."""
    route = route or {}
    candidates = relevant_quality_feedback(
        messages,
        route,
        limit=300,
    )
    # Preserve relevance ordering inside each scope, while ensuring a current-project or
    # matching-objective correction is not crowded out by unrelated recent feedback.
    candidates.sort(
        key=lambda item: FEEDBACK_GUIDANCE_SCOPE_PRIORITY.get(
            feedback_guidance_scope(item, route),
            0,
        ),
        reverse=True,
    )
    guidance = []
    seen = set()
    for item in candidates:
        if feedback_guidance_scope(item, route) == "unrelated":
            continue
        rating = str(item.get("rating") or "").lower()
        category, _ = feedback_category_for_record(item)
        diagnosis = item.get("diagnosis") if isinstance(item.get("diagnosis"), dict) else {}
        failure_kind = str(diagnosis.get("failureKind") or "").strip().lower()
        if rating == "fix":
            key = f"fix:{category or failure_kind or item.get('id') or 'uncategorized'}"
        else:
            key = f"{rating or 'feedback'}:{item.get('projectId') or 'general'}"
        if key in seen:
            continue
        seen.add(key)
        guidance.append(item)
        if len(guidance) >= max(1, int(limit)):
            break
    return guidance


def compact_command(command, limit=120):
    command = " ".join(str(command or "").split())
    prefix = "/bin/bash -lc "
    if command.startswith(prefix):
        command = command[len(prefix) :].strip()
    if len(command) > limit:
        return command[:limit].rstrip() + "..."
    return command


def first_url_host(text):
    urls = re.findall(r"https?://[^'\"\\)\]\s]+", str(text or ""))
    for url in urls:
        if url.startswith("https://r.jina.ai/http://"):
            url = url.replace("https://r.jina.ai/http://", "http://", 1)
        elif url.startswith("https://r.jina.ai/https://"):
            url = url.replace("https://r.jina.ai/https://", "https://", 1)
        host = urllib.parse.urlparse(url).netloc
        if host:
            return host
    return ""


def extract_http_urls(text, limit=6):
    urls = []
    seen = set()
    for raw in re.findall(r"https?://[^'\"\\)\]\s]+", str(text or "")):
        url = raw.rstrip(".,;:")
        if url.startswith("https://r.jina.ai/http://"):
            url = url.replace("https://r.jina.ai/http://", "http://", 1)
        elif url.startswith("https://r.jina.ai/https://"):
            url = url.replace("https://r.jina.ai/https://", "https://", 1)
        parsed = urllib.parse.urlparse(url)
        if parsed.scheme in {"http", "https"} and parsed.netloc and url not in seen:
            seen.add(url)
            urls.append(url)
        if len(urls) >= limit:
            break
    return urls


def command_progress(command, completed=False, exit_code=None):
    raw = str(command or "")
    if re.search(r"\b(curl|wget)\b|urllib|requests", raw):
        host = first_url_host(raw)
        source = f"`{host}`" if host else "a web source"
        if completed:
            if exit_code == 0:
                return f"Checked {source}."
            return f"Checking {source} finished with exit code {exit_code}."
        return f"Checking {source} for source data."

    compacted = compact_command(raw)
    if completed:
        if exit_code == 0:
            return f"Finished `{compacted}` successfully."
        return f"`{compacted}` finished with exit code {exit_code}."
    return f"Running `{compacted}`."


def non_fatal_codex_warning(message):
    text = str(message or "").lower()
    return any(
        marker in text
        for marker in [
            "model metadata for",
            "fallback metadata",
            "skill descriptions were shortened",
            "exceeded skills context budget",
        ]
    )


def run_capture(args, timeout=3):
    try:
        result = subprocess.run(
            args,
            stdout=subprocess.PIPE,
            stderr=subprocess.DEVNULL,
            text=True,
            timeout=timeout,
            env={**os.environ, "PATH": PATH_FOR_CODEX},
        )
    except (OSError, subprocess.SubprocessError):
        return ""
    if result.returncode != 0:
        return ""
    return result.stdout.strip()


def command_version(command, version_args):
    path = shutil.which(command, path=PATH_FOR_CODEX)
    if not path:
        return None
    output = run_capture([path, *version_args], timeout=3)
    first_line = output.splitlines()[0] if output else ""
    return {"name": command, "path": path, "version": first_line}


def human_bytes(value):
    try:
        value = float(value)
    except (TypeError, ValueError):
        return "0 B"
    units = ["B", "KB", "MB", "GB", "TB"]
    for unit in units:
        if value < 1024 or unit == units[-1]:
            return f"{value:.1f} {unit}" if unit != "B" else f"{int(value)} B"
        value /= 1024
    return f"{value:.1f} TB"


def ollama_json(path, timeout=2):
    try:
        with urllib.request.urlopen(f"http://127.0.0.1:11434{path}", timeout=timeout) as response:
            return json.loads(response.read().decode("utf-8"))
    except (OSError, urllib.error.URLError, json.JSONDecodeError):
        return None


def ollama_health():
    tags = ollama_json("/api/tags")
    ps = ollama_json("/api/ps")
    models = []
    for model in (tags or {}).get("models", []) or []:
        if not isinstance(model, dict):
            continue
        size = int(model.get("size") or 0)
        models.append(
            {
                "name": model.get("name", ""),
                "digest": model.get("digest", ""),
                "size": size,
                "sizeLabel": human_bytes(size),
                "modifiedAt": model.get("modified_at", ""),
            }
        )
    loaded = []
    for model in (ps or {}).get("models", []) or []:
        if isinstance(model, dict) and model.get("name"):
            loaded.append(model.get("name"))
    return {
        "running": tags is not None,
        "modelCount": len(models),
        "models": models[:12],
        "loadedModels": loaded[:12],
        "loadedCount": len(loaded),
    }


def mac_memory_health():
    total_text = run_capture(["sysctl", "-n", "hw.memsize"], timeout=1)
    try:
        total = int(total_text)
    except (TypeError, ValueError):
        total = 0

    vm_text = run_capture(["vm_stat"], timeout=1)
    page_size = 4096
    match = re.search(r"page size of (\d+) bytes", vm_text or "")
    if match:
        page_size = int(match.group(1))
    pages = {}
    for line in (vm_text or "").splitlines():
        match = re.match(r"([^:]+):\s+([0-9.]+)", line.strip())
        if match:
            key = match.group(1).strip().lower()
            pages[key] = int(match.group(2).replace(".", ""))
    pressure_pages = (
        pages.get("pages active", 0)
        + pages.get("pages wired down", 0)
        + pages.get("pages occupied by compressor", 0)
    )
    used = min(total, pressure_pages * page_size) if total else 0
    free = max(0, total - used) if total else 0
    percent = round((used / total) * 100, 1) if total else 0
    return {
        "total": total,
        "used": used,
        "free": free,
        "percent": percent,
        "totalLabel": human_bytes(total),
        "usedLabel": human_bytes(used),
        "freeLabel": human_bytes(free),
    }


def profiler_value(text, label):
    match = re.search(rf"^\s*{re.escape(label)}:\s*(.+?)\s*$", str(text or ""), re.MULTILINE)
    return match.group(1).strip() if match else ""


def mac_hardware_profile(refresh=False):
    now = time.time()
    if (
        not refresh
        and mac_hardware_cache.get("data")
        and now - mac_hardware_cache.get("time", 0) < 120
    ):
        return mac_hardware_cache["data"]

    hardware_text = run_capture(["system_profiler", "SPHardwareDataType"], timeout=5)
    display_text = run_capture(["system_profiler", "SPDisplaysDataType"], timeout=5)
    chip = profiler_value(hardware_text, "Chip") or run_capture(["sysctl", "-n", "machdep.cpu.brand_string"], timeout=1)
    memory = profiler_value(hardware_text, "Memory")
    if not memory:
        try:
            memory = human_bytes(int(run_capture(["sysctl", "-n", "hw.memsize"], timeout=1)))
        except (TypeError, ValueError):
            memory = ""
    profile = {
        "modelName": profiler_value(hardware_text, "Model Name"),
        "modelIdentifier": profiler_value(hardware_text, "Model Identifier"),
        "modelNumber": profiler_value(hardware_text, "Model Number"),
        "chip": chip,
        "cpuCores": profiler_value(hardware_text, "Total Number of Cores"),
        "memory": memory,
        "gpu": profiler_value(display_text, "Chipset Model") or chip,
        "gpuCores": profiler_value(display_text, "Total Number of Cores"),
    }
    apple_silicon = "apple" in str(chip).lower() or bool(
        re.match(r"^Mac\d+,\d+$", profile["modelIdentifier"])
    )
    profile.update(
        {
            "appleSilicon": apple_silicon,
            "memoryUpgradeable": False if apple_silicon else None,
            "source": "system_profiler SPHardwareDataType/SPDisplaysDataType and sysctl",
            "updatedAt": now,
        }
    )
    mac_hardware_cache.update({"time": now, "data": profile})
    return profile


def http_json_url(url, timeout=1.5):
    try:
        with urllib.request.urlopen(url, timeout=timeout) as response:
            return json.loads(response.read().decode("utf-8"))
    except (OSError, urllib.error.URLError, json.JSONDecodeError) as exc:
        return {"error": str(exc), "url": url}


def http_probe(url, timeout=1.2):
    try:
        request = urllib.request.Request(url, headers={"User-Agent": "Codex-CLI-UI/1.0"})
        with urllib.request.urlopen(request, timeout=timeout) as response:
            return {"online": True, "status": getattr(response, "status", 200), "url": url}
    except urllib.error.HTTPError as exc:
        # 401/403 still prove the printer service is reachable.
        return {
            "online": exc.code < 500,
            "status": exc.code,
            "url": url,
            "authRequired": exc.code in {401, 403},
            "error": "" if exc.code < 500 else str(exc),
        }
    except (OSError, urllib.error.URLError) as exc:
        return {"online": False, "status": 0, "url": url, "error": str(exc)}


def ping_host(host, timeout=0.65):
    if not host:
        return False
    try:
        result = subprocess.run(
            ["ping", "-c", "1", "-W", "350", host],
            stdout=subprocess.DEVNULL,
            stderr=subprocess.DEVNULL,
            timeout=timeout,
            env={**os.environ, "PATH": PATH_FOR_CODEX},
        )
    except (OSError, subprocess.SubprocessError):
        return False
    return result.returncode == 0


def round_number(value):
    try:
        return round(float(value), 1)
    except (TypeError, ValueError):
        return None


def service_kind(service):
    text = f"{service.get('name', '')} {service.get('url', '')}".lower()
    if "moonraker" in text or ":7125" in text:
        return "moonraker"
    if "prusalink" in text or "prusa link" in text:
        return "prusalink"
    if "creality" in text or "upload endpoint" in text or ":4408" in text:
        return "creality"
    if service.get("url"):
        return "http"
    return "host"


def is_printer_machine(machine):
    name = str(machine.get("name", "")).lower()
    notes = str(machine.get("notes", "")).lower()
    text = f"{name} {notes}"
    if any(term in name for term in ("router", "makersvpn", "netgear")):
        return False
    printer_terms = (
        "qidi",
        "snapmaker",
        "centauri",
        "rat rig",
        "ratrig",
        "bambu",
        "prusa",
        "creality",
        "printer",
        "core one",
        "x1 carbon",
        "h2d",
        "k2 plus",
    )
    if any(term in text for term in printer_terms):
        return True
    for service in machine.get("services") or []:
        if isinstance(service, dict) and service_kind(service) in {"moonraker", "prusalink"}:
            return True
    return False


def printer_inventory(inventory_path=None):
    printers = []
    for machine in load_machine_inventory(inventory_path=inventory_path).get("machines", []):
        if not isinstance(machine, dict) or not is_printer_machine(machine):
            continue
        services = [item for item in (machine.get("services") or []) if isinstance(item, dict)]
        primary = {}
        for wanted in ("moonraker", "prusalink", "creality", "http"):
            primary = next((item for item in services if service_kind(item) == wanted), {})
            if primary:
                break
        kind = service_kind(primary) if primary else "host"
        name_text = str(machine.get("name") or "").lower()
        if not primary and text_has_any(name_text, ("bambu", "h2d", "x1 carbon")):
            kind = "bambu"
        url = primary.get("url") or ""
        host = machine.get("host") or urllib.parse.urlparse(url).hostname or ""
        if kind == "moonraker" and not url and host:
            url = f"http://{host}:7125"
        status_override = machine.get("statusOverride") if isinstance(machine.get("statusOverride"), dict) else {}
        printers.append(
            {
                "id": re.sub(r"[^a-z0-9]+", "-", str(machine.get("name", "printer")).lower()).strip("-"),
                "name": machine.get("name", "Printer"),
                "host": host,
                "url": url,
                "kind": kind,
                "service": primary.get(
                    "name",
                    "Bambu status" if kind == "bambu" else ("Host ping" if kind == "host" else kind.title()),
                ),
                "statusOverride": status_override,
            }
        )
    return printers


def active_printer_status_override(printer):
    override = printer.get("statusOverride") if isinstance(printer.get("statusOverride"), dict) else {}
    if not override:
        return {}
    expires_at = override.get("expiresAtEpoch")
    if expires_at is not None:
        try:
            if float(expires_at) < time.time():
                return {}
        except (TypeError, ValueError):
            return {}
    state = str(override.get("state") or "").strip().lower()
    if not state and "online" not in override:
        return {}
    return override


def apply_printer_status_override(result):
    override = active_printer_status_override(result)
    if not override:
        return result
    online = bool(override.get("online", True))
    state = str(override.get("state") or ("online" if online else "offline")).strip().lower()
    result.update(
        {
            "online": online,
            "state": state,
            "statusOverrideActive": True,
            "statusSource": compact(override.get("source") or "local status override", 120),
            "statusNote": compact(override.get("note") or "", 180),
            "overrideUpdatedAt": override.get("updatedAt") or "",
            "overrideExpiresAt": override.get("expiresAt") or "",
            "telemetry": result.get("telemetry") or {},
        }
    )
    if online:
        result.pop("error", None)
    if override.get("progress") is not None:
        result["progress"] = override.get("progress")
    if override.get("timeRemaining") is not None:
        result["timeRemaining"] = override.get("timeRemaining")
    if override.get("timeRemainingSeconds") is not None:
        result["timeRemainingSeconds"] = override.get("timeRemainingSeconds")
    return result


def format_duration_short(seconds):
    try:
        total = max(0, int(round(float(seconds))))
    except (TypeError, ValueError):
        return ""
    hours, remainder = divmod(total, 3600)
    minutes, secs = divmod(remainder, 60)
    if hours:
        return f"{hours}h {minutes:02d}m"
    if minutes:
        return f"{minutes}m"
    return f"{secs}s"


def estimate_remaining_seconds(progress_fraction, elapsed_seconds):
    try:
        progress = float(progress_fraction)
        elapsed = float(elapsed_seconds)
    except (TypeError, ValueError):
        return None
    if progress <= 0 or progress >= 1 or elapsed <= 0:
        return None
    return max(0, elapsed * ((1 / progress) - 1))


def moonraker_printer_health(printer):
    base_url = (printer.get("url") or "").rstrip("/")
    result = dict(printer)
    result.update({"online": False, "state": "offline", "telemetry": {}})
    if not base_url:
        result["online"] = ping_host(printer.get("host", ""))
        result["state"] = "online" if result["online"] else "offline"
        return result

    objects_list = http_json_url(f"{base_url}/printer/objects/list", timeout=1.2)
    if objects_list.get("error"):
        server_info = http_json_url(f"{base_url}/server/info", timeout=1.2)
        result["online"] = isinstance(server_info, dict) and not server_info.get("error")
        result["state"] = "online" if result["online"] else "offline"
        result["error"] = server_info.get("error") if isinstance(server_info, dict) else ""
        return result

    available = set((objects_list.get("result") or {}).get("objects") or [])
    wanted = [item for item in ("extruder", "heater_bed", "print_stats", "virtual_sdcard") if item in available]
    humidity_objects = [
        item for item in sorted(available)
        if any(token in item.lower() for token in ("aht", "humidity", "heater_box"))
    ]
    wanted.extend(humidity_objects[:2])
    if not wanted:
        result["online"] = True
        result["state"] = "online"
        return result

    query = "&".join(urllib.parse.quote(item) for item in wanted)
    status_payload = http_json_url(f"{base_url}/printer/objects/query?{query}", timeout=1.5)
    if status_payload.get("error"):
        result["online"] = True
        result["state"] = "online"
        result["error"] = status_payload.get("error", "")
        return result

    status = (status_payload.get("result") or {}).get("status") or {}
    extruder = status.get("extruder") or {}
    heater_bed = status.get("heater_bed") or {}
    print_stats = status.get("print_stats") or {}
    virtual_sdcard = status.get("virtual_sdcard") or {}
    progress_fraction = virtual_sdcard.get("progress") or 0
    remaining_seconds = estimate_remaining_seconds(
        progress_fraction,
        print_stats.get("print_duration") or print_stats.get("total_duration") or 0,
    )
    humidity_value = None
    for name in humidity_objects:
        sensor = status.get(name) or {}
        humidity_value = round_number(sensor.get("humidity"))
        if humidity_value is not None:
            break

    state = str(print_stats.get("state") or "online")
    result.update(
        {
            "online": True,
            "state": state,
            "file": print_stats.get("filename") or "",
            "progress": round_number(progress_fraction * 100),
            "timeRemainingSeconds": int(round(remaining_seconds)) if remaining_seconds is not None else None,
            "timeRemaining": format_duration_short(remaining_seconds) if remaining_seconds is not None else "",
            "telemetry": {
                "nozzle": {
                    "current": round_number(extruder.get("temperature")),
                    "target": round_number(extruder.get("target")),
                },
                "bed": {
                    "current": round_number(heater_bed.get("temperature")),
                    "target": round_number(heater_bed.get("target")),
                },
                "humidity": humidity_value,
            },
        }
    )
    return result


def generic_printer_health(printer):
    result = dict(printer)
    url = result.get("url") or ""
    if url:
        probe = http_probe(url)
        result.update(
            {
                "online": probe.get("online", False),
                "state": "auth" if probe.get("authRequired") else ("online" if probe.get("online") else "offline"),
                "status": probe.get("status", 0),
                "authRequired": probe.get("authRequired", False),
                "error": probe.get("error", ""),
                "telemetry": {},
            }
        )
        return result
    online = ping_host(result.get("host", ""))
    result.update({"online": online, "state": "online" if online else "offline", "telemetry": {}})
    return result


def check_printer(printer):
    if printer.get("kind") == "moonraker":
        result = moonraker_printer_health(printer)
    else:
        result = generic_printer_health(printer)
    return apply_printer_status_override(result)


def printer_health():
    now = time.time()
    if printer_health_cache["data"] and now - printer_health_cache["time"] < 20:
        return printer_health_cache["data"]

    printers = printer_inventory()
    if printers:
        with concurrent.futures.ThreadPoolExecutor(max_workers=min(8, len(printers))) as executor:
            checked = list(executor.map(check_printer, printers))
    else:
        checked = []
    summary = {
        "total": len(checked),
        "online": sum(1 for item in checked if item.get("online")),
        "offline": sum(1 for item in checked if not item.get("online")),
        "active": sum(1 for item in checked if str(item.get("state", "")).lower() in {"printing", "paused"}),
    }
    data = {"summary": summary, "printers": checked, "updatedAt": now}
    printer_health_cache.update({"time": now, "data": data})
    return data


def qidi_health_from_printers(printers):
    for printer in printers:
        if printer.get("name") == "Qidi Plus 4":
            return {
                "url": printer.get("url") or QIDI_MOONRAKER_URL,
                "online": bool(printer.get("online")),
            }
    return {
        "url": QIDI_MOONRAKER_URL,
        "online": False,
    }


def is_printer_status_context_followup(messages):
    query = latest_user_text(messages).lower().strip()
    if not query:
        return False
    if not re.search(
        r"\b(?:is|are|can\s+you\s+see|can\s+you\s+reach|check|verify)\b.*\b(?:it|this|that|printer|machine)\b.*\b(?:online|reachable|connected|up)\b|\b(?:is\s+it|is\s+this|is\s+that)\s+(?:back\s+)?online\s+now\??$",
        query,
    ):
        return False
    recent = recent_conversation_text(messages, limit=5).lower()
    return text_has_any(
        recent,
        (
            "qidi plus 4",
            "plus 4",
            "qidi max ez",
            "max ez",
            "maxez",
            "snapmaker u1",
            "centauri carbon",
            "rat rig",
            "ratrig",
            "v-core",
            "bambu",
            "prusa core one",
            "creality k2",
            "moonraker",
            "printer inventory",
            "saved printer",
        ),
    )


