def has_recent_assistant_context(messages, window=6):
    recent = list(messages or [])[:-1][-window:]
    return any(
        str(message.get("role", "")).lower() == "assistant"
        and str(message.get("text") or message.get("content") or "").strip()
        for message in recent
    )


