def printer_inventory_ip_list_direct_answer(messages, inventory_path=None):
    if not is_printer_inventory_ip_list_request(messages):
        return ""
    inventory_path = Path(inventory_path or MACHINE_INVENTORY_PATH)
    printers = printer_inventory(inventory_path=inventory_path)
    if not printers:
        return "\n\n".join(
            [
                "I do not have a saved printer IP list in the local inventory yet.",
                f"This is why: the app reads printer hosts from `{inventory_path}`, and that file currently has no printer entries.",
                "You should also consider: add each printer name, host/IP, and service type once, then future status and UI checks can use that list without guessing.",
            ]
        )
    rows = ["| Printer | Saved host | Service | Endpoint |", "|---|---:|---|---|"]
