def makersvpn_visibility_direct_answer(messages):
    if not is_makersvpn_visibility_question(messages):
        return ""
    context = build_startup_context()
    machines = context.get("machines") or []
    tailscale_hosts = context.get("tailscaleHosts") or []
    machine = next(
        (
            item
            for item in machines
            if "makersvpn" in str(item.get("name") or item.get("host") or "").lower()
        ),
        None,
    )
    tail = next(
        (
            item
            for item in tailscale_hosts
            if "makersvpn" in str(item.get("name") or "").lower()
        ),
        None,
    )
    parts = []
    if machine:
        parts.append(f"local inventory has MakersVPN at `{machine.get('host', 'unknown host')}`")
    if tail:
        addresses = ", ".join(tail.get("addresses") or []) or "no tailnet IP listed"
        state = "online" if tail.get("online") else "offline"
        parts.append(f"Tailscale shows MakersVPN as {state} at `{addresses}`")
    if parts:
        lead = "Yes, I can see MakersVPN from the local inventory/Tailscale context."
        proof = "; ".join(parts)
    else:
        lead = "I do not currently see MakersVPN in the local inventory or Tailscale status from this app."
        proof = "the saved machine list and Tailscale host list did not return a MakersVPN entry"
    return "\n\n".join(
        [
            lead,
            f"This is why: {proof}.",
            "You should also consider: visibility is not the same as full route health. The next proof is a read-only ping/SSH/service check to the MakersVPN LAN or tailnet address, then checking whether subnet routes are accepted if the printers sit behind that node.",
        ]
    )


def makersvpn_reboot_direct_answer(messages):
    if not is_makersvpn_reboot_request(messages):
        return ""
    return "\n\n".join(
        [
            "Yes, I can help reboot MakersVPN, but the safe answer is to verify the host first and then reboot it deliberately, not blindly drop the VPN route.",
            "This is why: MakersVPN is network infrastructure. Rebooting it can temporarily cut off printer, SSH, and subnet-route access, so the right sequence is identify the MakersVPN host, confirm it is reachable, then use the known SSH/admin path or a physical power cycle.",
            "You should also consider: after the reboot, verify `tailscale status`, the MakersVPN peer, accepted subnet routes, and one printer endpoint behind it before calling the network healthy.",
        ]
    )


def tailscale_renewed_visibility_direct_answer(messages):
    if not is_tailscale_renewed_visibility_question(messages):
        return ""
    hosts = detect_tailscale_hosts(limit=12)
    if not hosts:
        return "\n\n".join(
            [
                "I cannot verify the renewed Tailscale state from this app right now.",
                "This is why: the local `tailscale status --json` check did not return host data, so I should not claim the mesh is healthy from stale memory.",
                "You should also consider: the next checks are `tailscale status`, `tailscale ping makersvpn`, and whether this Mac has accepted subnet routes for the printer LAN.",
            ]
        )
    online = [host for host in hosts if host.get("online")]
    rows = []
    for host in hosts:
        name = host.get("name") or "tailscale-host"
        addresses = ", ".join(host.get("addresses") or []) or "no IP"
        state = "online" if host.get("online") else "offline"
        rows.append(f"- {name}: {state}, `{addresses}`")
    return "\n\n".join(
        [
            f"Tailscale is visible again from this Mac; {len(online)} of {len(hosts)} listed tailnet hosts are online.",
            "\n".join(rows[:8]),
            "This is why: I checked the local Tailscale host list instead of repeating the earlier offline state.",
            "You should also consider: after renewal, the real acceptance test is whether MakersVPN subnet routes and printer endpoints behind it respond, not just whether the Tailscale daemon lists peers.",
        ]
    )


def qidi_red_error_direct_answer(messages):
    if not is_qidi_red_error_check_request(messages):
        return ""
    data = printer_health()
    qidis = [
        printer
        for printer in data.get("printers", [])
        if "qidi" in str(printer.get("name") or "").lower()
    ]
    if not qidis:
        return "\n\n".join(
            [
                "I cannot check the Qidi red error yet because I do not see a Qidi entry in the configured printer inventory.",
                "This is why: a red printer error needs current Moonraker/Klipper evidence from the actual machine, not a guessed host.",
                "You should also consider: add or confirm the Qidi IP/hostname, then I can run read-only state, temperature, MCU, and recent log checks before any restart or config change.",
            ]
        )

    online = [printer for printer in qidis if printer.get("online")]
    rows = []
    for printer in qidis:
        name = printer.get("name") or "Qidi"
        endpoint = printer_endpoint_label(printer)
        if printer.get("online"):
            state = printer.get("state") or "online"
            telemetry = printer.get("telemetry") or {}
            rows.append(f"- {name}: reachable at `{endpoint}`, state `{state}`, nozzle {temp_summary(telemetry.get('nozzle'))}, bed {temp_summary(telemetry.get('bed'))}")
        else:
            rows.append(f"- {name}: not reachable at `{endpoint}`")
    if online:
        lead = "I can reach at least one configured Qidi endpoint, so the next step is a read-only Klipper/Moonraker log pull for the red error."
    else:
        lead = "I checked the configured Qidi endpoints, but none are reachable from this Mac right now."
    return "\n\n".join(
        [
            lead,
            "\n".join(rows),
            "This is why: a red error can be heater, MCU, sensor, CAN/USB, Klipper shutdown, or Moonraker state. The useful first pass is current status plus recent `klippy.log` and `moonraker.log`, not a blind restart.",
            "You should also consider: keep this read-only until the exact Qidi and idle/safe state are verified. If the machine is reachable, pull logs and status first; if it is offline, fix network reachability before touching printer config.",
        ]
    )


def printer_stable_ip_direct_answer(messages):
    if not is_printer_stable_ip_question(messages):
        return ""
    return "\n\n".join(
        [
            "Yes. Use router-side DHCP reservations for the printers, and only use static IPs on the printer itself when the router cannot reserve addresses cleanly.",
            "This is why: when a printer gets a new IP after power cycling, DHCP is handing it a fresh lease. A reservation pins each printer's MAC address to the same IP while keeping DNS, gateway, and subnet settings managed by the router.",
            "You should also consider: reserve addresses outside the router's normal auto-pool or in a dedicated block, label each reservation by printer name, keep mDNS/Tailscale names as backups, and update saved Moonraker/Orca/PrusaLink endpoints after the reservation is proven with ping plus the printer API.",
        ]
    )


def health_snapshot(include_printers=True):
    disk = shutil.disk_usage(str(Path.home()))
    load = os.getloadavg() if hasattr(os, "getloadavg") else (0, 0, 0)
    cpu_count = os.cpu_count() or 1
    load_percent = min(100, round((load[0] / cpu_count) * 100, 1))
    disk_used = disk.total - disk.free
    disk_percent = round((disk_used / disk.total) * 100, 1) if disk.total else 0
    if include_printers:
        printer_data = printer_health()
        qidi_data = qidi_health_from_printers(printer_data.get("printers", []))
    else:
        printer_data = {"summary": {"total": 0, "online": 0, "offline": 0, "active": 0}, "printers": []}
        qidi_data = {"url": QIDI_MOONRAKER_URL, "online": False, "skipped": True}
    return {
        "timestamp": time.time(),
        "ollama": ollama_health(),
        "disk": {
            "total": disk.total,
            "used": disk_used,
            "free": disk.free,
            "percent": disk_percent,
            "totalLabel": human_bytes(disk.total),
            "usedLabel": human_bytes(disk_used),
            "freeLabel": human_bytes(disk.free),
        },
        "memory": mac_memory_health(),
        "load": {
            "one": round(load[0], 2),
            "five": round(load[1], 2),
            "fifteen": round(load[2], 2),
            "percent": load_percent,
            "cpuCount": cpu_count,
        },
        "qidi": qidi_data,
        "printerSummary": printer_data.get("summary", {}),
        "printers": printer_data.get("printers", []),
        "printerChecksSkipped": not include_printers,
        "serverSource": server_source_freshness(),
    }


def server_source_freshness(path=None, started_sha=None, started_size=None, started_mtime=None, started_time=None):
    source_path = Path(path or SERVER_SOURCE_PATH)
    started_sha = SERVER_START_SOURCE_SHA256 if started_sha is None else str(started_sha or "")
    started_size = SERVER_START_SOURCE_SIZE if started_size is None else int(started_size or 0)
    started_mtime = SERVER_START_SOURCE_MTIME if started_mtime is None else float(started_mtime or 0.0)
    started_time = SERVER_START_TIME if started_time is None else float(started_time or 0.0)
    try:
        stat = source_path.stat()
        current_bytes = source_path.read_bytes()
        current_sha = hashlib.sha256(current_bytes).hexdigest()
        current_size = int(stat.st_size)
        current_mtime = float(stat.st_mtime)
    except OSError as exc:
        return {
            "ok": False,
            "path": str(source_path),
            "reason": f"source unreadable: {exc}",
            "startedAt": started_time,
        }
    changed = bool(
        (bool(started_sha) and current_sha != started_sha)
        or (bool(started_size) and current_size != started_size)
    )
    newer_than_start = bool(started_time and current_mtime > started_time + 0.5)
    ok = not changed and not newer_than_start
    return {
        "ok": ok,
        "path": str(source_path),
        "reason": "running source matches disk" if ok else "server.py changed on disk after this process started; restart Codex CLI UI",
        "startedAt": started_time,
        "startedSourceMtime": started_mtime,
        "currentSourceMtime": current_mtime,
        "startedSha256": started_sha[:12],
        "currentSha256": current_sha[:12],
        "startedSize": started_size,
        "currentSize": current_size,
    }


def read_json(path, default):
    try:
        return json.loads(path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError):
        return default


def write_json_atomic(path, value):
    path.parent.mkdir(parents=True, exist_ok=True)
    tmp_path = path.with_name(
        f".{path.name}.{os.getpid()}.{threading.get_ident()}.{time.time_ns()}.tmp"
    )
    try:
        tmp_path.write_text(json.dumps(value, indent=2, sort_keys=True) + "\n", encoding="utf-8")
        tmp_path.replace(path)
    finally:
        try:
            if tmp_path.exists():
                tmp_path.unlink()
        except OSError:
            pass


def slugify(value, fallback="topic"):
    slug = re.sub(r"[^a-z0-9]+", "-", str(value or "").lower()).strip("-")
    return slug[:80] or fallback


def sanitize_filename(value, fallback="attachment.bin"):
    name = Path(str(value or fallback)).name
    name = re.sub(r"[^A-Za-z0-9._ -]+", "_", name).strip(" .")
    return name[:180] or fallback


class UploadTooLargeError(ValueError):
    pass


def upload_too_large_message(size):
    return (
        f"Upload is too large to copy through the browser: {human_bytes(size)} > {human_bytes(MAX_UPLOAD_BYTES)}. "
        "Use the native + button or /api/files/attach with a local absolute path so Codex can reference the file without copying it."
    )


def load_attachment_index():
    with ATTACHMENT_INDEX_LOCK:
        data = read_json(ATTACHMENT_INDEX_PATH, [])
    if isinstance(data, dict):
        data = data.get("items", [])
    if not isinstance(data, list):
        return []
    return [item for item in data if isinstance(item, dict)]


@contextlib.contextmanager
def temporary_attachment_index_path(path):
    global ATTACHMENT_INDEX_PATH
    with ATTACHMENT_INDEX_LOCK:
        original_index_path = ATTACHMENT_INDEX_PATH
        ATTACHMENT_INDEX_PATH = Path(path)
        try:
            yield ATTACHMENT_INDEX_PATH
        finally:
            ATTACHMENT_INDEX_PATH = original_index_path


def record_attachment_reference(attachment):
    if not isinstance(attachment, dict):
        return attachment
    path_text = str(attachment.get("path") or "").strip()
    if not path_text:
        return attachment
    try:
        path = Path(path_text).expanduser()
    except (OSError, RuntimeError, ValueError):
        return attachment
    name = sanitize_filename(attachment.get("name") or path.name, fallback=path.name or "attachment.bin")
    try:
        stat = path.stat()
        size = int(stat.st_size)
        mtime = float(stat.st_mtime)
    except OSError:
        size = int(attachment.get("size") or 0)
        mtime = 0.0
    record = {
        "name": name,
        "path": str(path),
        "size": size,
        "contentType": str(attachment.get("contentType") or attachment.get("type") or "application/octet-stream"),
        "source": str(attachment.get("source") or "upload"),
        "copied": bool(attachment.get("copied", True)),
        "mtime": mtime,
        "updatedAt": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()),
    }
    with ATTACHMENT_INDEX_LOCK:
        records = load_attachment_index()
        deduped = []
        record_key = (record["name"].lower(), record["path"])
        for existing in records:
            existing_key = (
                str(existing.get("name") or "").lower(),
                str(existing.get("path") or ""),
            )
            if existing_key == record_key or str(existing.get("path") or "") == record["path"]:
                continue
            deduped.append(existing)
        write_json_atomic(ATTACHMENT_INDEX_PATH, [record] + deduped[: max(0, ATTACHMENT_INDEX_LIMIT - 1)])
    return attachment


def record_message_attachments(messages):
    count = 0
    for attachment in message_attachments(messages):
        before = str(attachment.get("path") or "")
        if before:
            record_attachment_reference(attachment)
            count += 1
    return count


def recent_attachment_match(refs, extensions=(), searched=None):
    refs = [str(ref or "").strip().strip("`'\"") for ref in refs or [] if str(ref or "").strip()]
    if not refs:
        return None
    extensions = tuple(ext.lower() for ext in extensions or ())
    searched = searched if isinstance(searched, list) else []
    ref_keys = set()
    ref_lowers = []
    for ref in refs:
        ref_path = Path(ref).expanduser()
        ref_lower = ref.lower()
        ref_lowers.append(ref_lower)
        ref_keys.add(ref.lower())
        if ref_path.name:
            ref_keys.add(ref_path.name.lower())
    for record in load_attachment_index():
        name = str(record.get("name") or "").strip()
        path_text = str(record.get("path") or "").strip()
        if not path_text:
            continue
        path = Path(path_text).expanduser()
        path_lower = str(path).lower()
        name_lower = name.lower()
        if extensions and not (path_lower.endswith(extensions) or name_lower.endswith(extensions)):
            continue
        searched.append(f"attachment-index:{path}")
        basename_lower = path.name.lower()
        embedded_name_match = any(
            (name_lower and name_lower in ref_lower) or (basename_lower and basename_lower in ref_lower)
            for ref_lower in ref_lowers
        )
        if name_lower not in ref_keys and basename_lower not in ref_keys and path_lower not in ref_keys and not embedded_name_match:
            continue
        if path.exists() and path.is_file():
            return {
                "path": path,
                "source": "recent attachment index",
                "name": name or path.name,
                "searched": searched,
            }
    return None


def save_uploaded_bytes(name, data, content_type="application/octet-stream", raw_size=0):
    name = sanitize_filename(name, fallback="attachment.bin")
    data = data or b""
    raw_size = int(raw_size or 0)
    if raw_size <= 0 and len(data) == 0:
        raise ValueError("Attachment is empty.")
    if raw_size > MAX_UPLOAD_BYTES:
        raise UploadTooLargeError(upload_too_large_message(raw_size))
    if len(data) > MAX_UPLOAD_BYTES:
        raise UploadTooLargeError(upload_too_large_message(len(data)))
    if raw_size and abs(raw_size - len(data)) > 1:
        raise ValueError("Attachment size did not match the uploaded data.")

    UPLOAD_DIR.mkdir(parents=True, exist_ok=True)
    stamp = time.strftime("%Y%m%d-%H%M%S")
    target = UPLOAD_DIR / f"{stamp}-{name}"
    suffix = 1
    while target.exists():
        target = UPLOAD_DIR / f"{stamp}-{suffix}-{name}"
        suffix += 1
    target.write_bytes(data)
    result = {
        "ok": True,
        "name": name,
        "path": str(target),
        "size": len(data),
        "contentType": str(content_type or "application/octet-stream"),
    }
    record_attachment_reference(result)
    return result


def save_uploaded_file(payload):
    name = sanitize_filename(payload.get("name"), fallback="attachment.bin")
    raw_size = int(payload.get("size") or 0)
    local_path = str(payload.get("path") or payload.get("localPath") or "").strip()
    data_text = str(payload.get("dataBase64") or "")
    if local_path and not data_text:
        candidate = Path(local_path).expanduser()
        if not candidate.is_absolute():
            raise ValueError("Local attachment paths must be absolute.")
        if not candidate.exists() or not candidate.is_file():
            raise ValueError(f"Local attachment path is not a readable file: {candidate}")
        stat = candidate.stat()
        result = {
            "ok": True,
            "name": name if name != "attachment.bin" else candidate.name,
            "path": str(candidate),
            "size": int(stat.st_size),
            "contentType": str(payload.get("type") or payload.get("contentType") or "application/octet-stream"),
            "source": "native-local-path",
            "copied": False,
        }
        record_attachment_reference(result)
        return result
    if "," in data_text and data_text.lower().startswith("data:"):
        data_text = data_text.split(",", 1)[1]
    if raw_size > MAX_UPLOAD_BYTES:
        raise UploadTooLargeError(upload_too_large_message(raw_size))
    try:
        data = base64.b64decode(data_text, validate=True)
    except Exception as exc:
        raise ValueError(f"Attachment data is not valid base64: {exc}") from exc
    if len(data) > MAX_UPLOAD_BYTES:
        raise UploadTooLargeError(upload_too_large_message(len(data)))
    if raw_size and abs(raw_size - len(data)) > 1:
        raise ValueError("Attachment size did not match the uploaded data.")
    return save_uploaded_bytes(name, data, str(payload.get("type") or "application/octet-stream"), raw_size=raw_size)


def save_uploaded_multipart(handler):
    length = int(handler.headers.get("Content-Length", "0") or "0")
    if length > MAX_UPLOAD_BYTES + 8192:
        raise UploadTooLargeError(upload_too_large_message(length))
    environ = {
        "REQUEST_METHOD": "POST",
        "CONTENT_TYPE": handler.headers.get("Content-Type", ""),
        "CONTENT_LENGTH": str(length),
    }
    form = cgi.FieldStorage(
        fp=handler.rfile,
        headers=handler.headers,
        environ=environ,
        keep_blank_values=True,
    )
    if "file" not in form:
        raise ValueError("Multipart upload did not include a file field.")
    file_item = form["file"]
    if isinstance(file_item, list):
        file_item = file_item[0]
    filename = form.getfirst("name") or getattr(file_item, "filename", "") or "attachment.bin"
    content_type = form.getfirst("type") or getattr(file_item, "type", "") or "application/octet-stream"
    raw_size = int(form.getfirst("size") or 0)
    data = file_item.file.read() if getattr(file_item, "file", None) else b""
    return save_uploaded_bytes(filename, data, content_type, raw_size=raw_size)


def default_admin_state():
    return {
        "version": 1,
        "createdAt": time.time(),
        "updatedAt": time.time(),
        "projects": {},
        "recentTopics": [],
        "preferences": [],
    }


def load_admin_state():
    state = read_json(ADMIN_STATE_PATH, default_admin_state())
    state.setdefault("version", 1)
    state.setdefault("createdAt", time.time())
    state.setdefault("updatedAt", time.time())
    state.setdefault("projects", {})
    state.setdefault("recentTopics", [])
    state.setdefault("preferences", [])
    return state


def load_stable_knowledge():
    data = read_json(ADMIN_KNOWLEDGE_PATH, {"version": 1, "items": []})
    data.setdefault("version", 1)
    data.setdefault("items", [])
    return data


WORKING_PROFILE_FIELDS = ("objective", "answerStyle", "terminology", "constraints")
WORKING_PROFILE_FIELD_LIMITS = {
    "objective": 320,
    "answerStyle": 320,
    "terminology": 420,
    "constraints": 420,
}


def default_working_profiles():
    return {"version": 1, "profiles": []}


def load_working_profiles():
    data = read_json(WORKING_PROFILE_PATH, default_working_profiles())
    data.setdefault("version", 1)
    data.setdefault("profiles", [])
    if not isinstance(data.get("profiles"), list):
        data["profiles"] = []
    return data


def working_profile_project_options():
    options = {"general": "General"}
    for project_id, project in PROJECT_PLAYBOOKS.items():
        options[project_id] = str(project.get("name") or project_id.replace("-", " ").title())
    for project_id, project in ADMIN_TAXONOMY.items():
        options.setdefault(project_id, str(project.get("name") or project_id.replace("-", " ").title()))
        for route_id in project.get("routeProjects", ()):
            options.setdefault(route_id, str(project.get("name") or route_id.replace("-", " ").title()))
    return [
        {"id": project_id, "name": project_name}
        for project_id, project_name in sorted(options.items(), key=lambda item: (item[0] != "general", item[1].lower()))
    ]


def working_profile_project_name(project_id):
    key = str(project_id or "").strip()
    for option in working_profile_project_options():
        if option["id"] == key:
            return option["name"]
    return key.replace("-", " ").title() or "General"


def safe_working_profile_project_id(value):
    project_id = str(value or "").strip().lower()
    if not re.fullmatch(r"[a-z0-9][a-z0-9-]{0,80}", project_id):
        return ""
    return project_id


def sanitize_working_profile_text(value, limit):
    raw = " ".join(strip_thinking_markup(value).split())
    if raw != redact_sensitive_inline_text(raw):
        raise ValueError("Working profiles cannot include passwords, API keys, tokens, or secrets.")
    return sanitize_learning_text(raw, limit=limit)


def public_working_profile(profile):
    profile = profile if isinstance(profile, dict) else {}
    project_id = safe_working_profile_project_id(profile.get("projectId")) or "general"
    result = {
        "projectId": project_id,
        "projectName": str(profile.get("projectName") or working_profile_project_name(project_id)),
        "confirmedAt": profile.get("confirmedAt"),
        "updatedAt": profile.get("updatedAt"),
    }
    for field in WORKING_PROFILE_FIELDS:
        result[field] = str(profile.get(field) or "")
    return result


def working_profile_for_route(route=None):
    route = route if isinstance(route, dict) else {}
    project_id = safe_working_profile_project_id(route.get("projectId"))
    if not project_id:
        return None
    for profile in load_working_profiles().get("profiles", []):
        if safe_working_profile_project_id(profile.get("projectId")) == project_id:
            return public_working_profile(profile)
    return None


def working_profile_context(route=None):
    profile = working_profile_for_route(route)
    if not profile:
        return ""
    lines = [
        "User-confirmed project working profile:",
        f"- Project: {profile['projectName']}.",
    ]
    labels = {
        "objective": "Keep this current objective in view",
        "answerStyle": "Preferred answer style",
        "terminology": "Preferred terminology",
        "constraints": "Constraints and boundaries",
    }
    for field in WORKING_PROFILE_FIELDS:
        value = profile.get(field)
        if value:
            lines.append(f"- {labels[field]}: {value}")
    lines.append("- This is explicit user guidance, not evidence. Do not infer, extend, or reuse it outside this project.")
    lines.append("")
    return "\n".join(lines)


def update_working_profile(action, project_id, updates=None, confirmed=False):
    action = str(action or "").strip().lower()
    project_id = safe_working_profile_project_id(project_id)
    if not project_id:
        return {"ok": False, "error": "Choose a valid project for the working profile."}
    data = load_working_profiles()
    profiles = data.get("profiles", [])
    existing = next(
        (profile for profile in profiles if safe_working_profile_project_id(profile.get("projectId")) == project_id),
        None,
    )
    if action == "delete":
        if not existing:
            return {"ok": False, "error": "Working profile not found."}
        data["profiles"] = [profile for profile in profiles if profile is not existing]
        write_json_atomic(WORKING_PROFILE_PATH, data)
        return {"ok": True, "action": "delete", "projectId": project_id}
    if action != "save":
        return {"ok": False, "error": "Unsupported working profile action."}
    if confirmed is not True:
        return {"ok": False, "error": "Confirm the project guidance before saving it."}
    updates = updates if isinstance(updates, dict) else {}
    try:
        clean = {
            field: sanitize_working_profile_text(updates.get(field) or "", WORKING_PROFILE_FIELD_LIMITS[field])
            for field in WORKING_PROFILE_FIELDS
        }
    except ValueError as exc:
        return {"ok": False, "error": str(exc)}
    if not any(clean.values()):
        return {"ok": False, "error": "Add at least one project preference before saving."}
    now = time.time()
    payload = {
        "projectId": project_id,
        "projectName": working_profile_project_name(project_id),
        **clean,
        "source": "explicit-admin-confirmation",
        "confirmedAt": now,
        "updatedAt": now,
    }
    if existing:
        payload["createdAt"] = existing.get("createdAt") or now
        existing.update(payload)
        stored = existing
    else:
        payload["createdAt"] = now
        profiles.insert(0, payload)
        data["profiles"] = profiles[:80]
        stored = payload
    write_json_atomic(WORKING_PROFILE_PATH, data)
    return {"ok": True, "action": "save", "profile": public_working_profile(stored)}


