SESSION_COMPASS_FIELDS = ("objective", "decisions", "evidence", "openQuestions", "nextStep")
SESSION_COMPASS_FIELD_LIMITS = {
    "objective": 360,
    "decisions": 720,
    "evidence": 720,
    "openQuestions": 720,
    "nextStep": 420,
}
SESSION_COMPASS_PHASES = {
    "active": "Active",
    "verifying": "Verifying",
    "awaiting-decision": "Awaiting decision",
    "blocked": "Blocked",
    "complete": "Complete",
}


def sanitize_session_compass_text(value, limit):
    raw = " ".join(strip_thinking_markup(value).split())
    return compact(redact_sensitive_inline_text(raw), limit)


def sanitize_session_compass_phase(value):
    clean = re.sub(r"[^a-z]+", "-", str(value or "").lower()).strip("-")
    return clean if clean in SESSION_COMPASS_PHASES else "active"


def session_compass_phase_label(value):
    return SESSION_COMPASS_PHASES.get(sanitize_session_compass_phase(value), SESSION_COMPASS_PHASES["active"])


def normalize_session_compass(value):
    value = value if isinstance(value, dict) else {}
    compass = {
        field: sanitize_session_compass_text(value.get(field) or "", SESSION_COMPASS_FIELD_LIMITS[field])
        for field in SESSION_COMPASS_FIELDS
    }
    if not any(compass.values()):
        return None
    updated_at = str(value.get("updatedAt") or "").strip()
    return {
        "phase": sanitize_session_compass_phase(value.get("phase")),
        **compass,
        "updatedAt": updated_at[:80],
    }


def session_compass_context(route=None):
    route = route if isinstance(route, dict) else {}
    compass = normalize_session_compass(route.get("sessionCompass"))
    if not compass:
        return ""
    labels = {
        "objective": "Current objective",
        "decisions": "Decisions already made",
        "evidence": "Latest evidence",
        "openQuestions": "Open questions",
        "nextStep": "Next concrete step",
    }
    lines = ["Active thread session compass:"]
    lines.append(f"- Task phase: {session_compass_phase_label(compass.get('phase'))}")
    for field in SESSION_COMPASS_FIELDS:
        if compass.get(field):
            lines.append(f"- {labels[field]}: {compass[field]}")
    lines.append("- This is user-editable context for this thread only. Keep it separate from verified evidence and ask if it conflicts with the newest request.")
    lines.append("")
    return "\n".join(lines)


SESSION_COMPASS_FOLLOWUP_PREFIX_RE = re.compile(
    r"(?is)^\s*(?:(?:okay|ok|great|awesome|fantastic|alright|perfect|excellent|sounds good|that works)(?:\s*[.!,:;\-]+\s*|\s+))+"
)


def session_compass_followup_intent(messages, route=None):
    compass = normalize_session_compass((route or {}).get("sessionCompass"))
    query = " ".join(latest_user_text(messages).lower().split())
    query = SESSION_COMPASS_FOLLOWUP_PREFIX_RE.sub("", query)
    if not compass or not query:
        return None

    question_pattern = re.compile(
        r"^(?:so,? )?(?:what(?:'s|s| is)? next|what next|what should we do next|what do we do next|what is the next step|next step)[?!. ]*$"
    )
    execute_pattern = re.compile(
        r"^(?:okay,? )?(?:let'?s|lets) do it[!., ]*$|^(?:go ahead|do it|do the next step|continue|continue with that|keep going|keep moving forward|proceed)[!., ]*$"
    )
    intent = "recommend" if question_pattern.fullmatch(query) else "execute" if execute_pattern.fullmatch(query) else ""
    if not intent:
        return None
    next_step = compass.get("nextStep") or ""
    if not next_step:
        intent = "clarify"
    return {"intent": intent, "compass": compass, "nextStep": next_step}


def session_compass_followup_direct_answer(messages, route=None, objective_plan=None):
    intent = session_compass_followup_intent(messages, route)
    if not intent or intent.get("intent") != "recommend":
        return ""
    compass = intent.get("compass") or {}
    lead = (
        f"Current state: {session_compass_phase_label(compass.get('phase'))}. "
        f"Recommended next move: {intent.get('nextStep')}"
    )
    if compass.get("objective"):
        lead += f" This advances {str(compass['objective']).rstrip(' .')}"
    elif not lead.endswith((".", "!", "?")):
        lead += "."
    if not lead.endswith((".", "!", "?")):
        lead += "."
    lines = [lead]
    support = []
    if compass.get("evidence"):
        support.append(f"Latest evidence: {str(compass['evidence']).rstrip(' .')}.")
    if compass.get("decisions"):
        support.append(f"Decision already made: {str(compass['decisions']).rstrip(' .')}.")
    if support:
        lines.append(" ".join(support))
    if compass.get("openQuestions"):
        lines.append(f"Keep open: {compass['openQuestions']}")
    return "\n\n".join(lines)


def session_compass_progress_update(messages, route=None, answer=""):
    route = route or {}
    plan = route.get("objectivePlan") if isinstance(route.get("objectivePlan"), dict) else {}
    if plan.get("responseKind") != "execute-session-next-step":
        return None
    compass = normalize_session_compass(route.get("sessionCompass"))
    completed_step = compact(plan.get("sessionCompassNextStep") or (compass or {}).get("nextStep") or "", 420)
    if not compass or not completed_step:
        return None
    next_match = re.search(r"(?im)^next(?: concrete)? step\s*:\s*(.+?)\s*$", str(answer or ""))
    next_step = sanitize_session_compass_text(next_match.group(1), SESSION_COMPASS_FIELD_LIMITS["nextStep"]) if next_match else ""
    if next_step.lower() == completed_step.lower():
        next_step = ""
    return {
        "kind": "completed-next-step",
        "completedStep": completed_step,
        "nextStep": next_step,
        "phase": "active" if next_step else "complete",
    }


