def text_has_any(text, terms):
    lower = str(text or "").lower()
    return any(term in lower for term in terms)


DIRECT_FACTUAL_QUESTION_TERMS = (
    "what is",
    "what are",
    "which",
    "what file",
    "what format",
    "how much",
    "how many",
    "can you tell me",
    "do you know",
)
ARTIFACT_ACTION_TERMS = (
    "design",
    "designed",
    "create",
    "make",
    "build",
    "model",
    "generate",
    "draw",
    "draft",
    "save",
    "write",
    "stage",
    "import",
    "imported",
    "export",
)


def is_direct_factual_question_without_artifact_action(text):
    lower = str(text or "").lower().strip()
    if not lower:
        return False
    question_like = lower.endswith("?") or text_has_any(lower, DIRECT_FACTUAL_QUESTION_TERMS)
    return bool(question_like and not text_has_any(lower, ARTIFACT_ACTION_TERMS))


def latest_query_lower(messages):
    return latest_user_text(messages).lower()


def is_simple_route_term(needle):
    return bool(ROUTE_SIMPLE_TERM_RE.fullmatch(str(needle or "")))


def route_term_regex(needle):
    cached = ROUTE_TERM_REGEX_CACHE.get(needle)
    if cached is not None:
        return cached
    if len(ROUTE_TERM_REGEX_CACHE) > 4096:
        ROUTE_TERM_REGEX_CACHE.clear()
    compiled = re.compile(r"(?<![a-z0-9_])" + re.escape(needle) + r"(?![a-z0-9_])")
    ROUTE_TERM_REGEX_CACHE[needle] = compiled
    return compiled


def is_volatile_query_text(text):
    lower = str(text or "").lower()
    for term in VOLATILE_KNOWLEDGE_TERMS:
        needle = str(term or "").lower().strip()
        if not needle:
            continue
        if is_simple_route_term(needle):
            if route_term_regex(needle).search(lower):
                return True
        elif needle in lower:
            return True
    if re.search(r"\b(20[2-9]\d|19\d\d)\b", lower) and text_has_any(lower, {"current", "latest", "newest"}):
        return True
    return False


def admin_project_score(project_id, project, query, route):
    score = 0
    matched = []
    route_id = route.get("projectId", "") if isinstance(route, dict) else ""
    if route_id in project.get("routeProjects", ()):
        score += 18
        matched.append(route_id)
    for trigger in project.get("triggers", ()):
        if trigger and trigger in query:
            score += 8
            matched.append(trigger)
    return score, matched[:6]


def admin_folder_score(folder, query):
    score = 0
    matched = []
    for trigger in folder.get("triggers", ()):
        if trigger and trigger in query:
            score += 10
            matched.append(trigger)
    return score, matched[:6]


def admin_preference_boosts(query):
    state = load_admin_state()
    project_boosts = {}
    folder_boosts = {}
    # Learned filing preferences should break ties on ambiguous follow-ups, not
    # overpower explicit route/domain evidence from the current request.
    max_project_boost = 7
    max_folder_boost = 9
    for preference in state.get("preferences", [])[-80:]:
        terms = []
        for raw_term in preference.get("matchTerms") or []:
            term = re.sub(r"[^a-z0-9+#.\- ]+", "", str(raw_term).lower()).strip(" .")
            if len(term) < 4 or term in STOP_WORDS:
                continue
            terms.append(term)
        if terms and any(term in query for term in terms):
            project_id = preference.get("projectId")
            folder_id = preference.get("folderId")
            if project_id:
                project_boosts[project_id] = min(
                    max_project_boost,
                    project_boosts.get(project_id, 0) + max_project_boost,
                )
            if project_id and folder_id:
                folder_boosts[(project_id, folder_id)] = min(
                    max_folder_boost,
                    folder_boosts.get((project_id, folder_id), 0) + max_folder_boost,
                )
    return project_boosts, folder_boosts


