def is_same_action_missing_context_question(messages):
    query = latest_user_text(messages).lower().strip()
    if not query or has_recent_assistant_context(messages) or len(query) > 180:
        return False
    same_action = text_has_any(
        query,
        (
            "do the same",
            "same for",
            "same with",
            "same thing",
            "the same thing",
            "do that for",
            "apply that to",
            "run that on",
            "other one",
            "other printer",
            "other machine",
            "another printer",
            "another machine",
        ),
    )
    pronoun_action = bool(
        re.search(r"\b(?:do|apply|run|copy|put|use|send|move|rename)\s+(?:it|that|this|those|these)\b", query)
        or re.search(r"\b(?:that|this|those|these)\s+(?:one|file|profile|printer|machine|settings)\s+too\b", query)
        or re.search(r"\b(?:the\s+)?other\s+(?:one|file|profile|printer|machine)\s+too\b", query)
        or re.search(r"\bsame\s+(?:settings|place|profile|file)\b", query)
    )
    target_hint = text_has_any(
        query,
        (
            "printer",
            "machine",
            "profile",
            "config",
            "file",
            "settings",
            "place",
            "there",
            "other one",
            "other",
            "another",
            "that one",
            "this one",
            "last time",
            "max ez",
            "plus 4",
            "qidi",
            "snapmaker",
            "rat rig",
            "ratrig",
            "bambu",
            "sovol",
            "centauri",
            "creality",
        ),
    )
    return (same_action or pronoun_action) and target_hint


