def is_current_access_status_question(messages):
    query = latest_user_text(messages).lower().strip()
    if not query:
        return False
    if text_has_any(query, ("web access", "internet access", "public web")):
        return False
    access_terms = ("access", "acces", "access level", "acces level", "sandbox", "visibility", "rights", "permissions")
    status_terms = (
        "what access",
        "what are you showing",
        "what are you showing for access",
        "what access are you showing",
        "current access",
        "access level now",
        "showing now",
        "showing for acces",
        "showing for access",
        "do you have access now",
        "do you have access no",
    )
    restart_terms = ("restart", "stop and restart", "recognize this", "recognise this", "recognize full access", "recognise full access")
    if text_has_any(query, access_terms) and text_has_any(query, status_terms) and len(query.split()) <= 18:
        return True
    return (
        text_has_any(query, ("full access", "full acess", "access selected", "access level"))
        and text_has_any(query, restart_terms)
    )


