def local_maxez_printer_cfg_candidates(max_results=8, time_budget=2.0):
    roots = [
        HOME_DIR / "Desktop" / "BTT Build",
        HOME_DIR / "Desktop" / "Temp Qidi Config Files",
        HOME_DIR / "Desktop",
        HOME_DIR / "Downloads",
        HOME_DIR / "Documents" / "Codex" / "maxez_preflash_backups",
        HOME_DIR / "Documents" / "Codex" / "2026-06-25" / "r" / "maxez_preflash_backups",
        APP_DIR / "data" / "private",
        APP_DIR / "data" / "generated",
        HOME_DIR / "Documents" / "Codex",
    ]
    skip_dirs = {
        ".git",
        "__pycache__",
        "node_modules",
        ".venv",
        "venv",
        "build",
        "dist",
        "DerivedData",
        "Library",
    }
    allowed_suffixes = {".cfg", ".conf", ".txt", ".md", ".rtf", ".docx"}
    maxez_terms = ("maxez", "max ez", "max-ez", "qidiplus4maxez", "qidi plus4maxez", "plus4maxez", "qidi plus 4 max")
    started = time.time()
    candidates = {}

    def add_candidate(path, score, reason):
        key = str(path)
        current = candidates.get(key)
        if current and current["score"] >= score:
            return
        candidates[key] = {
            "path": key,
            "score": int(score),
            "reason": reason,
        }

    def maybe_add_candidate(path, source_hint=""):
        path = Path(path)
        filename = path.name
        name_lower = filename.lower()
        suffix = path.suffix.lower()
        if suffix not in allowed_suffixes and filename != "printer.cfg":
            return False
        full_lower = str(path).lower()
        maxez_match = any(term in full_lower for term in maxez_terms)
        printer_cfg_match = name_lower == "printer.cfg" or "printer.cfg" in name_lower or "printer cfg" in name_lower
        doc_hint = suffix == ".docx" and ("printer" in name_lower or maxez_match)
        if not (printer_cfg_match or doc_hint or (maxez_match and suffix in {".cfg", ".conf", ".txt", ".md", ".docx"})):
            return False
        score = 0
        reasons = []
        if printer_cfg_match:
            score += 70
            reasons.append("printer.cfg filename")
        if maxez_match:
            score += 45
            reasons.append("Max EZ/Qidi path match")
        if suffix == ".docx":
            score += 12
            reasons.append("Word document candidate")
        if "backup" in full_lower or "preflash" in full_lower:
            score += 10
            reasons.append("backup/preflash folder")
        if source_hint:
            reasons.append(source_hint)
        if score:
            add_candidate(path, score, ", ".join(reasons))
            return True
        return False

    for index_path in (PRIVATE_DATA_DIR / "local_file_index.json", DATA_DIR / "local_file_index.json"):
        if not index_path.exists():
            continue
        try:
            index_data = json.loads(index_path.read_text(encoding="utf-8"))
        except Exception:
            continue
        for entry in index_data.get("files", []):
            path = entry.get("path") if isinstance(entry, dict) else ""
            if not path:
                continue
            haystack = " ".join(
                str(value)
                for value in (
                    path,
                    entry.get("label", ""),
                    " ".join(entry.get("tags", []) if isinstance(entry.get("tags", []), list) else []),
                )
            ).lower()
            if any(term in haystack for term in maxez_terms) and text_has_any(haystack, ("printer.cfg", "printer cfg", "config")):
                maybe_add_candidate(path, "local evidence index")

    for root in roots[:2]:
        if not root.exists():
            continue
        try:
            found = subprocess.run(
                ["/usr/bin/find", str(root), "-maxdepth", "3", "-type", "f"],
                text=True,
                capture_output=True,
                timeout=0.8,
                check=False,
            )
        except Exception:
            continue
        for line in found.stdout.splitlines():
            maybe_add_candidate(line.strip(), "bounded find")

    try:
        spotlight = subprocess.run(
            [
                "/usr/bin/mdfind",
                'kMDItemFSName == "*QidiMaxEzPrinter*"cd || kMDItemFSName == "*Max*EZ*printer*cfg*"cd || kMDItemFSName == "*Qidiplus4maxEZ*"cd',
            ],
            text=True,
            capture_output=True,
            timeout=0.8,
            check=False,
        )
        for line in spotlight.stdout.splitlines():
            maybe_add_candidate(line.strip(), "Spotlight match")
    except Exception:
        pass

    seen_roots = set()
    for root in roots:
        if time.time() - started > time_budget:
            break
        resolved_root = str(root)
        if resolved_root in seen_roots:
            continue
        seen_roots.add(resolved_root)
        if not root.exists():
            continue
        for dirpath, dirnames, filenames in os.walk(root):
            if time.time() - started > time_budget:
                break
            dirnames[:] = [name for name in dirnames if name not in skip_dirs and not name.startswith(".")]
            dir_lower = str(dirpath).lower()
            maxez_path = any(term in dir_lower for term in maxez_terms)
            for filename in filenames:
                if time.time() - started > time_budget:
                    break
                path = Path(dirpath) / filename
                maybe_add_candidate(path)
    ordered = sorted(candidates.values(), key=lambda item: (-item["score"], item["path"].lower()))
    return ordered[:max_results], [str(root) for root in roots if root.exists()]


def local_maxez_printer_cfg_search_direct_answer(messages):
    if not is_local_maxez_printer_cfg_search_question(messages):
        return ""
    candidates, searched_roots = local_maxez_printer_cfg_candidates()
    if candidates:
        lines = []
        for index, item in enumerate(candidates[:3], 1):
            lines.append(f"{index}. `{item['path']}` - {item['reason']}")
        return "\n\n".join(
            [
                "I found likely local Max EZ `printer.cfg` candidates on this Mac.",
                "Strongest matches:\n" + "\n".join(lines),
                (
                    "This is why: this is a local Mac file-search task, so I checked bounded local folders and ranked files that look like "
                    "Max EZ/Qidi config backups, `printer.cfg` files, or Word-document config notes instead of waiting on the model or probing the live printer."
                ),
                (
                    "You should also consider: treat the newest real `printer.cfg` backup as evidence, not a Word note alone. Before restoring or editing anything, "
                    "compare the candidate against the active printer config and keep the search/read step separate from any live Klipper restart."
                ),
            ]
        )
    searched = ", ".join(f"`{root}`" for root in searched_roots[:6]) or "the expected local Codex/Desktop/Downloads folders"
    return "\n\n".join(
        [
            "I did not find a strong local Max EZ `printer.cfg` candidate in the bounded search window.",
            (
                f"This is why: I treated this as a local Mac search and checked likely roots first: {searched}. "
                "I stopped at the bounded search limit so the app would not hang on a huge recursive scan."
            ),
            (
                "You should also consider: narrow the search with a folder name, mount the SD card, or point me at the Word document if you remember its title. "
                "Then I can inspect that source directly before touching any live printer config."
            ),
        ]
    )


