def is_contextless_mapping_correct_question(messages):
    query = latest_user_text(messages).lower().strip()
    if not query:
        return False
    if not text_has_any(query, ("mapping", "map", "mapped")):
        return False
    if not text_has_any(query, ("correct", "right", "accurate")):
        return False
    if len(query.split()) > 12:
        return False
    specific_context = (
        "printer",
        "klipper",
        "fan",
        "pin",
        "motor",
        "stepper",
        "orca",
        "slicer",
        "network",
        "ip",
        "gis",
        "parcel",
        "wiring",
        "diagram",
        "profile",
        "filament",
    )
    def has_context_token(term):
        if len(term) <= 3:
            return bool(re.search(rf"\b{re.escape(term)}\b", query))
        return term in query

    return not any(has_context_token(term) for term in specific_context)


