def requested_step_file_label(messages):
    query = latest_user_text(messages).strip()
    match = re.search(r"\b(v\d+[a-z0-9_-]*)\b", query, flags=re.IGNORECASE)
    if match:
        return match.group(1)
    match = re.search(r"\b(?:for|called|named)\s+([A-Za-z0-9_-]{2,32})\b", query)
    return match.group(1) if match else ""


def find_local_step_files_for_label(label, limit=8):
    needle = str(label or "").lower().strip()
    roots = [
        APP_DIR / "Wind Turbine",
        LOCAL_WIND_TURBINE_OUTPUT_DIR,
        LOCAL_CAD_OUTPUT_DIR,
        LOCAL_AERO_OUTPUT_DIR,
        LOCAL_STRUCTURAL_OUTPUT_DIR,
        UPLOAD_DIR,
    ]
    matches = []
    for root in roots:
        try:
            if not root.exists():
                continue
            for path in root.rglob("*"):
                if len(matches) >= limit:
                    return matches
                if not path.is_file() or path.suffix.lower() not in {".step", ".stp"}:
                    continue
                if needle and needle not in path.name.lower() and needle not in str(path.parent).lower():
                    continue
                matches.append(path)
        except OSError:
            continue
    return matches


