def is_external_cad_source_retrieval_question(messages):
    """An external product/source URL needs public retrieval, not a local filename scan."""
    if not is_cad_model_source_search_question(messages):
        return False
    for url in extract_http_urls(latest_user_text(messages)):
        parsed = urllib.parse.urlparse(url)
        host = str(parsed.hostname or "").lower()
        if parsed.scheme in {"http", "https"} and host not in {"", "localhost", "127.0.0.1", "::1"}:
            return True
    return False


def is_named_hardware_spec_lookup_question(messages):
    """Physical dimensions/specs for a named component need source retrieval, not generation."""
    query = latest_user_text(messages).lower().strip()
    if not query or is_cad_design_request(messages):
        return False
    asks_for_measurement = text_has_any(
        query,
        (
            "dimension",
            "dimensions",
            "dimention",
            "dimentions",
            "measurement",
            "measurements",
            "physical size",
            "overall size",
            "how big",
        ),
    )
    component_terms = (
        "heater", "fan", "hotend", "extruder", "motor", "board", "sensor",
        "nozzle", "toolhead", "part", "component", "assembly", "module",
    )
    named_product = text_has_any(
        query,
        ("qidi", "bambu", "prusa", "creality", "elegoo", "voron", "rat rig", "snapmaker"),
    ) or bool(re.search(r"\b[a-z][a-z0-9-]{1,20}\s*[- ]\s*\d{1,4}\b", query))
    return asks_for_measurement and named_product and text_has_any(query, component_terms)


