def generated_artifact_revision_route_project(messages):
    try:
        if not is_generated_artifact_label_revision_followup(messages):
            return ""
        deliverables = extract_response_deliverables(previous_assistant_text(messages))
        selected = select_generated_artifact_deliverable(deliverables, latest_user_text(messages))
        suffix = Path(str((selected or {}).get("path") or "")).suffix.lower()
        kind = str((selected or {}).get("kind") or "")
        if kind == "diagram" or suffix in {".drawio", ".svg", ".mmd", ".dot", ".kicad_pro", ".kicad_sch"}:
            return "engineering-diagrams"
        if kind == "cad" or suffix in {".scad", ".step", ".stp", ".stl", ".f3d", ".f3z", ".3mf"}:
            return "cad-modeling-projects"
        if kind == "config" or suffix in {".cfg", ".ini", ".gcode"}:
            return "printer-klipper-ops"
    except Exception:
        return ""
    return ""


def is_ai_ui_human_qa_route_question(messages):
    query = latest_user_text(messages).lower()
    if not query:
        return False
    if text_has_any(
        query,
        (
            "ai ui",
            "ai-ui",
            "ai intent",
            "500-question audit",
            "500 question audit",
            "codex cli ui",
        ),
    ):
        return True
    if text_has_any(query, ("human qa", "human-qa", "human review", "qa review")) and text_has_any(
        query,
        (
            "production",
            "release-readiness",
            "accessibility",
            "assistive-tech",
            "evidence",
            "rehearsal",
            "worksheet",
            "lane",
            "review status",
            "ready for pass",
            "record command",
            "q321",
            "q500",
            "500",
        ),
    ):
        return True
    if re.search(r"\bq\d{1,3}\b", query) and text_has_any(
        query,
        (
            "evidence file",
            "evidence receipt",
            "evidence template",
            "record production",
            "record accessibility",
            "human qa",
            "human-qa",
        ),
    ):
        return True
    return False


