def is_local_context_that_looks_like_web_request(messages):
    """Filter local app/file follow-ups that contain words like current/source/website."""
    query = latest_user_text(messages).lower()
    if not query:
        return False
    if (
        is_cad_v5_folder_organization_request(messages)
        or is_arc_support_coverage_threshold_question(messages)
        or is_tinmanx_filament_dropdown_selection_ui_question(messages)
        or is_prusa_ui_codex_filament_import_request(messages)
        or is_tinmanx_worldclass_slicer_question(messages)
        or is_printer_inventory_ip_update_request(messages)
        or is_printer_inventory_ip_update_missing_context_request(messages)
        or is_printer_inventory_ip_list_request(messages)
        or is_bluetooth_rename_question(messages)
    ):
        return True
    if "current work" in query and "turbine" in query and text_has_any(query, ("will this help", "does this help", "help you")):
        return True
    if text_has_any(query, ("current orca prepare tab", "orca prepare tab", "rocket slicer prepare area", "reskinned version")):
        return True
    if "current folder" in query and text_has_any(query, ("folder", "files", "step files", "cad")):
        return True
    if "current load" in query and text_has_any(query, ("support", "supports", "threshold angle", "overhang")):
        return True
    return False


