def product_shopping_search_core(query):
    raw = re.sub(r"\ba(?=[A-Z][A-Za-z0-9])", "", str(query or ""))
    words = [
        word
        for word in re_words(raw.lower())
        if word not in STOP_WORDS and word not in PRODUCT_SHOPPING_FILLER_WORDS
    ]
    return " ".join(words[:10]).strip()


def is_current_product_shopping_request(messages):
    query = latest_user_text(messages).lower().strip()
    if not query:
        return False
    local_surface_terms = (
        "dashboard",
        "model health",
        "run log",
        "window",
        "panel",
        "percent complete",
        "time remaining",
    )
    if text_has_any(query, local_surface_terms) and not text_has_any(query, ("buy", "for sale", "in stock", "price")):
        return False
    explicit_sourcing = (
        re.search(r"\b(?:find|locate|source|get|buy|purchase)\b.{0,120}\b(?:for sale|in stock|available|availability|seller|vendor|price|shipping)\b", query)
        or re.search(r"\b(?:where\s+(?:can|do)\s+i\s+(?:buy|get|find)|where\s+to\s+buy)\b", query)
        or text_has_any(query, ("for sale", "in stock", "current price", "current availability", "seller link", "vendor link"))
    )
    product_signal = bool(product_shopping_search_core(latest_user_text(messages)))
    return bool(explicit_sourcing and product_signal)


