    query = latest_user_text(messages).lower()
    return text_has_any(
        query,
        (
            "one short sentence",
            "in one sentence",
            "single sentence",
            "just answer",
            "answer only",
            "no explanation",
            "short answer",
            "terse",
        ),
    )


