def prior_cad_deliverable_paths(messages):
    paths = []
    seen = set()
    for message in messages[:-1]:
        if message.get("role") != "assistant":
            continue
        for item in extract_response_deliverables(message.get("text") or ""):
            path = str(item.get("path") or "")
            suffix = Path(path).suffix.lower()
            if suffix in {".step", ".stp", ".f3d", ".f3z", ".py"} and path not in seen:
                seen.add(path)
                paths.append(path)
    return paths


