def _scan_local_klipper_feature_evidence():
    roots = [
        Path.home() / "Applications" / "Flightops_Tracker",
        Path.home() / "Downloads" / "ratrig_config",
        Path.home() / "printer_data" / "config",
        APP_DIR / "data" / "source-vault" / "3d-printing",
    ]
    patterns = ("*.cfg", "*.conf", "*.ini", "*.md", "*.txt")
    beacon_hits = []
    adaptive_hits = []
    scanned = 0
    max_files = 160
    max_hits = 4
    for root in roots:
        if not root.exists():
            continue
        candidates = []
        if root.is_file():
            candidates = [root]
        else:
            for pattern in patterns:
                candidates.extend(root.rglob(pattern))
        for path in candidates:
            if scanned >= max_files:
                break
            try:
                if not path.is_file() or path.stat().st_size > 2_000_000:
                    continue
                text = path.read_text(errors="ignore")
            except Exception:
                continue
            scanned += 1
            lower = text.lower()
            rel = str(path)
            if len(rel) > 110:
                rel = "..." + rel[-107:]
            if (
                ("[beacon" in lower or "beacon_contact" in lower or "beacon contact" in lower)
                and ("contact" in lower or "z_offset" in lower or "z offset" in lower or "probe" in lower)
                and len(beacon_hits) < max_hits
            ):
                beacon_hits.append(rel)
            if (
                ("adaptive=1" in lower or "adaptive bed mesh" in lower or "adaptive mesh" in lower or "kamp" in lower)
                and ("bed_mesh_calibrate" in lower or "bed mesh" in lower or "print_start" in lower)
                and len(adaptive_hits) < max_hits
            ):
                adaptive_hits.append(rel)
        if scanned >= max_files:
            break
    return {"scanned": scanned, "beacon": beacon_hits, "adaptive": adaptive_hits}


def beacon_contact_adaptive_mesh_status_direct_answer(messages):
    if not is_beacon_contact_adaptive_mesh_status_question(messages):
        return ""
    evidence = _scan_local_klipper_feature_evidence()
    beacon_hits = evidence.get("beacon") or []
    adaptive_hits = evidence.get("adaptive") or []
    if beacon_hits and adaptive_hits:
        lead = "I found local config evidence for both Beacon Contact and adaptive bed mesh, but I would call it config-evidenced, not live-confirmed yet."
    elif beacon_hits:
        lead = "I found local config evidence for Beacon Contact, but I did not find matching adaptive bed-mesh/KAMP evidence in the scanned local config copies."
    elif adaptive_hits:
        lead = "I found local config evidence for adaptive bed mesh, but I did not find matching Beacon Contact evidence in the scanned local config copies."
    else:
        lead = "I cannot honestly confirm that Beacon Contact and adaptive bed mesh are set up yet from the local evidence I can scan right now."

    checked = f"Checked: {evidence.get('scanned', 0)} local Klipper/config/reference files."
    beacon_line = "Beacon Contact evidence: " + (", ".join(beacon_hits[:3]) if beacon_hits else "not found in the bounded local scan.")
    adaptive_line = "Adaptive mesh evidence: " + (", ".join(adaptive_hits[:3]) if adaptive_hits else "not found in the bounded local scan.")
    return "\n\n".join(
        [
            lead,
            checked,
            beacon_line,
            adaptive_line,
            (
                "This is why: `set up` has to mean two things: the active Klipper config contains the Beacon/contact probing path, and the active `PRINT_START` or mesh macro actually runs adaptive mesh or KAMP with print bounds. "
                "A cached file, old backup, or hardware name alone is not enough proof."
            ),
            (
                "You should also consider: the next safe step is read-only live verification on the target printer: query Moonraker/Klipper for loaded config objects and loaded macros, then check `klippy.log` for the last `PRINT_START`, `BEACON`/contact probe, and `BED_MESH_CALIBRATE` or KAMP call. "
                "Do not run homing, probing, or bed mesh until the printer is idle and the endpoint is confirmed."
            ),
        ]
    )


