def cad_model_source_search_direct_answer(messages):
    if not is_cad_model_source_search_question(messages):
        return ""
    if is_external_cad_source_retrieval_question(messages):
        return ""
    query = latest_user_text(messages).lower()
    keywords = [word for word in re.findall(r"[a-z0-9]+", query) if word not in {"can", "you", "find", "cad", "model", "file", "for", "an", "a", "the"}]
    compact_m5_elbow = is_compact_m5_barbed_elbow_cad_search(messages)
    preferred_keywords = (
        ["m5", "barbed", "fitting"]
        if compact_m5_elbow
        else [word for word in keywords if word in {"m18", "helicoil", "staking", "tool"}] or keywords[:4]
    )
    roots = (
        [APP_DIR / "data" / "source-vault", APP_DIR / "data" / "uploads", Path.home() / "Downloads"]
        if compact_m5_elbow
        else [Path.home() / "Documents" / "Codex", APP_DIR]
    )
    suffix_rank = {".step": 0, ".stp": 1, ".f3d": 2, ".f3z": 3, ".stl": 4, ".zip": 5}
    candidates = []
    scanned = []
    inaccessible = []
    quick_roots = []
    if {"m18", "helicoil", "staking", "tool"}.issubset(set(preferred_keywords)):
        quick_roots.append(Path.home() / "Documents" / "Codex" / "2026-07-10" / "wh" / "outputs")
    for quick_root in quick_roots:
        if not quick_root.exists():
            continue
        scanned.append(str(quick_root))
        try:
            quick_entries = list(quick_root.iterdir())
        except OSError as exc:
            inaccessible.append(f"{quick_root} ({getattr(exc, 'strerror', None) or exc})")
            continue
        for path in quick_entries:
            name = path.name.lower()
            if path.suffix.lower() in suffix_rank and all(word in name for word in preferred_keywords):
                candidates.append(path)
    for root in roots:
        if candidates:
            break
        if not root.exists():
            continue
        scanned.append(str(root))
        if preferred_keywords:
            pattern = "*" + "*".join(preferred_keywords) + "*"
            try:
                output = run_capture(
                    [
                        "/usr/bin/find",
                        str(root),
                        "(",
                        "-name",
                        ".git",
                        "-o",
                        "-name",
                        "node_modules",
                        "-o",
                        "-name",
                        "__pycache__",
                        "-o",
                        "-name",
                        "local_checkpoints",
                        "-o",
                        "-name",
                        "work_checkpoints",
                        "-o",
                        "-name",
                        "golden_batch_results",
                        ")",
                        "-prune",
                        "-o",
                        "-iname",
                        pattern,
                        "-print",
                    ],
                    timeout=3,
                )
            except OSError as exc:
                inaccessible.append(f"{root} ({getattr(exc, 'strerror', None) or exc})")
                output = ""
            for line in output.splitlines():
                path = Path(line.strip())
                if path.suffix.lower() in suffix_rank:
                    candidates.append(path)
            if candidates:
                continue
            if compact_m5_elbow:
                continue
        checked = 0
        def note_walk_error(exc):
            inaccessible.append(f"{getattr(exc, 'filename', root)} ({getattr(exc, 'strerror', None) or exc})")

        for dirpath, dirnames, filenames in os.walk(root, onerror=note_walk_error):
            dirnames[:] = [
                name
                for name in dirnames
                if name not in {".git", "node_modules", "__pycache__", "local_checkpoints", "work_checkpoints", "golden_batch_results"}
            ]
            checked += len(filenames)
            if checked > 35000:
                break
            for filename in filenames:
                path = Path(dirpath) / filename
                name = filename.lower()
                if path.suffix.lower() not in suffix_rank:
                    continue
                if all(word in name for word in preferred_keywords):
                    candidates.append(path)
    candidates = sorted(
        set(candidates),
        key=lambda item: (0 if "assembly" in item.name.lower() else 1, suffix_rank.get(item.suffix.lower(), 99), len(str(item)), str(item)),
    )[:3]
    if candidates:
        best = candidates[0]
        more = f" Other candidates: {', '.join(str(item) for item in candidates[1:])}." if len(candidates) > 1 else ""
        if compact_m5_elbow:
            first = f"Yes. Best local CAD candidate I found for a compact M5 45-degree or 90-degree barbed/push fitting: {best}.{more}"
        else:
            first = f"Yes. Best local CAD candidate I found: {best}.{more}"
    else:
        if compact_m5_elbow:
            first = (
                "I did not find a local CAD candidate for a compact M5 45-degree or 90-degree barbed fitting; "
                f"a push-to-connect style is still the fallback. I scanned {', '.join(scanned) or 'the configured local roots'}."
            )
        else:
            if inaccessible:
                first = (
                    f"I did not find a local CAD candidate matching {' '.join(preferred_keywords) or 'the requested model'} because part of the local source search was blocked. "
                    f"Readable roots checked: {', '.join(scanned) or 'the configured local roots'}. Search blocker: {', '.join(inaccessible[:3])}."
                )
            else:
                first = f"I did not find a local CAD candidate matching {' '.join(preferred_keywords) or 'the requested model'} in {', '.join(scanned) or 'the configured local roots'}."
    return "\n\n".join(
        [
            first,
            (
                "This is why: this is a CAD source search, not a request to generate new geometry. A found STEP/F3D/F3Z/STL path or source URL is useful; an unrelated generated Fusion/OpenSCAD package would be the wrong response. For this fitting, the M5 thread, 45/90-degree elbow shape, and barbed-or-push connection style are the fit criteria."
            ),
            (
                "You should also consider: the verification boundary is dimensions, source, license, and fit; treat any local model as a candidate until those are checked. If no local model is found, the next step is a web/source search or a fallback parametric model clearly labeled as generated."
            ),
        ]
    )


