def collect_storage_audit_snapshot():
    stamp = time.strftime("%Y%m%d-%H%M%S")
    target = LOCAL_STORAGE_OUTPUT_DIR / f"{stamp}-mac-storage-snapshot"
    target.mkdir(parents=True, exist_ok=True)
    candidates = [
        ("Codex generated outputs", DATA_DIR / "generated"),
        ("Codex uploads", DATA_DIR / "uploads"),
        ("Codex source vault", SOURCE_VAULT_DIR),
        ("Golden batch results", DATA_DIR / "golden_batch_results"),
        ("Ollama models", Path.home() / ".ollama" / "models"),
        ("Downloads", Path.home() / "Downloads"),
        ("User caches", Path.home() / "Library" / "Caches"),
        ("OrcaSlicer-Codex app support", Path.home() / "Library" / "Application Support" / "OrcaSlicer-Codex"),
        ("Colima data", Path.home() / ".colima"),
    ]
    rows = []
    for label, path in candidates:
        path = Path(path).expanduser()
        if not path.exists():
            continue
        rows.append(
            {
                "label": label,
                "path": str(path),
                "kib": None,
                "size": "deeper scan needed",
            }
        )
    tmutil_snapshots = run_capture(["tmutil", "listlocalsnapshots", "/"], timeout=1)
    receipt = {
        "createdAt": time.strftime("%Y-%m-%dT%H:%M:%S%z"),
        "rows": rows,
        "tmutilLocalSnapshots": tmutil_snapshots,
    }
    json_path = target / "storage-snapshot.json"
    md_path = target / "STORAGE_SNAPSHOT.md"
    write_json_atomic(json_path, receipt)
    table = ["| Candidate | Size | Path |", "| --- | ---: | --- |"]
    for item in rows:
        table.append(f"| {item['label']} | {item['size']} | `{item['path']}` |")
    if not rows:
        table.append("| none measured | n/a | n/a |")
    md_path.write_text(
        "\n".join(
            [
                "# Mac Storage Snapshot",
                "",
                f"Created: {receipt['createdAt']}",
                "",
                "## Checked Candidates",
                "",
                *table,
                "",
                "## Time Machine Local Snapshots",
                "",
                "```text",
                tmutil_snapshots or "(none reported or not available)",
                "```",
                "",
            ]
        ),
        encoding="utf-8",
    )
    summary_items = [item["label"] for item in rows[:5]]
    return {
        "target": str(target),
        "markdown": str(md_path),
        "json": str(json_path),
        "summary": "; ".join(summary_items) if summary_items else "no large candidates measured",
    }


def mac_system_data_storage_direct_answer(messages):
    if not is_mac_system_data_storage_question(messages):
        return ""
    snapshot = collect_storage_audit_snapshot()
    free_text = "unknown free space"
    try:
        stat = os.statvfs(str(Path.home()))
        free_gb = stat.f_bavail * stat.f_frsize / (1024**3)
        free_text = f"about {free_gb:.1f} GiB free"
    except Exception:
        pass
    return "\n\n".join(
        [
            (
                f"I took a safe local storage snapshot. This Mac currently shows {free_text} on the home volume, and the receipt is here: {snapshot['markdown']}"
            ),
            (
                "This is why: macOS groups many unrelated things into `System Data`, so the label itself is not a source. The real breakdown comes from checking Time Machine local snapshots, `/var/folders`, `~/Library/Caches`, `~/Library/Application Support`, Docker/Colima data, Ollama models, Codex generated outputs, and old downloads/images."
            ),
            f"Top local candidates checked: {snapshot['summary']}",
            (
                "You should also consider: do not delete blind. The safe cleanup order is snapshots first, obvious generated/test outputs second, caches third, and only then large app/tool folders after confirming they can be rebuilt."
            ),
        ]
    )


