def is_ebb42_gen2_thermistor_support_question(messages):
    query = latest_user_text(messages).lower()
    if not query:
        return False
    return (
        text_has_any(query, ("ebb 42 gen 2", "ebb42 gen 2", "ebb42_gen2", "ebb 42gen2"))
        and text_has_any(query, ("thermister", "thermistor", "thermistors", "thermisters", "temperature sensor"))
        and text_has_any(query, ("support", "supported", "what"))
    )


