def stage_start_print_macro_artifact(messages):
    target = LOCAL_TOOL_OUTPUT_DIR / f"{time.strftime('%Y%m%d-%H%M%S')}-start-print-heat-soak-adaptive-mesh"
    target.mkdir(parents=True, exist_ok=True)
    macro_path = target / "START_PRINT_HEAT_SOAK_ADAPTIVE_MESH.cfg"
    readme_path = target / "README.md"
    macro_text = """# START_PRINT heat-soak/adaptive-mesh candidate.
# Review printer-specific chamber sensor and Beacon/contact-home commands before uploading.

[gcode_macro START_PRINT_HEAT_SOAK_ADAPTIVE_MESH]
description: Heat bed first, heat chamber/nozzle together, soak 15 min, then home Z/contact and run adaptive bed mesh.
gcode:
  {% set BED = params.BED|default(params.BED_TEMP|default(60))|float %}
  {% set HOTEND = params.HOTEND|default(params.NOZZLE|default(params.EXTRUDER_TEMP|default(200)))|float %}
  {% set CHAMBER = params.CHAMBER|default(params.CHAMBER_TEMP|default(0))|float %}
  {% set SOAK_MIN = params.SOAK_MIN|default(15)|float %}

  M117 Heating bed to {BED} C
  M140 S{BED}
  M190 S{BED}

  M117 Heating chamber and nozzle
  {% if CHAMBER > 0 %}
    M141 S{CHAMBER}
  {% endif %}
  M104 S{HOTEND}
  {% if CHAMBER > 0 %}
    # Replace chamber with the real chamber temperature sensor name if different.
    TEMPERATURE_WAIT SENSOR=\"temperature_sensor chamber\" MINIMUM={CHAMBER - 1}
  {% endif %}
  M109 S{HOTEND}

  M117 Heat soaking {SOAK_MIN} min
  G4 P{(SOAK_MIN * 60000)|int}

  M117 Homing and probing
  G28 X Y
  # If Beacon/contact Z home uses a printer-specific macro, replace G28 Z with that macro.
  G28 Z
  BED_MESH_CLEAR
  BED_MESH_CALIBRATE ADAPTIVE=1

  M117 Start-print prep complete
"""
    macro_path.write_text(macro_text, encoding="utf-8")
    readme_path.write_text(
        "\n".join(
            [
                "# START_PRINT Heat Soak Adaptive Mesh Candidate",
                "",
                "This is a staged Klipper macro candidate. It was not uploaded to a live printer.",
                "",
                "Review before live use:",
                "- Confirm the chamber heater command and chamber temperature sensor name.",
                "- Confirm whether the printer uses Beacon/contact Z home through plain `G28 Z` or a custom macro.",
                "- Confirm the adaptive mesh command syntax supported by the installed Klipper/KAMP stack.",
                "- Backup the active printer config before adding an include.",
                "",
                f"Macro file: {macro_path}",
            ]
        )
        + "\n",
        encoding="utf-8",
    )
    return {"targetDir": str(target), "macroPath": str(macro_path), "readmePath": str(readme_path)}


