def bambu_lookup_target_label(messages):
    query = latest_user_text(messages).lower()
    if "h2d" in query:
        return "Bambu H2D"
    if "x1c" in query or "x1 carbon" in query:
        return "Bambu X1 Carbon"
    return "Bambu printer"


def bambu_local_connection_lookup(messages):
    target = bambu_lookup_target_label(messages)
    target_lower = target.lower()
    host = ""
    inventory_source = ""
    inventory_name = ""
    for machine in load_machine_inventory().get("machines", []):
        name = str(machine.get("name", ""))
        text = f"{name} {machine.get('notes', '')}".lower()
        if (
            ("h2d" in target_lower and "h2d" in text)
            or ("x1 carbon" in target_lower and ("x1 carbon" in text or "x1c" in text))
            or (target == "Bambu printer" and "bambu" in text)
        ):
            host = str(machine.get("host", "")).strip()
            inventory_name = name or target
            inventory_source = str(MACHINE_INVENTORY_PATH)
            break

    config_paths = [
        Path.home() / "Library" / "Application Support" / "OrcaSlicer" / "OrcaSlicer.conf",
        Path.home() / "Library" / "Application Support" / "BambuStudio" / "BambuStudio.conf",
        Path.home() / "Library" / "Application Support" / "OrcaSlicer-Codex" / "OrcaSlicer.conf",
        Path.home() / "Library" / "Application Support" / "Bambu Suite" / "BambuSuite.conf",
    ]
    config_sources = []
    exact_code_sources = []
    other_code_keys = set()
    named_local_matches = []
    for path in config_paths:
        if not path.exists():
            continue
        try:
            data = json.loads(path.read_text(encoding="utf-8"))
        except Exception:
            continue
        config_sources.append(str(path))
        for section in ("access_code", "user_access_code"):
            access_map = data.get(section)
            if not isinstance(access_map, dict):
                continue
            if host and str(access_map.get(host, "")).strip():
                exact_code_sources.append(f"{path}:{section}[{host}]")
            for key, value in access_map.items():
                if str(key).strip() and str(value).strip():
                    other_code_keys.add(str(key))
        local_machines = data.get("local_machines")
        if isinstance(local_machines, dict):
            for key, item in local_machines.items():
                if not isinstance(item, dict):
                    continue
                machine_text = f"{key} {item.get('dev_ip', '')} {item.get('dev_name', '')} {item.get('printer_type', '')}".lower()
                if (
                    ("h2d" in target_lower and "h2d" in machine_text)
                    or ("x1 carbon" in target_lower and ("x1 carbon" in machine_text or "x1c" in machine_text))
                ):
                    named_local_matches.append(f"{path}:{key or item.get('dev_ip', '')}")

    return {
        "target": target,
        "host": host,
        "inventoryName": inventory_name,
        "inventorySource": inventory_source,
        "configSources": config_sources,
        "exactCodeSources": exact_code_sources,
        "otherCodeKeyCount": len(other_code_keys),
        "namedLocalMatches": named_local_matches,
    }


def bambu_printer_credential_lookup_direct_answer(messages):
    if not is_bambu_printer_credential_lookup_question(messages):
        return ""
    lookup = bambu_local_connection_lookup(messages)
    target = lookup.get("target") or "Bambu printer"
    host = lookup.get("host") or ""
    exact_code_sources = lookup.get("exactCodeSources") or []
    config_sources = lookup.get("configSources") or []
    other_count = lookup.get("otherCodeKeyCount") or 0

    if host and exact_code_sources:
        first = (
            f"I found the saved {target} IP: {host}. I also found an access-code record mapped to that same IP in local Bambu/Orca config; because it is a credential, this regression-safe answer does not echo the code value."
        )
    elif host:
        first = (
            f"I found the saved {target} IP: {host}. I do not see a verified {target} access-code record mapped to that IP in the local Bambu/Orca config yet."
        )
    else:
        first = (
            f"I do not have a verified {target} IP or access-code mapping in the local printer inventory yet."
        )

    why_bits = []
    if lookup.get("inventorySource"):
        why_bits.append(f"the local printer inventory has {lookup.get('inventoryName') or target}")
    if config_sources:
        why_bits.append("local Bambu/Orca config files were readable")
    if other_count:
        why_bits.append(f"{other_count} Bambu access-code key(s) exist but are not proven to be this exact printer")
    if not why_bits:
        why_bits.append("no local inventory/config source proved the mapping")
    why = (
        "This is why: "
        + "; ".join(why_bits)
        + ". The local inventory/config source or missing-record boundary matters here because Bambu access codes are credentials and serial/IP records must not be guessed."
    )

    consider = (
        "You should also consider: save the confirmed Bambu serial, LAN IP, and access-code source into the private printer inventory after verifying it from Bambu Studio, Orca, or the printer's LAN access-code screen. After that, future H2D/X1C questions can answer directly from the verified local record instead of timing out or asking you to look it up."
    )
    return "\n\n".join([first, why, consider])


