def current_public_ip_short(timeout=1.5):
    for url in ("https://api.ipify.org", "https://ifconfig.me/ip"):
        try:
            with urllib.request.urlopen(url, timeout=timeout) as response:
                value = response.read(80).decode("utf-8", errors="replace").strip()
            if re.fullmatch(r"\d{1,3}(?:\.\d{1,3}){3}", value) or ":" in value:
                return value
        except Exception:
            continue
    return ""


