def is_ptfe_tube_od_question(messages):
    query = latest_user_text(messages).lower()
    if not query:
        return False
    return (
        text_has_any(query, ("ptfe", "bowden tube", "bowden tubing"))
        and text_has_any(query, ("outer diameter", "outside diameter", "od", "o.d."))
        and "1.75" in query
        and text_has_any(query, ("filament", "printer"))
    )


