def mac_bluetooth_snapshot():
    text = run_capture(["system_profiler", "SPBluetoothDataType"], timeout=8)
    devices = []
    current_status = ""
    current = None
    controller_state = ""
    for raw_line in str(text or "").splitlines():
        if not raw_line.strip():
            continue
        indent = len(raw_line) - len(raw_line.lstrip(" "))
        stripped = raw_line.strip()
        if stripped.startswith("State:") and not current:
            controller_state = stripped.split(":", 1)[1].strip()
        if stripped.endswith(":"):
            label = stripped[:-1].strip()
            if indent <= 6 and label.lower() not in {"bluetooth", "bluetooth controller"}:
                current_status = label
                current = None
                continue
            if indent >= 10 and current_status and current_status.lower() not in {"bluetooth controller"}:
                current = {"name": label, "status": current_status, "address": "", "minorType": ""}
                devices.append(current)
                continue
        if current and ":" in stripped:
            key, value = [part.strip() for part in stripped.split(":", 1)]
            if key == "Address":
                current["address"] = value
            elif key == "Minor Type":
                current["minorType"] = value
            elif key == "RSSI":
                current["rssi"] = value
            elif key == "Firmware Version":
                current["firmwareVersion"] = value
            elif key == "Vendor ID":
                current["vendorId"] = value
            elif key == "Product ID":
                current["productId"] = value
    return {
        "ok": bool(text and "Bluetooth" in text),
        "controllerState": controller_state,
        "blueutilPath": command_path("blueutil") or "",
        "devices": devices,
        "rawSummary": compact(text, 1200),
    }


def bluetooth_requested_new_name(query):
    text = str(query or "").strip()
    if not text:
        return ""
    cutoff = len(text)
    for marker in (" Edit question", "\nEdit question", " CODEX", "\nCODEX", " Codex", "\nCodex"):
        idx = text.find(marker)
        if idx > 0:
            cutoff = min(cutoff, idx)
    request_text = text[:cutoff].strip()
    parts = re.split(r"\bto\b", request_text, flags=re.IGNORECASE)
    if len(parts) < 2:
        return ""
    name = parts[-1]
    name = name.strip().strip("`'\"?.!")
    name = re.sub(r"\s+", " ", name)
    return name[:80]


def find_bluetooth_target_device(snapshot, query):
    devices = snapshot.get("devices") or []
    lower = str(query or "").lower()
    target_terms = []
    for term in ("bose", "airpods", "headset", "headphones", "speaker"):
        if term in lower:
            target_terms.append(term)
    if not target_terms and any("bose" in str(device.get("name", "")).lower() for device in devices):
        target_terms = ["bose"]
    scored = []
    for device in devices:
        haystack = " ".join(str(device.get(key, "")) for key in ("name", "minorType", "address")).lower()
        score = sum(1 for term in target_terms if term in haystack)
        if str(device.get("status", "")).lower() == "connected":
            score += 2
        if score:
            scored.append((score, device))
    if scored:
        scored.sort(key=lambda item: item[0], reverse=True)
        return scored[0][1]
    return devices[0] if len(devices) == 1 else None


def is_bluetooth_rename_question(messages):
    query = latest_user_text(messages).lower()
    if not query:
        return False
    return (
        wants_mac_bluetooth_context(messages)
        and text_has_any(query, ("rename", "change the name", "change name", "name my"))
        and text_has_any(query, ("bluetooth", "bose", "headset", "headphones", "airpods", "speaker"))
    )


def mac_bluetooth_rename_direct_answer(messages):
    if not is_bluetooth_rename_question(messages):
        return ""
    query = latest_user_text(messages)
    requested_name = bluetooth_requested_new_name(query) or "the requested name"
    snapshot = mac_bluetooth_snapshot()
    target = find_bluetooth_target_device(snapshot, query)
    if not snapshot.get("ok"):
        return "\n\n".join(
            [
                "I could not rename the Bluetooth device because this Mac did not return readable Bluetooth state from `system_profiler`.",
                "This is why: a Bluetooth rename needs the target device to be identified first. Without a readable local Bluetooth device list, changing anything would be guesswork.",
                "You should also consider: use System Settings > Bluetooth, connect the headset, then rename it from the device info/details panel if macOS exposes the Name field.",
            ]
        )
    if not target:
        device_names = ", ".join(device.get("name", "") for device in snapshot.get("devices", [])[:6] if device.get("name"))
        return "\n\n".join(
            [
                f"I did not rename anything because I could not confidently identify the Bose headset in the local Bluetooth list. The requested name was `{requested_name}`.",
                (
                    "This is why: I checked this Mac's Bluetooth state, but the visible devices did not give me one clear target. "
                    f"Devices seen: {device_names or 'none listed'}."
                ),
                f"You should also consider: connect the headset first, then use System Settings > Bluetooth > the info/details button for the Bose device > Name, and set it to `{requested_name}` if macOS exposes the field. Once it is visible as the clear Bose target, I can report the exact device state and safe rename path.",
            ]
        )
    name = target.get("name") or "unknown Bluetooth device"
    address = target.get("address") or "unknown address"
    status = target.get("status") or "unknown status"
    blueutil_path = snapshot.get("blueutilPath")
    blueutil_note = (
        f"`blueutil` is installed at `{blueutil_path}`, but it is for Bluetooth state/device operations and does not give this app a confirmed friendly-name rename path."
        if blueutil_path
        else "`blueutil` is not installed here, and the supported Apple Bluetooth framework headers I checked expose the device name as read-only, not a safe rename setter."
    )
    return "\n\n".join(
        [
            f"I did not rename it from the CLI. I checked this Mac and found `{name}` at `{address}`, currently shown as `{status}`. The requested name was `{requested_name}`.",
            (
                "This is why: macOS exposes local Bluetooth listing/connection state, but I did not find a supported command-line or public framework rename API for a third-party Bluetooth headset. "
                f"{blueutil_note} I also did not edit hidden Bluetooth plist files, because that can corrupt pairing state or get overwritten by `bluetoothd`."
            ),
            (
                f"You should also consider: the safe path is System Settings > Bluetooth > the info/details button for `{name}` > Name, then set it to `{requested_name}`. "
                "If the Name field is missing, connect the headset first or use the Bose app if the headset firmware controls the displayed name."
            ),
        ]
    )


