def power_source_text(source_id):
    item = (load_power_source_index().get("sources") or {}).get(source_id) or {}
    text_path = Path(item.get("textPath") or "")
    if text_path.exists():
        try:
            return text_path.read_text(encoding="utf-8", errors="replace")
        except OSError:
            return ""
    return ""


