def source_vault_cached_items(index, seeds, limit=6):
    seed_map = {item.get("id"): item for item in seeds}
    sources = index.get("sources", {}) if isinstance(index, dict) else {}
    items = []
    for source_id, cached in sources.items():
        if not isinstance(cached, dict) or not cached.get("ok"):
            continue
        local_path = cached.get("localPath")
        if not local_path or not Path(local_path).exists():
            continue
        seed = seed_map.get(source_id) or {}
        items.append(
            {
                "id": source_id,
                "label": cached.get("label") or seed.get("label") or source_id,
                "kind": cached.get("kind") or seed.get("kind") or "source",
                "localPath": local_path,
                "url": cached.get("url") or seed.get("url") or "",
            }
        )
    items.sort(key=lambda item: (item["kind"], item["label"].lower()))
    return items[:limit], len(items)


def is_local_evidence_retrieval_route_question(messages):
    latest = latest_user_text(messages).lower().strip()
    if not latest:
        return False
    if is_source_vault_inventory_question(messages):
        return True
    recent = "\n".join(str(message.get("text") or "") for message in (messages or [])[-6:]).lower()
    has_local_source_context = text_has_any(
        recent,
        (
            "source text used:",
            "via direct text read",
            "previously cited local source",
            "local evidence",
            "local manual",
            "manuals cached locally",
            " in this folder",
        ),
    )
    if not has_local_source_context:
        return False
    if text_has_any(
        latest,
        (
            "local manual",
            "local file",
            "local evidence",
            "that file",
            "that local file",
            "that manual",
            "that source",
            "you did not read the local file",
        ),
    ):
        return True
    return text_has_any(
        latest,
        ("what", "which", "where", "how many", "answer", "recommend", "recommended", "baud", "communication"),
    ) and text_has_any(recent, ("source text used:", "via direct text read", "found and read"))


def is_source_vault_inventory_question(messages):
    query = latest_user_text(messages).lower().strip()
    if not query:
        return False
    inventory_terms = (
        "source vault",
        "source-vault",
        "cached source",
        "cached sources",
        "cached manual",
        "cached manuals",
        "local manual",
        "local manuals",
        "known resources",
        "catalogue of known resources",
        "catalog of known resources",
        "resource catalogue",
        "resource catalog",
        "what resources",
        "what manuals",
        "what docs",
    )
    if not text_has_any(query, inventory_terms):
        return False
    return text_has_any(query, ("what", "which", "where", "list", "catalog", "catalogue", "inventory", "have", "available", "cached"))


def source_vault_inventory_direct_answer(messages):
    if not is_source_vault_inventory_question(messages):
        return ""
    printing_index = load_printing_source_index()
    power_index = load_power_source_index()
    printing_items, printing_cached_count = source_vault_cached_items(printing_index, PRINTING_SOURCE_SEEDS)
    power_items, power_cached_count = source_vault_cached_items(power_index, POWER_EQUIPMENT_SOURCE_SEEDS)

    def section(title, items, cached_count, seed_count, vault_path):
        lines = [f"{title}: {cached_count}/{seed_count} seeded sources cached at `{vault_path}`."]
        for item in items:
            lines.append(f"- {item['label']}: `{item['localPath']}`")
        if not items:
            lines.append("- No readable cached files found in this vault yet.")
        return "\n".join(lines)

    body = "\n\n".join(
        [
            section("3D printing and printer hardware", printing_items, printing_cached_count, len(PRINTING_SOURCE_SEEDS), PRINTING_SOURCE_VAULT_DIR),
            section("Power equipment", power_items, power_cached_count, len(POWER_EQUIPMENT_SOURCE_SEEDS), POWER_SOURCE_VAULT_DIR),
        ]
    )
    return "\n\n".join(
        [
            "Yes. I have a local source-vault catalogue, and I should check it before researching stable manuals or known hardware facts again.",
            body,
            "This is why: source-vault files are local evidence. For stable items like manuals, pinouts, calibration guides, and cached product docs, they are faster and less brittle than asking the model or doing a fresh web search every time.",
            "You should also consider: refresh the vault before relying on current prices, availability, firmware versions, shipping dates, or changed manuals. For live machine state, source-vault facts still need to be paired with the active printer/Moonraker/SSH evidence.",
        ]
    )


def printing_query_text(messages):
    return "\n".join(str(message.get("text", "")) for message in messages[-4:]).lower()


def matching_printer_profiles(text):
    matches = []
    for profile in PRINTING_PRINTER_PROFILES:
        if any(alias in text for alias in profile.get("aliases", [])):
            matches.append(profile)
    return matches


def printing_source_seed_map():
    return {str(item.get("id") or ""): item for item in PRINTING_SOURCE_SEEDS}


def is_printer_machine_spec_limit_question(messages):
    query = latest_user_text(messages).lower()
    if not query or not matching_printer_profiles(query):
        return False
    hardware_terms = (
        "nozzle",
        "hotend",
        "hot end",
        "bed",
        "chamber",
        "build volume",
        "speed",
        "acceleration",
        "flow",
        "temperature",
        "temp",
    )
    spec_terms = (
        "max",
        "maximum",
        "rated",
        "spec",
        "specs",
        "limit",
        "limits",
        "capability",
        "capabilities",
        "how hot",
        "how high",
    )
    live_terms = (
        "current",
        "right now",
        "live",
        "status",
        "what is it at",
        "what's it at",
        "actual temp",
        "actual temperature",
    )
    if text_has_any(query, live_terms) and not text_has_any(query, spec_terms):
        return False
    return text_has_any(query, hardware_terms) and text_has_any(query, spec_terms)


def printer_machine_spec_limit_direct_answer(messages):
    query = latest_user_text(messages).strip()
    text = query.lower()
    profiles = matching_printer_profiles(text)
    if not query or not profiles or not is_printer_machine_spec_limit_question(messages):
        return ""

    field_map = [
        (("nozzle", "hotend", "hot end"), "maxNozzleTemp", "max nozzle temperature"),
        (("bed",), "maxBedTemp", "max bed temperature"),
        (("chamber", "enclosure"), "maxChamberTemp", "max chamber temperature"),
        (("speed",), "maxSpeed", "max speed"),
        (("acceleration", "accel"), "maxAcceleration", "max acceleration"),
        (("flow", "volumetric"), "maxFlow", "max flow"),
        (("build volume", "build size", "print volume"), "buildVolume", "build volume"),
    ]
    requested = []
    for terms, key, label in field_map:
        if text_has_any(text, terms):
            requested.append((key, label))
    if not requested:
        requested = [("maxNozzleTemp", "max nozzle temperature")]

    source_map = printing_source_seed_map()
    profile_lines = []
    source_lines = []
    seen_sources = set()
    for profile in profiles[:3]:
        limits = profile.get("limits") or {}
        values = []
        for key, label in requested:
            value = limits.get(key)
            if value:
                values.append(f"{label}: {value}")
        if not values and len(requested) == 1:
            key, label = requested[0]
            values.append(f"{label}: not captured in the local printer profile")
        if values:
            profile_lines.append(f"{profile.get('name')}: " + "; ".join(values))
        for source_id in profile.get("sources") or []:
            if source_id in seen_sources:
                continue
            seen_sources.add(source_id)
            source = source_map.get(source_id) or {}
            label = source.get("label") or source_id
            url = source.get("url") or ""
            if url:
                source_lines.append(f"{label}: {url}")

    first_line = profile_lines[0] if profile_lines else "I do not have that machine limit captured locally yet."
    return "\n\n".join(
        [
            first_line,
            (
                "This is why: this is a printer specification question, not a live temperature/status question. "
                "I used the local 3D-printing machine profile catalogue instead of probing a live printer endpoint or another printer."
            ),
            (
                "You should also consider: keep slicer filament/process temperatures below the machine's rated hotend limit, and verify the exact installed hotend/nozzle module before pushing abrasive or high-temperature materials."
            ),
            "Sources: " + "; ".join(source_lines[:3]) if source_lines else "Sources: local printer profile catalogue.",
        ]
    )


def material_alias_present(text, alias):
    alias = str(alias or "").strip().lower()
    if not alias:
        return False
    return re.search(r"(?<![a-z0-9])" + re.escape(alias) + r"(?![a-z0-9])", str(text or "").lower()) is not None


def material_key_present(text, keys=None):
    wanted = set(keys or PRINTING_MATERIAL_LIBRARY.keys())
    for key, material in PRINTING_MATERIAL_LIBRARY.items():
        if key not in wanted:
            continue
        if any(material_alias_present(text, alias) for alias in material.get("aliases", [])):
            return True
    return False


def matching_materials(text):
    matches = []
    for key, material in PRINTING_MATERIAL_LIBRARY.items():
        if any(material_alias_present(text, alias) for alias in material.get("aliases", [])):
            matches.append((key, material))
    return matches


def matching_components(text):
    matches = []
    for key, component in PRINTING_COMPONENT_LIBRARY.items():
        if any(alias in text for alias in component.get("aliases", [])):
            matches.append((key, component))
    return matches


