def is_slicer_profile_update_request(messages):
    query = latest_user_text(messages).strip()
    text = query.lower()
    if not query:
        return False
    if is_codex_ui_workflow_scenario_request(messages):
        return False
    profile_pack_creation = (
        text_has_any(text, PROFILE_CREATION_TERMS)
        or text_has_any(text, ("full set", "starter profile pack", "profile pack", "custom filament profiles", "custom profiles"))
    )
    explicit_update = (
        text_has_any(text, ("update", "change", "fix", "enable", "turn on"))
        or "pressure advance" in text
        or re.search(r"\bpa\b", text)
    )
    explicit_set_or_add = bool(re.search(r"\b(set|add)\b", text))
    if profile_pack_creation and not explicit_update:
        return False
    if not text_has_any(text, ("profile", "profiles", "preset", "presets")):
        return False
    if not (explicit_update or explicit_set_or_add):
        return False
    material_or_pa = (
        text_has_any(text, ("fiberon", "pet-cf17", "pet-cf", "pressure advance", "filament"))
        or bool(re.search(r"\bpa\b", text))
    )
    return text_has_any(text, ("bambu", "x1c", "h2d", "qidi", "plus 4", "orca", "orcaslicer", "tinmanx", "tinmanx1")) and material_or_pa


def slicer_profile_update_direct_answer(messages):
    if not is_slicer_profile_update_request(messages):
        return ""
    query = latest_user_text(messages).lower()
    if "pressure advance" in query or re.search(r"\bpa\b", query):
        first = "Yes. Treat pressure advance as a slicer/profile change for that Bambu profile, not a live-printer firmware tweak."
        why = (
            "This is why: on the Bambu side, pressure advance belongs with the filament or process/profile data that gets baked into the sliced G-code. "
            "Changing it safely means editing the specific profile you are using, not globally guessing for every Bambu or every material."
        )
        consider = (
            "You should also consider: make a backup of the active profile store first, enable or set PA only on the target profile, record the changed key and value, run a PA calibration for that filament/nozzle/temp, then verify installed-app visibility and confirm a fresh slice carries the intended value."
        )
        return "\n\n".join([first, why, consider])
    return "\n\n".join(
        [
            "Yes. Treat this as a slicer profile edit with a backup and verification pass, not a profile-parameter dump.",
            (
                "This is why: this is a live catalog/profile update. Pull the material list and profile downloads from https://polymaker.com/download-material/ and https://fiberon.polymaker.com/, then map those values into the TinmanX filament preset layer."
            ),
            (
                "You should also consider: keep machine/process limits separate unless print evidence says otherwise. The receipt should include the backup path, changed keys, source URL for each material family, JSON/profile lint, installed-app visibility, and one small slice or print check."
            ),
        ]
    )


