def is_inverter_battery_communication_question(messages):
    query = latest_user_text(messages).strip()
    text = query.lower()
    if not query:
        return False
    if is_vevor_power_manual_followup(messages):
        return True
    squashed = re.sub(r"[^a-z0-9]+", "", text)
    has_specific_pair = "vs8048amn" in squashed and "lps48100" in squashed
    has_power_pair = (
        text_has_any(text, ("inverter", "hybrid inverter", "solar inverter", "inverter/charger", "charger"))
        and text_has_any(text, ("battery", "batteries", "bms", "lifepo4", "lithium"))
    )
    asks_communication = (
        text_has_any(
            text,
            (
                "communicate",
                "communication",
                "talk to",
                "talk with",
                "closed loop",
                "closed-loop",
                "bms",
                "can bus",
                "canbus",
                "rs485",
                "rs-485",
                "rj45",
                "protocol",
            ),
        )
        or (text.startswith("can ") and has_specific_pair)
    )
    return asks_communication and (has_specific_pair or has_power_pair)


def has_vevor_vs8048amn_lps48100_context(messages):
    squashed = re.sub(r"[^a-z0-9]+", "", recent_conversation_text(messages, limit=8).lower())
    return "vs8048amn" in squashed and "lps48100" in squashed


def is_vevor_power_manual_followup(messages):
    query = latest_user_text(messages).strip()
    text = query.lower()
    if not query:
        return False
    squashed = re.sub(r"[^a-z0-9]+", "", text)
    has_full_context = has_vevor_vs8048amn_lps48100_context(messages)
    has_lps48100_parallel_context = "lps48100" in squashed and text_has_any(
        text,
        (
            "parallel",
            "paralleled",
            "battery bank",
            "how many",
            "batteries",
            "all communicate",
            "can they all",
        ),
    )
    has_lps48100_baud_context = "lps48100" in squashed and text_has_any(text, ("baud", "baud rate", "9600"))
    if not (has_full_context or has_lps48100_parallel_context or has_lps48100_baud_context):
        return False
    followup_terms = (
        "baud",
        "baud rate",
        "pinout",
        "pin out",
        "rj45",
        "rs485",
        "rs-485",
        "can",
        "bms",
        "protocol",
        "communication",
        "communicate",
        "cable",
        "port",
        "setting",
        "settings",
        "parallel",
        "paralleled",
        "how many",
        "batteries",
        "battery bank",
        "all communicate",
        "can they all",
        "listed above",
        "components listed above",
        "these units",
        "these",
        "the units",
        "them",
    )
    return text_has_any(text, followup_terms) and is_direct_factual_question_without_artifact_action(text)


def is_vevor_vs8048amn_lps48100_question(messages):
    squashed = re.sub(r"[^a-z0-9]+", "", latest_user_text(messages).lower())
    return ("vs8048amn" in squashed and "lps48100" in squashed) or is_vevor_power_manual_followup(messages)


def power_text_has(text, *phrases):
    lower = str(text or "").lower()
    return all(phrase.lower() in lower for phrase in phrases)


def vevor_manual_research_pack(web_search="disabled", emit=None):
    if web_search == "live":
        if emit:
            emit("Checking Vevor support pages and caching the inverter/battery manuals locally.")
        refresh = refresh_power_source_vault(source_ids=vevor_power_manual_source_ids())
    else:
        refresh = {"ok": False, "results": [], "vaultPath": str(POWER_SOURCE_VAULT_DIR), "indexPath": str(POWER_SOURCE_INDEX_PATH)}
    inverter_text = power_source_text("vevor-vs8048amn-manual-pdf")
    battery_text = power_source_text("vevor-lps48100-manual-pdf")
    product_text = power_source_text("vevor-lps48100-product")
    parallel_match = re.search(r"parallel\s+up\s+to\s+(\d+)", product_text or "", re.IGNORECASE)
    stack_match = re.search(r"stack\s+up\s+to\s+(\d+)", product_text or "", re.IGNORECASE)
    battery_text_flat = re.sub(r"\s+", " ", battery_text or "")
    inv = {
        "hasManual": bool(inverter_text),
        "hasBmsRs485Port": power_text_has(inverter_text, "BMS/RS485 communication port"),
        "hasBmsFunctionSwitch": power_text_has(inverter_text, "BMS Function switch"),
        "hasLithiumProtocolSetting": power_text_has(inverter_text, "Lithium battery protocol type"),
        "hasBaudSetting": power_text_has(inverter_text, "Baud rate") and "9600" in inverter_text,
        "baudOptions": [value for value in ("2400", "4800", "9600") if value in inverter_text],
        "hasLfpBatteryType": "BAT-LiFePO4" in inverter_text or "Lithium lron Phosphate" in inverter_text,
    }
    bat = {
        "hasManual": bool(battery_text),
        "hasRj45MultiProtocol": power_text_has(battery_text, "RJ45 single network interface integrates RS485, UART, and CAN"),
        "hasDefaultBaud": power_text_has(battery_text, "default baud rate of 9600bps"),
        "defaultBaud": "9600 bps" if power_text_has(battery_text, "default baud rate of 9600bps") else "",
        "hasInverterProtocol": power_text_has(battery_text, "inverter protocol supports RS485 and CAN"),
        "hasParamsRs485Can": power_text_has(battery_text, "Communication Method with Inverter Connection", "RS485/CAN"),
        "productClaimsPorts": power_text_has(product_text, "RS485 & CAN Ports") or power_text_has(product_text, "RS485", "CAN"),
        "parallelMaxClaim": int(parallel_match.group(1)) if parallel_match else None,
        "stackMaxClaim": int(stack_match.group(1)) if stack_match else None,
        "hasParallelConnectionMethod": power_text_has(battery_text, "Parallel Connection Method"),
        "parallelCommunicationMethod": "RS485/CAN" if power_text_has(battery_text, "Parallel Communication Method", "RS485/CAN") else "",
        "hasParallelMasterInstruction": (
            "communication between the inverter and the battery should be set to master communication" in battery_text_flat.lower()
            and "do not select slave communication with the inverter" in battery_text_flat.lower()
        ),
    }
    cached = {}
    for source_id in vevor_power_manual_source_ids():
        item = power_cached_source(source_id)
        if item.get("ok"):
            cached[source_id] = item
    return {
        "refresh": refresh,
        "inverter": inv,
        "battery": bat,
        "cached": cached,
        "vaultPath": str(POWER_SOURCE_VAULT_DIR),
    }


def vevor_manual_paths_and_sources(pack, include_product=False):
    cached = pack.get("cached") or {}
    inverter_manual = cached.get("vevor-vs8048amn-manual-pdf", {})
    battery_manual = cached.get("vevor-lps48100-manual-pdf", {})
    product_page = cached.get("vevor-lps48100-product", {})
    source_urls = [
        inverter_manual.get("url") or power_seed_by_id()["vevor-vs8048amn-manual-pdf"]["url"],
        battery_manual.get("url") or power_seed_by_id()["vevor-lps48100-manual-pdf"]["url"],
    ]
    manual_paths = [
        inverter_manual.get("localPath"),
        battery_manual.get("localPath"),
    ]
    if include_product:
        source_urls.append(product_page.get("url") or power_seed_by_id()["vevor-lps48100-product"]["url"])
        manual_paths.append(product_page.get("localPath"))
    extras = []
    if any(manual_paths):
        extras.append("Manuals cached locally: " + "; ".join(path for path in manual_paths if path))
    if any(source_urls):
        extras.append("Sources: " + "; ".join(url for url in source_urls if url))
    return extras


def vevor_power_manual_followup_direct_answer(messages, pack):
    if not is_vevor_power_manual_followup(messages):
        return ""
    text = latest_user_text(messages).lower()
    inv = pack.get("inverter") or {}
    bat = pack.get("battery") or {}
    extras = vevor_manual_paths_and_sources(pack)
    asks_parallel = text_has_any(text, ("parallel", "paralleled", "battery bank", "all communicate", "can they all")) or (
        "how many" in text and "batter" in text
    )
    if asks_parallel:
        max_parallel = bat.get("parallelMaxClaim") or 16
        stack_max = bat.get("stackMaxClaim")
        parallel_method = bat.get("parallelCommunicationMethod") or "RS485/CAN"
        extras = vevor_manual_paths_and_sources(pack, include_product=True)
        stack_note = f" Vevor also says they can be stacked up to {stack_max} high, but stacking and electrical paralleling are different limits." if stack_max else ""
        pair_context = has_vevor_vs8048amn_lps48100_context(messages)
        recommendation = (
            f"My recommendation: treat {max_parallel} LPS48100 batteries as the Vevor-claimed maximum parallel bank size, then wire communication as a master battery/BMS path to the VS8048AMN."
            if pair_context
            else f"My recommendation: treat {max_parallel} LPS48100 batteries as the Vevor-claimed maximum parallel bank size. For inverter communication, use the battery bank's master BMS path only with an inverter whose RS485/CAN protocol/profile is confirmed to match."
        )
        inverter_note = (
            ""
            if pair_context
            else " If the inverter you mean is the Vevor VS8048AMN, the cached manual path points to the same RS485/BMS style setup, but the protocol/profile and RJ45 pinout still need verification."
        )
        return "\n\n".join(
            [
                recommendation,
                (
                    f"This is why: Vevor's LPS48100 product page says the battery can be paralleled up to {max_parallel}. "
                    f"The LPS48100 manual lists parallel communication as {parallel_method} and says inverter-to-battery communication should be set to master communication; do not select slave communication with the inverter.{stack_note}{inverter_note}"
                ),
                (
                    "You should also consider: this does not prove the inverter will see every battery as a separate device. In practice, one battery or master BMS should be the inverter-facing communicator, with the rest of the bank connected through the battery parallel communication scheme. Verify the supplied communication cables, battery address or DIP settings, RJ45 pinout, and that the inverter reports bank SOC/limits before putting the system under load."
                ),
                *extras,
            ]
        )
    if "baud" in text:
        inverter_options = ", ".join(inv.get("baudOptions") or ["2400", "4800", "9600"])
        return "\n\n".join(
            [
                "My recommendation: set the inverter communication baud rate to 9600 bps to match the LPS48100 battery.",
                (
                    f"This is why: the LPS48100 manual lists its RJ45/BMS communication default baud rate as 9600 bps. "
                    f"The VS8048AMN manual shows a baud-rate setting with options including {inverter_options}, so 9600 bps is the matching starting point for the two units."
                ),
                (
                    "You should also consider: baud rate only makes the serial link speed match. The RS485/BMS protocol/profile and RJ45 pinout still have to match before plugging in the cable."
                ),
                *extras,
            ]
        )
    if text_has_any(text, ("pinout", "pin out", "rj45", "cable")):
        return "\n\n".join(
            [
                "I do not have a confirmed RJ45 pinout from the cached Vevor manual text yet, so do not plug in a random Ethernet cable as the communication cable.",
                (
                    "This is why: the manuals confirm the VS8048AMN uses a BMS/RS485 port and the LPS48100 uses an RJ45 communication interface, but a connector shape is not the same thing as a safe pinout. "
                    "RS485/CAN battery cables often use RJ45 shells with manufacturer-specific pin assignments."
                ),
                (
                    "You should also consider: get the pinout table from the full manual page image, Vevor support, or a supplied cable label before connecting. After pinout is verified, set the baud to 9600 bps and match the protocol/profile."
                ),
                *extras,
            ]
        )
    if text_has_any(text, ("protocol", "setting", "settings", "bms", "rs485", "can")):
        return "\n\n".join(
            [
                "Yes, they appear capable of closed-loop battery communication, but treat it as an RS485/BMS or CAN protocol match that still needs the exact profile and RJ45 pinout verified.",
                (
                    "This is why: the VS8048AMN manual identifies a BMS/RS485 port plus BMS, lithium protocol, and baud settings. "
                    "The LPS48100 manual says its inverter communication supports RS485/CAN and protocol selection."
                ),
                (
                    "You should also consider: start with 9600 bps, verify RJ45 pinout, then look for the inverter showing battery SOC or communication success before trusting closed-loop charge limits."
                ),
                *extras,
            ]
        )
    return ""


def format_vevor_communication_manual_answer(pack, web_search="disabled"):
    inv = pack.get("inverter") or {}
    bat = pack.get("battery") or {}
    has_manual_evidence = inv.get("hasManual") and bat.get("hasManual")
    hardware_path = inv.get("hasBmsRs485Port") and (
        bat.get("hasRj45MultiProtocol") or bat.get("hasInverterProtocol") or bat.get("hasParamsRs485Can")
    )
    protocol_path = inv.get("hasBmsFunctionSwitch") and inv.get("hasLithiumProtocolSetting") and (
        bat.get("hasInverterProtocol") or bat.get("hasParamsRs485Can")
    )
    extras = vevor_manual_paths_and_sources(pack)

    if has_manual_evidence and hardware_path:
        verdict = (
            "Yes, they appear capable of battery communication, but I would treat it as RS485/BMS communication that still needs the exact protocol/profile and pinout confirmed before plugging in the cable."
        )
        how = (
            "How: use the VS8048AMN `BMS/RS485` port and the LPS48100 RJ45 communication port, then match the inverter lithium/BMS settings to the battery protocol. "
            "On the inverter side, enable the BMS function, choose the LiFePO4/LFP battery type, set the lithium battery protocol type, and match the baud setting. "
            "On the battery side, use the RJ45 interface that carries RS485/UART/CAN and select the matching inverter protocol if the battery/Bluetooth/upper-computer menu exposes that setting."
        )
        why = (
            "This is why: the VS8048AMN manual shows a BMS/RS485 communication port plus BMS, lithium protocol, and baud-rate settings. "
            "The LPS48100 manual says its RJ45 interface integrates RS485, UART, and CAN, and its inverter communication supports RS485/CAN with protocol selection."
        )
        caveat = (
            "You should also consider: do not use a random network cable until the RJ45 pinout is verified. "
            "The first proof of success should be the inverter showing battery SOC/limits or the communication-success indicator, then you confirm charge voltage/current and low-voltage behavior before putting real loads on it."
        )
    elif web_search == "live":
        verdict = "I found the Vevor manual path, but I do not have enough extracted manual evidence yet to call the VS8048AMN and LPS48100 a confirmed communication pair."
        how = (
            "How to proceed: use manual voltage-based lithium settings until the inverter protocol/profile and battery RJ45 pinout are confirmed by the manuals or Vevor support."
        )
        why = (
            "This is why: closed-loop battery communication is not proven by shared 48V voltage or by both devices mentioning RS485/CAN. The protocol, pinout, baud, and supported battery profile still have to match."
        )
        caveat = "You should also consider: re-run with Web on after the manuals are reachable, or attach the PDFs directly if Vevor changes the download URLs."
    else:
        verdict = "My recommendation with Web off: treat communication as possible but not confirmed until the manuals are downloaded and checked."
        how = (
            "How to verify: turn Web on so I can download the VS8048AMN and LPS48100 manuals, then check the inverter BMS/RS485 port, battery RJ45 RS485/CAN port, protocol setting, baud rate, and pinout."
        )
        why = (
            "This is why: inverter-to-battery communication is a protocol match, not just a voltage match. The manuals have to prove the shared communication path."
        )
        caveat = "You should also consider: without confirmed pinout/protocol, run manual voltage-based lithium settings and do not connect the communication cable."
    return "\n\n".join([verdict, how, why, caveat] + extras)


def inverter_battery_communication_direct_answer(messages, web_search="disabled", emit=None):
    if not is_inverter_battery_communication_question(messages):
        return ""
    if is_vevor_vs8048amn_lps48100_question(messages):
        pack = vevor_manual_research_pack(web_search=web_search, emit=emit)
        query = latest_user_text(messages).lower()
        squashed = re.sub(r"[^a-z0-9]+", "", query)
        if "vs8048amn" in squashed and "lps48100" in squashed and re.search(r"\bcan\b.*\bcommunicat", query):
            return format_vevor_communication_manual_answer(pack, web_search=web_search)
        followup = vevor_power_manual_followup_direct_answer(messages, pack)
        if followup:
            return followup
        return format_vevor_communication_manual_answer(pack, web_search=web_search)
    return "\n\n".join(
        [
            "My recommendation: do not assume the Vevor VS8048AMN has confirmed closed-loop communication with the Vevor LPS48100 until both manuals show the same BMS protocol and pinout.",
            (
                "This is why: a 48V inverter and a 48V lithium battery can be electrically compatible without being data-compatible. "
                "Closed-loop battery communication needs the inverter and battery to share the same CAN or RS485 protocol, connector pinout, baud/settings, and supported battery profile."
            ),
            (
                "You should also consider: if the manuals do not explicitly match, run it as a voltage-based/manual lithium setup instead: set charge voltage, float/rebulk behavior, low-voltage cutoff, max charge current, and discharge limits from the LPS48100 spec, with the correct fuse, disconnect, wire size, and grounding. "
                "Do not plug random RJ45/CAN/RS485 cables between them until the pinout is verified."
            ),
        ]
    )


