def qidi_box_rfid_macro_direct_answer(messages):
    if not is_qidi_box_rfid_macro_question(messages):
        return ""
    candidate_dirs = [
        Path.home() / "Documents/Codex/2026-05-22/on-the-qidi-i-am-attempting/qidi-backup-20260522_113829/config",
        Path.home() / "Documents/Codex/2026-06-25/r/maxez-monitor-20260707",
    ]
    saved_path = ""
    saved_value = ""
    reader_files = []
    for root in candidate_dirs:
        if not root.exists():
            continue
        for path in sorted(root.rglob("saved_variables.cfg"))[:20]:
            try:
                text = path.read_text(encoding="utf-8", errors="replace")
            except OSError:
                continue
            match = re.search(r"(?im)^\s*auto_read_rfid\s*=\s*([^\s#]+)", text)
            if match:
                saved_path = str(path)
                saved_value = match.group(1)
                break
        if saved_path:
            break
    for root in candidate_dirs[:1]:
        if not root.exists():
            continue
        for path in sorted(root.glob("box*.cfg")):
            try:
                text = path.read_text(encoding="utf-8", errors="replace")
            except OSError:
                continue
            count = len(re.findall(r"(?im)^\s*\[box_rfid\b", text))
            if count:
                reader_files.append((str(path), count))
    if saved_value == "1":
        lead = "The Qidi Box RFID receivers appear to be enabled in the saved variables."
        action = "Leave `auto_read_rfid = 1` in place unless you are intentionally disabling RFID reads."
    elif saved_value == "0":
        lead = "Yes. The box RFID readers exist in the macros/config, but RFID auto-read is currently turned off."
        action = "Set `auto_read_rfid = 1` in `saved_variables.cfg`, then restart/reload Klipper when the printer is safe and idle."
    else:
        lead = "The box RFID readers are defined, but I could not confirm the current `auto_read_rfid` saved-variable value from the local backup."
        action = "Check `saved_variables.cfg` for `auto_read_rfid`; `0` means off and `1` means enabled."
    reader_summary = ", ".join(f"`{path}` ({count} reader blocks)" for path, count in reader_files[:4]) or "I did not find box RFID reader blocks in the first local config backup."
    saved_summary = f"`{saved_path}` shows `auto_read_rfid = {saved_value}`." if saved_path else "No local `saved_variables.cfg` with `auto_read_rfid` was confirmed."
    return "\n\n".join(
        [
            lead,
            f"This is why: {saved_summary} The box config evidence is: {reader_summary}",
            f"You should also consider: {action} Do not edit the live printer or restart services until the machine is idle, and keep a backup of the current `saved_variables.cfg` first.",
        ]
    )


