def generated_artifact_deliverable_score(item, query):
    path = str(item.get("path") or "")
    suffix = Path(path).suffix.lower()
    label = str(item.get("label") or "").lower()
    value = 0
    if item.get("exists"):
        value += 20
    if text_has_any(query, ("source", "editable", "drawio", "draw.io", "open first", "which file", "use that one", "use this one")):
        if suffix in {".drawio", ".f3d", ".f3z"}:
            value += 90
        elif suffix in {".py", ".scad", ".step", ".stp"}:
            value += 60
        elif suffix in {".mmd", ".kicad_pro", ".kicad_sch"}:
            value += 45
        elif suffix in {".svg", ".png", ".jpg", ".jpeg", ".pdf"}:
            value += 20
    if text_has_any(query, ("preview", "svg", "image", "view")) and suffix in {".svg", ".png", ".jpg", ".jpeg", ".pdf"}:
        value += 90
    if "editable" in label or "source" in label or "draw.io" in label or "drawio" in label or "fusion" in label:
        value += 15
    if "preview" in label and not text_has_any(query, ("preview", "svg", "image", "view")):
        value -= 5
    return value


def select_generated_artifact_deliverable(deliverables, query):
    query = str(query or "").lower()
    if not deliverables:
        return None
    if text_has_any(query, ("first one", "first file", "top one", "top file")):
        return deliverables[0]
    if text_has_any(query, ("second one", "second file")) and len(deliverables) >= 2:
        return deliverables[1]
    if text_has_any(query, ("third one", "third file")) and len(deliverables) >= 3:
        return deliverables[2]
    return sorted(deliverables, key=lambda item: generated_artifact_deliverable_score(item, query), reverse=True)[0]


def generated_artifact_selection_reason(item, query):
    path = str((item or {}).get("path") or "")
    suffix = Path(path).suffix.lower()
    if text_has_any(query, ("preview", "svg", "image", "view")) and suffix in {".svg", ".png", ".jpg", ".jpeg", ".pdf"}:
        return "you asked for the preview/viewable output, and this is the preview artifact from the prior answer"
    if suffix == ".drawio":
        return "you selected the editable/source-style output, and the `.drawio` file is the editable diagram"
    if suffix in {".f3d", ".f3z"}:
        return "you selected the editable CAD output, and this native Fusion archive preserves the most design context"
    if suffix == ".py":
        return "you selected the editable/rebuild output, and this script can recreate the generated artifact"
    if suffix in {".step", ".stp"}:
        return "you selected the CAD handoff model, which is the right file to open before support logs or reports"
    return "your follow-up is selecting from files already listed in the prior answer"


