GENERATED_ARTIFACT_TEXT_REVISION_SUFFIXES = {
    ".drawio",
    ".svg",
    ".mmd",
    ".md",
    ".txt",
    ".json",
    ".csv",
    ".xml",
    ".html",
    ".scad",
    ".py",
}


def generated_artifact_label_revision_target(text):
    raw = str(text or "").strip()
    if not raw:
        return ""
    patterns = (
        r"(?:change|set|update|revise)\s+(?:the\s+)?(?:title|label|name)(?:\s+(?:on|in|of)\s+(?:the\s+)?(?:editable\s+)?(?:file|artifact|diagram|svg|drawio))?\s+(?:to|as)\s+(?P<value>.+)$",
        r"(?:change|set|update|revise|rename)\s+(?:it|this|that|the\s+)?(?:svg\s+preview|preview\s+svg|editable\s+file|drawio|draw\.io|preview|svg|artifact|diagram|file)\s*(?:title|label|name)?\s*(?:to|as)\s+(?P<value>.+)$",
        r"(?:change|set|update|revise|rename)\s+(?:it|this|that|the\s+)?(?:(?:svg|preview|editable|drawio|draw\.io|artifact|diagram|file)\s*)?(?:title|label|name)?\s*(?:to|as)\s+(?P<value>.+)$",
        r"(?:use)\s+(?P<value>.+?)\s+as\s+(?:the\s+)?(?:title|label|name)\s*[.!?]*$",
        r"(?:rename)\s+(?:it|this|that|the\s+(?:file|artifact|diagram|output))?\s*(?:to|as)\s+(?P<value>.+)$",
        r"(?:label|title|name)\s+(?:it|this|that|the\s+(?:file|artifact|diagram|output))\s+(?:as|to)\s+(?P<value>.+)$",
        r"(?:call|name)\s+(?:it|this|that|the\s+(?:file|artifact|diagram|output))\s+(?P<value>.+)$",
        r"instead\s+of\s+.+?\s+(?:use|call\s+it|label\s+it|name\s+it)\s+(?P<value>.+)$",
    )
    for pattern in patterns:
        match = re.search(pattern, raw, flags=re.IGNORECASE)
        if not match:
            continue
        value = match.group("value").strip()
        value = value.strip(" `\"'.:;")
        value = re.sub(r"\s+(?:on|in)\s+the\s+(?:editable\s+)?(?:file|artifact|diagram|drawio|svg)\s*$", "", value, flags=re.IGNORECASE)
        value = re.sub(r"\s+(?:please|thanks|thank you)\s*$", "", value, flags=re.IGNORECASE)
        value = value.strip(" `\"'.:;")
        if 2 <= len(value) <= 120 and not text_has_any(
            value.lower(),
            (
                "the svg too",
                "the editable file",
                "that one",
                "match too",
                "match also",
                "same title",
                "same label",
                "same name",
            ),
        ):
            return value
    return ""


def generated_artifact_label_revision_target_from_messages(messages):
    explicit = generated_artifact_label_revision_target(latest_user_text(messages))
    if explicit:
        return explicit
    query = latest_user_text(messages).lower()
    if not text_has_any(
        query,
        (
            "match too",
            "match also",
            "same title",
            "same label",
            "same name",
            "same change",
            "make the svg",
            "make the preview",
            "sync the svg",
            "sync the preview",
            "preview match",
            "use that title everywhere",
            "use the same title everywhere",
            "same title everywhere",
            "same label everywhere",
            "all files",
            "all outputs",
            "all of them",
            "everything match",
            "make the rest match",
            "sync all",
        ),
    ):
        return ""
    previous = previous_assistant_text(messages)
    patterns = (
        r"set\s+to\s+`([^`]{2,120})`",
        r"(?:new|requested)\s+(?:title|label|name)\s+(?:was|is)\s+`([^`]{2,120})`",
        r"(?:title|label|name)\s+(?:to|as)\s+`([^`]{2,120})`",
    )
    for pattern in patterns:
        match = re.search(pattern, previous, flags=re.IGNORECASE)
        if match:
            value = match.group(1).strip(" `\"'.:;")
            if 2 <= len(value) <= 120:
                return value
    return ""


