def generated_artifact_revision_path(source_path, target_label):
    source = Path(source_path)
    slug = slugify(target_label, "revised-label")[:56]
    candidate = source.with_name(f"{source.stem}_revised_{slug}{source.suffix}")
    if not candidate.exists():
        return candidate
    stamp = time.strftime("%Y%m%d-%H%M%S")
    return source.with_name(f"{source.stem}_revised_{slug}_{stamp}{source.suffix}")


def apply_generated_artifact_label_revision_text(source_text, suffix, target_label, selected=None):
    selected = selected or {}
    suffix = str(suffix or "").lower()
    target_xml = html.escape(str(target_label), quote=True)
    target_text = str(target_label)
    text = str(source_text or "")
    changes = []

    if suffix == ".drawio":
        updated, count = re.subn(
            r'(<diagram\b[^>]*\bname=")[^"]*(")',
            lambda match: f"{match.group(1)}{target_xml}{match.group(2)}",
            text,
            count=1,
            flags=re.IGNORECASE,
        )
        if count:
            text = updated
            changes.append("draw.io diagram tab name")
    elif suffix == ".svg":
        updated, count = re.subn(
            r"(<title\b[^>]*>)(.*?)(</title>)",
            lambda match: f"{match.group(1)}{html.escape(target_text)}{match.group(3)}",
            text,
            count=1,
            flags=re.IGNORECASE | re.DOTALL,
        )
        if count:
            text = updated
            changes.append("SVG title")
        else:
            updated, count = re.subn(
                r"(<svg\b[^>]*>)",
                lambda match: f"{match.group(1)}\n<title>{html.escape(target_text)}</title>",
                text,
                count=1,
                flags=re.IGNORECASE,
            )
            if count:
                text = updated
                changes.append("SVG title")
    elif suffix == ".json":
        try:
            data = json.loads(text or "{}")
            if isinstance(data, dict):
                key = "title" if "title" in data or "name" not in data else "name"
                data[key] = target_text
                text = json.dumps(data, indent=2, ensure_ascii=False) + "\n"
                changes.append(f"JSON {key}")
        except json.JSONDecodeError:
            pass
    elif suffix in {".mmd", ".md", ".txt", ".csv", ".xml", ".html", ".scad", ".py"}:
        label = str(selected.get("label") or "").strip()
        candidates = [
            label,
            Path(str(selected.get("path") or "")).stem.replace("_", " ").replace("-", " "),
            Path(str(selected.get("path") or "")).stem,
        ]
        replaced = False
        for candidate in candidates:
            candidate = str(candidate or "").strip()
            if len(candidate) < 3:
                continue
            if candidate in text:
                text = text.replace(candidate, target_text, 1)
                changes.append("visible label text")
                replaced = True
                break
        if not replaced and suffix in {".md", ".txt", ".mmd"}:
            prefix = f"# {target_text}\n\n" if suffix == ".md" else f"{target_text}\n\n"
            text = prefix + text
            changes.append("document title header")

    if text == source_text or not changes:
        return "", []
    return text, changes


def generated_artifact_label_revision_result_for_item(item, target_label, skip_prior_original=False):
    source_path = Path(str((item or {}).get("path") or "")).expanduser()
    suffix = source_path.suffix.lower()
    label = item.get("label") or source_path.name
    if skip_prior_original and "_revised_" not in source_path.name.lower():
        return {
            "status": "skipped",
            "source": str(source_path),
            "label": label,
            "reason": "prior original left unchanged",
        }
    if not source_path.exists():
        return {
            "status": "skipped",
            "source": str(source_path),
            "label": label,
            "reason": "missing from disk",
        }
    if suffix not in GENERATED_ARTIFACT_TEXT_REVISION_SUFFIXES:
        return {
            "status": "skipped",
            "source": str(source_path),
            "label": label,
            "reason": f"{suffix or 'no extension'} is not a safe text artifact",
        }
    try:
        if source_path.stat().st_size > 8 * 1024 * 1024:
            return {
                "status": "skipped",
                "source": str(source_path),
                "label": label,
                "reason": "larger than safe inline text-edit limit",
            }
        source_text = source_path.read_text(encoding="utf-8", errors="replace")
        revised_text, changes = apply_generated_artifact_label_revision_text(
            source_text,
            suffix,
            target_label,
            selected=item,
        )
        if not revised_text:
            if str(target_label) in source_text:
                return {
                    "status": "matched",
                    "source": str(source_path),
                    "label": label,
                    "reason": "already uses requested label",
                }
            return {
                "status": "skipped",
                "source": str(source_path),
                "label": label,
                "reason": "no safe title/label field found",
            }
        revised_path = generated_artifact_revision_path(source_path, target_label)
        revised_path.write_text(revised_text, encoding="utf-8")
        return {
            "status": "revised",
            "source": str(source_path),
            "revised": str(revised_path),
            "label": label,
            "changes": changes,
        }
    except Exception as exc:
        return {
            "status": "skipped",
            "source": str(source_path),
            "label": label,
            "reason": compact(str(exc), 180),
        }


def generated_artifact_all_label_revision_answer(deliverables, target_label):
    revised_siblings = set()
    for item in deliverables:
        path = Path(str(item.get("path") or ""))
        name = path.name.lower()
        if "_revised_" not in name:
            continue
        original_stem = name.split("_revised_", 1)[0]
        revised_siblings.add((str(path.parent), original_stem, path.suffix.lower()))
    results = []
    for item in deliverables:
        source_path = Path(str(item.get("path") or ""))
        skip_prior_original = (
            "_revised_" not in source_path.name.lower()
            and (str(source_path.parent), source_path.stem.lower(), source_path.suffix.lower()) in revised_siblings
        )
        results.append(
            generated_artifact_label_revision_result_for_item(
                item,
                target_label,
                skip_prior_original=skip_prior_original,
            )
        )
    revised = [item for item in results if item.get("status") == "revised"]
    matched = [item for item in results if item.get("status") == "matched"]
    skipped = [item for item in results if item.get("status") == "skipped"]
    if not revised:
        matched_text = ""
        if matched:
            matched_text = "\n\nAlready matched:\n" + "\n".join(
                f"- {item.get('label')}: `{item.get('source')}`" for item in matched[:4]
            )
        skipped_text = ""
        if skipped:
            skipped_text = "\n\nSkipped:\n" + "\n".join(
                f"- {item.get('label')}: {item.get('reason')} (`{item.get('source')}`)" for item in skipped[:4]
            )
        return "\n\n".join(
            [
                f"I did not create new package-wide revisions because none of the visible safe artifacts needed a label change to `{target_label}`.",
                "This is why: I checked the generated files listed in the previous answer and only revise text-based artifacts when I can identify a safe title or label field.",
                "You should also consider: binary/native files still need their owning tool path, and originals stay unchanged unless you explicitly ask to overwrite them.",
            ]
        ) + matched_text + skipped_text

    revised_lines = [
        f"- {', '.join(item.get('changes') or ['label'])}: `{item.get('revised')}`"
        for item in revised[:8]
    ]
    matched_text = ""
    if matched:
        matched_text = "\n\nAlready matched:\n" + "\n".join(
            f"- {item.get('label')}: `{item.get('source')}`" for item in matched[:4]
        )
    skipped_text = ""
    if skipped:
        skipped_text = "\n\nSkipped safely:\n" + "\n".join(
            f"- {item.get('label')}: {item.get('reason')} (`{item.get('source')}`)" for item in skipped[:5]
        )
    return "\n\n".join(
        [
            f"I synced the generated package label across {len(revised)} visible artifact{'s' if len(revised) != 1 else ''} and saved revised copies beside the originals.",
            f"New label: `{target_label}`.\n\nRevised files:\n" + "\n".join(revised_lines),
            (
                "This is why: your follow-up asked for the same title across the package, so I used the visible generated-file paths "
                "from the previous answer and only edited safe text-based artifacts."
            ),
            (
                "You should also consider: originals are still left unchanged. Open the revised copies together; native CAD, PDFs, images, "
                "or solver files still need their owning tool path before I rewrite them."
            ),
        ]
    ) + matched_text + skipped_text


def generated_artifact_label_revision_followup_direct_answer(messages):
    if not is_generated_artifact_label_revision_followup(messages):
        return ""
    query = latest_user_text(messages)
    target_label = generated_artifact_label_revision_target_from_messages(messages)
    deliverables = extract_response_deliverables(previous_assistant_text(messages))
    if is_generated_artifact_all_label_revision_request(query):
        return generated_artifact_all_label_revision_answer(deliverables, target_label)
    selected = select_generated_artifact_deliverable(deliverables, query)
    if not selected:
        return ""
    source_path = Path(str(selected.get("path") or "")).expanduser()
    suffix = source_path.suffix.lower()
    label = selected.get("label") or source_path.name
    if not source_path.exists():
        return "\n\n".join(
            [
                f"I did not revise it because the prior path is not on disk from here: `{source_path}`.",
                f"This is why: your follow-up is a generated-artifact revision, but I cannot safely edit a file that is missing. The requested new label was `{target_label}`.",
                "You should also consider: rerun the generator or resend the artifact path, and I should create the revised copy beside the real source file instead of asking you to hunt for it.",
            ]
        )
    if suffix not in GENERATED_ARTIFACT_TEXT_REVISION_SUFFIXES:
        return "\n\n".join(
            [
                f"I did not auto-revise `{source_path.name}` because `{suffix or 'no extension'}` is not a safe text-based artifact format for this label edit.",
                "This is why: changing labels inside binary/native CAD, images, PDFs, or solver files needs the owning tool path so I do not corrupt the file.",
                "You should also consider: ask for the editable source version, such as `.drawio`, `.mmd`, `.scad`, `.py`, or a Fusion script, and I should revise that source and report the new path.",
            ]
        )
    result = generated_artifact_label_revision_result_for_item(selected, target_label)
    if result.get("status") == "matched":
        return "\n\n".join(
            [
                f"I did not create another revised copy because `{source_path.name}` already uses `{target_label}`.",
                f"This is why: your follow-up is a generated-artifact revision, and the selected artifact already contains the requested label.",
                "You should also consider: if the preview or supporting source should also match, say to apply the same title everywhere and I should revise every visible safe text artifact.",
            ]
        )
    if result.get("status") != "revised":
        reason = result.get("reason") or "the local file edit failed"
        return "\n\n".join(
            [
                f"I did not complete the artifact revision: {reason}.",
                f"This is why: your follow-up was attached to `{label}`, but the local file edit failed before I could create a verified revised copy.",
                "You should also consider: the next pass should retry the exact source path and preserve the original file until the revised artifact exists on disk.",
            ]
        )
    revised_path = Path(result.get("revised") or "")
    changes = result.get("changes") or []

    alternatives = [item for item in deliverables if item is not selected and item.get("path")][:2]
    alt_text = ""
    if alternatives:
        alt_text = "\n\nOther prior outputs left unchanged:\n" + "\n".join(
            f"- {item.get('label') or Path(item.get('path') or '').name}: `{item.get('path')}`"
            for item in alternatives
        )
    return "\n\n".join(
        [
            f"I revised the generated artifact and saved the new copy here: `{revised_path}`.",
            f"Changed: {', '.join(changes)} set to `{target_label}`. Original left unchanged: `{source_path}`.",
            (
                f"This is why: your follow-up is a revision to `{label}` from the previous answer, so I used that visible local path "
                "and wrote a revised copy beside it instead of starting a new task or asking you to find the file."
            ),
            (
                "You should also consider: open the revised copy first. If the preview artifact also needs the same label, say so and I should revise that visible preview source separately."
            )
            + alt_text,
        ]
    )


