def generated_artifact_open_followup_direct_answer(messages):
    if not is_generated_artifact_open_followup(messages):
        return ""
    query = latest_user_text(messages).lower().strip()
    deliverables = extract_response_deliverables(previous_assistant_text(messages))
    if not deliverables:
        return ""

    def score(item):
        path = str(item.get("path") or "")
        suffix = Path(path).suffix.lower()
        label = str(item.get("label") or "").lower()
        value = 0
        if item.get("exists"):
            value += 20
        if "source" in query or "editable" in query or "open first" in query or "which file" in query:
            if suffix in {".drawio", ".f3d", ".f3z"}:
                value += 80
            elif suffix in {".py", ".scad", ".step", ".stp"}:
                value += 55
            elif suffix in {".mmd", ".kicad_pro", ".kicad_sch"}:
                value += 45
            elif suffix in {".svg", ".png", ".jpg", ".jpeg", ".pdf"}:
                value += 20
        if "preview" in query and suffix in {".svg", ".png", ".jpg", ".jpeg", ".pdf"}:
            value += 75
        if "editable" in label or "source" in label or "draw.io" in label or "fusion" in label:
            value += 15
        if "preview" in label:
            value -= 5
        return value

    primary = sorted(deliverables, key=score, reverse=True)[0]
    path = primary.get("path") or ""
    label = primary.get("label") or Path(path).name or "the generated file"
    suffix = Path(path).suffix.lower()
    if suffix == ".drawio":
        reason = "it is the editable diagram source; the SVG or image output is better for previewing or sharing."
    elif suffix in {".f3d", ".f3z"}:
        reason = "it is the native Fusion archive, so it preserves the most editable CAD context."
    elif suffix == ".py":
        reason = "it is the rebuild/source script, so Fusion can recreate the modeled artifact from editable instructions."
    elif suffix in {".step", ".stp"}:
        reason = "it is the CAD handoff model, so open it before logs, notes, or secondary preview files."
    else:
        reason = "it is the highest-priority generated output from the previous answer."

    alternatives = [item for item in deliverables if item is not primary and item.get("path")][:2]
    alt_text = ""
    if alternatives:
        alt_text = "\n\nOther useful generated files:\n" + "\n".join(
            f"- {item.get('label') or Path(item.get('path') or '').name}: `{item.get('path')}`"
            for item in alternatives
        )
    return "\n\n".join(
        [
            f"Open this first: `{path}`.",
            f"This is why: the previous answer named `{label}`, and {reason}",
            (
                "You should also consider: click the generated-file card if it is visible in the UI. "
                "If not, use that exact path in Finder's Go to Folder box."
            )
            + alt_text,
        ]
    )


