def requested_response_language(text):
    query = str(text or "").lower()
    language_patterns = (
        ("Spanish", ("in spanish", "en español", "en espanol", "responde en español", "responder en español")),
        ("French", ("in french", "en français", "en francais", "réponds en français", "reponds en francais")),
        ("German", ("in german", "auf deutsch", "in deutsch")),
        ("Italian", ("in italian", "in italiano")),
        ("Portuguese", ("in portuguese", "em português", "em portugues")),
        ("English", ("in english", "en inglés", "en ingles")),
        ("British English", ("british english", "uk english", "en-gb")),
        ("American English", ("american english", "us english", "en-us")),
    )
    for language, patterns in language_patterns:
        if any(pattern in query for pattern in patterns):
            return language
    return ""


def ambiguous_slash_dates(text):
    dates = []
    for match in re.finditer(r"\b(0?[1-9]|1[0-2])/(0?[1-9]|1[0-2])/(20\d{2})\b", str(text or "")):
        first = int(match.group(1))
        second = int(match.group(2))
        if first != second:
            dates.append(
                {
                    "raw": match.group(0),
                    "mdy": f"{match.group(3)}-{first:02d}-{second:02d}",
                    "dmy": f"{match.group(3)}-{second:02d}-{first:02d}",
                }
            )
    return dates


