def ai_ui_intent_promotion_status_direct_answer(messages):
    if not is_ai_ui_intent_promotion_status_question(messages):
        return ""
    audit_path = APP_DIR / "tests" / "ai_ui_intent_500_audit.json"
    data = read_json(audit_path, {})
    items = data.get("items") if isinstance(data, dict) else []
    if not isinstance(items, list):
        items = []
    partials = [item for item in items if str(item.get("status") or "").upper() == "PARTIAL"]
    pass_count = sum(1 for item in items if str(item.get("status") or "").upper() == "PASS")
    review_count = sum(1 for item in items if str(item.get("status") or "").upper() == "REVIEW")
    hold_terms = (
        "human review",
        "human/product review",
        "product/human review",
        "manual",
        "manual qa",
        "human qa",
        "human/product qa",
        "sign off",
        "signs off",
        "still needs",
        "needs final",
        "needs real",
        "before pass",
        "before pass.",
        "kept partial until",
        "until ",
    )
    strong_prefixes = (
        "api:",
        "ui:",
        "tools:",
        "analysis:",
        "python:",
        "privacy:",
        "response:",
        "admin:",
    )
    auto_candidates = []
    human_holds = []
    for item in partials:
        note = str(item.get("note") or "").lower()
        evidence = [str(value or "") for value in (item.get("evidence") or [])]
        strong_count = sum(1 for value in evidence if value.startswith(strong_prefixes))
        if any(term in note for term in hold_terms):
            human_holds.append(item)
        elif strong_count >= 3:
            auto_candidates.append(item)
        else:
            human_holds.append(item)
    latest_report = latest_matching_file(DATA_DIR / "golden_batch_results", "*-ai-ui-intent-promotion-candidates.md")
    report_sentence = f" Latest promotion report: `{latest_report}`." if latest_report else ""
    total = len(items)
    if not total:
        return "\n\n".join(
            [
                "I do not have a readable 500-question AI intent audit file right now.",
                f"This is why: I checked `{audit_path}` and could not read an `items` list from it.",
                "You should also consider: rerun the audit generator before promoting any items to PASS.",
            ]
        )
    if not auto_candidates:
        return "\n\n".join(
            [
                f"None of the {len(partials)} PARTIAL AI UI intent items should be auto-promoted to PASS yet.",
                (
                    f"This is why: I read `{audit_path}` and found {pass_count} PASS, {len(partials)} PARTIAL, "
                    f"and {review_count} REVIEW out of {total} total. The PARTIAL items are classified as human-QA holds, "
                    f"so promoting them now would claim product review that has not happened.{report_sentence}"
                ),
                "You should also consider: keep them PARTIAL until the matching human/product QA lane is actually reviewed. The next useful action is to run the safety lane first, then privacy, high-stakes, accessibility, production, localization, latency, and prompt guidance.",
            ]
        )
    sample = "; ".join(f"Q{item.get('id')}: {item.get('question')}" for item in auto_candidates[:5])
    return "\n\n".join(
        [
            f"I found {len(auto_candidates)} PARTIAL items that may be promotion candidates after review. First candidates: {sample}.",
            (
                f"This is why: I read `{audit_path}` and separated automated-evidence candidates from human-QA holds. "
                f"The audit currently has {pass_count} PASS, {len(partials)} PARTIAL, and {review_count} REVIEW out of {total} total.{report_sentence}"
            ),
            "You should also consider: do not batch-promote these without reading the evidence and running the associated smoke or manual QA lane first.",
        ]
    )


def latest_matching_file(root, pattern):
    try:
        candidates = [path for path in Path(root).glob(pattern) if path.is_file()]
        if not candidates:
            return None
        return max(candidates, key=lambda path: path.stat().st_mtime)
    except OSError:
        return None


def latest_full_live_feedback_smoke_receipt(root=None, default_count=0):
    root_path = Path(root or DATA_DIR / "live_feedback_smoke_results")
    try:
        candidates = [path for path in root_path.glob("*-live-feedback-smoke.json") if path.is_file()]
    except OSError:
        return None
    full_receipts = []
    for path in candidates:
        data = read_json(path, {})
        if not isinstance(data, dict):
            continue
        if data.get("caseFilter") or data.get("expertConversation"):
            continue
        total = int(data.get("total") or 0)
        if default_count and total < int(default_count):
            continue
        full_receipts.append(path)
    if not full_receipts:
        return None
    try:
        return max(full_receipts, key=lambda path: path.stat().st_mtime)
    except OSError:
        return full_receipts[-1] if full_receipts else None


def local_improvement_status_artifacts():
    checkpoint_path = latest_matching_file(DATA_DIR / "work_checkpoints", "*.md")
    replay_path = latest_matching_file(DATA_DIR / "golden_batch_results", "*ai-ui-intent-500*quality-summary.json")
    smoke_path = latest_full_live_feedback_smoke_receipt()
    production_json_path = latest_matching_file(DATA_DIR / "golden_batch_results", "*-production-holds.json")
    production_md_path = latest_matching_file(DATA_DIR / "golden_batch_results", "*-production-holds.md")
    accessibility_json_path = latest_matching_file(DATA_DIR / "golden_batch_results", "*-accessibility-holds.json")
    accessibility_md_path = latest_matching_file(DATA_DIR / "golden_batch_results", "*-accessibility-holds.md")
    audit_path = APP_DIR / "tests" / "ai_ui_intent_500_audit.json"

    checkpoint_text = ""
    if checkpoint_path:
        try:
            checkpoint_text = checkpoint_path.read_text(encoding="utf-8", errors="replace")
        except OSError:
            checkpoint_text = ""
    health_label = ""
    package_section_match = re.search(
        r"(?is)package health:\s*(?:\n|\r\n)\s*-\s*`?(\d+)\s*/\s*(\d+)`?",
        checkpoint_text,
    )
    if not package_section_match:
        package_section_match = re.search(
            r"(?is)package health[^\n\r]{0,80}?`?(\d+)\s*/\s*(\d+)`?",
            checkpoint_text,
        )
    if package_section_match and package_section_match.group(1) == package_section_match.group(2):
        health_label = f"{package_section_match.group(1)}/{package_section_match.group(2)}"
    for match in re.finditer(r"(\d+)\s*/\s*(\d+)", checkpoint_text):
        if not health_label and match.group(1) == match.group(2):
            health_label = f"{match.group(1)}/{match.group(2)}"
    if not health_label and "package health" in checkpoint_text.lower():
        health_label = "see latest checkpoint"

    replay = read_json(replay_path, {}) if replay_path else {}
    smoke = read_json(smoke_path, {}) if smoke_path else {}
    production_report = read_json(production_json_path, {}) if production_json_path else {}
    accessibility_report = read_json(accessibility_json_path, {}) if accessibility_json_path else {}
    audit_data = read_json(audit_path, {})
    items = audit_data.get("items") if isinstance(audit_data, dict) else []
    if not isinstance(items, list):
        items = []
    counts = {}
    for item in items:
        status = str(item.get("status") or "UNKNOWN").upper()
        counts[status] = counts.get(status, 0) + 1
    production_hold_count = (
        int(production_report.get("productionPartialCount") or 0)
        if isinstance(production_report, dict)
        else 0
    )
    accessibility_hold_count = (
        int(accessibility_report.get("accessibilityPartialCount") or 0)
        if isinstance(accessibility_report, dict)
        else 0
    )
    if not production_hold_count or not accessibility_hold_count:
        production_hold_count = 0
        accessibility_hold_count = 0
        for item in items:
            if str(item.get("status") or "").upper() != "PARTIAL":
                continue
            category = str(item.get("category") or "").lower()
            if "production readiness" in category:
                production_hold_count += 1
            if "accessibility" in category:
                accessibility_hold_count += 1
    return {
        "checkpointPath": str(checkpoint_path) if checkpoint_path else "",
        "checkpointHealth": health_label,
        "replayPath": str(replay_path) if replay_path else "",
        "replayPassed": int(replay.get("passed") or 0) if isinstance(replay, dict) else 0,
        "replayTotal": int(replay.get("total") or 0) if isinstance(replay, dict) else 0,
        "replayFailed": int(replay.get("failed") or 0) if isinstance(replay, dict) else 0,
        "smokePath": str(smoke_path) if smoke_path else "",
        "smokePassed": int(smoke.get("passed") or 0) if isinstance(smoke, dict) else 0,
        "smokeTotal": int(smoke.get("total") or 0) if isinstance(smoke, dict) else 0,
        "smokeFailed": int(smoke.get("failed") or 0) if isinstance(smoke, dict) else 0,
        "auditPath": str(audit_path),
        "auditPass": int(counts.get("PASS", 0)),
        "auditPartial": int(counts.get("PARTIAL", 0)),
        "auditReview": int(counts.get("REVIEW", 0)),
        "auditTotal": len(items),
        "productionJsonPath": str(production_json_path) if production_json_path else "",
        "productionMarkdownPath": str(production_md_path) if production_md_path else "",
        "productionHoldCount": production_hold_count,
        "accessibilityJsonPath": str(accessibility_json_path) if accessibility_json_path else "",
        "accessibilityMarkdownPath": str(accessibility_md_path) if accessibility_md_path else "",
        "accessibilityHoldCount": accessibility_hold_count,
    }


