def local_live_feedback_smoke_inventory():
    live_smoke_tool = APP_DIR / "tools" / "live_feedback_smoke.py"
    inventory = {}
    if live_smoke_tool.exists():
        try:
            completed = subprocess.run(
                ["/usr/bin/python3", str(live_smoke_tool), "--list-cases", "--json"],
                cwd=str(APP_DIR),
                stdout=subprocess.PIPE,
                stderr=subprocess.PIPE,
                text=True,
                timeout=20,
                env=dict(os.environ),
            )
            if completed.returncode == 0:
                inventory = json.loads(completed.stdout or "{}")
        except Exception:
            inventory = {}
    case_ids = inventory.get("defaultCaseIds") if isinstance(inventory, dict) else []
    if not isinstance(case_ids, list):
        case_ids = []
    default_count = int(inventory.get("defaultCount") or len(case_ids)) if isinstance(inventory, dict) else len(case_ids)
    smoke_path = latest_full_live_feedback_smoke_receipt(default_count=default_count)
    if not smoke_path and default_count:
        smoke_path = latest_full_live_feedback_smoke_receipt()
    smoke = read_json(smoke_path, {}) if smoke_path else {}
    return {
        "toolPath": str(live_smoke_tool),
        "caseIds": [str(case_id) for case_id in case_ids],
        "defaultCount": default_count,
        "receiptPath": str(smoke_path) if smoke_path else "",
        "receiptPassed": int(smoke.get("passed") or 0) if isinstance(smoke, dict) else 0,
        "receiptTotal": int(smoke.get("total") or 0) if isinstance(smoke, dict) else 0,
        "receiptFailed": int(smoke.get("failed") or 0) if isinstance(smoke, dict) else 0,
    }


def live_feedback_smoke_coverage_direct_answer(messages):
    if not is_live_feedback_smoke_coverage_question(messages):
        return ""
    inventory = local_live_feedback_smoke_inventory()
    case_ids = inventory.get("caseIds") or []
    count = int(inventory.get("defaultCount") or len(case_ids))
    receipt_total = int(inventory.get("receiptTotal") or 0)
    receipt_passed = int(inventory.get("receiptPassed") or 0)
    receipt_failed = int(inventory.get("receiptFailed") or 0)
    receipt_path = inventory.get("receiptPath") or "no latest live-smoke receipt found"
    receipt = (
        f"Latest receipt: {receipt_passed}/{receipt_total} passing"
        if receipt_total
        else "Latest receipt: not found yet"
    )
    if receipt_failed:
        receipt += f", {receipt_failed} failed"
    groups = [
        ("conversation and status", ("agent-preference", "status", "human-qa", "audit")),
        ("Mac, printer, and local inventory", ("mac-", "printer-ip", "local-named-config")),
        ("cached manuals and source-vault evidence", ("source-vault", "local-manual")),
        ("Fusion, generated artifacts, and slicer profile continuity", ("fusion", "generated-artifact", "file-open", "pet-cf")),
        ("verification receipts and runtime exception status", ("verification-receipts", "runtime-exceptions")),
        ("Vevor power-equipment follow-ups", ("vevor",)),
        ("attachment, edit, native-file, and live steering recovery", ("attachment", "large-native", "live-steering")),
        ("aero/CFD preflight behavior", ("aero-cfd",)),
    ]
    coverage_parts = []
    for label, prefixes in groups:
        matches = [case_id for case_id in case_ids if any(case_id.startswith(prefix) or prefix in case_id for prefix in prefixes)]
        if matches:
            coverage_parts.append(f"{label} ({len(matches)})")
    coverage = "; ".join(coverage_parts) if coverage_parts else "case inventory unavailable"
    sample_ids = ", ".join(case_ids[:6]) if case_ids else "no case IDs available"
    return "\n\n".join(
        [
            f"Live feedback smoke currently covers {count} default real `/api/run` checks. {receipt}.",
            f"Coverage areas: {coverage}. Sample case IDs: {sample_ids}.",
            (
                "This is why: I read the live smoke inventory from "
                f"`{inventory.get('toolPath')}` and the latest receipt at `{receipt_path}` instead of describing the test suite from memory."
            ),
            (
                "You should also consider: this is smoke coverage, not the full human-QA story. "
                "It protects the failure-prone lanes we have been fixing: direct answers, follow-up context, local evidence retrieval, attachments, steering, generated files, and engineering preflights."
            ),
        ]
    )


def parse_receipt_time(value):
    if isinstance(value, (int, float)) and value > 0:
        return float(value)
    text = str(value or "").strip()
    if not text:
        return 0.0
    if re.fullmatch(r"\d+(?:\.\d+)?", text):
        try:
            return float(text)
        except ValueError:
            return 0.0
    for fmt in ("%Y-%m-%dT%H:%M:%SZ", "%Y%m%dT%H%M%SZ"):
        try:
            return float(calendar.timegm(time.strptime(text, fmt)))
        except ValueError:
            pass
    return 0.0


def receipt_age_label(timestamp, now=None):
    if not timestamp:
        return "age unknown"
    seconds = max(0, int((now or time.time()) - float(timestamp)))
    if seconds < 90:
        return "just now"
    minutes = seconds // 60
    if minutes < 90:
        return f"{minutes} min ago"
    hours = minutes // 60
    if hours < 48:
        return f"{hours} hr ago"
    days = hours // 24
    return f"{days} days ago"


def receipt_item_next_action(status, refresh_action):
    if status == "pass":
        return "No action needed."
    if status == "fail":
        return refresh_action
    return refresh_action


def public_export_freshness_status():
    manifest_path = APP_DIR / "build" / "public-export" / "codex-cli-ui-public" / "PUBLIC_EXPORT_MANIFEST.json"
    builder_path = APP_DIR / "tools" / "build_public_export.py"
    if not builder_path.exists():
        return {
            "ok": False,
            "manifestPath": str(manifest_path),
            "detail": "public export builder is missing",
        }
    if not manifest_path.exists():
        return {
            "ok": False,
            "manifestPath": str(manifest_path),
            "detail": "public export manifest is missing; build the public export",
        }
    manifest = read_json(manifest_path, {})
    if not isinstance(manifest, dict) or not manifest:
        return {
            "ok": False,
            "manifestPath": str(manifest_path),
            "detail": "public export manifest could not be read",
        }
    privacy_scan = manifest.get("privacyScan") if isinstance(manifest.get("privacyScan"), dict) else {}
    finding_count = int(privacy_scan.get("findingCount") or 0)
    if privacy_scan.get("status") != "pass" or finding_count:
        return {
            "ok": False,
            "manifestPath": str(manifest_path),
            "detail": f"public export privacy scan is not clean: {privacy_scan.get('status')}, {finding_count} findings",
        }
    try:
        spec = importlib.util.spec_from_file_location("_codex_public_export_builder", builder_path)
        if spec is None or spec.loader is None:
            raise RuntimeError("could not load public export builder spec")
        module = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(module)
        source_paths = []
        for rel in sorted(set(getattr(module, "PUBLIC_FILES", []) + getattr(module, "PUBLIC_TOOL_FILES", []))):
            source = APP_DIR / rel
            if source.is_file():
                source_paths.append((str(rel), source))
        for rel_dir in getattr(module, "PUBLIC_DIRS", []):
            source_dir = APP_DIR / rel_dir
            if not source_dir.exists():
                continue
            for source in sorted(source_dir.rglob("*")):
                if not source.is_file():
                    continue
                source_rel = source.relative_to(APP_DIR)
                if "__pycache__" in source_rel.parts or source.suffix == ".pyc":
                    continue
                source_paths.append((str(source_rel), source))
    except Exception as exc:
        return {
            "ok": False,
            "manifestPath": str(manifest_path),
            "detail": f"could not inspect public export inputs: {exc}",
        }
    if not source_paths:
        return {
            "ok": False,
            "manifestPath": str(manifest_path),
            "detail": "public export input list is empty",
        }
    copied_files = set(str(path) for path in (manifest.get("copiedFiles") or []))
    missing_copied_files = sorted(rel for rel, _source in source_paths if rel not in copied_files)
    if missing_copied_files:
        return {
            "ok": False,
            "manifestPath": str(manifest_path),
            "detail": f"public export manifest is missing copied files: {', '.join(missing_copied_files[:5])}",
        }
    manifest_mtime = float(manifest_path.stat().st_mtime)
    latest_rel, latest_source = max(source_paths, key=lambda item: item[1].stat().st_mtime)
    latest_mtime = float(latest_source.stat().st_mtime)
    if manifest_mtime + 1.0 < latest_mtime:
        return {
            "ok": False,
            "manifestPath": str(manifest_path),
            "detail": (
                "public export is stale: "
                f"manifest {time.strftime('%Y-%m-%dT%H:%M:%SZ', time.gmtime(manifest_mtime))}, "
                f"latest source {latest_rel} at {time.strftime('%Y-%m-%dT%H:%M:%SZ', time.gmtime(latest_mtime))}"
            ),
        }
    return {
        "ok": True,
        "manifestPath": str(manifest_path),
        "detail": (
            f"public export is current: {int(manifest.get('fileCount') or 0)} files, "
            f"{finding_count} privacy findings, latest source {latest_rel}"
        ),
        "createdAt": manifest.get("createdAt"),
        "fileCount": int(manifest.get("fileCount") or 0),
        "findingCount": finding_count,
    }


def verification_summary():
    artifacts = local_improvement_status_artifacts()
    checkpoint_path = artifacts.get("checkpointPath") or ""
    package_health_latest = read_json(PACKAGE_HEALTH_LATEST_PATH, {})
    package_latest_total = int(package_health_latest.get("total") or 0) if isinstance(package_health_latest, dict) else 0
    package_latest_passed = int(package_health_latest.get("passed") or 0) if isinstance(package_health_latest, dict) else 0
    package_latest_failed = int(package_health_latest.get("failed") or 0) if isinstance(package_health_latest, dict) else 0
    package_health_metric = (
        f"{package_latest_passed}/{package_latest_total}"
        if package_latest_total
        else artifacts.get("checkpointHealth") or ""
    )
    package_health_path = str(PACKAGE_HEALTH_LATEST_PATH) if package_latest_total else checkpoint_path
    package_health_detail = (
        "Latest saved package-health report."
        if package_latest_total
        else "Latest checkpoint package-health receipt."
    )
    now = time.time()
    package_created_at = (
        parse_receipt_time(package_health_latest.get("createdAt")) if package_latest_total else 0.0
    )
    smoke_path = artifacts.get("smokePath") or ""
    smoke_data = read_json(Path(smoke_path), {}) if smoke_path else {}
    replay_path = artifacts.get("replayPath") or ""
    replay_data = read_json(Path(replay_path), {}) if replay_path else {}
    public_manifest_path = APP_DIR / "build" / "public-export" / "codex-cli-ui-public" / "PUBLIC_EXPORT_MANIFEST.json"
    public_manifest = read_json(public_manifest_path, {}) if public_manifest_path.exists() else {}
    privacy_scan = public_manifest.get("privacyScan") if isinstance(public_manifest, dict) else {}
    if not isinstance(privacy_scan, dict):
        privacy_scan = {}
    public_freshness = public_export_freshness_status()
    package_status = (
        "fail"
        if package_latest_failed
        else
        "pass"
        if package_health_metric
        and package_health_metric.split("/", 1)[0] == package_health_metric.split("/", 1)[-1]
        else "unknown"
    )
    smoke_status = "pass" if artifacts.get("smokeTotal") and artifacts.get("smokeFailed") == 0 else "unknown"
    replay_status = "pass" if artifacts.get("replayTotal") == 500 and artifacts.get("replayFailed") == 0 else "unknown"
    public_status = "pass" if public_freshness.get("ok") else "fail"
    exception_path = APP_DIR / "logs" / "server-exceptions.log"
    try:
        exception_state = current_server_exception_log_state()
    except Exception as exc:
        exception_state = {"ok": False, "detail": f"could not check server exception log: {exc}"}
    exception_status = "pass" if exception_state.get("ok") else "fail"
    exception_latest_entry = exception_state.get("latestEntry") or ""
    exception_time = parse_server_exception_log_time(exception_latest_entry) if exception_latest_entry else 0.0
    if not exception_time and exception_path.exists():
        try:
            exception_time = float(exception_path.stat().st_mtime)
        except OSError:
            exception_time = 0.0
    exception_age = "clean since restart" if exception_status == "pass" else receipt_age_label(exception_time, now)
    self_healing_receipt = self_healing_summary(limit=3, auto_resolve=True)
    self_healing_queue = self_healing_receipt.get("queue") or {}
    self_queue_open = int(self_healing_queue.get("openCount") or 0)
    self_open_actions = int(self_healing_receipt.get("openActionCount") or 0)
    self_approval_count = int(self_healing_receipt.get("approvalCount") or 0)
    self_healing_status = "pass" if self_queue_open == 0 and self_open_actions == 0 and self_approval_count == 0 else "warn"
    self_healing_metric = (
        "0 open"
        if self_healing_status == "pass"
        else f"{self_queue_open} queued, {self_open_actions} action events, {self_approval_count} approvals"
    )
    self_queue_data = load_self_patch_queue()
    self_queue_time = float(self_queue_data.get("updatedAt") or 0.0) if isinstance(self_queue_data, dict) else 0.0
    self_healing_age = (
        "idle, no open work"
        if self_healing_status == "pass"
        else receipt_age_label(self_queue_time, now)
    )
    items = [
        {
            "id": "package-health-checkpoint",
            "label": "Package Health",
            "status": package_status,
            "metric": package_health_metric or "run Package Check",
            "path": package_health_path,
            "detail": package_health_detail,
            "age": receipt_age_label(package_created_at, now),
            "nextAction": receipt_item_next_action(package_status, "Run Package Check."),
        },
        {
            "id": "live-feedback-smoke",
            "label": "Live Smoke",
            "status": smoke_status,
            "metric": (
                f"{artifacts.get('smokePassed')}/{artifacts.get('smokeTotal')}"
                if artifacts.get("smokeTotal")
                else "no receipt"
            ),
            "path": smoke_path,
            "detail": "Live /api/run regression smoke receipt.",
            "age": receipt_age_label(parse_receipt_time(smoke_data.get("createdAt")), now),
            "nextAction": receipt_item_next_action(smoke_status, "Run live feedback smoke."),
        },
        {
            "id": "ai-intent-500",
            "label": "AI Intent 500",
            "status": replay_status,
            "metric": (
                f"{artifacts.get('replayPassed')}/{artifacts.get('replayTotal')}"
                if artifacts.get("replayTotal")
                else "no receipt"
            ),
            "path": replay_path,
            "detail": "500-question replay receipt.",
            "age": receipt_age_label(parse_receipt_time(replay_data.get("createdAt")), now),
            "nextAction": receipt_item_next_action(replay_status, "Run the AI intent 500 replay."),
        },
        {
            "id": "public-export",
            "label": "Public Export",
            "status": public_status,
            "metric": (
                (
                    f"{int(public_manifest.get('fileCount') or 0)} files, "
                    f"{int(privacy_scan.get('findingCount') or 0)} privacy findings, "
                    f"{'current' if public_freshness.get('ok') else 'stale'}"
                )
                if isinstance(public_manifest, dict) and public_manifest
                else "no export"
            ),
            "path": str(public_manifest_path) if public_manifest_path.exists() else "",
            "detail": public_freshness.get("detail") or "Curated public export manifest and privacy scan.",
            "age": receipt_age_label(parse_receipt_time(public_manifest.get("createdAt")), now),
            "nextAction": receipt_item_next_action(public_status, "Build the public export."),
        },
        {
            "id": "runtime-exceptions",
            "label": "Runtime Exceptions",
            "status": exception_status,
            "metric": "clean" if exception_status == "pass" else "current exception",
            "path": str(exception_path) if exception_path.exists() else "",
            "detail": exception_state.get("detail") or "Current server exception log checked.",
            "age": exception_age,
            "nextAction": receipt_item_next_action(exception_status, "Open server-exceptions.log and patch the traceback source."),
        },
        {
            "id": "self-healing-queue",
            "label": "Self-Healing Queue",
            "status": self_healing_status,
            "metric": self_healing_metric,
            "path": str(SELF_PATCH_QUEUE_PATH),
            "detail": (
                f"{int(self_healing_queue.get('archivedCount') or 0)} archived work orders; "
                f"{int(self_healing_receipt.get('validatedResolvedCount') or 0)} validated-resolved journal events."
            ),
            "age": self_healing_age,
            "nextAction": receipt_item_next_action(self_healing_status, "Open the Self-Healing Admin card and clear queued work orders."),
        },
    ]
    passed = sum(1 for item in items if item.get("status") == "pass")
    return {
        "ok": passed == len(items),
        "status": "pass" if passed == len(items) else "warn",
        "checkedAt": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()),
        "passed": passed,
        "total": len(items),
        "items": items,
    }


