def freshen_receipts_plan():
    summary = verification_summary()
    artifacts = local_improvement_status_artifacts()
    inventory = local_live_feedback_smoke_inventory()
    items = {item.get("id"): item for item in (summary.get("items") or []) if isinstance(item, dict)}
    package_item = items.get("package-health-checkpoint", {})
    smoke_item = items.get("live-feedback-smoke", {})
    replay_item = items.get("ai-intent-500", {})
    export_item = items.get("public-export", {})
    default_count = int(inventory.get("defaultCount") or 0)
    smoke_passed = int(inventory.get("receiptPassed") or artifacts.get("smokePassed") or 0)
    smoke_total = int(inventory.get("receiptTotal") or artifacts.get("smokeTotal") or 0)
    package_status = str(package_item.get("status") or "unknown")
    replay_metric = str(replay_item.get("metric") or "")
    export_status = str(export_item.get("status") or "unknown")
    stale = []
    current = []
    required_commands = []
    if package_status != "pass":
        stale.append("Package health is not green")
        required_commands.append("curl -sS http://127.0.0.1:8765/api/package-health > /tmp/codex-package-health-fresh.json")
    else:
        current.append(f"Package health is green at {package_item.get('metric') or 'unknown'}")
    if default_count and smoke_total < default_count:
        stale.append(f"Live smoke full receipt is stale: latest full receipt has {smoke_passed}/{smoke_total}, default inventory has {default_count} cases")
        required_commands.append("python3 tools/live_feedback_smoke.py --json")
    elif smoke_item.get("status") != "pass":
        stale.append("Live smoke receipt is missing or not green")
        required_commands.append("python3 tools/live_feedback_smoke.py --json")
    else:
        current.append(f"Live smoke full receipt is green at {smoke_item.get('metric') or 'unknown'}")
    if replay_metric != "500/500":
        stale.append(f"AI UI 500 replay is not current green: {replay_metric or 'no metric'}")
        required_commands.append(f"python3 tools/ai_ui_intent_quality_replay.py --label {command_label_for_ai_ui_replay()} --json")
    else:
        current.append("AI UI 500 replay is green at 500/500")
    if export_status != "pass":
        stale.append("Public export is stale or privacy scan is not green")
        required_commands.append("python3 tools/build_public_export.py --zip")
    else:
        current.append(str(export_item.get("metric") or "Public export is green"))
    standard_commands = [
        "python3 tools/build_public_export.py --zip",
        "curl -sS http://127.0.0.1:8765/api/package-health > /tmp/codex-package-health-fresh.json",
        f"python3 tools/ai_ui_intent_quality_replay.py --label {command_label_for_ai_ui_replay()} --json",
        "python3 tools/live_feedback_smoke.py --json",
    ]
    return {
        "summary": summary,
        "artifacts": artifacts,
        "inventory": inventory,
        "stale": stale,
        "current": current,
        "requiredCommands": list(dict.fromkeys(required_commands)),
        "commands": list(dict.fromkeys(standard_commands)),
        "packagePath": package_item.get("path") or "",
        "smokePath": smoke_item.get("path") or artifacts.get("smokePath") or "",
        "replayPath": replay_item.get("path") or artifacts.get("replayPath") or "",
        "exportPath": export_item.get("path") or "",
        "checkpointPath": artifacts.get("checkpointPath") or str(latest_matching_file(WORK_CHECKPOINT_DIR, "*.md") or ""),
    }


def freshen_receipts_direct_answer(messages):
    if not is_freshen_receipts_question(messages):
        return ""
    plan = freshen_receipts_plan()
    stale = plan.get("stale") or []
    current = plan.get("current") or []
    commands = plan.get("commands") or []
    stale_text = "; ".join(stale) if stale else "no stale required receipt groups found in the saved summary"
    current_text = "; ".join(current[:4]) if current else "no green receipt groups found"
    command_lines = "\n".join(f"- `{command}`" for command in commands)
    return "\n\n".join(
        [
            "Read-only freshen-receipts plan for Codex CLI UI: I did not run any refresh commands.",
            f"Stale or refresh-worthy items: {stale_text}. Current green items: {current_text}.",
            f"Commands to run, in order, when Tinman wants fresh receipts:\n{command_lines}",
            (
                f"Receipt paths: package-health `{plan.get('packagePath') or 'no path'}`; "
                f"live smoke `{plan.get('smokePath') or 'no path'}`; "
                f"AI UI 500 replay `{plan.get('replayPath') or 'no path'}`; "
                f"public export `{plan.get('exportPath') or 'no path'}`; "
                f"checkpoint `{plan.get('checkpointPath') or 'no path'}`."
            ),
            (
                "This is why: I compared the saved verification summary with the live smoke inventory and public-export freshness state, "
                "then produced commands instead of mutating files or running long tests automatically."
            ),
            (
                "You should also consider: after running any refresh command, ask for the latest receipts bundle again. "
                "GitHub push remains paused, and human-QA PASS still requires Preview-first, Record-second evidence."
            ),
        ]
    )


