def ai_ui_intent_human_qa_lane_plan_direct_answer(messages):
    if not is_ai_ui_intent_human_qa_lane_plan_question(messages):
        return ""
    query = latest_user_text(messages).lower()
    definitions = ai_ui_intent_human_qa_lane_definitions()
    lane = next((definition for definition in definitions if definition["term"] in query), definitions[0])
    audit_path = APP_DIR / "tests" / "ai_ui_intent_500_audit.json"
    data = read_json(audit_path, {})
    items = data.get("items") if isinstance(data, dict) else []
    if not isinstance(items, list):
        items = []
    lane_items = [
        item
        for item in items
        if str(item.get("status") or "").upper() == "PARTIAL"
        and lane["categoryTerm"] in str(item.get("category") or "").lower()
    ]
    samples = "; ".join(f"Q{item.get('id')}: {item.get('question')}" for item in lane_items[:5])
    sample_sentence = f"Start with: {samples}" if samples else "Start with the first five matching audit questions."
    checks = "\n".join(f"- {check}" for check in lane["checks"])
    latest_report = latest_matching_file(DATA_DIR / "golden_batch_results", "*-ai-ui-intent-human-qa-lanes.md")
    report_sentence = f" Latest lane report: `{latest_report}`." if latest_report else ""
    if not lane_items:
        return "\n\n".join(
            [
                f"I do not see PARTIAL items for {lane['label']} in the current AI UI intent audit.",
                f"This is why: I read `{audit_path}` and did not find matching PARTIAL questions for `{lane['categoryTerm']}`.",
                "You should also consider: rerun the lane report if the audit file was just regenerated.",
            ]
        )
    return "\n\n".join(
        [
            f"Run {lane['label']} as a human-QA lane with {len(lane_items)} PARTIAL items. {sample_sentence}",
            f"Checklist:\n{checks}",
            f"PASS criteria: {lane['passCriteria']} Do not mark the lane PASS until this review is actually complete.",
            f"This is why: I read `{audit_path}` and selected the `{lane['categoryTerm']}` PARTIAL questions instead of guessing from memory.{report_sentence}",
            "You should also consider: record any failed sample as a new regression or package-health check, then rerun the focused live `/api/run` case before changing the audit status.",
        ]
    )


