def cleanup_ai_ui_human_qa_pack_retention(root=None, keep=None):
    pack_root = Path(root) if root else LOCAL_QUALITY_OUTPUT_DIR / "ai-ui-human-qa"
    keep_count = max(1, int(keep if keep is not None else AI_UI_HUMAN_QA_PACK_RETENTION))
    if not pack_root.exists():
        return {"root": str(pack_root), "kept": 0, "removed": 0}
    pack_dirs = []
    for candidate in pack_root.iterdir():
        if not candidate.is_dir():
            continue
        if not candidate.name.endswith(("-all-lanes", "-remaining-lanes")):
            continue
        try:
            mtime = candidate.stat().st_mtime
        except OSError:
            continue
        pack_dirs.append((mtime, candidate.name, candidate))
    pack_dirs.sort(reverse=True)
    removed = 0
    for _, _, old_pack in pack_dirs[keep_count:]:
        try:
            shutil.rmtree(old_pack)
            removed += 1
        except OSError:
            continue
    return {"root": str(pack_root), "kept": min(len(pack_dirs), keep_count), "removed": removed}


def directory_tree_size_bytes(path):
    total = 0
    try:
        iterator = Path(path).rglob("*")
    except OSError:
        return 0
    for item in iterator:
        try:
            if item.is_file():
                total += item.stat().st_size
        except OSError:
            continue
    return total


def cleanup_checkpoint_directory_retention(root, keep, preserve_terms=None, protect_paths=None):
    checkpoint_root = Path(root)
    keep_count = max(1, int(keep))
    preserve_terms = tuple(str(term).lower() for term in (preserve_terms or CHECKPOINT_RETENTION_PRESERVE_TERMS))
    protected = {Path(path).resolve() for path in (protect_paths or []) if path}
    if not checkpoint_root.exists():
        return {"root": str(checkpoint_root), "kept": 0, "removed": 0, "preserved": 0, "freedBytes": 0}
    try:
        children = list(checkpoint_root.iterdir())
    except OSError:
        return {"root": str(checkpoint_root), "kept": 0, "removed": 0, "preserved": 0, "freedBytes": 0}
    candidates = []
    preserved = []
    for candidate in children:
        if not candidate.is_dir():
            continue
        try:
            resolved = candidate.resolve()
            mtime = candidate.stat().st_mtime
        except OSError:
            continue
        name = candidate.name.lower()
        if resolved in protected or any(term in name for term in preserve_terms):
            preserved.append(candidate)
            continue
        candidates.append((mtime, candidate.name, candidate))
    candidates.sort(reverse=True)
    keep_paths = {path for _mtime, _name, path in candidates[:keep_count]}
    removed = 0
    freed = 0
    for _mtime, _name, path in candidates:
        if path in keep_paths:
            continue
        freed += directory_tree_size_bytes(path)
        try:
            shutil.rmtree(path)
            removed += 1
        except OSError:
            continue
    return {
        "root": str(checkpoint_root),
        "kept": len(keep_paths),
        "removed": removed,
        "preserved": len(preserved),
        "freedBytes": freed,
    }


def cleanup_checkpoint_retention(local_keep=None, work_keep=None):
    return {
        "local": cleanup_checkpoint_directory_retention(
            LOCAL_CHECKPOINT_DIR,
            local_keep if local_keep is not None else LOCAL_CHECKPOINT_RETENTION,
        ),
        "work": cleanup_checkpoint_directory_retention(
            WORK_CHECKPOINT_DIR,
            work_keep if work_keep is not None else WORK_CHECKPOINT_RETENTION,
        ),
    }


def storage_retention_dir_counts(root, candidate_fn):
    path = Path(root)
    counts = {"root": str(path), "candidates": 0, "preserved": 0, "totalDirs": 0}
    if not path.exists():
        return counts
    try:
        children = list(path.iterdir())
    except OSError:
        return counts
    for entry in children:
        try:
            is_dir = entry.is_dir()
        except OSError:
            continue
        if not is_dir:
            continue
        counts["totalDirs"] += 1
        try:
            if candidate_fn(entry):
                counts["candidates"] += 1
            else:
                counts["preserved"] += 1
        except Exception:
            counts["preserved"] += 1
    return counts


def storage_retention_smoke_receipt_counts(root=None):
    path = Path(root or DATA_DIR / "live_feedback_smoke_results")
    counts = {"root": str(path), "passing": 0, "preserved": 0, "unreadable": 0, "totalFiles": 0}
    if not path.exists():
        return counts
    try:
        children = list(path.glob("*.json"))
    except OSError:
        return counts
    for receipt_path in children:
        if not receipt_path.is_file():
            continue
        counts["totalFiles"] += 1
        try:
            data = json.loads(receipt_path.read_text(encoding="utf-8"))
        except (OSError, json.JSONDecodeError):
            counts["unreadable"] += 1
            counts["preserved"] += 1
            continue
        if data.get("status") == "pass" and int(data.get("failed") or 0) == 0:
            counts["passing"] += 1
        else:
            counts["preserved"] += 1
    return counts


def storage_retention_bounds_snapshot(buffer=None):
    active_buffer = max(0, int(STORAGE_RETENTION_ACTIVE_RUN_BUFFER if buffer is None else buffer))
    checkpoint_preserve_terms = tuple(str(term).lower() for term in CHECKPOINT_RETENTION_PRESERVE_TERMS)
    checks = []
    counts = {}

    def add_dir_bound(key, root, keep, candidate_fn):
        item = storage_retention_dir_counts(root, candidate_fn)
        limit = int(keep) + active_buffer
        item["limit"] = limit
        item["ok"] = item["candidates"] <= limit
        counts[key] = item
        checks.append((key, item["ok"], item["candidates"], limit, item.get("preserved", 0)))

    add_dir_bound(
        "cad",
        LOCAL_CAD_OUTPUT_DIR,
        CAD_OUTPUT_RETENTION,
        lambda entry: bool(GENERATED_OUTPUT_TIMESTAMP_RE.match(entry.name)),
    )
    add_dir_bound(
        "wind",
        LOCAL_WIND_TURBINE_OUTPUT_DIR,
        WIND_TURBINE_OUTPUT_RETENTION,
        lambda entry: bool(GENERATED_OUTPUT_TIMESTAMP_RE.match(entry.name)),
    )
    add_dir_bound(
        "diagrams",
        LOCAL_DIAGRAM_OUTPUT_DIR,
        DIAGRAM_OUTPUT_RETENTION,
        lambda entry: bool(GENERATED_OUTPUT_TIMESTAMP_RE.match(entry.name)),
    )
    add_dir_bound(
        "orca",
        LOCAL_ORCA_PROFILE_OUTPUT_DIR,
        ORCA_PROFILE_OUTPUT_RETENTION,
        lambda entry: bool(GENERATED_OUTPUT_TIMESTAMP_RE.match(entry.name)),
    )
    add_dir_bound(
        "aero",
        LOCAL_AERO_OUTPUT_DIR,
        AERO_CFD_OUTPUT_RETENTION,
        lambda entry: not entry.name.startswith("_health"),
    )
    add_dir_bound(
        "quality",
        LOCAL_QUALITY_OUTPUT_DIR,
        QUALITY_GATE_TEMP_RETENTION,
        lambda entry: entry.name.startswith("quality-gate-"),
    )
    add_dir_bound(
        "localCheckpoints",
        LOCAL_CHECKPOINT_DIR,
        LOCAL_CHECKPOINT_RETENTION,
        lambda entry: not any(term in entry.name.lower() for term in checkpoint_preserve_terms),
    )
    add_dir_bound(
        "workCheckpoints",
        WORK_CHECKPOINT_DIR,
        WORK_CHECKPOINT_RETENTION,
        lambda entry: not any(term in entry.name.lower() for term in checkpoint_preserve_terms),
    )

    smoke = storage_retention_smoke_receipt_counts()
    smoke_limit = LIVE_FEEDBACK_SMOKE_RECEIPT_RETENTION + active_buffer
    smoke["limit"] = smoke_limit
    smoke["ok"] = smoke["passing"] <= smoke_limit
    counts["liveFeedbackSmoke"] = smoke
    checks.append(("liveFeedbackSmoke", smoke["ok"], smoke["passing"], smoke_limit, smoke.get("preserved", 0)))

    ok = all(item[1] for item in checks)
    detail = "; ".join(
        f"{name}={candidate}/{limit}, preserved={preserved}"
        for name, _ok, candidate, limit, preserved in checks
    )
    return {
        "ok": ok,
        "buffer": active_buffer,
        "counts": counts,
        "detail": f"live storage retention bounds {'ok' if ok else 'exceeded'}: {detail}",
    }


def latest_ai_ui_human_qa_pack_receipt(root=None, pack_kind="all-lanes"):
    pack_root = Path(root) if root else LOCAL_QUALITY_OUTPUT_DIR / "ai-ui-human-qa"
    if not pack_root.exists():
        return {}
    pack_kind = str(pack_kind or "all-lanes")
    candidates = []
    for candidate in pack_root.glob(f"*-{pack_kind}"):
        if not candidate.is_dir():
            continue
        manifest_path = candidate / "AI_UI_HUMAN_QA_WORKSHEET_PACK.json"
        index_path = candidate / "AI_UI_HUMAN_QA_WORKSHEET_PACK.md"
        if not manifest_path.exists() or not index_path.exists():
            continue
        try:
            candidates.append((candidate.stat().st_mtime, candidate, manifest_path, index_path))
        except OSError:
            continue
    if not candidates:
        return {}
    _, pack_dir, manifest_path, index_path = max(candidates, key=lambda item: item[0])
    manifest = read_json(manifest_path, {})
    if not isinstance(manifest, dict):
        return {}
    return {
        "packDir": str(pack_dir),
        "indexPath": str(index_path),
        "manifestPath": str(manifest_path),
        "createdAt": manifest.get("createdAt") or "",
        "packKind": manifest.get("packKind") or pack_kind,
        "laneCount": int(manifest.get("laneCount") or 0),
        "fullLaneCount": int(manifest.get("fullLaneCount") or 0),
        "partialCount": int(manifest.get("partialCount") or 0),
        "totalAuditPartialCount": int(manifest.get("totalAuditPartialCount") or 0),
        "sourceAudit": manifest.get("sourceAudit") or "",
        "worksheets": manifest.get("worksheets") if isinstance(manifest.get("worksheets"), list) else [],
    }


def stage_ai_ui_intent_human_qa_worksheet(messages=None, lane_term="", target_path=None):
    query = latest_user_text(messages or []).lower() if messages else str(lane_term or "").lower()
    lane = select_ai_ui_intent_human_qa_lane(query)
    audit_path = APP_DIR / "tests" / "ai_ui_intent_500_audit.json"
    data = read_json(audit_path, {})
    items = data.get("items") if isinstance(data, dict) else []
    if not isinstance(items, list):
        items = []
    lane_items = [
        item
        for item in items
        if str(item.get("status") or "").upper() == "PARTIAL"
        and lane["categoryTerm"] in str(item.get("category") or "").lower()
    ]
    stamp = time.strftime("%Y%m%dT%H%M%SZ", time.gmtime())
    output_root = Path(target_path) if target_path else LOCAL_QUALITY_OUTPUT_DIR / "ai-ui-human-qa"
    output_dir = output_root / f"{stamp}-{slugify(lane['label'], 'human-qa-lane')}"
    output_dir.mkdir(parents=True, exist_ok=True)
    json_path = output_dir / f"{slugify(lane['label'], 'human-qa-lane')}.json"
    md_path = output_dir / f"{slugify(lane['label'], 'human-qa-lane')}.md"
    worksheet = {
        "createdAt": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()),
        "sourceAudit": str(audit_path),
        "lane": lane["term"],
        "laneLabel": lane["label"],
        "partialCount": len(lane_items),
        "passCriteria": lane["passCriteria"],
        "checklist": lane["checks"],
        "items": [
            {
                "id": item.get("id"),
                "category": item.get("category"),
                "question": item.get("question"),
                "status": item.get("status"),
                "evidence": item.get("evidence") or [],
                "note": item.get("note") or "",
                "reviewResult": "",
                "reviewNotes": "",
                "followupRegression": "",
            }
            for item in lane_items
        ],
    }
    write_json_atomic(json_path, worksheet)
    lines = [
        f"# {lane['label']} Worksheet",
        "",
        f"- Source audit: `{audit_path}`",
        f"- PARTIAL items: {len(lane_items)}",
        f"- PASS criteria: {lane['passCriteria']}",
        "- Status: not reviewed",
        "",
        "## Checklist",
    ]
    lines.extend(f"- [ ] {check}" for check in lane["checks"])
    lines.extend(
        [
            "",
            "## Review Items",
            "",
            "| ID | Question | Automated Evidence | Human Result | Notes | Follow-up Regression |",
            "| --- | --- | --- | --- | --- | --- |",
        ]
    )
    for item in lane_items:
        evidence = ", ".join(str(value) for value in (item.get("evidence") or [])[:4])
        question = str(item.get("question") or "").replace("|", "\\|")
        note = str(item.get("note") or "").replace("|", "\\|")
        lines.append(
            f"| Q{item.get('id')} | {question} | {evidence} | TODO | {note} | TODO |"
        )
    lines.extend(
        [
            "",
            "## Completion Rule",
            "",
            "Do not change these audit items to PASS until every worksheet row has a human result, any failure has a regression or package-health check, and the focused live `/api/run` proof is green.",
        ]
    )
    md_path.write_text("\n".join(lines) + "\n", encoding="utf-8")
    return {
        "ok": bool(lane_items) and md_path.exists() and json_path.exists(),
        "lane": lane,
        "partialCount": len(lane_items),
        "jsonPath": str(json_path),
        "markdownPath": str(md_path),
        "sourceAudit": str(audit_path),
    }


def stage_ai_ui_intent_all_human_qa_worksheets(target_path=None, active_only=False):
    stamp = time.strftime("%Y%m%dT%H%M%SZ", time.gmtime())
    persistent_output = target_path is None
    pack_kind = "remaining-lanes" if active_only else "all-lanes"
    pack_root = Path(target_path) if target_path else LOCAL_QUALITY_OUTPUT_DIR / "ai-ui-human-qa" / f"{stamp}-{pack_kind}"
    pack_root.mkdir(parents=True, exist_ok=True)
    audit_path = APP_DIR / "tests" / "ai_ui_intent_500_audit.json"
    audit_data = read_json(audit_path, {})
    audit_items = audit_data.get("items") if isinstance(audit_data, dict) else []
    if not isinstance(audit_items, list):
        audit_items = []
    expected_partial_count = sum(1 for item in audit_items if str(item.get("status") or "").upper() == "PARTIAL")
    definitions = ai_ui_intent_human_qa_lane_definitions()
    if active_only:
        active_categories = set()
        for item in audit_items:
            if str(item.get("status") or "").upper() != "PARTIAL":
                continue
            category = str(item.get("category") or "").lower()
            for definition in definitions:
                if definition["categoryTerm"] in category:
                    active_categories.add(definition["categoryTerm"])
                    break
        definitions = [definition for definition in definitions if definition["categoryTerm"] in active_categories]
    results = []
    for definition in definitions:
        result = stage_ai_ui_intent_human_qa_worksheet(lane_term=definition["term"], target_path=pack_root)
        results.append(result)
    manifest_path = pack_root / "AI_UI_HUMAN_QA_WORKSHEET_PACK.json"
    index_path = pack_root / "AI_UI_HUMAN_QA_WORKSHEET_PACK.md"
    total_items = sum(int(result.get("partialCount") or 0) for result in results)
    full_lane_count = len(ai_ui_intent_human_qa_lane_definitions())
    manifest = {
        "createdAt": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()),
        "sourceAudit": str(audit_path),
        "packKind": pack_kind,
        "laneCount": len(results),
        "fullLaneCount": full_lane_count,
        "partialCount": total_items,
        "totalAuditPartialCount": expected_partial_count,
        "worksheets": [
            {
                "lane": (result.get("lane") or {}).get("term"),
                "laneLabel": (result.get("lane") or {}).get("label"),
                "partialCount": result.get("partialCount"),
                "markdownPath": result.get("markdownPath"),
                "jsonPath": result.get("jsonPath"),
                "ok": result.get("ok"),
            }
            for result in results
        ],
    }
    write_json_atomic(manifest_path, manifest)
    title = "AI UI Remaining Human-QA Worksheet Pack" if active_only else "AI UI Human-QA Worksheet Pack"
    lines = [
        f"# {title}",
        "",
        f"- Source audit: `{manifest['sourceAudit']}`",
        f"- Lanes: {manifest['laneCount']}",
        f"- Pack kind: {pack_kind}",
        f"- PARTIAL items: {manifest['partialCount']}",
        "- Status: not reviewed",
        "",
        "## Worksheets",
    ]
    for entry in manifest["worksheets"]:
        lines.append(
            f"- {entry.get('laneLabel')}: {entry.get('partialCount')} items. "
            f"Open: `{entry.get('markdownPath')}`"
        )
    lines.extend(
        [
            "",
            "## Completion Rule",
            "",
            "Do not change any audit lane to PASS until the matching worksheet is reviewed, failed rows become regressions or package-health checks, and the focused live `/api/run` proof is green.",
        ]
    )
    index_path.write_text("\n".join(lines) + "\n", encoding="utf-8")
    active_results = [result for result in results if int(result.get("partialCount") or 0) > 0]
    expected_lane_count = len(definitions) if active_only else full_lane_count
    pack_ok = (
        len(results) == expected_lane_count
        and total_items == expected_partial_count
        and all(result.get("ok") for result in active_results)
        and all(Path(result.get("markdownPath") or "").exists() for result in results)
        and all(Path(result.get("jsonPath") or "").exists() for result in results)
        and manifest_path.exists()
        and index_path.exists()
    )
    retention = cleanup_ai_ui_human_qa_pack_retention() if persistent_output else {"removed": 0}
    return {
        "ok": pack_ok,
        "packKind": pack_kind,
        "laneCount": len(results),
        "fullLaneCount": full_lane_count,
        "partialCount": total_items,
        "totalAuditPartialCount": expected_partial_count,
        "indexPath": str(index_path),
        "manifestPath": str(manifest_path),
        "worksheets": manifest["worksheets"],
        "retention": retention,
    }


