def ai_ui_human_qa_review_status_direct_answer(messages):
    if not is_ai_ui_human_qa_review_status_question(messages):
        return ""
    query = latest_user_text(messages).lower()
    pack_kind = "all-lanes" if "all-lanes" in query or "all lanes" in query or "complete pack" in query else "remaining-lanes"
    report = ai_ui_human_qa_review_status_receipt(pack_kind=pack_kind, write_report=True)
    if not report.get("ok"):
        return "\n\n".join(
            [
                f"I cannot check the AI UI human-QA review status yet because I do not see a `{pack_kind}` worksheet pack.",
                f"This is why: {report.get('error') or 'the worksheet pack manifest was missing'}.",
                "You should also consider: create the remaining AI UI human-QA worksheet pack first, then ask for the review status again.",
            ]
        )
    lane_text = "; ".join(
        f"{lane.get('laneLabel')}: reviewed {lane.get('reviewed')}/{lane.get('total')}"
        for lane in report.get("lanes", [])
    )
    requested_lane = None
    if "production" in query or "release-readiness" in query or "release readiness" in query:
        requested_lane = next((lane for lane in report.get("lanes", []) if "production" in str(lane.get("laneLabel") or "").lower()), None)
    elif "accessibility" in query or "assistive" in query or "screen reader" in query or "keyboard" in query:
        requested_lane = next((lane for lane in report.get("lanes", []) if "accessibility" in str(lane.get("laneLabel") or "").lower()), None)
    if requested_lane:
        lane_label = requested_lane.get("laneLabel") or "Requested lane"
        reviewed = int(requested_lane.get("reviewed") or 0)
        total = int(requested_lane.get("total") or 0)
        missing = int(requested_lane.get("missing") or 0)
        failed_without_regression = int(requested_lane.get("failedWithoutRegression") or 0)
        blocked = int(requested_lane.get("blocked") or 0)
        samples = ", ".join(requested_lane.get("missingSamples") or []) or "none"
        if requested_lane.get("readyForPass"):
            lead = f"Yes. {lane_label} is ready for PASS review: {reviewed}/{total} rows have human results."
        else:
            lead = (
                f"No. {lane_label} is not ready for PASS: {reviewed}/{total} rows have human results, "
                f"{missing} rows are still missing review, {failed_without_regression} failed rows lack follow-up regressions, "
                f"and {blocked} rows are blocked."
            )
        return "\n\n".join(
            [
                lead,
                f"Missing sample rows: {samples}.",
                f"Review-status receipt: `{report.get('markdownPath')}`. Machine-readable receipt: `{report.get('jsonPath')}`.",
                f"This is why: I read the {lane_label} worksheet JSON rows from `{requested_lane.get('worksheetPath')}` and counted `reviewResult` plus `followupRegression` fields instead of treating the worksheet pack itself as completed human review.",
                "You should also consider: keep this lane PARTIAL until the missing rows are reviewed, failed rows have regressions, blocked rows are resolved, and focused live `/api/run` proof is green.",
            ]
        )
    if report.get("readyForPass"):
        lead = f"Yes. The `{pack_kind}` AI UI human-QA worksheet pack is ready for PASS review: {report.get('reviewedRows')}/{report.get('totalRows')} rows have human results."
    else:
        lead = (
            f"No. The `{pack_kind}` AI UI human-QA worksheet pack is not ready for PASS: "
            f"{report.get('reviewedRows')}/{report.get('totalRows')} rows have human results, "
            f"{report.get('missingRows')} rows are still missing review, "
            f"{report.get('failedWithoutRegression')} failed rows lack follow-up regressions, "
            f"and {report.get('blockedRows')} rows are blocked."
        )
    return "\n\n".join(
        [
            lead,
            f"Lane status: {lane_text}.",
            f"Review-status receipt: `{report.get('markdownPath')}`. Machine-readable receipt: `{report.get('jsonPath')}`.",
            f"This is why: I read the worksheet JSON rows from `{report.get('packIndex')}` and counted `reviewResult` plus `followupRegression` fields instead of treating the worksheet pack itself as completed human review.",
            "You should also consider: keep these items PARTIAL until the missing rows are reviewed, failed rows have regressions, blocked rows are resolved, and focused live `/api/run` proof is green.",
        ]
    )


