def production_release_rehearsal_evidence_for_question(question):
    text = str(question or "").lower()
    evidence = []
    if "rollback" in text:
        evidence.append("rollback-rehearsal")
    if "incident" in text or "safety" in text or "defending" in text or "failure" in text:
        evidence.append("incident-response-rehearsal")
    if "failed tool" in text or "hallucination" in text or "wrong answer" in text or "latency" in text or "downtime" in text or "monitoring" in text:
        evidence.append("monitoring-review")
    if "privacy" in text or "data handling" in text:
        evidence.append("privacy-export-review")
    if "support" in text or "abuse" in text or "disclosure" in text or "feedback" in text:
        evidence.append("support-disclosure-review")
    if "legal" in text or "claims" in text or "commercial" in text:
        evidence.append("public-claims-review")
    if "approver" in text or "approval" in text or "ownership" in text:
        evidence.append("launch-approval")
    if "model" in text or "release notes" in text or "ai behavior" in text:
        evidence.extend(["fresh-package-health", "monitoring-review", "public-claims-review"])
    if not evidence:
        evidence.append("fresh-package-health")
    return list(dict.fromkeys(evidence))


def rehearsal_evidence_entry_workflow_lines(kind, sample_row_id=None):
    kind = rehearsal_receipt_kind_from_lane(kind)
    row_id = str(sample_row_id or ("481" if kind == "production" else "321")).strip().lstrip("#Qq")
    if kind == "accessibility":
        lane_label = "Accessibility"
        sample_receipt = "/path/to/keyboard-walkthrough.md"
        sample_notes = "keyboard walkthrough completed"
    else:
        lane_label = "Production"
        sample_receipt = "/path/to/rollback-rehearsal.md"
        sample_notes = "rollback rehearsal completed"
    return [
        "",
        "## Evidence Entry Workflow",
        "",
        "Use Preview first, then Record only after the row, result, evidence receipt, notes, and reviewer look correct.",
        "",
        f"- Preview: `Preview {lane_label} Q{row_id} as pass with evidence receipt '{sample_receipt}', notes '{sample_notes}', reviewer 'Tinman'.`",
        f"- Record: `Record {lane_label} Q{row_id} as pass with evidence receipt '{sample_receipt}', notes '{sample_notes}', reviewer 'Tinman'.`",
        "- One row per command. Failed rows also require a follow-up regression or package-health check.",
    ]


def stage_production_release_rehearsal_receipt(target_path=None, pack_root=None):
    pack_kind = "remaining-lanes"
    receipt = latest_ai_ui_human_qa_pack_receipt(root=pack_root, pack_kind=pack_kind)
    if not receipt and pack_root is None:
        stage_ai_ui_intent_all_human_qa_worksheets(active_only=True)
        receipt = latest_ai_ui_human_qa_pack_receipt(pack_kind=pack_kind)
    if not receipt:
        return {
            "ok": False,
            "status": "missing-pack",
            "readyForPass": False,
            "error": "no remaining-lanes AI UI human-QA worksheet pack found",
            "jsonPath": "",
            "markdownPath": "",
        }
    production_entry = next(
        (
            entry
            for entry in receipt.get("worksheets", [])
            if "production" in str(entry.get("laneLabel") or "").lower()
        ),
        None,
    )
    if not production_entry:
        return {
            "ok": False,
            "status": "missing-production-lane",
            "readyForPass": False,
            "error": "remaining-lanes pack did not include the Production release-readiness worksheet",
            "jsonPath": "",
            "markdownPath": "",
        }
    worksheet_path = Path(production_entry.get("jsonPath") or "")
    worksheet = read_json(worksheet_path, {}) if worksheet_path.exists() else {}
    items = worksheet.get("items") if isinstance(worksheet, dict) else []
    if not isinstance(items, list):
        items = []
    stamp = time.strftime("%Y%m%dT%H%M%SZ", time.gmtime())
    output_root = Path(target_path) if target_path else LOCAL_QUALITY_OUTPUT_DIR / "ai-ui-human-qa" / "production-rehearsals"
    output_dir = output_root / f"{stamp}-production-release-readiness-rehearsal"
    output_dir.mkdir(parents=True, exist_ok=True)
    json_path = output_dir / "production-release-readiness-rehearsal.json"
    md_path = output_dir / "production-release-readiness-rehearsal.md"
    docs = [
        str(APP_DIR / "docs" / "production-readiness-playbook.md"),
        str(APP_DIR / "docs" / "release-checklist.md"),
        str(APP_DIR / "docs" / "public-release-plan.md"),
        str(APP_DIR / "docs" / "support.md"),
        str(APP_DIR / "docs" / "security.md"),
    ]
    evidence_plan = production_release_rehearsal_evidence_plan()
    evidence_by_id = {item["id"]: item for item in evidence_plan}
    rows = []
    for item in items:
        evidence_ids = production_release_rehearsal_evidence_for_question(item.get("question"))
        rows.append(
            {
                "id": item.get("id"),
                "question": item.get("question"),
                "sourceStatus": item.get("status"),
                "automatedEvidence": item.get("evidence") or [],
                "requiredEvidence": evidence_ids,
                "requiredEvidenceLabels": [evidence_by_id[evidence_id]["label"] for evidence_id in evidence_ids if evidence_id in evidence_by_id],
                "humanResult": "",
                "evidenceReceipt": "",
                "followupRegression": "",
                "notes": "",
            }
        )
    report = {
        "createdAt": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()),
        "status": "not-run",
        "ok": True,
        "readyForPass": False,
        "laneLabel": production_entry.get("laneLabel") or "Production release-readiness review",
        "partialCount": len(items),
        "reviewedRows": 0,
        "worksheetPath": str(worksheet_path),
        "packKind": receipt.get("packKind") or pack_kind,
        "packIndex": receipt.get("indexPath"),
        "packManifest": receipt.get("manifestPath"),
        "sourceDocs": docs,
        "requiredEvidence": evidence_plan,
        "rows": rows,
        "completionRule": "Do not mark Production PASS until every row has a human result, required evidence receipt, any failed-row regression, a focused live `/api/run` proof, and Tinman's explicit launch approval.",
    }
    report["jsonPath"] = str(json_path)
    report["markdownPath"] = str(md_path)
    write_json_atomic(json_path, report)
    lines = [
        "# Production Release-Readiness Rehearsal Receipt",
        "",
        "- Status: not run",
        "- Ready for PASS: no",
        f"- Current lane hold: {len(items)} PARTIAL",
        f"- Worksheet: `{worksheet_path}`",
        f"- Pack index: `{receipt.get('indexPath')}`",
        f"- Machine-readable receipt: `{json_path}`",
        "",
        "Do not mark Production PASS until every row below has a human result, a concrete evidence receipt, any failed-row regression, focused live `/api/run` proof, and Tinman's explicit launch approval.",
    ]
    lines.extend(rehearsal_evidence_entry_workflow_lines("production", rows[0].get("id") if rows else 481))
    lines.extend(
        [
            "",
            "## Evidence Checklist",
            "",
            "| Evidence | Required Proof | Receipt / Notes |",
            "| --- | --- | --- |",
        ]
    )
    for item in evidence_plan:
        proof = item["proof"].replace("|", "\\|")
        lines.append(f"| {item['label']} | {proof} | TODO |")
    lines.extend(
        [
            "",
            "## Worksheet Rows",
            "",
            "| ID | Question | Required Evidence | Human Result | Evidence Receipt | Follow-up Regression |",
            "| --- | --- | --- | --- | --- | --- |",
        ]
    )
    for row in rows:
        question = str(row.get("question") or "").replace("|", "\\|")
        labels = ", ".join(row.get("requiredEvidenceLabels") or []).replace("|", "\\|")
        lines.append(f"| Q{row.get('id')} | {question} | {labels} | TODO | TODO | TODO |")
    lines.extend(
        [
            "",
            "## Source Docs",
            "",
        ]
    )
    lines.extend(f"- `{doc}`" for doc in docs)
    lines.extend(
        [
            "",
            "## Completion Rule",
            "",
            report["completionRule"],
        ]
    )
    md_path.write_text("\n".join(lines) + "\n", encoding="utf-8")
    return report


def is_production_release_rehearsal_request(messages):
    query = latest_user_text(messages).lower()
    if not query:
        return False
    if not ("production" in query and ("release-readiness" in query or "release readiness" in query or "release" in query)):
        return False
    if not text_has_any(query, ("rehearsal", "drill", "dry run", "tabletop", "receipt", "template", "checklist")):
        return False
    return text_has_any(query, ("create", "generate", "stage", "make", "build", "prepare", "run"))


