def accessibility_rehearsal_evidence_plan():
    return [
        {
            "id": "keyboard-only-walkthrough",
            "label": "keyboard-only walkthrough",
            "proof": "Tab and Shift-Tab through New Chat, Projects, Admin, Chats, Tests, chat messages, attachment, composer, Send, run controls, and Run Log; verify Command/Control Enter, Command/Control Period, Escape, Option C, Option L, and Option N.",
        },
        {
            "id": "voiceover-screen-reader-walkthrough",
            "label": "VoiceOver/screen-reader walkthrough",
            "proof": "Use VoiceOver or another real screen reader to verify chat logs, user/Codex message identity, composer status, run-state announcements, Stop/cancel state, attachment chips, local file links, and error/recovery messages.",
        },
        {
            "id": "visual-text-scale-review",
            "label": "visual focus and text-scale review",
            "proof": "Verify contrast, visible focus rings, status not conveyed by color alone, 150 percent and 200 percent text scaling, mobile width, and reduced-motion behavior.",
        },
        {
            "id": "media-transcript-review",
            "label": "captions/transcripts media review",
            "proof": "For any audio/video work, confirm the answer includes a text transcript, caption file, or concise text summary plus a clickable text receipt; visible chat text remains usable without hearing audio.",
        },
        {
            "id": "optional-voice-input-review",
            "label": "optional voice input review",
            "proof": "Verify typed text, file attach, edit question, steering, stopping, review, and keyboard shortcuts work without microphone permission or a browser speech API.",
        },
        {
            "id": "assistive-tech-input-review",
            "label": "assistive-tech input review",
            "proof": "Test attach, type, edit, steer, stop, reveal local file links, and read run output with actual assistive technology rather than static markup alone.",
        },
        {
            "id": "plain-language-novice-review",
            "label": "plain-language novice review",
            "proof": "Have a non-expert or novice scenario verify that answers lead with the answer, explain `This is why:`, give a useful next step, and avoid burying the action in jargon.",
        },
        {
            "id": "slow-connection-accessibility-review",
            "label": "slow-connection accessibility review",
            "proof": "Run a slow or held task and verify visible text status, run state, steering, cancellation, local attachments/paths, and readable blockers remain usable.",
        },
    ]


def accessibility_rehearsal_evidence_for_question(question):
    text = str(question or "").lower()
    evidence = []
    if "screen reader" in text or "screen-reader" in text:
        evidence.extend(["voiceover-screen-reader-walkthrough", "keyboard-only-walkthrough", "slow-connection-accessibility-review"])
    if "caption" in text or "transcript" in text or "audio" in text or "video" in text:
        evidence.append("media-transcript-review")
    if "voice input" in text or "microphone" in text:
        evidence.append("optional-voice-input-review")
    if "plain-language" in text or "plain language" in text:
        evidence.append("plain-language-novice-review")
    if "assistive technology" in text or "assistive-tech" in text or "assistive" in text:
        evidence.extend(["assistive-tech-input-review", "keyboard-only-walkthrough", "voiceover-screen-reader-walkthrough"])
    if "low technical literacy" in text or "low technical" in text or "technical literacy" in text:
        evidence.append("plain-language-novice-review")
    if not evidence:
        evidence.extend(["keyboard-only-walkthrough", "visual-text-scale-review"])
    return list(dict.fromkeys(evidence))


