def latest_human_qa_rehearsal_receipt(kind, root=None):
    root_path = Path(root) if root else LOCAL_QUALITY_OUTPUT_DIR / "ai-ui-human-qa"
    if kind == "production":
        pattern = "production-rehearsals/*production-release-readiness-rehearsal/production-release-readiness-rehearsal.json"
    elif kind == "accessibility":
        pattern = "accessibility-rehearsals/*accessibility-assistive-tech-rehearsal/accessibility-assistive-tech-rehearsal.json"
    else:
        return {}
    try:
        candidates = [path for path in root_path.glob(pattern) if path.is_file()]
    except OSError:
        return {}
    if not candidates:
        return {}
    try:
        latest_path = max(candidates, key=lambda path: path.stat().st_mtime)
    except OSError:
        latest_path = candidates[-1]
    data = read_json(latest_path, {})
    if not isinstance(data, dict):
        data = {}
    data.setdefault("jsonPath", str(latest_path))
    markdown_path = str(data.get("markdownPath") or "")
    if not markdown_path:
        candidate_md = latest_path.with_suffix(".md")
        if candidate_md.exists():
            data["markdownPath"] = str(candidate_md)
    return data


def is_ai_ui_human_qa_next_row_question(messages):
    query = latest_user_text(messages).lower()
    if not query:
        return False
    if is_human_qa_evidence_update_request(messages):
        return False
    if text_has_any(query, ("create", "generate", "build", "stage", "make")) and text_has_any(
        query,
        ("worksheet", "rehearsal", "receipt", "pack", "dashboard"),
    ):
        return False
    scope = text_has_any(
        query,
        (
            "ai ui",
            "ai intent",
            "500 question",
            "500-question",
            "human qa",
            "human-qa",
            "human review",
            "qa review",
        ),
    )
    row_hint = text_has_any(
        query,
        (
            "next row",
            "first row",
            "exact row",
            "which row",
            "what row",
            "row should",
            "qa row",
            "review row",
            "which question",
            "what question",
            "exact question",
            "question should",
        ),
    ) or bool(re.search(r"\bq\s*#?\s*\d{1,4}\b", query, flags=re.I))
    return scope and row_hint


def requested_human_qa_rehearsal_kind(query):
    text = str(query or "").lower()
    if "production" in text or "release-readiness" in text or "release readiness" in text:
        return "production"
    if "accessibility" in text or "assistive" in text or "screen reader" in text or "voiceover" in text:
        return "accessibility"
    return ""


def first_unreviewed_human_qa_rehearsal_row(kind):
    report = latest_human_qa_rehearsal_receipt(kind)
    if not report:
        if kind == "production":
            stage_production_release_rehearsal_receipt()
        elif kind == "accessibility":
            stage_accessibility_rehearsal_receipt()
        report = latest_human_qa_rehearsal_receipt(kind)
    rows = report.get("rows") if isinstance(report.get("rows"), list) else []
    for row in rows:
        if not isinstance(row, dict):
            continue
        if not normalize_human_qa_review_result(row.get("humanResult")):
            return report, row
    return report, {}


def ai_ui_human_qa_next_row_direct_answer(messages):
    if not is_ai_ui_human_qa_next_row_question(messages):
        return ""
    query = latest_user_text(messages).lower()
    preferred_kind = requested_human_qa_rehearsal_kind(query)
    candidate_kinds = [preferred_kind] if preferred_kind else ["accessibility", "production"]
    candidate_kinds = [kind for kind in candidate_kinds if kind]
    selected_report = {}
    selected_row = {}
    selected_kind = ""
    for kind in candidate_kinds:
        report, row = first_unreviewed_human_qa_rehearsal_row(kind)
        if row:
            selected_report = report
            selected_row = row
            selected_kind = kind
            break
        if not selected_report:
            selected_report = report
            selected_kind = kind
    if not selected_row:
        if selected_report:
            lane_label = selected_report.get("laneLabel") or selected_kind or "requested lane"
            return "\n\n".join(
                [
                    f"I do not see an unreviewed AI UI human-QA row left in {lane_label}.",
                    f"Open this receipt: `{selected_report.get('markdownPath') or selected_report.get('jsonPath')}`",
                    f"This is why: I read the latest rehearsal receipt and every row already had a `humanResult` value.",
                    "You should also consider: run the review-status check before marking anything PASS; failed rows still need follow-up regressions, blocked rows must be resolved, and focused live `/api/run` proof must be green.",
                ]
            )
        return "\n\n".join(
            [
                "I could not choose the next AI UI human-QA row because I do not see a remaining-lanes rehearsal receipt yet.",
                "This is why: the next-row helper needs the generated Accessibility or Production rehearsal receipt so it can point to one exact row and avoid fake PASS promotion.",
                "You should also consider: create the remaining AI UI human-QA worksheet pack and the matching rehearsal receipt first, then ask for the next row again.",
            ]
        )
    lane_label = selected_report.get("laneLabel") or ("Accessibility and assistive-tech review" if selected_kind == "accessibility" else "Production release-readiness review")
    short_lane = "Accessibility" if selected_kind == "accessibility" else "Production"
    row_id = selected_row.get("id")
    question = selected_row.get("question") or "unknown question"
    labels = selected_row.get("requiredEvidenceLabels") if isinstance(selected_row.get("requiredEvidenceLabels"), list) else []
    required_evidence = ", ".join(str(label) for label in labels) or "required evidence listed in the rehearsal receipt"
    automated = ", ".join(str(value) for value in (selected_row.get("automatedEvidence") or [])[:4]) or "none listed"
    if selected_kind == "accessibility":
        sample_receipt = "/path/to/voiceover-screen-reader-walkthrough.md"
        sample_notes = "screen-reader and keyboard walkthrough completed"
    else:
        sample_receipt = "/path/to/rollback-rehearsal.md"
        sample_notes = "rollback rehearsal completed"
    preview = f"Preview {short_lane} Q{row_id} as pass with evidence receipt '{sample_receipt}', notes '{sample_notes}', reviewer 'Tinman'."
    record = f"Record {short_lane} Q{row_id} as pass with evidence receipt '{sample_receipt}', notes '{sample_notes}', reviewer 'Tinman'."
    reviewed = int(selected_report.get("reviewedRows") or 0)
    partial = int(selected_report.get("partialCount") or len(selected_report.get("rows") or []))
    return "\n\n".join(
        [
            f"Next AI UI human-QA row: {lane_label} Q{row_id} - {question}",
            f"Open this worksheet first: `{selected_report.get('worksheetPath')}`",
            f"Record evidence in this rehearsal receipt: `{selected_report.get('markdownPath')}`. Machine-readable receipt: `{selected_report.get('jsonPath')}`.",
            f"Required evidence: {required_evidence}. Automated evidence already present: {automated}.",
            f"Preview-first, Record-second:\n- Preview: `{preview}`\n- Record: `{record}`",
            f"This is why: I read the latest remaining-lanes rehearsal receipt and picked the first row with blank `humanResult`/`evidenceReceipt` instead of promoting anything automatically. Current lane progress is {reviewed}/{partial} rows reviewed.",
            "You should also consider: if the row fails, record it as `fail` with a follow-up regression or package-health check; if it is blocked, record `blocked` and keep the lane PARTIAL until the blocker is resolved and focused live `/api/run` proof is green.",
        ]
    )


def human_qa_row_id_from_query(query):
    match = re.search(r"\bq\s*#?\s*(\d{1,4})\b", str(query or ""), flags=re.I)
    if not match:
        match = re.search(r"\brow\s*#?\s*(\d{1,4})\b", str(query or ""), flags=re.I)
    return int(match.group(1)) if match else 0


def find_human_qa_rehearsal_row(row_id=0, preferred_kind=""):
    kinds = [preferred_kind] if preferred_kind else ["accessibility", "production"]
    kinds = [kind for kind in kinds if kind]
    for kind in kinds:
        report = latest_human_qa_rehearsal_receipt(kind)
        if not report:
            if kind == "production":
                stage_production_release_rehearsal_receipt()
            elif kind == "accessibility":
                stage_accessibility_rehearsal_receipt()
            report = latest_human_qa_rehearsal_receipt(kind)
        rows = report.get("rows") if isinstance(report.get("rows"), list) else []
        for row in rows:
            if not isinstance(row, dict):
                continue
            if row_id and int(row.get("id") or -1) != int(row_id):
                continue
            if not row_id and normalize_human_qa_review_result(row.get("humanResult")):
                continue
            return kind, report, row
    return "", {}, {}


def is_ai_ui_human_qa_evidence_receipt_request(messages):
    query = latest_user_text(messages).lower()
    if not query:
        return False
    if is_human_qa_evidence_update_request(messages):
        return False
    scope = text_has_any(
        query,
        (
            "ai ui",
            "ai intent",
            "500 question",
            "500-question",
            "human qa",
            "human-qa",
            "human review",
            "qa review",
        ),
    )
    evidence_hint = text_has_any(
        query,
        (
            "evidence file",
            "evidence receipt",
            "evidence template",
            "proof file",
            "proof receipt",
            "what evidence",
            "which evidence",
            "receipt should i create",
            "file should i create",
            "create for q",
            "make for q",
            "stage for q",
        ),
    )
    row_hint = bool(human_qa_row_id_from_query(query)) or text_has_any(query, ("next row", "next question", "exact row"))
    return scope and evidence_hint and row_hint


