def parse_ai_ui_human_qa_evidence_markdown_manual_result(path):
    md_path = Path(path or "")
    if not md_path.exists():
        return {}
    try:
        text = md_path.read_text(encoding="utf-8")
    except OSError:
        return {}
    fields = {}
    in_manual = False
    for raw_line in text.splitlines():
        line = raw_line.strip()
        if line.startswith("## "):
            in_manual = line.lower() == "## manual result"
            continue
        if not in_manual or not line.startswith("- ") or ":" not in line:
            continue
        label, value = line[2:].split(":", 1)
        key = AI_UI_HUMAN_QA_EVIDENCE_MD_FIELDS.get(label.strip().lower())
        if key:
            fields[key] = value.strip()
    return fields


def evidence_template_todo_value(value):
    text = str(value or "").strip()
    if not text:
        return True
    return text.lower() in {"todo", "n/a"} or text.lower().startswith("todo ")


def evidence_template_manual_result(receipt):
    manual = receipt.get("manualResult") if isinstance(receipt.get("manualResult"), dict) else {}
    combined = dict(manual)
    markdown_fields = parse_ai_ui_human_qa_evidence_markdown_manual_result(receipt.get("markdownPath"))
    for key, value in markdown_fields.items():
        if value and not evidence_template_todo_value(value):
            combined[key] = value
        elif key not in combined:
            combined[key] = value
    return combined


