def command_safe_value(value):
    return re.sub(r"\s+", " ", str(value or "").strip()).replace("'", "")


def evidence_template_record_commands(receipt):
    row_id = int(receipt.get("rowId") or 0)
    kind = rehearsal_receipt_kind_from_lane(receipt.get("lane") or receipt.get("laneLabel"))
    short_lane = "Accessibility" if kind == "accessibility" else "Production"
    manual = evidence_template_manual_result(receipt)
    result = normalize_rehearsal_human_result(manual.get("result")) or "pass"
    reviewer = command_safe_value(manual.get("tester") or "Tinman")
    notes = command_safe_value(manual.get("notes") or "")
    evidence_path = command_safe_value(receipt.get("markdownPath") or "")
    regression = command_safe_value(manual.get("followupRegression") or "")
    regression_part = f", follow-up regression '{regression}'" if result == "fail" and regression else ""
    preview = (
        f"Preview {short_lane} Q{row_id} as {result} with evidence receipt '{evidence_path}'"
        f"{regression_part}, notes '{notes}', reviewer '{reviewer}'."
    )
    record = (
        f"Record {short_lane} Q{row_id} as {result} with evidence receipt '{evidence_path}'"
        f"{regression_part}, notes '{notes}', reviewer '{reviewer}'."
    )
    return preview, record


def is_ai_ui_human_qa_evidence_summary_question(messages):
    query = latest_user_text(messages).lower()
    if not query:
        return False
    if is_human_qa_evidence_update_request(messages):
        return False
    if is_ai_ui_human_qa_evidence_record_command_request(messages):
        return False
    scope = text_has_any(
        query,
        (
            "ai ui human qa",
            "ai ui human-qa",
            "ai intent human qa",
            "ai intent human-qa",
            "500 question human qa",
            "500-question human qa",
            "human qa q",
            "human-qa q",
            "q321",
        ),
    )
    evidence_hint = text_has_any(
        query,
        (
            "evidence receipt",
            "evidence template",
            "evidence file",
            "manual walkthrough",
            "manual result",
        ),
    )
    summary_hint = text_has_any(
        query,
        (
            "summarize",
            "summary",
            "recap",
            "replay",
            "compare",
            "what does",
            "what is in",
            "what's in",
            "what fields",
            "missing fields",
            "still missing",
            "is it filled",
            "is it complete",
            "completion",
            "status of",
        ),
    )
    row_hint = bool(human_qa_row_id_from_query(query)) or text_has_any(
        query,
        (
            "screen reader",
            "screen-reader",
            "voiceover",
            "accessibility",
            "assistive",
        ),
    )
    return scope and evidence_hint and summary_hint and row_hint


def ai_ui_human_qa_evidence_summary_direct_answer(messages):
    if not is_ai_ui_human_qa_evidence_summary_question(messages):
        return ""
    query = latest_user_text(messages)
    row_id = human_qa_row_id_from_query(query) or 321
    preferred_kind = requested_human_qa_rehearsal_kind(query) or "accessibility"
    kind, report, row = find_human_qa_rehearsal_row(row_id=row_id, preferred_kind=preferred_kind)
    receipt = latest_ai_ui_human_qa_evidence_receipt(row_id=row_id, kind=kind or preferred_kind)
    if not receipt:
        lane_label = report.get("laneLabel") or ("Accessibility and assistive-tech review" if (kind or preferred_kind) == "accessibility" else "Production release-readiness review")
        question = row.get("question") if row else ""
        rehearsal_result = normalize_human_qa_review_result(row.get("humanResult")) if row else ""
        rehearsal_evidence = str(row.get("evidenceReceipt") or "").strip() if row else ""
        if row and (rehearsal_result or rehearsal_evidence):
            rehearsal_state = f"the rehearsal row already has `humanResult` `{rehearsal_result}` and `evidenceReceipt` `{rehearsal_evidence}`"
        elif row:
            rehearsal_state = "the rehearsal row still has blank `humanResult` and blank `evidenceReceipt`"
        else:
            rehearsal_state = "I could not find the matching rehearsal row in the latest local receipt"
        return "\n\n".join(
            [
                f"I do not see a local evidence receipt/template for AI UI human-QA Q{row_id} yet.",
                f"Rehearsal row: {lane_label} Q{row_id}{(' - ' + question) if question else ''}.",
                f"Comparison to rehearsal receipt: {rehearsal_state}. Rehearsal receipt: `{report.get('markdownPath') or ''}`.",
                "I did not create a new template, update `humanResult`, update `evidenceReceipt`, or change the 500-question audit.",
                "This is why: a summarize/replay/compare request should read existing evidence only. Creating or recording evidence from this prompt would blur the manual-QA audit trail.",
                f"You should also consider: ask `What evidence file should I create for AI UI human QA Q{row_id}?` first, fill the template after the real manual review, then ask for the evidence summary again.",
            ]
        )
    row_id = int(receipt.get("rowId") or row_id or 0)
    lane_label = receipt.get("laneLabel") or report.get("laneLabel") or ("Accessibility and assistive-tech review" if (kind or preferred_kind) == "accessibility" else "Production release-readiness review")
    question = receipt.get("question") or row.get("question") or ""
    manual = evidence_template_manual_result(receipt)
    gaps = evidence_template_completion_gaps(receipt)
    gap_text = ", ".join(gaps) if gaps else "none"
    manual_result = normalize_rehearsal_human_result(manual.get("result"))
