def ai_ui_intent_human_qa_status_direct_answer(messages):
    if not is_ai_ui_intent_human_qa_status_question(messages):
        return ""
    query = latest_user_text(messages).lower()
    audit_path = APP_DIR / "tests" / "ai_ui_intent_500_audit.json"
    data = read_json(audit_path, {})
    items = data.get("items") if isinstance(data, dict) else []
    if not isinstance(items, list):
        items = []
    lane_terms = (
        ("Safety", "safety"),
        ("Privacy", "privacy"),
        ("High-stakes", "high-stakes"),
        ("Accessibility", "accessibility"),
        ("Production", "production readiness"),
        ("Localization", "localization"),
        ("Latency", "latency"),
        ("Prompt guidance", "prompt guidance"),
        ("Personalization", "personalization"),
    )
    lane_counts = {label: 0 for label, _ in lane_terms}
    lane_samples = {label: [] for label, _ in lane_terms}
    partial_count = 0
    pass_count = 0
    review_count = 0
    for item in items:
        status = str(item.get("status") or "").upper()
        if status == "PASS":
            pass_count += 1
        elif status == "REVIEW":
            review_count += 1
        if status != "PARTIAL":
            continue
        partial_count += 1
        category = str(item.get("category") or "").lower()
        for label, term in lane_terms:
            if term in category:
                lane_counts[label] += 1
                if len(lane_samples[label]) < 3:
                    lane_samples[label].append(f"Q{item.get('id')}: {item.get('question')}")
                break
    if not partial_count:
        return "\n\n".join(
            [
                "I do not see any PARTIAL human-QA items in the current AI UI intent audit.",
                f"This is why: I read `{audit_path}` and found {pass_count} PASS, {partial_count} PARTIAL, and {review_count} REVIEW items.",
                "You should also consider: rerun the human-QA lane report if the audit file was just regenerated.",
            ]
        )
    latest_report = ""
    try:
        reports = sorted((DATA_DIR / "golden_batch_results").glob("*-ai-ui-intent-human-qa-lanes.md"), key=lambda path: path.stat().st_mtime, reverse=True)
        if reports:
            latest_report = str(reports[0])
    except OSError:
        latest_report = ""
    active_lane_counts = {label: count for label, count in lane_counts.items() if count}
    lane_text = ", ".join(f"{label} {count}" for label, count in active_lane_counts.items())
    active_lane_count = len(active_lane_counts)
    report_sentence = f" Latest detailed report: `{latest_report}`." if latest_report else ""
    wants_next = text_has_any(query, ("next", "start", "sample", "example", "examples", "detail", "drill"))
    if wants_next:
        next_label = next((label for label, _ in lane_terms if lane_counts.get(label)), "")
        samples = "; ".join(lane_samples.get(next_label) or [])
        following = ", ".join(label.lower() for label, _ in lane_terms if label != next_label and lane_counts.get(label))
        return "\n\n".join(
            [
                f"Start with {next_label}: {lane_counts.get(next_label, 0)} human-QA items. Sample questions: {samples}.",
                f"This is why: {next_label.lower()} is first in the review order for the remaining {partial_count} PARTIAL items, and I read those samples from `{audit_path}` instead of guessing. The full lane summary is: {lane_text}.{report_sentence}",
                f"You should also consider: after {next_label.lower()}, move through {following}. Keep these as PARTIAL until the human/product review is actually done.",
            ]
        )
    return "\n\n".join(
        [
            f"The remaining human-QA work is {partial_count} PARTIAL items across {active_lane_count} lanes: {lane_text}.",
            f"This is why: I read the local audit file at `{audit_path}` and grouped the PARTIAL items by review lane instead of guessing from memory. The audit currently has {pass_count} PASS and {review_count} REVIEW items.{report_sentence}",
            f"You should also consider: review them in this order: {', '.join(label.lower() for label in active_lane_counts)}. These are not failed items; they are items with automated evidence that still need real human/product QA before PASS.",
        ]
    )


def is_ai_ui_intent_gap_backlog_question(messages):
    query = latest_user_text(messages).lower()
    if not query:
        return False
    scope = text_has_any(
        query,
        (
            "ai ui intent",
            "500 question",
            "500-question",
            "intent audit",
            "audit backlog",
            "gap backlog",
            "partial lane",
            "partial lanes",
            "partial items",
        ),
    )
    priority = text_has_any(
        query,
        (
            "gap backlog",
            "priority",
            "priorities",
            "what should we fix next",
            "what should we attack next",
            "next high value target",
            "next target",
            "where should we start",
            "what is next",
            "which lane",
            "which category",
        ),
    )
    return scope and priority and not is_ai_ui_intent_human_qa_status_question(messages)


def latest_ai_ui_intent_gap_backlog():
    output_dir = DATA_DIR / "golden_batch_results"
    latest_json = latest_matching_file(output_dir, "*-ai-ui-intent-gap-backlog.json")
    latest_md = latest_matching_file(output_dir, "*-ai-ui-intent-gap-backlog.md")
    if not latest_json:
        tool_path = APP_DIR / "tools" / "ai_ui_intent_gap_backlog.py"
        try:
            completed = subprocess.run(
                ["/usr/bin/python3", str(tool_path)],
                cwd=str(APP_DIR),
                stdout=subprocess.PIPE,
                stderr=subprocess.PIPE,
                text=True,
                timeout=30,
                env=dict(os.environ),
            )
            if completed.returncode == 0:
                latest_json = latest_matching_file(output_dir, "*-ai-ui-intent-gap-backlog.json")
                latest_md = latest_matching_file(output_dir, "*-ai-ui-intent-gap-backlog.md")
        except Exception:
            pass
    data = read_json(latest_json, {}) if latest_json else {}
    return {
        "jsonPath": str(latest_json) if latest_json else "",
        "markdownPath": str(latest_md) if latest_md else "",
        "data": data if isinstance(data, dict) else {},
    }


def ai_ui_intent_gap_backlog_direct_answer(messages):
    if not is_ai_ui_intent_gap_backlog_question(messages):
        return ""
    backlog = latest_ai_ui_intent_gap_backlog()
    data = backlog.get("data") if isinstance(backlog.get("data"), dict) else {}
    totals = data.get("gapTotals") if isinstance(data.get("gapTotals"), dict) else {}
    categories = data.get("categories") if isinstance(data.get("categories"), list) else []
    priority_rows = [row for row in categories if isinstance(row, dict)]
    priority_rows.sort(
        key=lambda row: (
            0 if str(row.get("priority") or "").upper() == "P1" else 1,
            -int((row.get("statusCounts") or {}).get("PARTIAL") or 0),
            str(row.get("category") or ""),
        )
    )
    top_rows = priority_rows[:5]
    if not top_rows:
        audit_path = APP_DIR / "tests" / "ai_ui_intent_500_audit.json"
        return "\n\n".join(
            [
                "I do not have a generated AI UI intent gap backlog receipt yet.",
                f"This is why: I looked under `{DATA_DIR / 'golden_batch_results'}` and did not find a usable gap-backlog JSON. The source audit is `{audit_path}`.",
                "You should also consider: run `python3 tools/ai_ui_intent_gap_backlog.py`, then ask again and I will answer from that local receipt.",
            ]
        )
    first = top_rows[0]
    first_category = str(first.get("category") or "the first P1 category")
    first_count = int((first.get("statusCounts") or {}).get("PARTIAL") or 0)
    partial = int(totals.get("partial") or data.get("summary", {}).get("PARTIAL") or 0)
    review = int(totals.get("review") or data.get("summary", {}).get("REVIEW") or 0)
    category_total = int(totals.get("categories") or len(priority_rows))
    row_text = "; ".join(
        f"{row.get('category')} ({(row.get('statusCounts') or {}).get('PARTIAL', 0)} PARTIAL)"
        for row in top_rows
    )
    action = str(first.get("action") or "turn the first priority lane into focused smoke/regression cases").strip()
    json_path = backlog.get("jsonPath") or "no JSON receipt found"
    markdown_path = backlog.get("markdownPath") or "no Markdown report found"
    return "\n\n".join(
        [
            f"Start with {first_category}: {first_count} PARTIAL items. That is the next highest-value target from the AI UI intent gap backlog.",
            f"This is why: I read the local gap-backlog receipt instead of guessing. It shows {partial} PARTIAL items, {review} REVIEW items, and {category_total} gap categories. Top priorities: {row_text}. Receipt: `{json_path}`. Report: `{markdown_path}`.",
            f"You should also consider: for {first_category}, the next concrete action is to {action[0].lower() + action[1:] if action else 'add focused regression cases and manual QA gates.'} Keep the lane PARTIAL until the new checks and human/product review both pass.",
        ]
    )


