def common_material_comparison_direct_answer(messages, route):
    """Serve a small, curated material identity reference before asking a model to infer chemistry."""
    if not is_general_material_property_question(messages):
        return ""
    query = latest_user_text(messages).lower()
    if not text_has_any(query, ("compare", "contrast", "versus", " vs ", "better", "which", "difference", "stronger")):
        return ""
    matched = []
    for material in COMMON_MATERIAL_REFERENCE.values():
        if any(re.search(r"(?<![a-z0-9])" + re.escape(alias) + r"(?![a-z0-9])", query) for alias in material["aliases"]):
            matched.append(material)
    if len(matched) != 2:
        return ""
    labels = {item["label"] for item in matched}
    if labels != {"PLA", "PPS-CF"}:
        return ""
    pla = COMMON_MATERIAL_REFERENCE["pla"]
    pps_cf = COMMON_MATERIAL_REFERENCE["pps-cf"]
    return "\n\n".join(
        [
            "Pick PLA for easy prototypes and low-temperature parts. Pick PPS-CF when the part truly needs high heat resistance, chemical resistance, and stiffness, and the printer is equipped for it.",
            f"PLA is {pla['identity']}; PPS-CF is {pps_cf['identity']}. They are not close substitutes.",
            "The practical difference is that PLA " + pla["behavior"] + ". PPS-CF " + pps_cf["behavior"] + ".",
            "For printing, PLA " + pla["process"] + ". PPS-CF " + pps_cf["process"] + ".",
            "Before committing a functional PPS-CF part, check that filament grade's datasheet and print a coupon in the same orientation as the real load. That is where the specific temperature limits, strength, and chemical compatibility belong.",
        ]
    )


def common_material_reference_p34_synthetic_check():
    messages = [{"role": "user", "text": "Compare PLA and PPS-CF for a functional printed fixture."}]
    route = route_manager(messages, requested_profile="manager", web_search="live")
    answer = common_material_comparison_direct_answer(messages, route)
    bad_answer = "PPS-CF is carbon-fiber-filled polyphosphazene."
    gaps = general_expert_quality_gaps(messages, bad_answer)
    return (
        "polyphenylene sulfide" in answer.lower()
        and "polyphosphazene" not in answer.lower()
        and "datasheet" in answer.lower()
        and any(gap.get("kind") == "material-identity-mismatch" for gap in gaps)
    )


def human_bytes(num):
    try:
        value = float(num)
    except (TypeError, ValueError):
        return "unknown"
    for unit in ("B", "KiB", "MiB", "GiB", "TiB"):
        if abs(value) < 1024.0 or unit == "TiB":
            return f"{value:.1f} {unit}" if unit != "B" else f"{int(value)} B"
        value /= 1024.0
    return f"{value:.1f} TiB"


def disk_free_bytes(path=APP_DIR):
    try:
        return shutil.disk_usage(str(path)).free
    except OSError:
        return 0


