def load_machine_inventory(inventory_path=None):
    inventory_path = Path(inventory_path or MACHINE_INVENTORY_PATH)
    if not inventory_path.exists():
        return {}
    try:
        data = json.loads(inventory_path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError):
        return {}
    if not isinstance(data, dict):
        return {}
    data.setdefault("preferred_name", "Tinman")
    data.setdefault("machines", [])
    sanitized = []
    for machine in data.get("machines", []):
        if not isinstance(machine, dict):
            continue
        safe_machine = dict(machine)
        safe_machine["ssh"] = sanitize_ssh_info(safe_machine.get("ssh", {}))
        sanitized.append(safe_machine)
    data["machines"] = sanitized
    return data


def public_machine_hint(name_hint=""):
    hint = str(name_hint or "").lower()
    data = load_machine_inventory()
    machines = data.get("machines", []) if isinstance(data, dict) else []
    matches = []
    for machine in machines:
        if not isinstance(machine, dict):
            continue
        text = json.dumps(machine).lower()
        if hint and hint not in text and not any(part in text for part in hint.split()):
            continue
        services = []
        for service in machine.get("services", []) or []:
            if not isinstance(service, dict):
                continue
            services.append(
                {
                    "name": service.get("name", ""),
                    "url": service.get("url", ""),
                }
            )
        ssh = machine.get("ssh", {}) if isinstance(machine.get("ssh"), dict) else {}
        matches.append(
            {
                "name": machine.get("name", ""),
                "host": machine.get("host", ""),
                "services": services,
                "ssh": {
                    "alias": ssh.get("alias", ""),
                    "username": ssh.get("username", ""),
                    "port": ssh.get("port", 22),
                    "identity_file": ssh.get("identity_file", ""),
                    "password_keychain_service": ssh.get("password_keychain_service", ""),
                    "password_keychain_account": ssh.get("password_keychain_account", ""),
                },
                "remotePaths": machine.get("remote_paths", []) or machine.get("remotePaths", []),
                "notes": machine.get("notes", ""),
            }
        )
    return matches


def score_printer_config_dir(path, hint=""):
    path = Path(path).expanduser()
    score = 0
    if not path.is_dir():
        return 0
    printer_cfg = path / "printer.cfg"
    if printer_cfg.exists():
        score += 50
    files = set()
    try:
        for item in path.iterdir():
            try:
                if item.is_file() or item.is_symlink():
                    files.add(item.name.lower())
            except OSError:
                if item.is_symlink():
                    files.add(item.name.lower())
    except OSError:
        return score
    for name in ("rgb.cfg", "gcode_macro.cfg", "macros.cfg", "moonraker.conf"):
        if name in files:
            score += 10
    lower_path = str(path).lower()
    for term in (
        "klipper",
        "moonraker",
        "mainsail",
        "fluidd",
        "printer_data/config",
        "config",
        "qidi",
        "snapmaker",
        "ratrig",
        "rat_rig",
        "rat rig",
        "v-core",
    ):
        if term in lower_path:
            score += 12
    if hint and hint.lower() in lower_path:
        score += 20
    return score


def printer_config_candidate(path, source, hint=""):
    path = Path(path).expanduser()
    score = score_printer_config_dir(path, hint)
    if not score:
        return None
    source_lower = str(source or "").lower()
    if "current" in source_lower:
        score += 250
    elif "audit" in source_lower:
        score += 20
    elif "baseline" in source_lower:
        score += 5
    files = []
    try:
        for item in path.iterdir():
            try:
                if item.is_file() or item.is_symlink():
                    files.append(item.name)
            except OSError:
                if item.is_symlink():
                    files.append(item.name)
        files = sorted(files)
    except OSError:
        files = []
    return {
        "path": str(path),
        "source": source,
        "score": score,
        "printerCfg": str(path / "printer.cfg") if (path / "printer.cfg").exists() else "",
        "hasRgb": "RGB.cfg" in files or "rgb.cfg" in {name.lower() for name in files},
        "hasMacroFiles": any(name.lower() in {"macros.cfg", "gcode_macro.cfg"} for name in files),
        "files": files[:40],
        "writable": os.access(path, os.W_OK),
    }


def is_specific_machine_hint(hint):
    normalized = str(hint or "").strip().lower()
    return normalized not in {"", "klipper", "printer", "printers", "moonraker", "mainsail", "fluidd", "config"}


def candidate_matches_hint(candidate, hint):
    if not is_specific_machine_hint(hint):
        return True
    text = json.dumps(candidate, separators=(",", ":")).lower()
    normalized = str(hint or "").strip().lower()
    aliases = {
        "rat rig": ("ratrig", "rat_rig", "v-core", "vcore", "monster"),
        "ratrig": ("rat rig", "rat_rig", "v-core", "vcore", "monster"),
        "qidi": ("plus 4", "plus4", "max ez", "qidi"),
        "snapmaker": ("snapmaker", "u1"),
    }
    conflict_aliases = {
        "qidi": ("ratrig", "rat rig", "rat_rig", "v-core", "vcore", "snapmaker", "centauri", "sv08"),
        "snapmaker": ("ratrig", "rat rig", "rat_rig", "v-core", "vcore", "qidi", "centauri", "sv08"),
        "centauri": ("ratrig", "rat rig", "rat_rig", "v-core", "vcore", "qidi", "snapmaker", "sv08"),
        "sv08": ("ratrig", "rat rig", "rat_rig", "v-core", "vcore", "qidi", "snapmaker", "centauri"),
    }
    positives = (normalized, *aliases.get(normalized, ()))
    if not any(alias in text for alias in positives):
        return False
    conflicts = conflict_aliases.get(normalized, ())
    if conflicts and any(alias in text for alias in conflicts):
        return False
    return True


def discover_klipper_config_dirs(hint="", scan=False):
    known = [
        ("~/Downloads/ratrig_config", "current-klipper-config-ratrig"),
        (
            "~/Documents/Codex/2026-05-22/on-the-qidi-i-am-attempting/ratrig_audit/config",
            "known-klipper-config-ratrig-audit",
        ),
        (
            "~/Applications/Flightops_Tracker/docs/ratrig_baseline_20260314_190144/ratrig_config",
            "known-klipper-config-ratrig-baseline",
        ),
    ]
    candidates = []
    seen = set()
    for path, source in known:
        candidate = printer_config_candidate(path, source, hint)
        if candidate and candidate_matches_hint(candidate, hint) and candidate["path"] not in seen:
            candidates.append(candidate)
            seen.add(candidate["path"])

    if scan:
        scan_roots = [
            Path("~/Downloads").expanduser(),
            Path("~/Documents/Codex/2026-05-22/on-the-qidi-i-am-attempting").expanduser(),
            Path("~/Applications/Flightops_Tracker/docs").expanduser(),
        ]
        for root in scan_roots:
            if not root.exists():
                continue
            try:
                for printer_cfg in root.glob("**/printer.cfg"):
                    if len(candidates) >= 16:
                        break
                    folder = printer_cfg.parent
                    if str(folder) in seen:
                        continue
                    candidate = printer_config_candidate(folder, "limited-scan", hint)
                    if candidate and candidate_matches_hint(candidate, hint):
                        candidates.append(candidate)
                        seen.add(str(folder))
            except OSError:
                continue

    candidates.sort(key=lambda item: item.get("score", 0), reverse=True)
    remote_targets = []
    inventory_matches = public_machine_hint(hint) if hint else []
    if not inventory_matches:
        inventory_matches = public_machine_hint("moonraker")
    for machine in inventory_matches:
        services = machine.get("services", [])
        moonraker = ""
        for service in services:
            if "moonraker" in str(service.get("name", "")).lower():
                moonraker = service.get("url", "")
        if not moonraker and hint and "moonraker" not in json.dumps(machine).lower():
            continue
        remote_targets.append(
            {
                "name": machine.get("name", ""),
                "host": machine.get("host", ""),
                "moonraker": moonraker,
                "remotePaths": machine.get("remotePaths", []),
                "notes": machine.get("notes", ""),
                "safeWritePolicy": "Verify idle/standby before upload, restart, or live config change.",
            }
        )
    return {
        "hint": hint,
        "scan": bool(scan),
        "candidates": candidates[:12],
        "remoteTargets": remote_targets,
        "policy": "Local staging is allowed. Live upload/restart requires explicit request and idle/standby verification.",
    }


def discover_printer_config_dirs(hint=""):
    return discover_klipper_config_dirs(hint, scan=True)


def detect_klipper_led_name(config_dir):
    config_dir = Path(config_dir).expanduser()
    preferred = []
    fallback = []
    try:
        cfg_files = list(config_dir.glob("*.cfg"))
    except OSError:
        cfg_files = []
    pattern = re.compile(r"^\s*\[(neopixel|led|dotstar|pca9533)\s+([^\]]+)\]", re.IGNORECASE)
    for cfg_file in cfg_files:
        try:
            lines = cfg_file.read_text(encoding="utf-8", errors="replace").splitlines()
        except OSError:
            continue
        for line in lines:
            match = pattern.match(line)
            if not match:
                continue
            name = match.group(2).strip()
            if not name:
                continue
            if name.lower() in {"rgb", "caselight", "caselights", "status_led", "status"}:
                preferred.append(name)
            fallback.append(name)
    return (preferred or fallback or ["rgb"])[0]


def chamber_light_pin_evidence():
    candidates = [
        Path("~/Downloads/ratrig_config/RGB.cfg").expanduser(),
        Path("~/Desktop/printer.cfg").expanduser(),
        Path("~/Desktop/Temp Qidi Config Files/Qidiplus4maxEZ-Nebula-EBB42Gen2-Mosquito-printer.cfg").expanduser(),
    ]
    for config_dir in (discover_klipper_config_dirs("ratrig", scan=False).get("candidates") or [])[:3]:
        folder = Path(config_dir.get("path") or "")
        if folder.exists():
            candidates.extend([folder / "RGB.cfg", folder / "rgb.cfg", folder / "printer.cfg"])
    seen = set()
    evidence = []
    section_re = re.compile(r"^\s*\[(output_pin|neopixel|led|dotstar|pca9533)\s+([^\]]+)\]", re.IGNORECASE)
    pin_re = re.compile(r"^\s*#?\s*pin\s*:\s*([^\s#;]+)", re.IGNORECASE)
    macro_pin_re = re.compile(r"\bSET_PIN\s+PIN=([A-Za-z0-9_.:-]+)", re.IGNORECASE)
    for raw_path in candidates:
        path = Path(raw_path).expanduser()
        if path in seen or not path.is_file():
            continue
        seen.add(path)
        try:
            lines = path.read_text(encoding="utf-8", errors="replace").splitlines()
        except OSError:
            continue
        active = None
        active_line = 0
        for index, line in enumerate(lines, start=1):
            section = section_re.match(line)
            if section:
                name = section.group(2).strip()
                name_lower = name.lower()
                active = name if text_has_any(name_lower, ("chamber", "case", "caselight", "light")) else None
                active_line = index if active else 0
                continue
            if active:
                pin = pin_re.match(line)
                if pin:
                    evidence.append(
                        {
                            "section": active,
                            "pin": pin.group(1).strip(),
                            "path": str(path),
                            "line": active_line,
                            "kind": "pin-declaration",
                        }
                    )
                    active = None
                    active_line = 0
            macro_pin = macro_pin_re.search(line)
            if macro_pin and text_has_any(macro_pin.group(1).lower(), ("chamber", "case", "caselight", "light")):
                evidence.append(
                    {
                        "section": "macro reference",
                        "pin": macro_pin.group(1).strip(),
                        "path": str(path),
                        "line": index,
                        "kind": "macro-reference",
                    }
                )
    unique = []
    keys = set()
    for item in evidence:
        key = (item["section"], item["pin"], item["path"], item["kind"])
        if key in keys:
            continue
        keys.add(key)
        unique.append(item)
    return unique[:8]


def klipper_accel_rgb_macro_text(led_name="rgb"):
    safe_led_name = re.sub(r"[^A-Za-z0-9_ .:-]", "", str(led_name or "rgb")).strip() or "rgb"
    return """#####################################################################
# Klipper acceleration-aware RGB status
#
# Klipper acceleration is mm/s^2. Thresholds:
# - 1500..2000 mm/s^2 = yellow
# - above 2000 mm/s^2 = red
#
# Assumes an existing Klipper LED object named __LED_NAME__.
#####################################################################

[gcode_macro _ACCEL_RGB_STATE]
description: Internal state for acceleration RGB monitor
variable_enabled: 1
variable_last_zone: -1
variable_poll_seconds: 1.0
gcode:

[gcode_macro ACCEL_RGB_UPDATE]
description: Update RGB color from current or supplied acceleration. Usage: ACCEL_RGB_UPDATE [ACCEL=2000]
gcode:
  {% set st = printer["gcode_macro _ACCEL_RGB_STATE"] %}
  {% set accel = params.ACCEL|default(printer.toolhead.max_accel)|float %}
  {% set print_state = printer.print_stats.state|default("standby")|string|lower %}
  {% set forced = 1 if params.ACCEL is defined else 0 %}
  {% set active = forced or print_state in ["printing", "paused"] %}

  {% if active %}
    {% if accel > 2000 %}
      {% set zone = 2 %}
    {% elif accel >= 1500 %}
      {% set zone = 1 %}
    {% else %}
      {% set zone = 0 %}
    {% endif %}

    {% if zone != st.last_zone|int or forced %}
      {% if zone == 2 %}
        SET_LED LED=__LED_NAME__ RED=0.85 GREEN=0.00 BLUE=0.00 TRANSMIT=1
        RESPOND TYPE=command MSG="ACCEL_RGB: acceleration {'%.0f'|format(accel)} mm/s^2 -> red"
      {% elif zone == 1 %}
        SET_LED LED=__LED_NAME__ RED=0.90 GREEN=0.70 BLUE=0.00 TRANSMIT=1
        RESPOND TYPE=command MSG="ACCEL_RGB: acceleration {'%.0f'|format(accel)} mm/s^2 -> yellow"
      {% else %}
        SET_LED LED=__LED_NAME__ RED=0.00 GREEN=0.80 BLUE=0.05 TRANSMIT=1
        RESPOND TYPE=command MSG="ACCEL_RGB: acceleration {'%.0f'|format(accel)} mm/s^2 -> normal"
      {% endif %}
      SET_GCODE_VARIABLE MACRO=_ACCEL_RGB_STATE VARIABLE=last_zone VALUE={zone}
    {% endif %}
  {% else %}
    {% if st.last_zone|int != 9 %}
      SET_GCODE_VARIABLE MACRO=_ACCEL_RGB_STATE VARIABLE=last_zone VALUE=9
    {% endif %}
  {% endif %}

[delayed_gcode _ACCEL_RGB_WATCHDOG]
initial_duration: 2.0
gcode:
  {% set st = printer["gcode_macro _ACCEL_RGB_STATE"] %}
  {% if st.enabled|int == 1 %}
    ACCEL_RGB_UPDATE
    UPDATE_DELAYED_GCODE ID=_ACCEL_RGB_WATCHDOG DURATION={st.poll_seconds|float}
  {% else %}
    UPDATE_DELAYED_GCODE ID=_ACCEL_RGB_WATCHDOG DURATION=0
  {% endif %}

[gcode_macro ACCEL_RGB_ENABLE]
description: Enable acceleration RGB monitor
gcode:
  SET_GCODE_VARIABLE MACRO=_ACCEL_RGB_STATE VARIABLE=enabled VALUE=1
  SET_GCODE_VARIABLE MACRO=_ACCEL_RGB_STATE VARIABLE=last_zone VALUE=-1
  UPDATE_DELAYED_GCODE ID=_ACCEL_RGB_WATCHDOG DURATION=0.1
  RESPOND TYPE=command MSG="ACCEL_RGB enabled."

[gcode_macro ACCEL_RGB_DISABLE]
description: Disable acceleration RGB monitor
gcode:
  SET_GCODE_VARIABLE MACRO=_ACCEL_RGB_STATE VARIABLE=enabled VALUE=0
  SET_GCODE_VARIABLE MACRO=_ACCEL_RGB_STATE VARIABLE=last_zone VALUE=-1
  UPDATE_DELAYED_GCODE ID=_ACCEL_RGB_WATCHDOG DURATION=0
  RESPOND TYPE=command MSG="ACCEL_RGB disabled."
""".replace("__LED_NAME__", safe_led_name).strip() + "\n"


def ratrig_accel_rgb_macro_text():
    return klipper_accel_rgb_macro_text("rgb")


def insert_include_before_save_config(printer_text, include_line):
    if include_line in printer_text:
        return printer_text, True
    save_marker = "#*# <---------------------- SAVE_CONFIG ---------------------->"
    rgb_line = "[include RGB.cfg]"
    if rgb_line in printer_text:
        return printer_text.replace(rgb_line, f"{rgb_line}\n{include_line}", 1), False
    if save_marker in printer_text:
        return printer_text.replace(save_marker, f"{include_line}\n\n{save_marker}", 1), False
    return printer_text.rstrip() + f"\n{include_line}\n", False


def klipper_hint_from_query(query):
    lower = str(query or "").lower()
    if any(term in lower for term in ("ratrig", "rat rig", "v-core", "vcore", "monster")):
        return "ratrig"
    if "qidi" in lower or "plus 4" in lower or "max ez" in lower:
        return "qidi"
    if "snapmaker" in lower or "u1" in lower:
        return "snapmaker"
    if "centauri" in lower:
        return "centauri"
    if "sv08" in lower or "sovol" in lower:
        return "sv08"
    return "klipper"


def stage_klipper_accel_rgb_macro(target_path=None, patch_include=True, hint="klipper", led_name=""):
    discovery = discover_klipper_config_dirs(hint)
    selected = None
    target = Path(target_path).expanduser() if target_path else None
    if target:
        target.mkdir(parents=True, exist_ok=True)
        selected = printer_config_candidate(target, "requested-target", hint) or {
            "path": str(target),
            "source": "requested-target",
            "score": 1,
            "printerCfg": str(target / "printer.cfg") if (target / "printer.cfg").exists() else "",
            "hasRgb": (target / "RGB.cfg").exists(),
            "hasMacroFiles": (target / "macros.cfg").exists() or (target / "Gcode_Macro.cfg").exists(),
            "files": [],
            "writable": os.access(target, os.W_OK),
        }
    elif discovery["candidates"]:
        selected = discovery["candidates"][0]
        target = Path(selected["path"])
    else:
        target = LOCAL_TOOL_OUTPUT_DIR
        target.mkdir(parents=True, exist_ok=True)
        selected = {
            "path": str(target),
            "source": "fallback-generated-output",
            "score": 0,
            "printerCfg": "",
            "hasRgb": False,
            "hasMacroFiles": False,
            "files": [],
            "writable": os.access(target, os.W_OK),
        }
    if not os.access(target, os.W_OK):
        raise PermissionError(f"Target folder is not writable: {target}")

    led_object = led_name or detect_klipper_led_name(target)
    macro_path = target / "Acceleration_RGB.cfg"
    macro_path.write_text(klipper_accel_rgb_macro_text(led_object), encoding="utf-8")
    printer_cfg = target / "printer.cfg"
    patched = False
    include_already_present = False
    if patch_include and printer_cfg.exists():
        text = printer_cfg.read_text(encoding="utf-8")
        updated, include_already_present = insert_include_before_save_config(
            text, "[include Acceleration_RGB.cfg]"
        )
        if updated != text:
            printer_cfg.write_text(updated, encoding="utf-8")
            patched = True
    return {
        "ok": True,
        "savedPath": str(macro_path),
        "targetDir": str(target),
        "selectedCandidate": selected,
        "printerCfg": str(printer_cfg) if printer_cfg.exists() else "",
        "printerCfgPatched": patched,
        "includeAlreadyPresent": include_already_present,
        "ledName": led_object,
        "remoteNotTouched": True,
        "liveUpload": False,
        "discovery": discovery,
    }


def stage_ratrig_accel_rgb_macro(target_path=None, patch_include=True):
    return stage_klipper_accel_rgb_macro(
        target_path=target_path,
        patch_include=patch_include,
        hint="ratrig",
        led_name="rgb",
    )


def cad_number(pattern, text, default):
    match = re.search(pattern, text, flags=re.IGNORECASE | re.DOTALL)
    if not match:
        return default
    try:
        return float(match.group(1))
    except (TypeError, ValueError):
        return default


def cad_number_any(patterns, text, default):
    for pattern in patterns:
        value = cad_number(pattern, text, None)
        if value is not None:
            return value
    return default


def cad_request_dimensions(prompt):
    text = str(prompt or "")
    return {
        "toolheadX": cad_number(r"([0-9]+(?:\.[0-9]+)?)\s*mm\s*(?:in\s+the\s+)?x", text, 50.0),
        "toolheadY": cad_number(r"([0-9]+(?:\.[0-9]+)?)\s*mm\s*(?:in\s+the\s+)?y", text, 50.0),
        "toolheadZ": cad_number(r"([0-9]+(?:\.[0-9]+)?)\s*mm\s*(?:in\s+the\s+)?z", text, 150.0),
        "inletDiameter": cad_number_any(
            (
                r"([0-9]+(?:\.[0-9]+)?)\s*mm\s+(?:diameter\s+)?(?:cpap\s+)?inlet",
                r"inlet[^0-9]{0,60}([0-9]+(?:\.[0-9]+)?)\s*mm",
            ),
            text,
            18.0,
        ),
        "frontClearance": cad_number(r"([0-9]+(?:\.[0-9]+)?)\s*mm\s+in\s+the\s+front", text, 8.0),
        "nozzleBelow": cad_number(r"nozzle\s+tip[^0-9]{0,80}([0-9]+(?:\.[0-9]+)?)\s*mm\s+below", text, 9.0),
        "flowLowCfm": cad_number(r"([0-9]+(?:\.[0-9]+)?)\s*(?:-|to|~|--|/)\s*[0-9]+(?:\.[0-9]+)?\s*cfm", text, 12.0),
        "flowHighCfm": cad_number(r"[0-9]+(?:\.[0-9]+)?\s*(?:-|to|~|--|/)\s*([0-9]+(?:\.[0-9]+)?)\s*cfm", text, 15.0),
        "outletDiameter": cad_number_any(
            (
                r"outlet\s+(?:id|inner\s+diameter|diameter)[^0-9]{0,40}([0-9]+(?:\.[0-9]+)?)\s*mm",
                r"([0-9]+(?:\.[0-9]+)?)\s*mm\s+(?:id\s+)?outlet",
            ),
            text,
            8.0,
        ),
    }


def scad_cpap_duct_text(dim):
    x = dim["toolheadX"]
    y = dim["toolheadY"]
    z = dim["toolheadZ"]
    inlet = dim["inletDiameter"]
    front = dim["frontClearance"]
    nozzle = dim["nozzleBelow"]
    wall = 1.8
    outlet_d = float(dim.get("outletDiameter", 8.0) or 8.0)
    inlet_od = inlet + wall * 2
    plenum_z = -max(5.0, nozzle * 0.55)
    outlet_z = -max(2.0, nozzle - 1.5)
    inlet_y = -y / 2 - 15
    plenum_y = min(y / 2 + front - 2.0, y / 2 + 5.0)
    outlet_y = min(y / 2 + front - 1.0, y / 2 + 7.0)
    outlet_x = max(9.0, min(x / 2 - 7.0, 15.0))
    return f"""// Tinman CPAP part-cooling duct concept
// Generated by Codex CLI UI. Units: mm.
// Coordinate assumption: X left/right, Y front/back with positive Y forward, Z vertical.
// This is a first-pass printable envelope, not a validated CFD result.

$fn = 48;
wall = {wall:.2f};
tool_x = {x:.2f};
tool_y = {y:.2f};
tool_z = {z:.2f};
inlet_id = {inlet:.2f};
inlet_od = {inlet_od:.2f};
outlet_id = {outlet_d:.2f};
outlet_od = outlet_id + 2 * wall;

module marker_cube(size, center) {{
  translate(center) cube(size, center=true);
}}

module node(p, d) {{
  translate(p) sphere(d=d);
}}

module tube_path(points, d) {{
  for (i = [0:len(points)-2]) {{
    hull() {{
      node(points[i], d);
      node(points[i+1], d);
    }}
  }}
}}

inlet_center = [0, {inlet_y:.2f}, {plenum_z + 12.0:.2f}];
plenum_center = [0, {plenum_y:.2f}, {plenum_z:.2f}];
left_outlet = [-{outlet_x:.2f}, {outlet_y:.2f}, {outlet_z:.2f}];
right_outlet = [{outlet_x:.2f}, {outlet_y:.2f}, {outlet_z:.2f}];

module airflow_core() {{
  tube_path([inlet_center, [0, -{y / 2 + 4.0:.2f}, {plenum_z + 6.0:.2f}], plenum_center], inlet_id);
  tube_path([plenum_center, [-{outlet_x * 0.55:.2f}, {plenum_y + 1.0:.2f}, {outlet_z + 1.0:.2f}], left_outlet], outlet_id);
  tube_path([plenum_center, [{outlet_x * 0.55:.2f}, {plenum_y + 1.0:.2f}, {outlet_z + 1.0:.2f}], right_outlet], outlet_id);
}}

module duct_shell() {{
  difference() {{
    union() {{
      tube_path([inlet_center, [0, -{y / 2 + 4.0:.2f}, {plenum_z + 6.0:.2f}], plenum_center], inlet_od);
      tube_path([plenum_center, [-{outlet_x * 0.55:.2f}, {plenum_y + 1.0:.2f}, {outlet_z + 1.0:.2f}], left_outlet], outlet_od);
      tube_path([plenum_center, [{outlet_x * 0.55:.2f}, {plenum_y + 1.0:.2f}, {outlet_z + 1.0:.2f}], right_outlet], outlet_od);
      translate([0, {plenum_y:.2f}, {plenum_z:.2f}]) scale([1.4, 0.6, 0.45]) sphere(d={min(x - 6.0, 34.0):.2f});
    }}
    airflow_core();
    translate([0, 0, {z / 2:.2f}]) cube([tool_x, tool_y, tool_z + 4], center=true);
  }}
}}

duct_shell();

// Uncomment for fit/reference only.
// color([0.2, 0.5, 1.0, 0.18]) marker_cube([tool_x, tool_y, tool_z], [0, 0, tool_z / 2]);
// color([1, 0.1, 0.1, 0.7]) translate([0, 0, -{nozzle:.2f}]) sphere(d=2.2);
"""


def fusion_cpap_duct_script_text(dim):
    return f'''# Tinman CPAP cooling duct concept for Fusion 360
# Generated by Codex CLI UI. Units in this file are millimeters.
# Run from Fusion 360: Utilities > Scripts and Add-Ins > Scripts > + > select this file.
# This creates reference geometry and a first-pass duct envelope. Use the OpenSCAD
# file in the same folder for a printable hollow STL workflow.

import adsk.core, adsk.fusion, traceback

TOOL_X = {dim["toolheadX"]:.3f}
TOOL_Y = {dim["toolheadY"]:.3f}
TOOL_Z = {dim["toolheadZ"]:.3f}
INLET_ID = {dim["inletDiameter"]:.3f}
FRONT_CLEARANCE = {dim["frontClearance"]:.3f}
NOZZLE_BELOW = {dim["nozzleBelow"]:.3f}
WALL = 1.8
OUTLET_ID = {float(dim.get("outletDiameter", 8.0) or 8.0):.3f}

def mm(value):
    return value / 10.0

def add_box(comp, name, center, size):
    sketches = comp.sketches
    sketch = sketches.add(comp.xYConstructionPlane)
    x, y, z = center
    sx, sy, sz = size
    lines = sketch.sketchCurves.sketchLines
    lines.addTwoPointRectangle(
        adsk.core.Point3D.create(mm(x - sx / 2), mm(y - sy / 2), 0),
        adsk.core.Point3D.create(mm(x + sx / 2), mm(y + sy / 2), 0)
    )
    prof = sketch.profiles.item(0)
    ext = comp.features.extrudeFeatures
    inp = ext.createInput(prof, adsk.fusion.FeatureOperations.NewBodyFeatureOperation)
    inp.setDistanceExtent(False, adsk.core.ValueInput.createByReal(mm(sz)))
    body = ext.add(inp).bodies.item(0)
    body.name = name
    move_body(comp, body, (0, 0, z - sz / 2))
    return body

def move_body(comp, body, delta):
    bodies = adsk.core.ObjectCollection.create()
    bodies.add(body)
    matrix = adsk.core.Matrix3D.create()
    matrix.translation = adsk.core.Vector3D.create(mm(delta[0]), mm(delta[1]), mm(delta[2]))
    move_input = comp.features.moveFeatures.createInput(bodies, matrix)
    comp.features.moveFeatures.add(move_input)

def add_cylinder_y(comp, name, center, diameter, length):
    sketches = comp.sketches
    sketch = sketches.add(comp.xZConstructionPlane)
    x, y, z = center
    sketch.sketchCurves.sketchCircles.addByCenterRadius(
        adsk.core.Point3D.create(mm(x), mm(z), 0),
        mm(diameter / 2)
    )
    prof = sketch.profiles.item(0)
    ext = comp.features.extrudeFeatures
    inp = ext.createInput(prof, adsk.fusion.FeatureOperations.NewBodyFeatureOperation)
    inp.setDistanceExtent(False, adsk.core.ValueInput.createByReal(mm(length)))
    body = ext.add(inp).bodies.item(0)
    body.name = name
    move_body(comp, body, (0, y - length / 2, 0))
    return body

def run(context):
    app = adsk.core.Application.get()
    ui = app.userInterface
    try:
        doc = app.documents.add(adsk.core.DocumentTypes.FusionDesignDocumentType)
        design = app.activeProduct
        root = design.rootComponent
        root.name = "Tinman CPAP Cooling Duct Concept"

        add_box(root, "reference_toolhead_50x50x150", (0, 0, TOOL_Z / 2), (TOOL_X, TOOL_Y, TOOL_Z))
        add_box(root, "front_clearance_limit_8mm", (0, TOOL_Y / 2 + FRONT_CLEARANCE / 2, 4), (TOOL_X, FRONT_CLEARANCE, 8))
        add_cylinder_y(root, "cpap_inlet_outer_18mm_id_plus_wall", (0, -TOOL_Y / 2 - 15, -1), INLET_ID + 2 * WALL, 20)
        add_box(root, "rounded_front_plenum_envelope", (0, TOOL_Y / 2 + min(FRONT_CLEARANCE, 8) / 2, -5), (TOOL_X - 6, min(FRONT_CLEARANCE, 8), 10))
        add_cylinder_y(root, "left_outlet_aimed_at_nozzle_zone", (-min(15, TOOL_X / 2 - 7), TOOL_Y / 2 + FRONT_CLEARANCE - 2, -NOZZLE_BELOW + 2), OUTLET_ID + 2 * WALL, 8)
        add_cylinder_y(root, "right_outlet_aimed_at_nozzle_zone", (min(15, TOOL_X / 2 - 7), TOOL_Y / 2 + FRONT_CLEARANCE - 2, -NOZZLE_BELOW + 2), OUTLET_ID + 2 * WALL, 8)

        ui.messageBox("Created CPAP duct concept geometry. Use the matching .scad file for hollow printable export, then refine bends and outlet aiming after fit check.")
    except:
        ui.messageBox("CPAP duct script failed:\\n" + traceback.format_exc())
'''


def cad_readme_text(prompt, dim, paths):
    flow_low = dim["flowLowCfm"]
    flow_high = dim["flowHighCfm"]
    outlet_id = 8.0
    metrics = cad_flow_metrics(dim)
    outlet_area_mm2 = metrics["outletAreaMm2"]
    inlet_area_mm2 = metrics["inletAreaMm2"]
    return f"""# CPAP Cooling Duct CAD Concept

This folder contains a first-pass CPAP part-cooling duct concept generated from Tinman's prompt.

## Files

- `{Path(paths["fusionScriptPath"]).name}`: Fusion 360 Python script for reference geometry and a design envelope.
- `{Path(paths["openScadPath"]).name}`: OpenSCAD parametric hollow duct model.

## Assumptions

- Coordinate frame: X is left/right, Y is front/back with positive Y forward, Z is vertical.
- Toolhead envelope is {dim["toolheadX"]:.1f} x {dim["toolheadY"]:.1f} x {dim["toolheadZ"]:.1f} mm.
- CPAP inlet inner diameter is {dim["inletDiameter"]:.1f} mm.
- Front clearance is {dim["frontClearance"]:.1f} mm and side/back clearance is treated as zero.
- Nozzle tip is {dim["nozzleBelow"]:.1f} mm below the toolhead bottom.
- Fan free-flow estimate is {flow_low:.1f}-{flow_high:.1f} CFM.

## Airflow basis

- Inlet area is about {inlet_area_mm2:.0f} mm^2.
- Two {outlet_id:.1f} mm outlets have combined area about {outlet_area_mm2:.0f} mm^2.
- {flow_low:.1f}-{flow_high:.1f} CFM is about {metrics["flowLowLs"]:.1f}-{metrics["flowHighLs"]:.1f} L/s.
- Ideal inlet velocity is about {metrics["inletVelocityLow"]:.0f}-{metrics["inletVelocityHigh"]:.0f} m/s before duct losses.
- Ideal twin-outlet velocity is about {metrics["outletVelocityLow"]:.0f}-{metrics["outletVelocityHigh"]:.0f} m/s before duct losses.
- The outlet-to-inlet area ratio is about {metrics["outletToInletRatio"]:.2f}; this intentionally raises exit velocity for PLA bridging/detail cooling while keeping the duct compact.
- This is not a completed CFD result. Treat it as a parametric starting geometry for fit, smoke/flow visualization, and later CFD validation.

## Design intent

- Keep the body inside the 50 mm left/right width and use only the 8 mm available front envelope.
- Treat the aft 18 mm CPAP inlet as an existing connector, then turn the flow forward into a compact pressure plenum.
- Split the plenum into left/right balanced outlets aimed at the nozzle zone instead of trying to wrap around the sides or back.
- Use smooth internal transitions, generous fillets, and a removable/tunable outlet insert if the first print overcools ABS/PCTG or undercools PLA.
- Make the outside look like a swept cowl with ribs/fins, but keep the internal airway smooth.

## Material cooling guidance

- PLA: highest airflow; this duct can be run aggressively for bridges, overhangs, and detail.
- PCTG: moderate airflow; start around 25-60 percent and tune for layer adhesion versus surface quality.
- ABS/ASA: low airflow except bridges or small features; use enclosure heat and avoid blasting the part continuously.

## CFD setup notes

- Use a velocity inlet based on {flow_low:.1f}-{flow_high:.1f} CFM at the 18 mm inlet, pressure outlets at the two nozzles, and no-slip walls.
- Check velocity balance at the left/right outlets, recirculation in the plenum, and the velocity vector at the nozzle tip.
- Validate with smoke/tuft testing or a small anemometer before trusting the printed duct on long jobs.

## Fusion 360 import route

1. Run the `.py` script in Fusion 360 to create reference bodies and the design envelope.
2. If OpenSCAD is installed, export the `.scad` model to STL and import that STL into Fusion 360.
3. Refine outlet angles, fillets, mounting tabs, and clearances around the actual hotend/nozzle/sock.

Original prompt excerpt:

```text
{compact(prompt, 1200)}
```
"""


GENERATED_OUTPUT_TIMESTAMP_RE = re.compile(r"^\d{8}-\d{6}-")


def cleanup_cad_output_retention(root=None, keep=None, protect_paths=None):
    output_root = Path(root) if root else LOCAL_CAD_OUTPUT_DIR
    keep_count = max(1, int(keep if keep is not None else CAD_OUTPUT_RETENTION))
    protected = {Path(path).resolve() for path in (protect_paths or []) if path}
    if not output_root.exists():
        return {"root": str(output_root), "kept": 0, "removed": 0, "preserved": 0}
    try:
        children = list(output_root.iterdir())
    except OSError:
        return {"root": str(output_root), "kept": 0, "removed": 0, "preserved": 0}
    candidates = []
    preserved = []
    for candidate in children:
        if not candidate.is_dir():
            continue
        try:
            resolved = candidate.resolve()
            mtime = candidate.stat().st_mtime
        except OSError:
            continue
        if resolved in protected or candidate.name.startswith("_health") or not GENERATED_OUTPUT_TIMESTAMP_RE.match(candidate.name):
            preserved.append(candidate)
            continue
        candidates.append((mtime, candidate.name, candidate))
    candidates.sort(reverse=True)
    keep_paths = {path for _mtime, _name, path in candidates[:keep_count]}
    removed = 0
    for _mtime, _name, path in candidates:
        if path in keep_paths:
            continue
        try:
            shutil.rmtree(path)
            removed += 1
        except OSError:
            continue
    return {
        "root": str(output_root),
        "kept": len(keep_paths),
        "removed": removed,
        "preserved": len(preserved),
    }


def stage_cad_artifact(prompt="", target_path=None, artifact_name=""):
    prompt = str(prompt or "")
    dim = cad_request_dimensions(prompt)
    slug = slugify(artifact_name or "cpap cooling duct", fallback="cad-artifact")
    timestamp = time.strftime("%Y%m%d-%H%M%S")
    persistent_output = target_path is None
    target = Path(target_path).expanduser() if target_path else LOCAL_CAD_OUTPUT_DIR / f"{timestamp}-{slug}"
    target.mkdir(parents=True, exist_ok=True)
    if not os.access(target, os.W_OK):
        raise PermissionError(f"Target folder is not writable: {target}")

    fusion_path = target / f"{slug}_fusion360.py"
    scad_path = target / f"{slug}.scad"
    readme_path = target / "README.md"
    fusion_path.write_text(fusion_cpap_duct_script_text(dim), encoding="utf-8")
    scad_path.write_text(scad_cpap_duct_text(dim), encoding="utf-8")
    paths = {
        "fusionScriptPath": str(fusion_path),
        "openScadPath": str(scad_path),
        "readmePath": str(readme_path),
    }
    readme_path.write_text(cad_readme_text(prompt, dim, paths), encoding="utf-8")
    openscad_path = command_path("openscad")
    if persistent_output:
        cleanup_cad_output_retention(protect_paths=[target])
    return {
        "ok": True,
        "targetDir": str(target),
        **paths,
        "dimensions": dim,
        "openscadInstalled": bool(openscad_path),
        "openscadPath": openscad_path,
        "freeCadInstalled": bool(command_path("FreeCADCmd") or command_path("freecad")),
        "fullCfdRun": False,
        "cfdNote": "No CFD solver was run. The artifact uses first-order airflow sizing and should be validated with fit checks, flow visualization, and CFD if needed.",
        "importRoute": "Run the Fusion 360 Python script directly, or export the OpenSCAD model to STL and import it into Fusion 360.",
    }


def cad_flow_metrics(dim):
    cfm_to_m3_s = 0.00047194745
    flow_low_cfm = float(dim.get("flowLowCfm", 12.0) or 12.0)
    flow_high_cfm = float(dim.get("flowHighCfm", 15.0) or 15.0)
    inlet_d_mm = float(dim.get("inletDiameter", 18.0) or 18.0)
    outlet_d_mm = float(dim.get("outletDiameter", 8.0) or 8.0)
    inlet_area_m2 = math.pi * (inlet_d_mm / 2000.0) ** 2
    outlet_area_m2 = 2.0 * math.pi * (outlet_d_mm / 2000.0) ** 2
    flow_low_m3_s = flow_low_cfm * cfm_to_m3_s
    flow_high_m3_s = flow_high_cfm * cfm_to_m3_s
    inlet_velocity_low = flow_low_m3_s / inlet_area_m2 if inlet_area_m2 else 0.0
    inlet_velocity_high = flow_high_m3_s / inlet_area_m2 if inlet_area_m2 else 0.0
    outlet_velocity_low = flow_low_m3_s / outlet_area_m2 if outlet_area_m2 else 0.0
    outlet_velocity_high = flow_high_m3_s / outlet_area_m2 if outlet_area_m2 else 0.0
    return {
        "flowLowLs": flow_low_m3_s * 1000.0,
        "flowHighLs": flow_high_m3_s * 1000.0,
        "inletAreaMm2": inlet_area_m2 * 1_000_000.0,
        "outletAreaMm2": outlet_area_m2 * 1_000_000.0,
        "outletToInletRatio": outlet_area_m2 / inlet_area_m2 if inlet_area_m2 else 0.0,
        "inletVelocityLow": inlet_velocity_low,
        "inletVelocityHigh": inlet_velocity_high,
        "outletVelocityLow": outlet_velocity_low,
        "outletVelocityHigh": outlet_velocity_high,
        "outletDiameter": outlet_d_mm,
    }


def is_cad_artifact_tool_request(messages):
    if is_wind_turbine_design_request(messages):
        return False
    if is_speaker_pod_cad_request(messages):
        return False
    if is_slicer_plate_workflow_question(messages):
        return False
    if is_filament_profile_pull_request(messages):
        return False
    if not is_cad_design_request(messages):
        return False
    query = latest_user_text(messages).lower()
    duct_terms = (
        "cpap",
        "duct",
        "cooling duct",
        "part cooling",
        "cooling fan",
        "blower",
        "fan duct",
        "airflow",
    )
    if not text_has_any(query, duct_terms):
        return False
    artifact_terms = (
        "cad",
        "fusion",
        "fusion 360",
        "step",
        "stl",
        "scad",
        "import",
        "imported",
        "duct",
        "cpap",
        "cooling duct",
        "part cooling",
        "model",
        "geometry",
    )
    action_terms = (
        "design",
        "create",
        "make",
        "build",
        "model",
        "import",
        "imported",
    )
    return text_has_any(query, artifact_terms) and text_has_any(query, action_terms)


def is_cpap_cad_artifact_revision_request(messages):
    latest = latest_user_text(messages).lower()
    if not latest or is_wind_turbine_design_request(messages):
        return False
    previous = previous_assistant_text(messages).lower()
    if not previous:
        return False
    prior_cpap_artifact = (
        text_has_any(previous, ("cpap", "cooling duct", "part cooling", "fusion 360", "openscad"))
        and text_has_any(previous, ("fusion360.py", ".scad", "design notes and assumptions", "data/generated/cad"))
    )
    if not prior_cpap_artifact:
        return False
    correction_terms = (
        "regenerate",
        "revise",
        "update",
        "change",
        "make",
        "increase",
        "decrease",
        "set",
        "adjust",
        "fix",
        "this file",
        "the file",
        "the model",
        "the duct",
    )
    geometry_terms = (
        "outlet",
        "inlet",
        "diameter",
        "clearance",
        "nozzle",
        "wall",
        "plenum",
        "angle",
        "aim",
        "width",
        "height",
        "mm",
    )
    return text_has_any(latest, correction_terms) and text_has_any(latest, geometry_terms)


def combined_cpap_revision_prompt(messages):
    user_text = "\n".join(
        str(message.get("text") or "")
        for message in messages
        if str(message.get("role") or "").lower() == "user"
    )
    assistant_context = previous_assistant_text(messages)
    return "\n\n".join(
        [
            "Prior CPAP CAD design context:",
            compact(assistant_context, 1800),
            "Requested revision:",
            user_text,
        ]
    )


def cpap_cad_revision_change_summary(messages, dim):
    latest = latest_user_text(messages)
    lower = latest.lower()
    changes = []
    if "outlet" in lower and re.search(r"\d", lower):
        changes.append(f"outlet diameter set to {float(dim.get('outletDiameter', 8.0) or 8.0):.1f} mm")
    if "inlet" in lower and re.search(r"\d", lower):
        changes.append(f"inlet diameter set to {float(dim.get('inletDiameter', 18.0) or 18.0):.1f} mm")
    if "front" in lower and "clearance" in lower:
        changes.append(f"front clearance set to {float(dim.get('frontClearance', 8.0) or 8.0):.1f} mm")
    return ", ".join(changes) if changes else compact(latest, 180)


def format_cpap_cad_revision_answer(result, messages):
    if not result.get("ok"):
        return format_cad_artifact_result_answer(result)
    dim = result.get("dimensions") or {}
    change_summary = cpap_cad_revision_change_summary(messages, dim)
    metrics = cad_flow_metrics(dim)
    return "\n\n".join(
        [
            f"I regenerated the CPAP cooling duct package with the requested change: {change_summary}.",
            "\n".join(
                [
                    f"Fusion 360 script: `{result.get('fusionScriptPath')}`",
                    f"OpenSCAD model: `{result.get('openScadPath')}`",
                    f"Design notes: `{result.get('readmePath')}`",
                ]
            ),
            (
                "This is why: your latest message is a correction to the generated CPAP duct, so I kept it attached to the prior CAD context "
                "and staged a revised artifact instead of starting a new unrelated task or waiting on the local model."
            ),
            (
                f"You should also consider: the revised outlet area is about {metrics['outletAreaMm2']:.0f} mm2 total for two outlets. "
                "Larger outlets reduce exit velocity and restriction; smaller outlets raise velocity but can choke the CPAP blower. "
                "Do a Fusion fit check and a smoke/anemometer check before treating it as final."
            ),
        ]
    )


def cpap_cad_artifact_revision_synthetic_check():
    previous = "\n\n".join(
        [
            "I made a first-pass CPAP cooling duct CAD package for you, Tinman.",
            "Open this first in Fusion 360: `/tmp/example_fusion360.py`",
            "Editable OpenSCAD backup: `/tmp/example.scad`",
            "Design notes and assumptions: `/tmp/README.md`",
            "Plain-English design: this uses a short swept front plenum fed by the aft 18 mm CPAP inlet, then splits into two balanced 8 mm ID outlet paths.",
        ]
    )
    messages = [
        {
            "role": "user",
            "text": "I need a CPAP cooling duct designed in CAD that can be imported into Fusion 360. The toolhead is 50mm x 50mm x 150mm, inlet is 18mm, front clearance is 8mm, nozzle is 9mm below.",
        },
        {"role": "assistant", "text": previous},
        {"role": "user", "text": "Make the outlet diameter 10mm and regenerate this file."},
    ]
    if not is_cpap_cad_artifact_revision_request(messages):
        return False
    with tempfile.TemporaryDirectory(prefix="cpap-cad-revision-health-") as tmp_dir:
        artifact = stage_cad_artifact(
            combined_cpap_revision_prompt(messages),
            target_path=Path(tmp_dir) / "revision",
            artifact_name="revised-cpap-cooling-duct",
        )
        answer = format_cpap_cad_revision_answer(artifact, messages)
        scad_text = Path(artifact.get("openScadPath") or "").read_text(encoding="utf-8")
        dim = artifact.get("dimensions") or {}
        return (
            artifact.get("ok")
            and abs(float(dim.get("outletDiameter", 0)) - 10.0) < 0.001
            and "outlet_id = 10.00" in scad_text
            and "regenerated the CPAP cooling duct package" in answer
            and "outlet diameter set to 10.0 mm" in answer
            and "local model" in answer
        )


def fix_this_generated_artifact_repair(payload, route=None):
    messages = payload.get("messages") if isinstance(payload.get("messages"), list) else []
    route = route or (payload.get("route") if isinstance(payload.get("route"), dict) else {})
    if not messages:
        prompt = str(payload.get("prompt") or "")
        if prompt:
            messages = [{"role": "user", "text": prompt}]
    if is_cpap_cad_artifact_revision_request(messages):
        artifact = stage_cad_artifact(
            combined_cpap_revision_prompt(messages),
            artifact_name=slugify("fix-this-revised-cpap-cooling-duct", "fix-this-revised-cpap-cooling-duct")[:48],
        )
        answer = format_cpap_cad_revision_answer(artifact, messages)
        return {
            "ok": True,
            "kind": "generated-artifact-revision",
            "action": "replace-answer",
            "route": route,
            "artifact": artifact,
            "answer": answer,
            "summary": "Fix This regenerated the CPAP CAD artifact from the prior output context.",
        }
    return None


def is_underspecified_generic_cad_design_request(messages):
    if is_bambu_h2d_model_health_request(messages):
        return False
    # A linked public component is a retrieval request even when it contains no
    # geometry. Let the source-retrieval workflow identify it before asking for
    # dimensions needed to model a replacement.
    if is_external_cad_source_retrieval_question(messages):
        return False
    if not is_cad_design_request(messages):
        return False
    if (
        is_cad_artifact_tool_request(messages)
        or is_wind_turbine_design_request(messages)
        or is_stl_cfd_duct_design_request(messages)
        or is_aero_cfd_analysis_request(messages)
        or is_structural_mechanical_design_request(messages)
        or is_speaker_pod_cad_request(messages)
    ):
        return False
    query = latest_user_text(messages).lower()
    if not text_has_any(
        query,
        (
            "design",
            "create",
            "make",
            "model",
            "generate",
            "cad",
            "fusion",
            "imported into fusion",
            "import into fusion",
        ),
    ):
        return False
    if text_has_any(
        query,
        (
            "what file",
            "what format",
            "how do i",
            "how can i",
            "explain",
            "workflow",
            "tutorial",
            "mirror",
            "subtract",
            "sweep",
            "move sketch",
            "copy sketch",
        ),
    ):
        return False
    has_geometry = bool(message_attachments(messages)) or bool(geometry_names_from_text(query))
    has_numbers = bool(re.search(r"\b\d+(?:\.\d+)?\s*(?:mm|cm|in|inch|inches|deg|degree|n|lb|lbs|kg|v|rpm|cfm)\b", query))
    has_feature_detail = text_has_any(
        query,
        (
            "hole",
            "holes",
            "bolt",
            "screw",
            "m3",
            "m4",
            "m5",
            "mounting pattern",
            "thickness",
            "radius",
            "clearance",
            "load",
            "material",
            "wall",
            "fillet",
            "bearing",
            "shaft",
            "plate",
            "tab",
            "slot",
        ),
    )
    return not has_geometry and not has_numbers and not has_feature_detail


def underspecified_generic_cad_design_direct_answer(messages):
    if not is_underspecified_generic_cad_design_request(messages):
        return ""
    query = latest_user_text(messages)
    part_label = "the part"
    lower = query.lower()
    if "bracket" in lower:
        part_label = "the bracket"
    elif "mount" in lower:
        part_label = "the mount"
    elif "holder" in lower:
        part_label = "the holder"
    return "\n\n".join(
        [
            f"I can design {part_label}, but I do not have enough geometry to create a useful Fusion-ready CAD file yet.",
            (
                "This is why: the request asks for an importable CAD part, but it does not include the mounting hole pattern, "
                "overall envelope, thickness, load direction, material, printer/process constraints, or what {part_label} attaches to."
            ).format(part_label=part_label),
            (
                "You should also consider: send the critical dimensions or a sketch/photo with scale. The minimum I need is overall size, "
                "hole count/diameter/spacing, thickness, material, load/force direction, required clearances, and whether you want STEP, STL, "
                "or a Fusion 360 script. Once those are present, I should create the files and give clickable outputs instead of asking you to do the work."
            ),
        ]
    )


def cad_artifact_working_notes(result):
    if not result.get("ok"):
        return ["CAD artifact tool failed before design analysis could run."]
    dim = result.get("dimensions") or {}
    metrics = cad_flow_metrics(dim)
    return [
        (
            "Parsed the CAD envelope: "
            f"{dim.get('toolheadX', 50):.0f} x {dim.get('toolheadY', 50):.0f} x {dim.get('toolheadZ', 150):.0f} mm toolhead, "
            f"{dim.get('inletDiameter', 18):.0f} mm inlet, {dim.get('frontClearance', 8):.0f} mm front clearance, "
            f"nozzle {dim.get('nozzleBelow', 9):.0f} mm below the toolhead."
        ),
        (
            "Sized the airflow: "
            f"{dim.get('flowLowCfm', 12):.0f}-{dim.get('flowHighCfm', 15):.0f} CFM is "
            f"{metrics['flowLowLs']:.1f}-{metrics['flowHighLs']:.1f} L/s through a {metrics['inletAreaMm2']:.0f} mm2 inlet."
        ),
        (
            "Selected a compact front plenum with twin balanced outlets because the sides and back have zero clearance."
        ),
        (
            "Marked CFD as pending: this run creates importable CAD and first-order flow math, then calls out what must be validated."
        ),
    ]


def format_cad_web_evidence_section(web_evidence):
    if web_evidence is None:
        return ""
    items = list((web_evidence or {}).get("items") or [])
    error = str((web_evidence or {}).get("error") or "").strip()
    if not items:
        detail = error or "the local web evidence pass did not return usable public sources"
        return (
            "Industry/web check: I tried to gather public web evidence for the CAD request, but could not confirm usable sources in this pass. "
            f"This is why I am treating the design as first-order engineering, not web-validated CFD. Web check detail: {compact(detail, 220)}."
        )
    lines = [
        (
            "Industry/web check: I checked public sources for 3D-printer part-cooling and duct-design cues. "
            "I used them as general design guidance only; they do not validate this exact geometry."
        )
    ]
    for item in items[:4]:
        title = compact(item.get("title") or item.get("pageTitle") or "source", 90)
        url = item.get("url", "")
        if url:
            lines.append(f"- {title}: {url}")
    return "\n".join(lines)


def format_cad_artifact_result_answer(result, recovered_from_error="", web_evidence=None):
    if not result.get("ok"):
        return "\n\n".join(
            [
                "I could not stage the CAD artifact package.",
                f"This is why: {result.get('error', 'the local CAD artifact tool returned an unknown error')}.",
                "You should also consider: no live printer was touched; this is a local CAD-file staging problem.",
            ]
        )

    dim = result.get("dimensions") or {}
    preface = "I made a first-pass CPAP cooling duct CAD package for you, Tinman. The useful files are below, and the UI should let you click each path to reveal it."
    if recovered_from_error:
        preface = (
            "The local model failed, so I pivoted instead of stopping there. "
            "I made a first-pass CPAP cooling duct CAD package for you, Tinman. The useful files are below, and the UI should let you click each path to reveal it."
        )
    flow_low = dim.get("flowLowCfm", 12.0)
    flow_high = dim.get("flowHighCfm", 15.0)
    tool_x = dim.get("toolheadX", 50.0)
    tool_y = dim.get("toolheadY", 50.0)
    tool_z = dim.get("toolheadZ", 150.0)
    inlet = dim.get("inletDiameter", 18.0)
    front = dim.get("frontClearance", 8.0)
    nozzle = dim.get("nozzleBelow", 9.0)
    metrics = cad_flow_metrics(dim)
    outlet_d = metrics["outletDiameter"]
    outlet_x = max(9.0, min(tool_x / 2 - 7.0, 15.0))
    sections = [
            preface,
            "\n".join(
                [
                    f"Open this first in Fusion 360: `{result.get('fusionScriptPath')}`",
                    f"Editable OpenSCAD backup: `{result.get('openScadPath')}`",
                    f"Design notes and assumptions: `{result.get('readmePath')}`",
                ]
            ),
            (
                "Plain-English design: this uses a short swept front plenum fed by the aft 18 mm CPAP inlet, then splits into two balanced "
                f"{outlet_d:.0f} mm ID outlet paths near X +/-{outlet_x:.0f} mm. I am keeping the duct inside the 50 mm width and using "
                f"the available {front:.0f} mm front envelope instead of wrapping around the sides or back, because your hard side/back clearance is zero. "
                "The outlets are aimed toward the nozzle zone rather than straight down so the flow hits the fresh bead and nearby overhangs without blasting the heater block."
            ),
            (
                "Why the sizing makes sense: "
                f"{flow_low:.0f}-{flow_high:.0f} CFM is about {metrics['flowLowLs']:.1f}-{metrics['flowHighLs']:.1f} L/s. "
                f"The {inlet:.0f} mm inlet area is about {metrics['inletAreaMm2']:.0f} mm2, giving an ideal inlet velocity of "
                f"{metrics['inletVelocityLow']:.0f}-{metrics['inletVelocityHigh']:.0f} m/s before losses. "
                f"Two {outlet_d:.0f} mm outlets total about {metrics['outletAreaMm2']:.0f} mm2, so the ideal outlet velocity would be "
                f"{metrics['outletVelocityLow']:.0f}-{metrics['outletVelocityHigh']:.0f} m/s before bend, plenum, and outlet losses. "
                f"That {metrics['outletToInletRatio']:.2f} outlet/inlet area ratio is deliberate: compact, high velocity, and tunable."
            ),
            (
                "Material cooling plan: PLA gets the most benefit from this layout, especially bridges and small layers. "
                "For PCTG, start with moderate fan power and watch layer adhesion versus surface finish. "
                "For ABS/ASA, treat the duct as bridge/detail assist, not full-time cooling; enclosure temperature and low airflow matter more than maximum blast."
            ),
            (
                "CFD/validation plan: no full CFD solver was run in this local pass, so I am not pretending this is validated. "
                f"The CFD setup should use a velocity inlet equivalent to {flow_low:.0f}-{flow_high:.0f} CFM at the 18 mm inlet, "
                "pressure outlets at the two nozzles, no-slip walls, and checks for left/right balance, plenum recirculation, and vectors around the nozzle tip. "
                "Before a final print, do a smoke/tuft test or anemometer check and tune outlet ID between roughly 8-10 mm if the fan is choking or the part is undercooled."
            ),
            (
                "Style direction: keep the internal airway smooth, but shape the outside like a low-profile swept cowl with shallow ribs or fins. "
                "That gives it the aggressive look you asked for without putting decorative turbulence inside the duct."
            ),
    ]
    web_section = format_cad_web_evidence_section(web_evidence)
    if web_section:
        sections.append(web_section)
    sections.extend(
        [
            (
                "This is why: the prompt is a CAD/design deliverable, so the useful recovery is an importable artifact. "
                f"The staged concept uses a {tool_x:.0f} x {tool_y:.0f} x {tool_z:.0f} mm toolhead envelope, "
                f"{inlet:.0f} mm CPAP inlet, {front:.0f} mm front clearance, and nozzle target about {nozzle:.0f} mm below the toolhead. "
                f"It assumes roughly {flow_low:.0f}-{flow_high:.0f} CFM free-flow and uses a compact plenum with twin outlet paths aimed near the nozzle zone."
            ),
            (
                "You should also consider: the aft-inlet/back-clearance wording conflicts slightly, so I treated the 18 mm aft inlet as an existing connector "
                "and did not add extra rear growth. If that connector itself must fit inside the same zero-back-clearance envelope, the next revision needs a top-entry "
                "or angled elbow. Treat these files as a parametric starting point for Fusion 360 fit checks, outlet aiming, flow visualization, and later CFD validation before final printing."
            ),
        ]
    )
    return "\n\n".join(sections)


def wind_turbine_design_parameters(messages):
    text = recent_conversation_text(messages, limit=8) or latest_user_text(messages)
    lower = text.lower()
    build = re.search(
        r"([0-9]+(?:\.[0-9]+)?)\s*mm\s*x\s*([0-9]+(?:\.[0-9]+)?)\s*mm\s*x\s*([0-9]+(?:\.[0-9]+)?)\s*mm",
        lower,
    )
    build_volume = [270.0, 270.0, 270.0]
    if build:
        build_volume = [float(build.group(1)), float(build.group(2)), float(build.group(3))]
    voltage = cad_number_any(
        (
            r"([0-9]+(?:\.[0-9]+)?)\s*vdc",
            r"([0-9]+(?:\.[0-9]+)?)\s*v\s*dc",
            r"([0-9]+(?:\.[0-9]+)?)\s*v\s+generator",
            r"([0-9]+(?:\.[0-9]+)?)\s*v\b",
        ),
        lower,
        60.0,
    )
    wind_mph = cad_number_any((r"([0-9]+(?:\.[0-9]+)?)\s*mph", r"([0-9]+(?:\.[0-9]+)?)\s*miles?\s+per\s+hour"), lower, 4.0)
    material = "ASA-CF" if text_has_any(lower, ("asa-cf", "asa cf")) else "ASA-CF assumed"
    infill_percent = cad_number_any(
        (
            r"([0-9]+(?:\.[0-9]+)?)\s*%\s*infill",
            r"infill[^0-9]{0,24}([0-9]+(?:\.[0-9]+)?)\s*%",
        ),
        lower,
        None,
    )
    module_height = min(build_volume[2] - 10.0, 260.0)
    module_height = max(180.0, module_height)
    tiers = 3
    diameter = min(build_volume[0] * 1.92, 520.0)
    diameter = max(360.0, diameter)
    total_height = module_height * tiers
    swept_area_m2 = (diameter / 1000.0) * (total_height / 1000.0)
    wind_ms = wind_mph * 0.44704
    rho = 1.225
    available_w = 0.5 * rho * swept_area_m2 * wind_ms ** 3
    betz_w = available_w * 0.593
    expected_mech_low = available_w * 0.16
    expected_mech_high = available_w * 0.28
    return {
        "buildVolumeMm": build_volume,
        "voltageVdc": voltage,
        "windMph": wind_mph,
        "windMs": wind_ms,
        "material": material,
        "infillPercent": infill_percent,
        "moduleHeightMm": module_height,
        "tiers": tiers,
        "rotorDiameterMm": diameter,
        "rotorHeightMm": total_height,
        "sweptAreaM2": swept_area_m2,
        "availableWindPowerW": available_w,
        "betzLimitW": betz_w,
        "expectedMechanicalPowerLowW": expected_mech_low,
        "expectedMechanicalPowerHighW": expected_mech_high,
    }


def is_wind_turbine_connection_revision_request(messages):
    if not is_wind_turbine_design_request(messages):
        return False
    query = latest_user_text(messages).lower()
    return text_has_any(
        query,
        (
            "not constrained",
            "not connected",
            "not attached",
            "doesn't connect",
            "does not connect",
            "open it in fusion",
            "when i open",
            "fusion",
            "joints",
            "mates",
            "assembly",
        ),
    )


def requested_fusion_native_archive(messages):
    query = latest_user_text(messages).lower()
    if not query:
        return ""
    if ".f3z" in query or "f3z" in query:
        return ".f3z"
    if ".f3d" in query or "f3d" in query or "native fusion" in query or "fusion archive" in query:
        return ".f3d"
    return ""


_FUSION360_APP_PATH_CACHE = None


def fusion360_app_path():
    global _FUSION360_APP_PATH_CACHE
    if _FUSION360_APP_PATH_CACHE is not None:
        return _FUSION360_APP_PATH_CACHE

    direct_candidates = [
        Path("/Applications/Autodesk Fusion 360.app"),
        Path("/Applications/Autodesk Fusion.app"),
        Path.home() / "Applications/Autodesk Fusion 360.app",
        Path.home() / "Applications/Autodesk Fusion.app",
    ]
    candidates = [path for path in direct_candidates if path.exists()]

    webdeploy = Path.home() / "Library/Application Support/Autodesk/webdeploy/production"
    if webdeploy.exists():
        try:
            for deployment_dir in webdeploy.iterdir():
                if not deployment_dir.is_dir():
                    continue
                for app_name in ("Autodesk Fusion 360.app", "Autodesk Fusion.app", "Fusion 360.app"):
                    candidate = deployment_dir / app_name
                    if candidate.exists():
                        candidates.append(candidate)
        except OSError:
            pass

    if not candidates:
        _FUSION360_APP_PATH_CACHE = ""
        return ""
    candidates.sort(key=lambda item: item.stat().st_mtime if item.exists() else 0, reverse=True)
    _FUSION360_APP_PATH_CACHE = str(candidates[0])
    return _FUSION360_APP_PATH_CACHE


def fusion_wind_turbine_script_text(params):
    payload = json.dumps(params, sort_keys=True)
    return f'''# Tinman modular VAWT Fusion 360 native rebuild script.
# Run inside Fusion 360: Utilities > Scripts and Add-Ins > Scripts > + > select this file.
# After it runs, save/export from Fusion as .f3d or .f3z to preserve Fusion-native relationships.
import json
import math
import traceback
import adsk.core
import adsk.fusion

PARAMS = json.loads({payload!r})


def mm(value):
    return float(value) / 10.0


def add_box(component, name, size_mm, center_mm):
    sketches = component.sketches
    sketch = sketches.add(component.xYConstructionPlane)
    cx, cy, cz = [mm(value) for value in center_mm]
    sx, sy, sz = [mm(value) for value in size_mm]
    sketch.name = name + "_profile"
    lines = sketch.sketchCurves.sketchLines
    p1 = adsk.core.Point3D.create(cx - sx / 2, cy - sy / 2, 0)
    p2 = adsk.core.Point3D.create(cx + sx / 2, cy + sy / 2, 0)
    lines.addTwoPointRectangle(p1, p2)
    profile = sketch.profiles.item(0)
    extrudes = component.features.extrudeFeatures
    ext_input = extrudes.createInput(profile, adsk.fusion.FeatureOperations.NewBodyFeatureOperation)
    ext_input.setDistanceExtent(False, adsk.core.ValueInput.createByReal(sz))
    body = extrudes.add(ext_input).bodies.item(0)
    body.name = name
    move = component.features.moveFeatures
    entities = adsk.core.ObjectCollection.create()
    entities.add(body)
    transform = adsk.core.Matrix3D.create()
    transform.translation = adsk.core.Vector3D.create(0, 0, cz - sz / 2)
    move_input = move.createInput(entities, transform)
    move.add(move_input)
    return body


def add_cylinder(component, name, radius_mm, height_mm, z_mm):
    sketch = component.sketches.add(component.xYConstructionPlane)
    sketch.name = name + "_profile"
    sketch.sketchCurves.sketchCircles.addByCenterRadius(
        adsk.core.Point3D.create(0, 0, 0),
        mm(radius_mm),
    )
    profile = sketch.profiles.item(0)
    extrudes = component.features.extrudeFeatures
    ext_input = extrudes.createInput(profile, adsk.fusion.FeatureOperations.NewBodyFeatureOperation)
    ext_input.setDistanceExtent(False, adsk.core.ValueInput.createByReal(mm(height_mm)))
    body = extrudes.add(ext_input).bodies.item(0)
    body.name = name
    move = component.features.moveFeatures
    entities = adsk.core.ObjectCollection.create()
    entities.add(body)
    transform = adsk.core.Matrix3D.create()
    transform.translation = adsk.core.Vector3D.create(0, 0, mm(z_mm))
    move.add(move.createInput(entities, transform))
    return body


def new_component(root, name):
    transform = adsk.core.Matrix3D.create()
    occurrence = root.occurrences.addNewComponent(transform)
    occurrence.component.name = name
    return occurrence


def run(context):
    app = adsk.core.Application.get()
    ui = app.userInterface
    try:
        doc = app.documents.add(adsk.core.DocumentTypes.FusionDesignDocumentType)
        design = adsk.fusion.Design.cast(app.activeProduct)
        design.designType = adsk.fusion.DesignTypes.ParametricDesignType
        root = design.rootComponent
        root.name = "Tinman_Modular_VAWT_Native"

        diameter = float(PARAMS["rotorDiameterMm"])
        radius = diameter / 2
        module_h = float(PARAMS["moduleHeightMm"])
        tiers = int(PARAMS["tiers"])
        total_h = float(PARAMS["rotorHeightMm"])
        shaft_radius = 18.0
        hub_radius = min(88.0, radius * 0.42)
        blade_chord = min(96.0, radius * 0.46)
        blade_radius = radius - blade_chord * 0.52 - 8.0

        shaft_occ = new_component(root, "Center_Shaft_Sleeve_36mm_OD_rigid_reference")
        add_cylinder(shaft_occ.component, "center_shaft_sleeve_body", shaft_radius, total_h + 24, -12)

        bottom_occ = new_component(root, "Bottom_Generator_Coupler_Interface_60V_target")
        add_cylinder(bottom_occ.component, "bottom_generator_coupler_body", hub_radius * 0.72, 14, -14)

        top_occ = new_component(root, "Top_Bearing_Cap_Interface")
        add_cylinder(top_occ.component, "top_bearing_cap_body", hub_radius * 0.62, 10, total_h)

        for tier in range(tiers):
            tier_name = tier + 1
            z0 = tier * module_h
            zc = z0 + module_h / 2
            occ = new_component(root, f"Rotor_Tier_{{tier_name}}_CONSTRAINED_NATIVE_MODULE")
            comp = occ.component
            add_cylinder(comp, "lower_hub_disk", hub_radius, 10, z0 + 2)
            add_cylinder(comp, "upper_hub_disk", hub_radius, 10, z0 + module_h - 12)
            add_cylinder(comp, "shaft_collar_web", shaft_radius + 6, module_h - 12, z0 + 6)
            for blade in range(3):
                base_angle = blade * 120.0
                x = blade_radius * math.cos(math.radians(base_angle))
                y = blade_radius * math.sin(math.radians(base_angle))
                add_box(comp, f"blade_{{chr(65 + blade)}}_body", (blade_chord, 4, module_h - 18), (x, y, zc))
                root_length = max(60.0, blade_radius - hub_radius + blade_chord * 0.72)
                root_center_r = hub_radius + root_length / 2.0 - 8.0
                rx = root_center_r * math.cos(math.radians(base_angle))
                ry = root_center_r * math.sin(math.radians(base_angle))
                add_box(comp, f"blade_{{chr(65 + blade)}}_root_web", (root_length, 14, module_h - 30), (rx, ry, zc))

        occs = adsk.core.ObjectCollection.create()
        for occ in root.occurrences:
            occs.add(occ)
        if occs.count > 1:
            root.rigidGroups.add(occs, True)

        ui.messageBox(
            "Created Tinman native Fusion VAWT assembly. Save as .f3d, or export as .f3z if this design has external references. "
            "This script creates native Fusion components and a rigid group; STEP is still only a neutral backup."
        )
    except:
        ui.messageBox("Tinman native Fusion VAWT script failed:\\n" + traceback.format_exc())
'''


def freecad_wind_turbine_script_text(params, step_path):
    payload = json.dumps(params, sort_keys=True)
    return f"""# Tinman modular vertical wind turbine concept generator.
# Run with FreeCADCmd to export the labeled STEP assembly.
import json
import math
import FreeCAD
import Part
import Import
from FreeCAD import Vector

PARAMS = json.loads({payload!r})
STEP_PATH = {str(step_path)!r}

doc = FreeCAD.newDocument("Tinman_Modular_VAWT_Concept")
objects = []

diameter = float(PARAMS["rotorDiameterMm"])
radius = diameter / 2.0
module_h = float(PARAMS["moduleHeightMm"])
tiers = int(PARAMS["tiers"])
total_h = float(PARAMS["rotorHeightMm"])
shaft_radius = 18.0
hub_radius = min(88.0, radius * 0.42)
blade_chord = min(96.0, radius * 0.46)
blade_thickness = 3.0
blade_radius = radius - blade_chord * 0.52 - 8.0
root_web_width = 14.0
strut_width = 10.0


def add_shape(name, shape):
    obj = doc.addObject("Part::Feature", name)
    obj.Label = name
    obj.Shape = shape
    objects.append(obj)
    return obj


def cyl_shape(r, h, z):
    return Part.makeCylinder(r, h, Vector(0, 0, z), Vector(0, 0, 1))


def box_shape(sx, sy, sz, center, angle_deg=0.0):
    shape = Part.makeBox(sx, sy, sz)
    shape.translate(Vector(-sx / 2.0, -sy / 2.0, -sz / 2.0))
    shape.rotate(Vector(0, 0, 0), Vector(0, 0, 1), angle_deg)
    shape.translate(Vector(center[0], center[1], center[2]))
    return shape


def connected_module(name, shapes):
    if not shapes:
        raise RuntimeError("No shapes for connected module")
    try:
        joined = shapes[0].multiFuse(shapes[1:]) if len(shapes) > 1 else shapes[0]
        joined = joined.removeSplitter()
    except Exception:
        joined = Part.makeCompound(shapes)
    return add_shape(name, joined)


add_shape("Center_Shaft_Sleeve_36mm_OD_full_stack_reference", cyl_shape(shaft_radius, total_h + 24.0, -12.0))
add_shape("Bottom_Bearing_Generator_Coupler_Interface_60V_target", cyl_shape(hub_radius * 0.72, 14.0, -14.0))
add_shape("Top_Bearing_Cap_Interface", cyl_shape(hub_radius * 0.62, 10.0, total_h))

for tier in range(tiers):
    z0 = tier * module_h
    zc = z0 + module_h / 2.0
    tier_name = tier + 1
    tier_shapes = [
        cyl_shape(hub_radius, 10.0, z0 + 2.0),
        cyl_shape(hub_radius, 10.0, z0 + module_h - 12.0),
        cyl_shape(shaft_radius + 6.0, module_h - 12.0, z0 + 6.0),
    ]
    for blade in range(3):
        base_angle = blade * 120.0
        angle = base_angle + tier * 18.0
        x = blade_radius * math.cos(math.radians(base_angle))
        y = blade_radius * math.sin(math.radians(base_angle))
        tier_shapes.append(
            box_shape(
            blade_chord,
            blade_thickness,
            module_h - 18.0,
            (x, y, zc),
            angle + 28.0,
            )
        )
        root_length = max(60.0, blade_radius - hub_radius + blade_chord * 0.72)
        root_center_r = hub_radius + root_length / 2.0 - 8.0
        rx = root_center_r * math.cos(math.radians(base_angle))
        ry = root_center_r * math.sin(math.radians(base_angle))
        tier_shapes.append(
            box_shape(
                root_length,
                root_web_width,
                module_h - 30.0,
                (rx, ry, zc),
                base_angle,
            )
        )
        for z_web in (z0 + 20.0, z0 + module_h - 24.0):
            tier_shapes.append(
                box_shape(
                    root_length,
                    strut_width,
                    10.0,
                    (rx, ry, z_web),
                    base_angle,
                )
            )
    connected_module(
        f"Rotor_Tier_{{tier_name}}_CONNECTED_PRINT_MODULE_blades_hub_struts",
        tier_shapes,
        )

doc.recompute()
Import.export(objects, STEP_PATH)
print("WROTE_STEP", STEP_PATH)
"""


def wind_turbine_design_report_text(result):
    params = result.get("params") or {}
    step_status = "generated" if result.get("stepGenerated") else "not generated"
    native_ext = result.get("requestedFusionNativeExtension") or params.get("requestedFusionNativeArchive") or ""
    native_requested = bool(result.get("fusionNativeRequested"))
    native_status = "not requested"
    if native_requested:
        native_status = "generated" if result.get("fusionNativeArchiveGenerated") else "not generated locally"
    return f"""# Modular Vertical Wind Turbine Design Case

## Request

Design, test, and refine a modular vertical wind turbine printable in ASA-CF on a printer with a {params.get("buildVolumeMm", [270, 270, 270])} mm build volume. Target a generator/electronics path that can reach at least {params.get("voltageVdc", 60):.0f} VDC at {params.get("windMph", 4):.1f} mph.

## Generated Outputs

- STEP status: {step_status}
- STEP path: `{result.get("stepPath") or "not generated"}`
- FreeCAD generator: `{result.get("freecadScriptPath")}`
- Requested Fusion native archive: `{native_ext or "not requested"}`
- Fusion native archive status: {native_status}
- Fusion native rebuild script: `{result.get("fusionScriptPath") or "not generated"}`
- Fusion native export notes: `{result.get("fusionExportReadmePath") or "not generated"}`
- Case setup: `{result.get("caseSetupPath")}`

## First-Pass Geometry

- Rotor type: modular vertical-axis hybrid drag/lift concept for low-speed startup.
- Print material: {params.get("material", "ASA-CF")}; infill: {f'{params.get("infillPercent"):.0f}%' if params.get("infillPercent") is not None else "not specified in prompt"}.
- Rotor diameter: {params.get("rotorDiameterMm", 0):.0f} mm.
- Rotor stack height: {params.get("rotorHeightMm", 0):.0f} mm across {params.get("tiers", 0)} printable tiers.
- Module height: {params.get("moduleHeightMm", 0):.0f} mm, kept below the Z build volume.
- Bodies are labeled by tier, shaft sleeve, bearing cap, and generator coupler role.
- Each rotor tier is exported as a connected printable module with hub disks, blade root webs, struts, and blade bodies fused or compounded into one tier body.

## Fusion / STEP Assembly Note

STEP is a neutral solid-exchange format. It can preserve body/component names and positions, but it does not reliably preserve Fusion 360 parametric joints, mates, or constraints. This revision fixes the practical problem by making the printable tier modules physically connected and labeled instead of exporting loose blade and strut bodies.

## Fusion Native Archive Note

If Tinman requested `.f3d` or `.f3z`, STEP is not an acceptable substitute for the requested native Fusion deliverable. This local app can stage a Fusion 360 Python script that rebuilds native components and a rigid group, but a valid Fusion archive still has to be saved or exported by Fusion 360 itself. Blocker: {result.get("fusionNativeBlocker") or "not applicable"}.

## Feasibility Check

- Wind speed: {params.get("windMph", 0):.1f} mph = {params.get("windMs", 0):.2f} m/s.
- Swept area: {params.get("sweptAreaM2", 0):.3f} m^2.
- Wind power crossing that area: about {params.get("availableWindPowerW", 0):.2f} W.
- Betz-limit maximum: about {params.get("betzLimitW", 0):.2f} W.
- Practical first-pass mechanical range at low Reynolds number: about {params.get("expectedMechanicalPowerLowW", 0):.2f}-{params.get("expectedMechanicalPowerHighW", 0):.2f} W before generator losses.

The important engineering point is that {params.get("voltageVdc", 60):.0f} VDC at {params.get("windMph", 4):.1f} mph is mostly a generator winding, gearing, rectifier, and boost-converter target. It does not imply useful power unless the rotor swept area and torque are large enough.

## Validation Plan

1. Export or open the STEP and verify every module fits inside the {params.get("buildVolumeMm", [270, 270, 270])} mm print envelope.
2. Run a blade/rotor analysis pass with QBlade/OpenVSP/XFOIL or an OpenFOAM simplified rotor-domain study.
3. Bench-test startup RPM at 3, 4, 5, and 10 mph equivalent airflow.
4. Match measured RPM/torque to the generator KV, rectifier drop, and boost-converter input range.
5. Revise blade chord, solidity, twist offset, and tier count before calling the design final.

## Limits

This case is not a solved CFD or FEA result yet. It is a labeled CAD starting point plus a feasibility gate that prevents claiming the 60 VDC target as validated before RPM, torque, and generator data exist.
"""


def cleanup_wind_turbine_output_retention(root=None, keep=None, protect_paths=None):
    output_root = Path(root) if root else LOCAL_WIND_TURBINE_OUTPUT_DIR
    keep_count = max(1, int(keep if keep is not None else WIND_TURBINE_OUTPUT_RETENTION))
    protected = {Path(path).resolve() for path in (protect_paths or []) if path}
    if not output_root.exists():
        return {"root": str(output_root), "kept": 0, "removed": 0, "preserved": 0}
    try:
        children = list(output_root.iterdir())
    except OSError:
        return {"root": str(output_root), "kept": 0, "removed": 0, "preserved": 0}
    candidates = []
    preserved = []
    for candidate in children:
        if not candidate.is_dir():
            continue
        try:
            resolved = candidate.resolve()
            mtime = candidate.stat().st_mtime
        except OSError:
            continue
        if resolved in protected or candidate.name.startswith("_health"):
            preserved.append(candidate)
            continue
        candidates.append((mtime, candidate.name, candidate))
    candidates.sort(reverse=True)
    keep_paths = {path for _mtime, _name, path in candidates[:keep_count]}
    removed = 0
    for _mtime, _name, path in candidates:
        if path in keep_paths:
            continue
        try:
            shutil.rmtree(path)
            removed += 1
        except OSError:
            continue
    return {
        "root": str(output_root),
        "kept": len(keep_paths),
        "removed": removed,
        "preserved": len(preserved),
    }


def stage_wind_turbine_design_case(messages, cwd="", target_path=None, run_freecad=True):
    params = wind_turbine_design_parameters(messages)
    revision = is_wind_turbine_connection_revision_request(messages)
    fusion_native_ext = requested_fusion_native_archive(messages)
    persistent_output = target_path is None
    params["connectionRevision"] = revision
    params["requestedFusionNativeArchive"] = fusion_native_ext
    slug = slugify(latest_user_text(messages), fallback="vertical-wind-turbine")[:52]
    target = Path(target_path).expanduser() if target_path else LOCAL_WIND_TURBINE_OUTPUT_DIR / f"{time.strftime('%Y%m%d-%H%M%S')}-{slug}"
    target.mkdir(parents=True, exist_ok=True)
    step_name = "Tinman_Modular_VAWT_Connected_labeled.step" if revision else "Tinman_Modular_VAWT_Concept_labeled.step"
    step_path = target / step_name
    script_path = target / "generate_tinman_modular_vawt_freecad.py"
    fusion_script_path = target / "generate_tinman_modular_vawt_fusion360_native.py"
    fusion_readme_path = target / "FUSION_NATIVE_EXPORT.md"
    requested_archive_path = target / f"Tinman_Modular_VAWT_Native{fusion_native_ext}" if fusion_native_ext else None
    report_path = target / "WIND_TURBINE_DESIGN_REPORT.md"
    setup_path = target / "case_setup.json"
    script_path.write_text(freecad_wind_turbine_script_text(params, step_path), encoding="utf-8")
    fusion_installed_path = fusion360_app_path() if fusion_native_ext else ""
    if fusion_native_ext:
        fusion_script_path.write_text(fusion_wind_turbine_script_text(params), encoding="utf-8")
        fusion_readme_path.write_text(
            "\n".join(
                [
                    "# Fusion Native Export Handoff",
                    "",
                    f"Requested output: `{fusion_native_ext}`",
                    "",
                    "STEP is a neutral CAD exchange format and is not a valid substitute for Fusion 360 native constraints, joints, or design history.",
                    "",
                    "What was staged:",
                    f"- Fusion 360 script: `{fusion_script_path}`",
                    f"- Neutral STEP backup: `{step_path}`",
                    "",
                    "How to finish the native archive:",
                    "1. Open Fusion 360.",
                    "2. Go to Utilities > Scripts and Add-Ins > Scripts.",
                    "3. Add and run the staged Python script.",
                    "4. Verify the generated components and rigid group.",
                    f"5. Save/export from Fusion as `{requested_archive_path.name if requested_archive_path else 'Tinman_Modular_VAWT_Native.f3d'}`.",
                    "",
                    "Local blocker: this server does not have a safe, supported headless Fusion export path for writing a valid native `.f3d` or `.f3z` archive. It must not rename another format and pretend it is native Fusion.",
                ]
            )
            + "\n",
            encoding="utf-8",
        )
    freecad = command_path("FreeCADCmd") or command_path("freecad")
    run = {
        "attempted": False,
        "ok": False,
        "command": freecad or "",
        "returnCode": None,
        "stdout": "",
        "stderr": "",
    }
    if run_freecad and freecad:
        run["attempted"] = True
        try:
            proc = subprocess.run(
                [freecad, "-c"],
                input=f"exec(open({str(script_path)!r}, 'r', encoding='utf-8').read())\n",
                stdout=subprocess.PIPE,
                stderr=subprocess.PIPE,
                text=True,
                timeout=120,
                env={**os.environ, "PATH": PATH_FOR_CODEX},
            )
            run.update(
                {
                    "ok": proc.returncode == 0 and step_path.exists() and step_path.stat().st_size > 0,
                    "returnCode": proc.returncode,
                    "stdout": compact(proc.stdout, 1800),
                    "stderr": compact(proc.stderr, 1800),
                }
            )
        except Exception as exc:
            run.update({"ok": False, "stderr": compact(str(exc), 1800)})
    result = {
        "ok": True,
        "targetDir": str(target),
        "params": params,
        "stepPath": str(step_path),
        "stepGenerated": step_path.exists() and step_path.stat().st_size > 0,
        "freecadScriptPath": str(script_path),
        "fusionNativeRequested": bool(fusion_native_ext),
        "requestedFusionNativeExtension": fusion_native_ext,
        "fusionNativeArchivePath": str(requested_archive_path) if requested_archive_path else "",
        "fusionNativeArchiveGenerated": bool(requested_archive_path and requested_archive_path.exists() and requested_archive_path.stat().st_size > 0),
        "fusionNativeBlocker": (
            "Fusion 360 native archives must be saved or exported by Fusion 360; the local server staged the Fusion script but cannot safely export a valid native archive headlessly."
            if fusion_native_ext
            else ""
        ),
        "fusion360Installed": bool(fusion_installed_path),
        "fusion360Path": fusion_installed_path,
        "fusionScriptPath": str(fusion_script_path) if fusion_native_ext else "",
        "fusionExportReadmePath": str(fusion_readme_path) if fusion_native_ext else "",
        "reportPath": str(report_path),
        "caseSetupPath": str(setup_path),
        "freecadInstalled": bool(freecad),
        "freecadRun": run,
        "connectionRevision": revision,
        "promptExcerpt": compact(latest_user_text(messages), 1200),
    }
    report_path.write_text(wind_turbine_design_report_text(result), encoding="utf-8")
    setup_path.write_text(json.dumps(result, indent=2, sort_keys=True) + "\n", encoding="utf-8")
    if persistent_output:
        cleanup_wind_turbine_output_retention(protect_paths=[target])
    return result


def wind_turbine_design_working_notes(result):
    params = result.get("params") or {}
    notes = [
        "Classified the request as a blank-sheet vertical wind turbine design, not a printer accessory task.",
        (
            f"Captured the print envelope: {params.get('buildVolumeMm', [270, 270, 270])} mm, "
            f"material {params.get('material', 'ASA-CF')}, target {params.get('voltageVdc', 60):.0f} VDC at {params.get('windMph', 4):.1f} mph."
        ),
        (
            f"Checked the low-wind energy limit: swept area {params.get('sweptAreaM2', 0):.3f} m2, "
            f"available wind power about {params.get('availableWindPowerW', 0):.2f} W before Betz and generator losses."
        ),
    ]
    if result.get("connectionRevision"):
        notes.append("Applied Tinman's STEP feedback by exporting connected tier modules instead of loose blade/strut bodies.")
    if result.get("fusionNativeRequested"):
        requested = result.get("requestedFusionNativeExtension") or "Fusion-native archive"
        if result.get("fusionNativeArchiveGenerated"):
            notes.append(f"Generated the requested {requested} native Fusion archive.")
        else:
            notes.append(
                f"Captured the requested {requested} output as a hard contract and staged a Fusion 360 native rebuild script instead of treating STEP as equivalent."
            )
    if result.get("stepGenerated"):
        notes.append(f"Generated the labeled STEP candidate at {result.get('stepPath')}.")
