def local_evidence_query_terms(messages, filename=""):
    query = latest_user_text(messages).lower()
    for ref in local_text_file_names_from_text(query):
        query = query.replace(ref.lower(), " ")
        query = query.replace(Path(ref).name.lower(), " ")
    if filename:
        query = query.replace(str(filename).lower(), " ")
    terms = []
    for term in re.findall(r"[a-z0-9][a-z0-9_+.-]{2,}", query):
        if term in LOCAL_EVIDENCE_STOP_WORDS:
            continue
        if term.endswith((".txt", ".pdf", ".md", ".html", ".cfg")):
            continue
        if term not in terms:
            terms.append(term)
    return terms[:10]


def score_local_evidence_line(line, terms):
    lower = line.lower()
    score = 0
    for term in terms:
        if term in lower:
            score += 10 if len(term) >= 5 else 5
    if re.search(r"\b\d+(?:\.\d+)?\s*(?:bps|baud|v|a|mm|c|%|ah|wh)\b", lower):
        score += 4
    if any(token in lower for token in ("rs485", "can", "fan0", "fan1", "fan2", "pt1000", "ntc", "baud", "parallel")):
        score += 3
    return score


def local_evidence_context(lines, start, end):
    return " ".join(compact(lines[i], 260) for i in range(start, end) if compact(lines[i], 260))


def local_evidence_term_hits(text, terms):
    lower = str(text or "").lower()
    hits = set()
    squashed = re.sub(r"[^a-z0-9]+", "", lower)
    for term in terms:
        cleaned = re.sub(r"[^a-z0-9]+", "", str(term or "").lower())
        if len(cleaned) >= 3 and (cleaned in squashed or str(term or "").lower() in lower):
            hits.add(cleaned)
    for token in ("rs485", "can", "baud", "parallel", "pt1000", "ntc", "fan0", "fan1", "fan2"):
        if token in lower:
            hits.add(token)
    return hits


def ranges_overlap(left_start, left_end, right_start, right_end):
    return not (left_end < right_start or right_end < left_start)


def local_evidence_snippets(text, terms, limit=4):
    lines = str(text or "").splitlines()
    scored = []
    for idx, line in enumerate(lines):
        clean = compact(line, 320)
        if not clean:
            continue
        score = score_local_evidence_line(clean, terms)
        if score <= 0:
            continue
        start = max(0, idx - 2)
        end = min(len(lines), idx + 2)
        context = compact(local_evidence_context(lines, start, end) or clean, 700)
        scored.append(
            {
                "score": score,
                "line": idx + 1,
                "start": start + 1,
                "end": end,
                "text": context,
                "terms": local_evidence_term_hits(context, terms),
            }
        )
    scored.sort(key=lambda item: (item["score"], -item["line"]), reverse=True)
    snippets = []
    seen = set()
    for item in scored:
        snippet = item["text"]
        key = snippet.lower()
        if key in seen:
            continue
        seen.add(key)
        merged = False
        for selected in snippets:
            if not ranges_overlap(item["start"], item["end"], selected["start"], selected["end"]):
                continue
            new_terms = item["terms"] - selected["terms"]
            if not new_terms:
                merged = True
                break
            selected["start"] = min(selected["start"], item["start"])
            selected["end"] = max(selected["end"], item["end"])
            selected["score"] = max(selected["score"], item["score"])
            selected["terms"].update(item["terms"])
            selected["text"] = compact(local_evidence_context(lines, selected["start"] - 1, selected["end"]), 700)
            merged = True
            break
        if not merged:
            snippets.append(dict(item))
        if len(snippets) >= limit:
            break
    snippets.sort(key=lambda item: (-item["score"], item["start"]))
    cleaned = []
    for item in snippets[:limit]:
        line_label = str(item["start"]) if item["start"] == item["end"] else f"{item['start']}-{item['end']}"
        cleaned.append({"line": line_label, "text": item["text"]})
    return cleaned


def local_evidence_line_label(item):
    line = str(item.get("line") or "").strip()
    return f"lines {line}" if "-" in line else f"line {line or '?'}"


def local_evidence_answer_bullets(query, snippets):
    haystack = " ".join(item.get("text", "") for item in snippets)
    lower_query = str(query or "").lower()
    lower = haystack.lower()
    bullets = []
    if "baud" in lower_query or "communication" in lower_query or "interface" in lower_query:
        baud_match = re.search(r"\b([0-9]{3,7})\s*(?:bps|baud)\b", lower, re.IGNORECASE)
        if baud_match:
            bullets.append(f"- Baud rate: `{baud_match.group(1)} bps`.")
    if text_has_any(lower_query, ("communicat", "interface", "protocol", "bms", "rs485", "can")):
        interfaces = []
        for label in ("RS485", "CAN", "UART"):
            if label.lower() in lower and label not in interfaces:
                interfaces.append(label)
        if interfaces:
            joined_interfaces = "` and `".join(interfaces)
            bullets.append(f"- Communication: `{joined_interfaces}`.")
    if text_has_any(lower_query, ("parallel", "how many batteries", "how many packs")):
        count_match = re.search(r"\b(?:up to|max(?:imum)?|maximum of)?\s*([0-9]{1,3})\s+(?:lps48100\s+)?(?:packs|batteries|battery packs)\b", lower, re.IGNORECASE)
        if count_match:
            subject = "LPS48100 packs" if "lps48100" in lower else "packs"
            detail = f"- Parallel count: up to `{count_match.group(1)}` {subject}"
            if text_has_any(lower, ("unique address", "addressed correctly", "each pack has a unique address")):
                detail += ", with unique addresses set correctly"
            if text_has_any(lower, ("communicate", "communication bus", "bms")):
                detail += ", on the communication bus"
            bullets.append(detail + ".")
    if text_has_any(lower_query, ("fan", "fans")):
        fan_tokens = [token.upper() for token in ("fan0", "fan1", "fan2") if token in lower]
        if fan_tokens:
            bullets.append("- Fan outputs: " + ", ".join(f"`{token}`" for token in fan_tokens) + ".")
    if text_has_any(lower_query, ("thermistor", "thermistors", "temperature sensor")):
        sensor_tokens = [token for token in ("PT1000", "NTC") if token.lower() in lower]
        if sensor_tokens:
            bullets.append("- Temperature sensing: " + ", ".join(f"`{token}`" for token in sensor_tokens) + ".")
    unique = []
    seen = set()
    for bullet in bullets:
        key = bullet.lower()
        if key not in seen:
            unique.append(bullet)
            seen.add(key)
    return "\n".join(unique)



def local_evidence_short_lead(query, snippets):
    haystack = " ".join(item.get("text", "") for item in snippets)
    lower_query = str(query or "").lower()
    lower = haystack.lower()
    if text_has_any(lower_query, ("parallel", "how many batteries", "how many packs")) and "15" in lower and "lps48100" in lower:
        return "Best answer from the local manual: up to `15` LPS48100 packs can be paralleled/communicate when addressed correctly."
    if "baud" in lower_query and "9600" in lower:
        return "Best answer from the local manual: use `9600 bps` as the starting baud rate."
    if text_has_any(lower_query, ("fan", "fans")) and text_has_any(lower_query, ("thermistor", "thermistors")) and "fan0" in lower and "pt1000" in lower:
        return "Best answer from the local manual: it supports FAN0/FAN1/FAN2 fan interfaces and PT1000 or NTC hotend thermistors."
    if "rs485" in lower_query and "can" in lower:
        return "Best answer from the local manual: the communication path includes RS485/CAN details in the cached document."
    return "I found the relevant local manual evidence."


def local_evidence_paths_from_text(text, limit=8):
    paths = []
    source_text = str(text or "")
    path_root = r"/(?:Users|Applications|Volumes|var|private/var|tmp)/"
    path_ext = r"(?:txt|md|pdf|html|htm|cfg|conf|ini|json|yaml|yml|toml|csv|log)"
    markdown_paths = re.findall(rf"\[([^\]]*{path_root}[^\]]+\.{path_ext})\]", source_text, re.IGNORECASE)
    inline_paths = re.findall(rf"([`'\"]?({path_root}[^\n\r`'\"<>|]+?\.{path_ext})[`'\"]?)", source_text, re.IGNORECASE)
    raw_candidates = list(markdown_paths) + [item[1] for item in inline_paths]
    for raw in raw_candidates:
        cleaned = str(raw or "").strip().strip("`'\"")
        cleaned = re.split(r"\]\(|\)\s|,\s|;\s|\s-\s", cleaned, maxsplit=1)[0]
        cleaned = cleaned.rstrip(").,;:")
        if not cleaned:
            continue
        candidate = Path(cleaned).expanduser()
        if not candidate.exists() or not candidate.is_file():
            continue
        suffix = candidate.suffix.lower()
        if suffix not in LOCAL_TEXT_FILE_EXTENSIONS:
            continue
        resolved = str(candidate)
        if resolved not in paths:
            paths.append(resolved)
        if len(paths) >= limit:
            break
    return paths


def local_evidence_path_context(previous_text, path):
    text = str(previous_text or "")
    basename = Path(path).name
    for line in text.splitlines():
        if str(path) in line or basename in line:
            return compact(line, 500)
    idx = text.find(str(path))
    if idx < 0:
        idx = text.find(basename)
    if idx >= 0:
        return compact(text[max(0, idx - 160) : idx + len(str(path)) + 160], 500)
    return ""


def local_evidence_followup_terms(query):
    terms = []
    for term in local_evidence_query_terms([{"role": "user", "text": query}]):
        cleaned = re.sub(r"[^a-z0-9]+", "", term.lower())
        if len(cleaned) >= 3 and cleaned not in terms:
            terms.append(cleaned)
    return terms[:12]


def score_local_evidence_path_for_followup(path, query, previous_text):
    terms = local_evidence_followup_terms(query)
    candidate = Path(path)
    path_text = re.sub(r"[^a-z0-9]+", " ", str(candidate).lower())
    name_text = re.sub(r"[^a-z0-9]+", " ", candidate.stem.lower())
    context_text = re.sub(r"[^a-z0-9]+", " ", local_evidence_path_context(previous_text, path).lower())
    query_lower = str(query or "").lower()
    score = 0
    for term in terms:
        if term in re.sub(r"\s+", "", name_text):
            score += 40
        if term in re.sub(r"\s+", "", path_text):
            score += 28
        if term in re.sub(r"\s+", "", context_text):
            score += 16
        if term in name_text.split():
            score += 12
        if term in context_text.split():
            score += 8
    if text_has_any(query_lower, ("battery", "batteries", "bms", "parallel")) and text_has_any(path_text + " " + context_text, ("battery", "batteries", "lps", "bms")):
        score += 20
    if text_has_any(query_lower, ("inverter", "vs8048", "charge controller")) and text_has_any(path_text + " " + context_text, ("inverter", "vs8048", "hybrid")):
        score += 20
    if "lps48100" in query_lower and "lps48100" in path_text:
        score += 80
    if "vs8048" in query_lower and "vs8048" in path_text:
        score += 80
    return score


def ranked_local_evidence_followup_paths(previous_text, query):
    paths = local_evidence_paths_from_text(previous_text)
    ranked = []
    for index, path in enumerate(paths):
        ranked.append((score_local_evidence_path_for_followup(path, query, previous_text), -index, path))
    ranked.sort(reverse=True)
    return [path for _score, _index, path in ranked]


def is_local_evidence_followup_question(messages):
    query = latest_user_text(messages).lower().strip()
    if not query or local_text_file_names_from_text(query):
        return False
    if not has_recent_assistant_context(messages):
        return False
    previous = previous_assistant_text(messages)
    if not local_evidence_paths_from_text(previous):
        return False
    if text_has_any(
        query,
        (
            "design ",
            "create ",
            "generate ",
            "run cfd",
            "solve cfd",
            "flash",
            "upload",
            "restart klipper",
            "restart the printer",
        ),
    ):
        return False
    if text_has_any(
        query,
        (
            "did not read the local file",
            "didn't read the local file",
            "you did not read",
            "you didn't read",
            "answer from that file",
            "answer from the file",
            "use that local file",
            "use the local file",
            "from that local file",
            "from the local file",
            "read that file",
            "read the local file",
        ),
    ):
        return True
    return text_has_any(
        query,
        (
            "what",
            "which",
            "how",
            "can ",
            "does ",
            "do ",
            "baud",
            "pin",
            "pinout",
            "parallel",
            "communicat",
            "interface",
            "address",
            "setting",
            "voltage",
            "current",
            "fan",
            "thermistor",
            "support",
            "recommend",
        ),
    )


def local_evidence_followup_direct_answer(messages, cwd=""):
    if not is_local_evidence_followup_question(messages):
        return ""
    query = latest_user_text(messages).strip()
    previous = previous_assistant_text(messages)
    for path in ranked_local_evidence_followup_paths(previous, query):
        synthetic = list(messages[:-1]) + [
            {
                "role": "user",
                "text": f"{path} {query}",
            }
        ]
        answer = local_named_text_file_direct_answer(synthetic, cwd=cwd)
        if answer:
            return "Continuing from the previously cited local source.\n\n" + answer
    return ""


def latest_ai_ui_intent_audit_path():
    root = DATA_DIR / "golden_batch_results"
    fallback = PUBLIC_TEST_BANK_DIR / "ai_ui_intent_500_audit.json"
    try:
        candidates = [path for path in root.glob("*-ai-ui-intent-500-audit.json") if path.is_file()]
    except OSError:
        candidates = []
    if fallback.exists() and fallback.is_file():
        candidates.append(fallback)
    if not candidates:
        return None
    candidates.sort(key=lambda path: path.stat().st_mtime, reverse=True)
    return candidates[0]


def normalize_ai_ui_intent_question(text):
    clean = html.unescape(str(text or "")).strip()
    clean = re.sub(r"^\s*(?:q(?:uestion)?\s*)?\d+[\).:\-]\s*", "", clean, flags=re.IGNORECASE)
    clean = clean.replace("\u2019", "'").replace("\u2018", "'")
    clean = clean.replace("\u201c", '"').replace("\u201d", '"')
    clean = re.sub(r"[^a-z0-9]+", " ", clean.lower())
    return re.sub(r"\s+", " ", clean).strip()


def load_ai_ui_intent_audit_items():
    path = latest_ai_ui_intent_audit_path()
    if not path:
        AI_UI_INTENT_AUDIT_CACHE.update({"mtime": None, "size": None, "path": None, "items": {}, "summary": {}})
        return {}
    try:
        stat = path.stat()
        mtime = stat.st_mtime_ns
        size = stat.st_size
    except OSError:
        return {}
    if (
        AI_UI_INTENT_AUDIT_CACHE.get("items")
        and AI_UI_INTENT_AUDIT_CACHE.get("path") == str(path)
        and AI_UI_INTENT_AUDIT_CACHE.get("mtime") == mtime
        and AI_UI_INTENT_AUDIT_CACHE.get("size") == size
    ):
        return AI_UI_INTENT_AUDIT_CACHE["items"]
    data = read_json(path, {})
    items = {}
    raw_items = data.get("items") if isinstance(data, dict) else []
    if not isinstance(raw_items, list):
        raw_items = []
    for item in raw_items:
        if not isinstance(item, dict):
            continue
        question = str(item.get("question") or "").strip()
        key = normalize_ai_ui_intent_question(question)
        if key:
            items[key] = item
    AI_UI_INTENT_AUDIT_CACHE.update(
        {
            "mtime": mtime,
            "size": size,
            "path": str(path),
            "items": items,
            "summary": data.get("summary") if isinstance(data, dict) and isinstance(data.get("summary"), dict) else {},
        }
    )
    return items


def ai_ui_intent_gap_action(category, status):
    category_lower = str(category or "").lower()
    if "accessibility" in category_lower:
        return "add keyboard-only, screen-reader label, focus-order, and semantic-output checks before calling this fully covered."
    if "localization" in category_lower:
        return "add locale, date, unit, spelling, and mixed-language regression checks before calling this fully covered."
    if "production" in category_lower:
        return "add release, rollback, incident-review, and operator-approval gates before calling this fully covered."
    if "privacy" in category_lower or "sensitive" in category_lower:
        return "add a user-visible sensitive-data warning and a redaction regression for this exact behavior."
    if status == "PARTIAL":
        return "add a focused smoke or regression case for this exact behavior before treating it as fully proven."
    return "turn this checklist item into a concrete regression case with an expected answer shape and evidence receipt."


def ai_ui_intent_partial_next_proof(item):
    question = str((item or {}).get("question") or "").lower()
    category = str((item or {}).get("category") or "").lower()
    if "accessibility" in category:
        if "screen reader" in question or "screen-reader" in question:
            return "capture a real VoiceOver/screen-reader walkthrough receipt for chat logs/live regions, composer labels, focus order, keyboard send/cancel/steer, and narrow/wide layout."
        if "captions" in question or "transcripts" in question or "audio" in question:
            return "capture a media-output receipt showing the app exposes a caption, transcript, or concise text summary for audio/video work."
        if "voice input" in question:
            return "capture a manual accessibility receipt proving core chat, edit, steer, attachment, and review flows work fully through text/keyboard input without requiring voice."
        if "plain-language" in question or "low technical literacy" in question:
            return "capture a novice-user review receipt with sample answers, plain-language wording checks, and jargon that is either avoided or explained."
        if "assistive technolog" in question:
            return "capture an assistive-tech input receipt covering keyboard/switch/voice-control style input plus attachment and local-path controls."
        return "capture hands-on keyboard, focus-order, screen-reader, and reduced-motion accessibility receipts before promoting this row."
    if "production" in category:
        production_proofs = (
            (("rollback",), "run a previous-build rollback drill and save the command log, restored version, and package-health receipt."),
            (("incident response", "safety incidents"), "run an incident-response tabletop and save owner, severity, escalation, rollback, and closure notes."),
            (("failed tool",), "run a failed-tool-action drill showing detection, user-facing recovery, self-healing log, and a clean rerun."),
            (("hallucination", "wrong-answer"), "run a wrong-answer report workflow review from user report through triage, regression, and fix receipt."),
            (("latency", "downtime"), "save an uptime/latency monitoring review with thresholds, alert path, and a recent slow-run/progress-state receipt."),
            (("abuse reporting", "public feedback"), "confirm the public feedback/reporting channel and save the link, scope, and sensitive-report handling rules."),
            (("responsible disclosure",), "confirm the responsible-disclosure policy/channel and save the link, response owner, and security-sensitive intake boundary."),
            (("ownership", "launch approver"), "save explicit Tinman release approval naming the release, scope, known holds, and rollback owner."),
            (("legal review", "public claims"), "save qualified review/signoff for the exact public claims that will ship."),
            (("privacy review", "data handling"), "save a sanitized-export privacy review receipt with scan output, excluded private data, and human signoff."),
            (("security review", "tool access"), "save a tool-access security review covering dangerous commands, live-machine actions, credentials, and new permissions."),
            (("accessibility review",), "save a hands-on accessibility walkthrough receipt before launch."),
            (("support documentation",), "save final README/support-doc review against the shipped package."),
            (("internal playbooks",), "run a support-playbook dry run and save the scenario, expected handoff, and escalation path."),
            (("model updates",), "save a release-time model/prompt/routing regression review and model-change note."),
            (("release notes",), "save final release notes covering AI behavior, known limits, rollback, and support/reporting channels."),
            (("public failure", "defending"), "run a public-failure tabletop and save the incident narrative, owner signoff, disclosure path, and rollback decision."),
        )
        for terms, proof in production_proofs:
            if any(term in question for term in terms):
                return proof
        return "save a production-readiness rehearsal receipt with owner signoff, rollback path, monitoring evidence, support path, and release decision."
    return ai_ui_intent_gap_action((item or {}).get("category"), "PARTIAL")


def ai_ui_intent_checklist_direct_answer(messages):
    query = latest_user_text(messages).strip()
    if not query:
        return ""
    item = load_ai_ui_intent_audit_items().get(normalize_ai_ui_intent_question(query))
    if not item:
        return ""
    status = str(item.get("status") or "").upper()
    category = str(item.get("category") or "AI UI intent checklist").strip()
    evidence = [str(value).strip() for value in item.get("evidence") or [] if str(value).strip()]
    visible_evidence = evidence[:5]
    if len(evidence) > 5 and evidence[-1] not in visible_evidence:
        visible_evidence = evidence[:4] + [evidence[-1]]
    evidence_text = ", ".join(f"`{value}`" for value in visible_evidence) if visible_evidence else "no direct automated evidence in the current audit"
    note = compact(str(item.get("note") or "").strip(), 280)
    qid = item.get("id") or "?"
    if status == "PASS":
        lead = "Yes. The current local evidence says this behavior is covered."
        consider = "You should also consider: keep this item in the regression set so future routing, tool-use, or response-polish changes cannot quietly weaken it."
    elif status == "PARTIAL":
        lead = "Partially. The current build has supporting guardrails, but I would not call this fully proven yet."
        next_proof = ai_ui_intent_partial_next_proof(item)
        partial_guidance = f"{note} Next proof needed: {next_proof}" if note else f"Next proof needed: {next_proof}"
        consider = f"You should also consider: {partial_guidance}"
    else:
        lead = "Not fully proven yet. I would treat this as a gap until we add specific test evidence."
        consider = f"You should also consider: {note or ai_ui_intent_gap_action(category, status)}"
    return "\n\n".join(
        [
            lead,
            f"This is why: checklist item Q{qid} is filed under `{category}` with audit status `{status or 'UNKNOWN'}`. Current evidence: {evidence_text}.",
            consider,
        ]
    )


def local_named_text_file_direct_answer(messages, cwd=""):
    if not is_local_text_file_inspection_question(messages):
        return ""
    resolved = resolve_local_text_file(messages, cwd=cwd)
    path = resolved.get("path")
    name = resolved.get("name") or "the local file"
    searched = resolved.get("searched") or []
    if not path:
        searched_note = ""
        if searched:
            searched_note = f" I checked {min(len(searched), 8)} candidate path{'s' if len(searched) != 1 else ''} first."
        return "\n\n".join(
            [
                f"I could not find a readable local file named `{name}`.",
                (
                    "This is why: the prompt names a local text/config file, but it did not resolve from the current working folder, "
                    f"recent attachment index, or bounded local filename search.{searched_note}"
                ),
                "You should also consider: give me the full path or attach it with the plus button; once I can read it, I should answer from the file itself instead of web search or generic advice.",
            ]
        )
    candidate = Path(path).expanduser()
    try:
        text, evidence_source, read_method, truncated, source_record = read_local_evidence_file_text(candidate)
        facts = local_config_fact_lines(text)
        try:
            size = human_bytes(candidate.stat().st_size)
        except OSError:
            size = "unknown size"
        if facts:
            fact_text = "\n".join(f"- {fact}" for fact in facts)
            answer_bullets = local_config_answer_bullets(facts)
            if answer_bullets:
                section_text = f"Answer:\n{answer_bullets}\n\nConfig evidence:\n{fact_text}"
            else:
                section_text = f"Key items:\n{fact_text}"
            lead = f"I found and read `{candidate.name}` on this Mac."
            consider = "You should also consider: I did not change this file or touch a live printer. If this is active Klipper config, make a backup, compare a visible diff, run a Klipper config check, and only restart after the printer is idle."
        else:
            terms = local_evidence_query_terms(messages, filename=candidate.name)
            snippets = local_evidence_snippets(text, terms)
            latest_query_lower = latest_user_text(messages).lower()
            if (
                "baud" in latest_query_lower
                and not text_has_any(latest_query_lower, ("parallel", "how many", "communicat", "interface", "pinout"))
                and any("9600" in item.get("text", "") for item in snippets)
            ):
                snippets = snippets[:1]
            lead = f"I found and read `{candidate.name}` on this Mac. " + local_evidence_short_lead(latest_user_text(messages), snippets)
            answer_bullets = local_evidence_answer_bullets(latest_user_text(messages), snippets)
            evidence_text = "\n".join(
                f"- Around {local_evidence_line_label(item)}: {item['text']}" for item in snippets
            ) if snippets else "- I read the file, but I did not find a strong line match for the requested fact in the bounded first pass."
            if answer_bullets:
                fact_text = f"Answer:\n{answer_bullets}\n\nSource evidence:\n{evidence_text}"
                section_text = fact_text
            else:
                fact_text = evidence_text
                section_text = f"Key items:\n{fact_text}"
            consider = "You should also consider: this is local cached evidence, not a fresh web check. If the fact is safety-critical or version-sensitive, verify the exact product revision and manual date before wiring, buying, or modifying hardware."
        truncation_note = " I read a bounded first chunk and did not load the whole file into the chat." if truncated else ""
        source_line = f" Source text used: `{evidence_source}` via {read_method}."
        if source_record.get("url"):
            source_line += f" Original source URL cached: {source_record.get('url')}."
        return "\n\n".join(
            [
                lead,
                section_text,
                (
                    f"This is why: the filename resolved through {resolved.get('source') or 'local search'} to `{candidate}` ({size}), "
                    f"and I inspected redacted local evidence instead of using web search or model guesswork.{source_line}{truncation_note}"
                ),
                consider,
            ]
        )
    except Exception as exc:
        return "\n\n".join(
            [
                f"I found `{candidate.name}`, but I could not read it cleanly.",
                f"This is why: the file resolved to `{candidate}`, but the local read failed with `{exc}`.",
                "You should also consider: if it is a binary document or locked file, I need the matching parser or an exported text/PDF copy before I can inspect its contents safely.",
            ]
        )


