def parse_xz_robot_uncompressed_bytes(text):
    best = 0
    for line in str(text or "").splitlines():
        parts = [part.strip() for part in line.split("\t") if part.strip()]
        if not parts or parts[0] not in {"file", "totals"}:
            continue
        nums = [int(part) for part in parts[1:] if re.fullmatch(r"\d+", part)]
        if nums:
            best = max(best, max(nums))
    return best


def disk_space_for_path(path):
    candidate = Path(path).expanduser()
    probe = candidate if candidate.exists() else candidate.parent
    while probe and not probe.exists() and probe != probe.parent:
        probe = probe.parent
    usage = shutil.disk_usage(probe if probe and probe.exists() else Path.home())
    return {
        "path": str(probe if probe and probe.exists() else Path.home()),
        "totalBytes": int(usage.total),
        "usedBytes": int(usage.used),
        "freeBytes": int(usage.free),
        "total": human_bytes(usage.total),
        "used": human_bytes(usage.used),
        "free": human_bytes(usage.free),
    }


def estimate_embedded_image_work_bytes(image_size, uncompressed_size=0):
    base = max(int(uncompressed_size or 0), int(image_size or 0) * 4, int(image_size or 0))
    if base <= 0:
        return 0
    return int(base * 2.35) + (2 * 1024 * 1024 * 1024)


def stage_ratos_pi5_builder(target, image_path):
    target = Path(target)
    script_path = target / "build_ratos_pi5_candidate.sh"
    runner_path = target / "run_build.command"
    template_candidates = [
        APP_DIR / "tools" / "ratos-pi5-experimental" / "scripts" / "build-ratos-pi5-candidate.sh",
        Path.home() / "Documents" / "GitHub" / "ratos-pi5-experimental" / "scripts" / "build-ratos-pi5-candidate.sh",
    ]
    template_used = ""
    for template in template_candidates:
        if template.exists() and template.is_file():
            try:
                script_path.write_bytes(template.read_bytes())
                template_used = str(template)
                break
            except OSError:
                continue
    if not script_path.exists():
        script_path.write_text(
            "\n".join(
                [
                    "#!/usr/bin/env bash",
                    "set -euo pipefail",
                    "cat >&2 <<'NOTE'",
                    "No RatOS Pi 5 builder template is installed in this Codex CLI UI package yet.",
                    "Install or provide the free ratos-pi5-experimental builder, then rerun this wrapper.",
                    "This script intentionally does not flash removable media.",
                    "NOTE",
                    "exit 2",
                    "",
                ]
            ),
            encoding="utf-8",
        )
    source_literal = str(image_path or "").replace("\\", "\\\\").replace('"', '\\"').replace("$", "\\$")
    runner_path.write_text(
        "\n".join(
            [
                "#!/usr/bin/env bash",
                "set -euo pipefail",
                "WORKDIR=$(cd \"$(dirname \"$0\")\" && pwd)",
                f"SOURCE_IMAGE=\"${{1:-{source_literal}}}\"",
                "exec \"$WORKDIR/build_ratos_pi5_candidate.sh\" --source \"$SOURCE_IMAGE\" --out \"$WORKDIR\"",
                "",
            ]
        ),
        encoding="utf-8",
    )
    try:
        script_path.chmod(0o755)
        runner_path.chmod(0o755)
    except OSError:
        pass
    return {
        "scriptPath": str(script_path),
        "runnerPath": str(runner_path),
        "templateUsed": template_used,
        "available": bool(template_used),
        "candidateImagePath": str(target / "ratos-pi5-candidate.img"),
        "verificationPath": str(target / "pi5-graft-verification.txt"),
    }


def run_ratos_pi5_builder(target, builder):
    target = Path(target)
    stdout_path = target / "build_stdout.txt"
    stderr_path = target / "build_stderr.txt"
    if not builder.get("available"):
        return {
            "attempted": False,
            "ok": False,
            "blocked": True,
            "reason": "RatOS Pi 5 builder template is not installed.",
        }
    runner = builder.get("runnerPath")
    if not runner or not Path(runner).exists():
        return {
            "attempted": False,
            "ok": False,
            "blocked": True,
            "reason": "Candidate-builder runner was not staged.",
        }
    if not command_path("docker"):
        return {
            "attempted": False,
            "ok": False,
            "blocked": True,
            "reason": "Docker CLI is not available for the Pi 5 image graft builder.",
        }
    timeout = int(os.environ.get("CODEX_EMBEDDED_IMAGE_BUILD_TIMEOUT_SEC", "1800"))
    started = time.time()
    try:
        proc = subprocess.run(
            [runner],
            cwd=str(target),
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            text=True,
            timeout=timeout,
            env={**os.environ, "PATH": PATH_FOR_CODEX},
        )
        stdout_path.write_text(proc.stdout or "", encoding="utf-8")
        stderr_path.write_text(proc.stderr or "", encoding="utf-8")
        candidate_exists = Path(builder.get("candidateImagePath") or "").exists()
        verification_exists = Path(builder.get("verificationPath") or "").exists()
        return {
            "attempted": True,
            "ok": proc.returncode == 0 and candidate_exists,
            "returnCode": proc.returncode,
            "durationSec": round(time.time() - started, 1),
            "candidateExists": candidate_exists,
            "verificationExists": verification_exists,
            "stdoutPath": str(stdout_path),
            "stderrPath": str(stderr_path),
            "stdoutTail": compact(proc.stdout[-2000:] if proc.stdout else "", 2000),
            "stderrTail": compact(proc.stderr[-2000:] if proc.stderr else "", 2000),
        }
    except subprocess.TimeoutExpired as exc:
        stdout_path.write_text(exc.stdout or "", encoding="utf-8")
        stderr_path.write_text(exc.stderr or "", encoding="utf-8")
        return {
            "attempted": True,
            "ok": False,
            "blocked": True,
            "reason": f"Candidate build timed out after {timeout} seconds.",
            "durationSec": round(time.time() - started, 1),
            "stdoutPath": str(stdout_path),
            "stderrPath": str(stderr_path),
        }
    except Exception as exc:
        return {
            "attempted": True,
            "ok": False,
            "blocked": True,
            "reason": str(exc),
            "durationSec": round(time.time() - started, 1),
            "stdoutPath": str(stdout_path),
            "stderrPath": str(stderr_path),
        }


def embedded_image_xz_listing(path):
    if not path:
        return {"ok": False, "error": "missing image path"}
    xz_path = command_path("xz")
    if not xz_path:
        return {"ok": False, "error": "xz command is not available"}
    try:
        proc = subprocess.run(
            [xz_path, "-l", str(path)],
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            text=True,
            timeout=30,
            env={**os.environ, "PATH": PATH_FOR_CODEX},
        )
        robot_proc = subprocess.run(
            [xz_path, "--robot", "-l", str(path)],
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            text=True,
            timeout=30,
            env={**os.environ, "PATH": PATH_FOR_CODEX},
        )
    except Exception as exc:
        return {"ok": False, "error": str(exc)}
    return {
        "ok": proc.returncode == 0,
        "stdout": compact(proc.stdout, 1200),
        "stderr": compact(proc.stderr, 600),
        "robotStdout": compact(robot_proc.stdout, 1200),
        "robotStderr": compact(robot_proc.stderr, 600),
        "returnCode": proc.returncode,
        "robotReturnCode": robot_proc.returncode,
        "uncompressedBytes": parse_xz_robot_uncompressed_bytes(robot_proc.stdout),
    }


def stage_embedded_linux_image_preflight(messages, cwd="", target_path=None, execute_build=False):
    resolved = resolve_embedded_image_file(messages, cwd=cwd)
    image_path = resolved.get("path")
    slug = slugify(latest_user_text(messages), fallback="embedded-image")[:48]
    target = Path(target_path).expanduser() if target_path else LOCAL_EMBEDDED_IMAGE_OUTPUT_DIR / f"{time.strftime('%Y%m%d-%H%M%S')}-{slug}"
    target.mkdir(parents=True, exist_ok=True)
    action_requested = embedded_image_action_requested(messages)
    source_found = bool(image_path and Path(image_path).exists())
    image_size = int(Path(image_path).stat().st_size) if source_found else 0
    xz_info = embedded_image_xz_listing(image_path) if source_found and str(image_path).lower().endswith(".xz") else {"ok": False, "error": "not an xz-compressed image or source missing"}
    uncompressed_size = int(xz_info.get("uncompressedBytes") or (image_size if source_found and str(image_path).lower().endswith(".img") else 0))
    estimated_required = estimate_embedded_image_work_bytes(image_size, uncompressed_size) if source_found else 0
    disk_info = disk_space_for_path(target)
    storage_ok = bool(source_found and estimated_required and disk_info.get("freeBytes", 0) > estimated_required)
    builder = stage_ratos_pi5_builder(target, image_path) if source_found else {}
    build_result = {}
    file_info = ""
    if source_found and command_path("file"):
        try:
            proc = subprocess.run(
                [command_path("file"), str(image_path)],
                stdout=subprocess.PIPE,
                stderr=subprocess.PIPE,
                text=True,
                timeout=20,
                env={**os.environ, "PATH": PATH_FOR_CODEX},
            )
            file_info = compact(proc.stdout or proc.stderr, 400)
        except Exception as exc:
            file_info = f"file command failed: {exc}"

    setup = {
        "task": "RatOS/Raspberry Pi 5 image compatibility action",
        "actionRequested": action_requested,
        "sourceFound": source_found,
        "sourcePath": str(image_path) if source_found else "",
        "sourceName": resolved.get("name") or "",
        "source": resolved.get("source") or "",
        "sizeBytes": image_size,
        "size": human_bytes(image_size) if image_size else "",
        "uncompressedBytes": uncompressed_size,
        "uncompressedSize": human_bytes(uncompressed_size) if uncompressed_size else "",
        "estimatedWorkBytes": estimated_required,
        "estimatedWorkSize": human_bytes(estimated_required) if estimated_required else "",
        "disk": disk_info,
        "storageOk": storage_ok,
        "searched": resolved.get("searched", [])[:30],
        "targetDir": str(target),
        "builder": builder,
        "pi5MustCheck": [
            "boot firmware files in the FAT boot partition",
            "Raspberry Pi 5 DTB files such as bcm2712-rpi-5-b.dtb",
            "kernel version/config with Pi 5 support",
            "config.txt overlays and cmdline.txt rootfs references",
            "32-bit versus 64-bit userland and RatOS service compatibility",
            "Klipper/Moonraker/RatOS services after first boot",
        ],
        "safetyBoundary": "Check local storage before expansion; never flash removable media or claim Pi 5 bootability without explicit hardware confirmation.",
    }
    setup_path = target / "case_setup.json"
    write_json_atomic(setup_path, setup)

    report_path = target / "RATOS_PI5_IMAGE_ACTION.md"
    searched_lines = "\n".join(f"- `{item}`" for item in resolved.get("searched", [])[:12]) or "- No candidate paths were searched."
    xz_block = xz_info.get("stdout") or xz_info.get("stderr") or xz_info.get("error") or "not run"
    report_path.write_text(
        "\n".join(
            [
                "# RatOS Raspberry Pi 5 Image Action Readiness",
                "",
                "## Result",
                (
                    f"- Source image found: `{image_path}` ({human_bytes(image_size)})"
                    if source_found
                    else f"- Source image not found. Filename reference: `{resolved.get('name') or 'unknown'}`"
                ),
                f"- Resolver source: {resolved.get('source') or 'not resolved'}",
                "- Classification: embedded Linux / Raspberry Pi OS-image port, not CAD, CFD, or structural FEA.",
                (
                    "- Status: action-ready. Local storage is sufficient for expansion/candidate work, and a candidate builder path is staged."
                    if source_found and storage_ok and action_requested
                    else "- Status: blocked before image modification until the source image and storage decision are resolved."
                ),
                "- Boot status: not yet boot-tested on Raspberry Pi 5.",
                "- Flash status: no removable media was written or flashed.",
                "",
                "## Storage Decision",
                f"- Volume checked: `{disk_info.get('path')}`",
                f"- Free space: {disk_info.get('free')}",
                f"- Compressed image size: {human_bytes(image_size) if image_size else 'unknown'}",
                f"- Uncompressed image size: {human_bytes(uncompressed_size) if uncompressed_size else 'unknown'}",
                f"- Estimated local work space needed: {human_bytes(estimated_required) if estimated_required else 'unknown'}",
                f"- Storage OK for local candidate work: {'yes' if storage_ok else 'no'}",
                "",
                "## Candidate Builder",
                f"- Builder script: `{builder.get('scriptPath', '') or 'not staged'}`",
                f"- One-shot runner: `{builder.get('runnerPath', '') or 'not staged'}`",
                f"- Expected candidate image: `{builder.get('candidateImagePath', '') or 'not staged'}`",
                f"- Verification output: `{builder.get('verificationPath', '') or 'not staged'}`",
                f"- Builder template source: `{builder.get('templateUsed', '') or 'missing'}`",
                "",
                "## Quick File Inspection",
                f"- `file`: {file_info.strip() or 'not run'}",
                "- `xz -l`:",
                "```text",
                xz_block,
                "```",
                "",
                "## Pi 5 Compatibility Checklist",
                "- Confirm the boot partition has Pi 5 firmware and `bcm2712-rpi-5-b.dtb`.",
                "- Confirm the kernel and modules support Raspberry Pi 5 hardware.",
                "- Confirm `config.txt`, overlays, and `cmdline.txt` match the partition layout.",
                "- Confirm the RatOS base is not pinned to Pi 4-only firmware or kernel packages.",
                "- Confirm Klipper, Moonraker, CAN/USB printer interfaces, networking, and RatOS services start cleanly after first boot.",
                "- Write only to a confirmed removable target after Tinman explicitly chooses the target device.",
                "",
                "## Searched Paths",
                searched_lines,
                "",
                "## Next Safe Step",
                (
                    "Run the one-shot builder in this folder to create a local candidate image, then boot-test it on a spare Pi 5 SD card."
                    if source_found and storage_ok and builder.get("available")
                    else "Resolve the blocker above, then expand locally, inspect the boot partition, and patch or rebuild against a Pi 5-capable Raspberry Pi OS/RatOS base."
                ),
                "",
            ]
        ),
        encoding="utf-8",
    )

    script_path = target / "inspect_ratos_pi5_image.sh"
    script_path.write_text(
        "\n".join(
            [
                "#!/usr/bin/env bash",
                "set -euo pipefail",
                f"SOURCE_IMAGE=\"${{1:-{str(image_path) if source_found else '<path-to-ratos-img-xz>'}}}\"",
                "WORKDIR=$(cd \"$(dirname \"$0\")\" && pwd)",
                "echo \"Source: $SOURCE_IMAGE\"",
                "test -f \"$SOURCE_IMAGE\"",
                "file \"$SOURCE_IMAGE\" || true",
                "xz -l \"$SOURCE_IMAGE\" || true",
                "shasum -a 256 \"$SOURCE_IMAGE\"",
                "cat <<'NOTE'",
                "",
                "This inspection script intentionally stops before modifying or flashing media.",
                "Storage was checked by Codex CLI UI before staging this folder. For local candidate work, run ./run_build.command.",
                "For manual inspection, expand to $WORKDIR/source.img, attach read-only, and inspect:",
                "- boot firmware files",
                "- bcm2712-rpi-5-b.dtb",
                "- kernel/modules",
                "- config.txt overlays",
                "- cmdline.txt rootfs mapping",
                "- RatOS/Klipper/Moonraker services",
                "NOTE",
                "",
            ]
        ),
        encoding="utf-8",
    )
    try:
        script_path.chmod(0o755)
    except OSError:
        pass

    if execute_build and action_requested and source_found and storage_ok:
        build_result = run_ratos_pi5_builder(target, builder)
        setup["buildResult"] = build_result
        write_json_atomic(setup_path, setup)
        with report_path.open("a", encoding="utf-8") as handle:
            handle.write("\n## Build Attempt\n")
            handle.write(f"- Attempted: {'yes' if build_result.get('attempted') else 'no'}\n")
            handle.write(f"- Result: {'pass' if build_result.get('ok') else 'blocked/failed'}\n")
            if build_result.get("returnCode") is not None:
                handle.write(f"- Return code: {build_result.get('returnCode')}\n")
            if build_result.get("durationSec") is not None:
                handle.write(f"- Duration: {build_result.get('durationSec')} sec\n")
            if build_result.get("reason"):
                handle.write(f"- Reason: {build_result.get('reason')}\n")
            if build_result.get("stdoutPath"):
                handle.write(f"- stdout log: `{build_result.get('stdoutPath')}`\n")
            if build_result.get("stderrPath"):
                handle.write(f"- stderr log: `{build_result.get('stderrPath')}`\n")
            handle.write("\n")

    return {
        "ok": source_found,
        "targetDir": str(target),
        "sourceFound": source_found,
        "sourcePath": str(image_path) if source_found else "",
        "sourceName": resolved.get("name") or "",
        "source": resolved.get("source") or "",
        "sizeBytes": image_size,
        "size": human_bytes(image_size) if image_size else "",
        "uncompressedBytes": uncompressed_size,
        "uncompressedSize": human_bytes(uncompressed_size) if uncompressed_size else "",
        "estimatedWorkBytes": estimated_required,
        "estimatedWorkSize": human_bytes(estimated_required) if estimated_required else "",
        "disk": disk_info,
        "storageOk": storage_ok,
        "actionRequested": action_requested,
        "builder": builder,
        "buildResult": build_result,
        "fileInfo": file_info.strip(),
        "xzInfo": xz_info,
        "searched": resolved.get("searched", []),
        "reportPath": str(report_path),
        "caseSetupPath": str(setup_path),
        "inspectScriptPath": str(script_path),
    }


def embedded_linux_image_preflight_working_notes(result):
    notes = []
    if result.get("sourceFound"):
        notes.append(f"Found source OS image: {result.get('sourcePath')} ({result.get('size')}).")
    else:
        notes.append("Did not find the referenced OS image yet; stopping before pretending a Pi 5 image was created.")
    notes.append("Classified the request as Raspberry Pi/RatOS embedded Linux image work, not CAD, CFD, or structural FEA.")
    disk = result.get("disk") or {}
    if result.get("estimatedWorkSize"):
        notes.append(
            f"Checked local storage myself: {disk.get('free', 'unknown')} free on {disk.get('path', 'the target volume')}; estimated local work space is {result.get('estimatedWorkSize')}."
        )
    if result.get("sourceFound") and result.get("storageOk") and (result.get("builder") or {}).get("runnerPath"):
        notes.append("Storage is sufficient, so I staged a candidate-builder runner instead of asking Tinman to confirm disk space.")
    elif result.get("sourceFound") and not result.get("storageOk"):
        notes.append("Storage is not safely sufficient for expansion/candidate work, so this is a real blocker rather than a generic excuse.")
    build = result.get("buildResult") or {}
    if build.get("attempted") and build.get("ok"):
        notes.append(f"Ran the candidate builder and produced the local candidate image in {build.get('durationSec')} seconds.")
    elif build.get("attempted"):
        notes.append(f"Tried to run the candidate builder; it failed or blocked with return code {build.get('returnCode', 'unknown')}. Logs were saved.")
    elif build.get("blocked"):
        notes.append(f"Candidate builder is blocked: {build.get('reason')}")
    notes.append("No removable media was flashed, and no Pi 5 bootability claim is made without a hardware boot test.")
    return notes


def format_embedded_linux_image_preflight_answer(result):
    found = bool(result.get("sourceFound"))
    builder = result.get("builder") or {}
    build = result.get("buildResult") or {}
    disk = result.get("disk") or {}
    source_path = result.get("sourcePath") or ""
    source_line = f"Source image: `{source_path}`" if source_path else ""
    storage_summary = (
        f"{disk.get('free', 'unknown')} free; about {result.get('estimatedWorkSize') or 'unknown'} needed"
        if result.get("estimatedWorkSize")
        else "not enough information to estimate safely"
    )
    if found and build.get("attempted") and build.get("ok"):
        lead = "Done with the local build step: I created an experimental RatOS Raspberry Pi 5 candidate image."
        candidate_path = builder.get("candidateImagePath")
        candidate_size = ""
        if candidate_path and Path(candidate_path).exists():
            try:
                candidate_size = f" ({human_bytes(Path(candidate_path).stat().st_size)})"
            except OSError:
                candidate_size = ""
        duration = build.get("durationSec")
        duration_note = f" in {duration} seconds" if duration else ""
        status_lines = [
            source_line,
            f"Storage checked: {storage_summary}.",
            f"Build result: succeeded{duration_note}; candidate exists on disk{candidate_size}.",
            "Verification summary: Pi 5 DTB, 2712 kernel, matching root modules, and FAT/ext4 filesystem checks were found.",
            f"Candidate image: `{candidate_path}`",
            f"Verification report: `{builder.get('verificationPath')}`",
            f"Build log: `{build.get('stdoutPath')}`",
        ]
    elif found and build.get("attempted"):
        lead = "I am not done yet: I found the RatOS image and tried the Pi 5 build, but the builder did not produce a candidate image."
        status_lines = [
            source_line,
            f"What I confirmed: source image was found and storage is OK ({storage_summary}).",
            f"Build blocker: {build.get('reason') or ('return code ' + str(build.get('returnCode', 'unknown')))}.",
            f"Build stdout log: `{build.get('stdoutPath')}`",
            f"Build stderr log: `{build.get('stderrPath')}`",
            f"Action report: `{result.get('reportPath')}`",
        ]
    elif found and result.get("storageOk") and builder.get("runnerPath") and builder.get("available"):
        lead = "I found the RatOS image and prepared the Pi 5 builder. The build has not run in this test pass."
        status_lines = [
            source_line,
            f"Storage checked: source image was found and storage is OK ({storage_summary}).",
            f"One-shot builder: `{builder.get('runnerPath')}`",
            f"Action report: `{result.get('reportPath')}`",
        ]
    elif found and result.get("storageOk") and builder.get("runnerPath"):
        lead = "I am not done yet: I found the RatOS image and enough disk space, but the Pi 5 builder tool is not installed where I can use it."
        status_lines = [
            source_line,
            f"Storage checked: source image was found and storage is OK ({storage_summary}).",
            f"Missing tool: RatOS Pi 5 builder template.",
            f"Action report: `{result.get('reportPath')}`",
        ]
    elif found:
        lead = "I am not done yet: I found the RatOS image, but there is not enough safe local workspace to build the Pi 5 candidate."
        status_lines = [
            source_line,
            f"What I confirmed: source image was found, but storage is not OK ({storage_summary}).",
            f"Action report: `{result.get('reportPath')}`",
        ]
    else:
        lead = "I am not done yet: I treated this as a RatOS Raspberry Pi image-porting job, but I could not find the source image."
        status_lines = [
            f"Referenced file: `{result.get('sourceName') or 'unknown'}`",
            f"Action report folder: `{result.get('targetDir') or LOCAL_EMBEDDED_IMAGE_OUTPUT_DIR}`",
        ]
    return "\n\n".join(
        [
            lead,
            "\n".join(f"- {line}" for line in status_lines if line and "None" not in line),
            (
                "This is why: moving a RatOS image from Raspberry Pi 4 to Raspberry Pi 5 is a boot/kernel/firmware compatibility job. "
                "The useful deliverable is not a data dump; it is a candidate image plus a short report showing what boot files, kernel, DTB, firmware, `config.txt`, and `cmdline.txt` changes were made."
            ),
            (
                "You should also consider: no removable media was written or flashed, and this is not yet a boot-tested Raspberry Pi 5 image. "
                "The final proof is to flash a spare SD card, bench boot the Pi 5, verify `uname -a`, SSH/networking, Klipper, Moonraker, and RatOS services, then connect it to a printer only after those checks pass."
            ),
        ]
    )


def is_aero_cfd_analysis_request(messages):
    query = latest_user_text(messages).lower()
    if not query:
        return False
    if is_advisory_circular_source_quiz_question(messages):
        return False
    if is_aero_tool_install_question(messages):
        return False
    if is_aero_analysis_tools_recommendation_question(messages):
        return False
    if is_contextless_cfd_this_model_followup(messages):
        return False
    if is_embedded_linux_image_request(messages):
        return False
    if is_klipper_config_snippet(messages):
        return False
    if is_cad_design_request(messages) and text_has_any(query, ("cpap", "part cooling", "cooling duct", "fusion 360")):
        return False
    if is_aero_duct_research_request(messages):
        return False
    aero_terms = (
        "aero", "aerodynamic", "airfoil", "lift", "drag", "downforce",
        "pressure drop", "external flow", "wind tunnel", "openfoam", "paraview",
        "vspaero", "xfoil", "qblade", "streamline", "coefficient of drag",
        "cd ", "cl ", "cfd",
    )
    analysis_terms = (
        "analyze", "analysis", "simulate", "simulation", "run", "check",
        "validate", "mesh", "solve", "solver", "flow", "component", "body",
        "duct", "wing", "blade", "propeller", "shroud", "fairing",
    )
    has_geometry_hint = bool(geometry_names_from_text(query)) or any(
        str(item.get("name") or item.get("path") or "").lower().endswith(GEOMETRY_FILE_EXTENSIONS)
        for item in message_attachments(messages)
    )
    return text_has_any(query, aero_terms) and (text_has_any(query, analysis_terms) or has_geometry_hint)


def aero_cfd_solve_requested(messages):
    query = latest_user_text(messages).lower()
    return text_has_any(
        query,
        (
            "run a cfd",
            "run cfd",
            "cfd model",
            "cfd simulation",
            "solve cfd",
            "solved cfd",
            "solver convergence",
            "aerodynamic performance",
            "performance report",
            "force coefficient",
            "forcecoeffs",
        ),
    )


def safe_file_signature(path):
    try:
        candidate = Path(path).expanduser().resolve()
        stat = candidate.stat()
        return {
            "path": str(candidate),
            "name": candidate.name,
            "size": int(stat.st_size),
            "mtimeNs": int(getattr(stat, "st_mtime_ns", int(stat.st_mtime * 1_000_000_000))),
        }
    except Exception:
        return {"path": str(path or ""), "name": Path(str(path or "")).name, "size": 0, "mtimeNs": 0}


def aero_speed_case_key(params):
    cases = params.get("speedCases") or []
    if not cases:
        return [round(float(params.get("speedMs") or 20.0), 6)]
    return [
        round(float(case.get("speedMs") or 0), 6)
        for case in cases
    ]


def aero_cfd_cache_key_from_parts(geometry_path, params, solve_requested, revision_requested):
    payload = {
        "geometry": safe_file_signature(geometry_path),
        "speeds": aero_speed_case_key(params or {}),
        "solveRequested": bool(solve_requested),
        "revisionRequested": bool(revision_requested),
        "flowDirection": (params or {}).get("flowDirection", "+X"),
        "requestedBuildVolumeMm": (params or {}).get("buildVolumeMm"),
    }
    encoded = json.dumps(payload, sort_keys=True, separators=(",", ":")).encode("utf-8")
    return hashlib.sha256(encoded).hexdigest()


def aero_cfd_preflight_cache_key(messages, cwd="", resolved=None):
    resolved = resolved or {}
    params = aero_analysis_parameters(messages)
    geometry_path = resolved.get("path") or ""
    return aero_cfd_cache_key_from_parts(
        geometry_path,
        params,
        aero_cfd_solve_requested(messages),
        aero_revision_requested(messages),
    )


def aero_cfd_case_setup_paths(limit=80):
    try:
        folders = sorted(
            (item for item in LOCAL_AERO_OUTPUT_DIR.iterdir() if item.is_dir()),
            key=lambda item: item.stat().st_mtime,
            reverse=True,
        )
    except OSError:
        return []
    paths = []
    for folder in folders[:limit]:
        setup = folder / "case_setup.json"
        if setup.exists():
            paths.append(setup)
    return paths


def cleanup_aero_cfd_output_retention(root=None, keep=None, protect_paths=None):
    output_root = Path(root) if root else LOCAL_AERO_OUTPUT_DIR
    keep_count = max(1, int(keep if keep is not None else AERO_CFD_OUTPUT_RETENTION))
    protected = {Path(path).resolve() for path in (protect_paths or []) if path}
    if not output_root.exists():
        return {"root": str(output_root), "kept": 0, "removed": 0, "preserved": 0}
    candidates = []
    preserved = []
    try:
        children = list(output_root.iterdir())
    except OSError:
        return {"root": str(output_root), "kept": 0, "removed": 0, "preserved": 0}
    for candidate in children:
        if not candidate.is_dir():
            continue
        try:
            resolved = candidate.resolve()
            mtime = candidate.stat().st_mtime
        except OSError:
            continue
        if resolved in protected or candidate.name.startswith("_health"):
            preserved.append(candidate)
            continue
        candidates.append((mtime, candidate.name, candidate))
    candidates.sort(reverse=True)
    keep_paths = {path for _mtime, _name, path in candidates[:keep_count]}
    removed = 0
    for _mtime, _name, path in candidates:
        if path in keep_paths:
            continue
        try:
            shutil.rmtree(path)
            removed += 1
        except OSError:
            continue
    return {
        "root": str(output_root),
        "kept": len(keep_paths),
        "removed": removed,
        "preserved": len(preserved),
    }


def aero_cfd_result_is_reusable(result, cache_key, max_age_seconds=AERO_PREFLIGHT_CACHE_TTL_SECONDS):
    if not isinstance(result, dict):
        return False
    result_cache_key = result.get("cacheKey") or aero_cfd_cache_key_from_parts(
        result.get("geometryPath") or "",
        result.get("params") or {},
        result.get("solveRequested"),
        result.get("revisionRequested"),
    )
    if result_cache_key != cache_key:
        return False
    action_report = result.get("actionReportPath")
    if action_report and not Path(action_report).exists():
        return False
    target = Path(result.get("targetDir") or "")
    try:
        if max_age_seconds and time.time() - target.stat().st_mtime > max_age_seconds:
            return False
    except OSError:
        return False
    surface = result.get("surfaceCheck")
    if isinstance(surface, dict) and not surface.get("ran") and not surface.get("ok"):
        return False
    if (
        isinstance(surface, dict)
        and surface.get("ok")
        and (result.get("solveRequested") or result.get("revisionRequested"))
        and not result.get("volumeMeshPreflight")
    ):
        return False
    volume_mesh = result.get("volumeMeshPreflight") or {}
    if (
        isinstance(surface, dict)
        and surface.get("ok")
        and volume_mesh.get("ok")
        and (result.get("solveRequested") or result.get("revisionRequested"))
        and not volume_mesh.get("bodyConformingMeshRunnerPath")
    ):
        return False
    return bool(result.get("geometryPath"))


def cached_aero_cfd_preflight_result(cache_key):
    if not cache_key:
        return None
    for setup_path in aero_cfd_case_setup_paths():
        try:
            result = json.loads(setup_path.read_text(encoding="utf-8"))
        except Exception:
            continue
        if aero_cfd_result_is_reusable(result, cache_key):
            result["cacheKey"] = cache_key
            result["cacheSourcePath"] = str(setup_path)
            result["caseSetupPath"] = result.get("caseSetupPath") or str(setup_path)
            try:
                action_report = Path(result.get("actionReportPath") or setup_path.with_name("AERO_CFD_ACTION_REPORT.md"))
                precheck = Path(result.get("precheckPath") or setup_path.with_name("AERO_CFD_PRECHECK.md"))
                result["actionReportPath"] = str(action_report)
                result["precheckPath"] = str(precheck)
                action_report.write_text(aero_cfd_action_report_text(result), encoding="utf-8")
                precheck.write_text(aero_cfd_precheck_text(result), encoding="utf-8")
                setup_path.write_text(json.dumps(result, indent=2, sort_keys=True) + "\n", encoding="utf-8")
            except Exception:
                pass
            result["cacheHit"] = True
            return result
    return None


def wait_for_cached_aero_cfd_preflight(cache_key, timeout_seconds=35):
    deadline = time.time() + max(0, timeout_seconds)
    while time.time() < deadline:
        cached = cached_aero_cfd_preflight_result(cache_key)
        if cached:
            return cached
        time.sleep(1.0)
    return None


def aero_cfd_job_lock(cache_key):
    with AERO_PREFLIGHT_LOCKS_GUARD:
        lock = AERO_PREFLIGHT_LOCKS.get(cache_key)
        if lock is None:
            lock = threading.Lock()
            AERO_PREFLIGHT_LOCKS[cache_key] = lock
        return lock


def aero_cfd_in_progress_result(messages, cwd="", target_path=None, resolved=None, cache_key=""):
    params = aero_analysis_parameters(messages)
    slug = slugify(latest_user_text(messages), fallback="aero-cfd")[:48]
    target = Path(target_path).expanduser() if target_path else LOCAL_AERO_OUTPUT_DIR / f"{time.strftime('%Y%m%d-%H%M%S')}-{slug}-in-progress"
    target.mkdir(parents=True, exist_ok=True)
    resolved = resolved or resolve_geometry_file(messages, cwd=cwd)
    readme = target / "AERO_CFD_PRECHECK.md"
    action_report = target / "AERO_CFD_ACTION_REPORT.md"
    result = {
        "ok": False,
        "inProgress": True,
        "cacheKey": cache_key,
        "targetDir": str(target),
        "geometryPath": str(resolved.get("path") or ""),
        "geometrySource": resolved.get("source", ""),
        "searched": (resolved.get("searched") or [])[:30],
        "params": params,
        "toolchain": cfd_toolchain_status(),
        "solveRequested": aero_cfd_solve_requested(messages),
        "revisionRequested": aero_revision_requested(messages),
        "precheckPath": str(readme),
        "actionReportPath": str(action_report),
        "error": "A matching Aero/CFD preflight is already running, so I did not start a duplicate heavy mesh job.",
    }
    readme.write_text(aero_cfd_precheck_text(result), encoding="utf-8")
    action_report.write_text(aero_cfd_action_report_text(result), encoding="utf-8")
    (target / "case_setup.json").write_text(json.dumps(result, indent=2, sort_keys=True) + "\n", encoding="utf-8")
    result["caseSetupPath"] = str(target / "case_setup.json")
    return result


def aero_revision_requested(messages):
    query = latest_user_text(messages).lower()
    return text_has_any(
        query,
        (
            "revised step",
            "revised .step",
            "revised cad",
            "modify any part",
            "aerodynamically improve",
            "improve the design",
            "output step",
            "step file output",
        ),
    )


def is_stl_cfd_duct_design_request(messages):
    query = latest_user_text(messages).lower()
    attachments = message_attachments(messages)
    has_stl = text_has_any(query, (".stl", "stl file", "attached stl", "source stl")) or any(
        str(item.get("name") or item.get("path") or "").lower().endswith(".stl")
        for item in attachments
    )
    if not has_stl:
        return False
    duct_terms = ("duct", "cooling", "part cooling", "cpap", "airflow", "tube")
    action_terms = ("design", "connect", "routing", "route", "clearance", "wall thickness", "cfd", "smooth")
    return text_has_any(query, duct_terms) and text_has_any(query, action_terms)


def extract_stl_cfd_constraints(messages):
    text = "\n".join(
        str(message.get("text", ""))
        for message in (messages or [])[-8:]
        if str(message.get("role", "")).lower() == "user"
    )
    latest = latest_user_text(messages)
    flow_given = bool(re.search(r"\bcfm\b", text, re.IGNORECASE))
    dimensions = cad_request_dimensions(text)
    named_features = sorted(
        {
            compact(match.group(0), 80)
            for match in re.finditer(r"\bCPAP\s+(?:inlet|outlet)\s+\d+\b", text, re.IGNORECASE)
        }
    )
    return {
        "clearanceMm": cad_number(r"([0-9]+(?:\.[0-9]+)?)\s*mm\s+clearance", latest, 1.5),
        "wallThicknessMm": cad_number_any(
            (
                r"([0-9]+(?:\.[0-9]+)?)\s*mm\s+wall(?:\s+thickness)?",
                r"wall\s+thickness(?:\s+should\s+be|\s+is|\s*=|\s*:)?[^0-9]{0,16}([0-9]+(?:\.[0-9]+)?)\s*mm",
            ),
            latest,
            1.0,
        ),
        "maxGrowthMm": cad_number_any(
            (
                r"max[^0-9]{0,80}([0-9]+(?:\.[0-9]+)?)\s*mm",
                r"exist\s+away[^0-9]{0,80}([0-9]+(?:\.[0-9]+)?)\s*mm",
            ),
            latest,
            5.0,
        ),
        "yGrowthMm": cad_number(r"([0-9]+(?:\.[0-9]+)?)\s*mm\s+in\s+the\s+y\s+direction", latest, 0.0),
        "flowLowCfm": dimensions.get("flowLowCfm", 12.0),
        "flowHighCfm": dimensions.get("flowHighCfm", 15.0),
        "flowSpecified": flow_given,
        "namedFeatures": named_features,
        "promptExcerpt": compact(latest, 1000),
    }


def round_list(values, digits=3):
    return [round(float(value), digits) for value in values]


def analyze_stl_geometry(path):
    try:
        import trimesh
    except Exception as exc:
        return {"ok": False, "error": f"trimesh is not available: {exc}"}

    try:
        loaded = trimesh.load(path, force="scene")
        scene_names = []
        meshes = []
        if isinstance(loaded, trimesh.Scene):
            scene_names = list(loaded.geometry.keys())
            meshes = [geometry for geometry in loaded.geometry.values() if hasattr(geometry, "faces")]
            if not meshes:
                return {"ok": False, "error": "The STL loaded but did not contain mesh geometry."}
            mesh = trimesh.util.concatenate(meshes) if len(meshes) > 1 else meshes[0]
            scene_geometry_count = len(meshes)
        else:
            mesh = loaded
            scene_geometry_count = 1
        bounds = mesh.bounds.tolist() if getattr(mesh, "bounds", None) is not None else [[0, 0, 0], [0, 0, 0]]
        extents = mesh.extents.tolist() if getattr(mesh, "extents", None) is not None else [0, 0, 0]
        parts = []
        if len(mesh.faces) <= 650000:
            split_parts = mesh.split(only_watertight=False)
            for index, part in enumerate(sorted(split_parts, key=lambda item: len(item.faces), reverse=True)[:12]):
                parts.append(
                    {
                        "index": index,
                        "faces": int(len(part.faces)),
                        "bounds": [round_list(part.bounds[0]), round_list(part.bounds[1])],
                        "extents": round_list(part.extents),
                    }
                )
        return {
            "ok": True,
            "path": str(path),
            "fileSize": Path(path).stat().st_size,
            "sceneGeometryCount": scene_geometry_count,
            "sceneNames": scene_names[:20],
            "vertices": int(len(mesh.vertices)),
            "faces": int(len(mesh.faces)),
            "bounds": [round_list(bounds[0]), round_list(bounds[1])],
            "extents": round_list(extents),
            "watertight": bool(getattr(mesh, "is_watertight", False)),
            "connectedComponentCount": len(parts) if parts else 0,
            "largestComponents": parts,
        }
    except Exception as exc:
        return {"ok": False, "error": f"Could not read STL mesh: {exc}"}


def python_module_available(name):
    try:
        return importlib.util.find_spec(name) is not None
    except (ImportError, ValueError):
        return False


def docker_openfoam_status():
    docker = command_path("docker")
    colima = command_path("colima")
    colima_profiles = []
    if colima:
        try:
            listing = subprocess.run(
                [colima, "list"],
                stdout=subprocess.PIPE,
                stderr=subprocess.PIPE,
                text=True,
                timeout=5,
                env={**os.environ, "PATH": PATH_FOR_CODEX},
            )
            if listing.returncode == 0:
                for line in (listing.stdout or "").splitlines()[1:]:
                    parts = line.split()
                    if not parts:
                        continue
                    colima_profiles.append(
                        {
                            "name": parts[0],
                            "status": parts[1] if len(parts) > 1 else "",
                            "arch": parts[2] if len(parts) > 2 else "",
                            "cpus": parts[3] if len(parts) > 3 else "",
                            "memory": parts[4] if len(parts) > 4 else "",
                            "disk": parts[5] if len(parts) > 5 else "",
                        }
                    )
        except Exception:
            colima_profiles = []
    colima_running = any(
        str(profile.get("status", "")).lower() == "running" for profile in colima_profiles
    )
    colima_stopped = any(
        str(profile.get("status", "")).lower() == "stopped" for profile in colima_profiles
    )
    if not docker:
        return {
            "dockerPath": "",
            "daemon": False,
            "images": [],
            "colimaPath": colima or "",
            "colimaProfiles": colima_profiles,
            "colimaRunning": colima_running,
            "colimaStopped": colima_stopped,
            "onDemand": False,
            "dormant": False,
        }
    try:
        info = subprocess.run(
            [docker, "info", "--format", "{{.ServerVersion}}"],
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            text=True,
            timeout=5,
            env={**os.environ, "PATH": PATH_FOR_CODEX},
        )
        daemon = info.returncode == 0
    except Exception:
        daemon = False
    images = []
    if daemon:
        try:
            listing = subprocess.run(
                [docker, "image", "ls", "--format", "{{.Repository}}:{{.Tag}}"],
                stdout=subprocess.PIPE,
                stderr=subprocess.PIPE,
                text=True,
                timeout=8,
                env={**os.environ, "PATH": PATH_FOR_CODEX},
            )
            images = [
                line.strip()
                for line in (listing.stdout or "").splitlines()
                if "openfoam" in line.lower()
            ][:8]
        except Exception:
            images = []
    dormant = bool(not daemon and colima and colima_stopped)
    return {
        "dockerPath": docker,
        "daemon": daemon,
        "images": images,
        "colimaPath": colima or "",
        "colimaProfiles": colima_profiles,
        "colimaRunning": colima_running,
        "colimaStopped": colima_stopped,
        "onDemand": bool(colima and docker),
        "dormant": dormant,
    }


def cfd_toolchain_status():
    commands = {
        "openscad": command_path("openscad"),
        "gmsh": command_path("gmsh"),
        "docker": command_path("docker"),
        "simpleFoam": command_path("simpleFoam"),
        "blockMesh": command_path("blockMesh"),
        "snappyHexMesh": command_path("snappyHexMesh"),
        "surfaceFeatureExtract": command_path("surfaceFeatureExtract"),
        "checkMesh": command_path("checkMesh"),
        "freecad": command_path("FreeCADCmd") or command_path("freecad"),
        "paraview": command_path("paraview"),
        "pvpython": command_path("pvpython"),
        "vsp": command_path("vsp"),
        "vspaero": command_path("vspaero"),
        "vspscript": command_path("vspscript"),
        "xfoil": command_path("xfoil"),
        "SU2_CFD": command_path("SU2_CFD"),
        "SU2_DEF": command_path("SU2_DEF"),
        "SU2_DOT": command_path("SU2_DOT"),
        "qblade-linux": command_path("qblade-linux"),
        "openmdao": command_path("openmdao"),
        "wingproj": command_path("wingproj"),
        "ccx": command_path("ccx"),
    }
    modules = {
        "numpy": python_module_available("numpy"),
        "scipy": python_module_available("scipy"),
        "trimesh": python_module_available("trimesh"),
        "meshio": python_module_available("meshio"),
        "gmsh": python_module_available("gmsh"),
        "pyvista": python_module_available("pyvista"),
        "vtk": python_module_available("vtk"),
        "cadquery": python_module_available("cadquery"),
        "OCP": python_module_available("OCP"),
        "aerosandbox": python_module_available("aerosandbox"),
        "openmdao": python_module_available("openmdao"),
        "neuralfoil": python_module_available("neuralfoil"),
    }
    docker = docker_openfoam_status()
    openfoam_local = bool(commands["simpleFoam"] and commands["blockMesh"] and commands["snappyHexMesh"])
    openfoam_docker = bool(docker.get("daemon") and docker.get("images"))
    openfoam_on_demand = bool(not openfoam_local and not openfoam_docker and docker.get("onDemand"))
    return {
        "commands": commands,
        "pythonModules": modules,
        "docker": docker,
        "openfoamAvailable": openfoam_local or openfoam_docker,
        "openfoamRunnableOnDemand": openfoam_on_demand,
        "openfoamStatus": (
            "local"
            if openfoam_local
            else "docker-ready"
            if openfoam_docker
            else "docker-colima-dormant"
            if openfoam_on_demand and docker.get("dormant")
            else "docker-colima-on-demand"
            if openfoam_on_demand
            else "missing"
        ),
        "openfoamLocal": openfoam_local,
        "openfoamDocker": openfoam_docker,
        "meshingAvailable": bool(commands["gmsh"] or modules["gmsh"] or modules["meshio"]),
        "visualizationAvailable": bool(commands["paraview"] or commands["pvpython"] or modules["pyvista"]),
        "cadKernelAvailable": bool(commands["freecad"] or modules["cadquery"] or modules["OCP"]),
        "airfoilToolsAvailable": bool(commands["xfoil"]),
        "aircraftToolsAvailable": bool(commands["vsp"] or commands["vspaero"]),
        "su2Available": bool(commands["SU2_CFD"]),
        "qbladeLinuxLauncherAvailable": bool(commands["qblade-linux"]),
        "structuralFeaAvailable": bool(commands["ccx"]),
        "aeroModelingAvailable": bool(modules["aerosandbox"] or modules["neuralfoil"]),
        "optimizationAvailable": bool(commands["openmdao"] or modules["openmdao"]),
    }


