def structural_material_from_text(text):
    lower = str(text or "").lower()
    aliases = [
        ("aluminum 6061", ("6061", "aluminum", "aluminium")),
        ("pet-cf", ("pet-cf", "pet cf")),
        ("pa-cf", ("pa-cf", "pa cf", "nylon cf", "nylon-cf", "carbon fiber nylon")),
        ("pctg", ("pctg",)),
        ("asa", ("asa",)),
        ("abs", ("abs",)),
        ("petg", ("petg",)),
        ("nylon", ("nylon", "pa6", "pa12")),
        ("steel", ("steel", "mild steel")),
        ("pla", ("pla",)),
    ]
    for key, terms in aliases:
        if any(term in lower for term in terms):
            return {**STRUCTURAL_MATERIAL_LIBRARY[key], "key": key}
    return {**STRUCTURAL_MATERIAL_LIBRARY["aluminum 6061"], "key": "aluminum 6061", "assumed": True}


def structural_face_from_text(text, role="fixed"):
    lower = str(text or "").lower()
    if role == "fixed":
        patterns = [
            (("fixed on the bottom", "clamped on the bottom", "mounted on the bottom", "base is fixed", "bottom is fixed", "at the base"), "min_z"),
            (("fixed on top", "top is fixed", "ceiling mounted"), "max_z"),
            (("fixed on the back", "back is fixed", "rear is fixed", "aft is fixed", "mounted to the back"), "min_y"),
            (("fixed on the front", "front is fixed"), "max_y"),
            (("fixed on the left", "left is fixed"), "min_x"),
            (("fixed on the right", "right is fixed"), "max_x"),
            (("cantilever", "wall mounted", "bolted to wall", "mounted to wall"), "min_x"),
        ]
        default = "min_x"
    else:
        patterns = [
            (("load on the bottom", "force on the bottom"), "min_z"),
            (("load on top", "force on top", "top load"), "max_z"),
            (("load on the back", "force on the back", "rear load"), "min_y"),
            (("load on the front", "force on the front", "front load"), "max_y"),
            (("load on the left", "force on the left"), "min_x"),
            (("load on the right", "force on the right"), "max_x"),
            (("free end", "tip load", "end load"), "opposite"),
        ]
        default = "opposite"
    for terms, face in patterns:
        if any(term in lower for term in terms):
            return face
    axis_match = re.search(rf"{role}(?:ed)?(?:\s+face|\s+side)?[^a-z0-9]{{0,18}}(?:at|on|=|:)?\s*(min|max)[-_ ]?([xyz])", lower)
    if axis_match:
        return f"{axis_match.group(1)}_{axis_match.group(2)}"
    return default


def opposite_structural_face(face):
    opposites = {
        "min_x": "max_x",
        "max_x": "min_x",
        "min_y": "max_y",
        "max_y": "min_y",
        "min_z": "max_z",
        "max_z": "min_z",
    }
    return opposites.get(face, "max_x")


def structural_load_vector_from_text(text):
    lower = str(text or "").lower()
    explicit = re.search(
        r"(?:load|force)\s+(?:vector|direction)[^0-9+\-]{0,16}\(?\s*([+\-]?[0-9]+(?:\.[0-9]+)?)\s*,\s*([+\-]?[0-9]+(?:\.[0-9]+)?)\s*,\s*([+\-]?[0-9]+(?:\.[0-9]+)?)",
        lower,
    )
    if explicit:
        values = [float(explicit.group(i)) for i in range(1, 4)]
    elif re.search(r"\b(?:down|downward|gravity|weight|hanging|vertical load)\b", lower):
        values = [0.0, 0.0, -1.0]
    elif re.search(r"\b(?:up|upward|pulling up)\b", lower):
        values = [0.0, 0.0, 1.0]
    elif re.search(r"\b(?:wind|side load|sideways|lateral)\b", lower):
        values = [1.0, 0.0, 0.0]
    elif re.search(r"\b(?:x direction|along x|\+x)\b", lower):
        values = [1.0, 0.0, 0.0]
    elif re.search(r"\b(?:-x|negative x)\b", lower):
        values = [-1.0, 0.0, 0.0]
    elif re.search(r"\b(?:y direction|along y|\+y)\b", lower):
        values = [0.0, 1.0, 0.0]
    elif re.search(r"\b(?:-y|negative y)\b", lower):
        values = [0.0, -1.0, 0.0]
    elif re.search(r"\b(?:z direction|along z|\+z)\b", lower):
        values = [0.0, 0.0, 1.0]
    elif re.search(r"\b(?:-z|negative z)\b", lower):
        values = [0.0, 0.0, -1.0]
    else:
        values = [0.0, 0.0, -1.0]
    magnitude = math.sqrt(sum(value * value for value in values)) or 1.0
    return [round(value / magnitude, 6) for value in values]


def structural_analysis_parameters(messages):
    text = latest_user_text(messages)
    lower = text.lower()
    load_n = cad_number_any((r"([0-9]+(?:\.[0-9]+)?)\s*n\b", r"([0-9]+(?:\.[0-9]+)?)\s*newtons?\b"), lower, 100.0)
    lbf_match = re.search(r"([0-9]+(?:\.[0-9]+)?)\s*(?:lbf|lb|lbs|pounds?)\b", lower)
    if lbf_match:
        load_n = float(lbf_match.group(1)) * 4.44822
    kg_match = re.search(r"([0-9]+(?:\.[0-9]+)?)\s*kg\b", lower)
    if kg_match:
        load_n = float(kg_match.group(1)) * 9.80665
    safety_factor = cad_number_any(
        (
            r"safety\s+factor[^0-9]{0,16}([0-9]+(?:\.[0-9]+)?)",
            r"\bsf[^0-9]{0,8}([0-9]+(?:\.[0-9]+)?)",
        ),
        lower,
        2.5,
    )
    dims = None
    dim_match = re.search(
        r"([0-9]+(?:\.[0-9]+)?)\s*(?:mm|millimeters?)?\s*x\s*([0-9]+(?:\.[0-9]+)?)\s*(?:mm|millimeters?)?\s*x\s*([0-9]+(?:\.[0-9]+)?)\s*(?:mm|millimeters?)?",
        lower,
    )
    if dim_match:
        dims = [float(dim_match.group(i)) for i in range(1, 4)]
    fixed_face = structural_face_from_text(text, role="fixed")
    load_face = structural_face_from_text(text, role="load")
    if load_face == "opposite":
        load_face = opposite_structural_face(fixed_face)
    return {
        "loadN": round(load_n, 3),
        "safetyFactor": safety_factor,
        "material": structural_material_from_text(text),
        "dimensionsMm": dims,
        "fixedFace": fixed_face,
        "loadFace": load_face,
        "loadVector": structural_load_vector_from_text(text),
        "promptExcerpt": compact(text, 1000),
    }


def is_structural_mechanical_design_request(messages):
    query = latest_user_text(messages).lower()
    if not query:
        return False
    if is_embedded_linux_image_request(messages):
        return False
    if is_general_regression_test_bank_expansion_request(messages):
        return False
    if is_belt_tension_measurement_question(messages):
        return False
    if is_filament_load_unload_gcode_request(messages):
        return False
    if is_propeller_fatigue_material_quiz_question(messages):
        return False
    if is_wind_torque_rpm_followup(messages):
        return False
    if re.match(r"\s*what\s+is\s+the\s+best\s+filament\b", query):
        return False
    explicit_analysis_terms = (
        "stress", "strain", "deflection", "fea", "fem", "finite element",
        "calculix", "safety factor", "factor of safety", "load", "force",
        "torque", "bending", "fatigue", "vibration", "strong enough",
        "will it hold", "mechanically sound", "structurally sound",
        "structural analysis", "mechanical analysis",
    )
    structural_geometry_terms = (
        "bracket", "mount", "holder", "fixture", "cantilever", "rib",
        "ribs", "gusset", "boss", "bolt", "fastener",
    )
    action_terms = (
        "design", "analyze", "analysis", "simulate", "simulation", "validate",
        "check", "optimize", "create", "make", "model", "engineer",
        "will it hold", "strong enough", "support",
    )
    has_geometry_hint = bool(geometry_names_from_text(query)) or any(
        str(item.get("name") or item.get("path") or "").lower().endswith(GEOMETRY_FILE_EXTENSIONS)
        for item in message_attachments(messages)
    )
    high_signal = any(
        route_term_present(query, term)
        for term in ("fea", "fem", "stress", "deflection", "calculix", "finite element", "safety factor", "factor of safety")
    )
    analysis_signal = any(route_term_present(query, term) for term in explicit_analysis_terms)
    geometry_signal = any(route_term_present(query, term) for term in structural_geometry_terms)
    action_signal = text_has_any(query, action_terms)
    if high_signal:
        return True
    if analysis_signal and (action_signal or has_geometry_hint or geometry_signal):
        return True
    return False


