    {"awg": "16", "planningAmpacityA": 10, "ohmsPer1000Ft": 4.016},
    {"awg": "14", "planningAmpacityA": 15, "ohmsPer1000Ft": 2.525},
    {"awg": "12", "planningAmpacityA": 20, "ohmsPer1000Ft": 1.588},
    {"awg": "10", "planningAmpacityA": 30, "ohmsPer1000Ft": 0.999},
