def local_review_prompt(messages, route, friendliness_level=None, humor_level=None):
    clean_messages = []
    for message in messages[-12:]:
        role = str(message.get("role", "")).strip().lower()
        text = str(message.get("text", "")).strip()
        if role in {"user", "assistant"} and text:
            clean_messages.append((role, text))

    if not clean_messages:
        return ""

    blocks = [
        "You are Tinman's local Review specialist running fully locally through Ollama.",
        build_assistant_style_context(friendliness_level, humor_level, route).strip(),
        build_autonomy_supervisor_context(messages, route=route, web_search="live").strip(),
        build_analytical_context(messages, route=route, web_search="live", local_tools=True).strip(),
        build_response_quality_context(messages, route).strip(),
        "You are a second-pass teammate, not a command runner.",
        "Review the latest request or answer for correctness, domain/platform classification, tool-family choice, missing constraints, weak assumptions, safety, tests, source quality, and whether it actually helps Tinman.",
        "If the answer used the wrong ecosystem, such as Klipper tools for a Marlin/Prusa printer, call that out first.",
        "Do not reveal hidden chain-of-thought. Give only the final review.",
        "Be plain-spoken and decisive.",
        "If there is no real issue, say that directly and name any small residual risk.",
        "If there is a problem, lead with the highest-impact fix or recommendation.",
        "Keep the final review under 180 words unless Tinman asks for detail.",
        "Do not use Markdown headings, bold labels, or decorative formatting.",
        "Prefer two to four short plain paragraphs, or a few simple hyphen bullets when that is clearer.",
        "Do not restate the whole item being reviewed unless a short quote is necessary.",
        "",
        format_manager_context(route).strip(),
        "",
    ]
    history_context = build_history_context(messages, fast=False, route=route)
    if history_context:
        blocks.append(history_context.strip())
        blocks.append("")
    blocks.append("Conversation to review:")
    for role, text in clean_messages:
        label = "User" if role == "user" else "Assistant"
        blocks.append(f"{label}:\n{text}")
        blocks.append("")
    blocks.extend(
        [
            "Review the latest item now.",
            "Use concise plain language. Avoid headings, bold labels, and bloated review-report formatting.",
        ]
    )
    return "\n".join(blocks).strip()


def strip_terminal_control_sequences(text):
    clean = str(text or "")
    clean = re.sub(
        r"\x1B(?:[@-Z\\-_]|\[[0-?]*[ -/]*[@-~]|\][^\x07]*(?:\x07|\x1B\\))",
        "",
        clean,
    )
    clean = clean.replace("\r", "\n")
    while "\b" in clean:
        next_clean = re.sub(r".\x08", "", clean)
        if next_clean == clean:
            clean = clean.replace("\b", "")
            break
        clean = next_clean
    return clean


def strip_thinking_markup(text):
    clean = strip_terminal_control_sequences(text)
    clean = re.sub(r"(?is)<think\b[^>]*>.*?</think\s*>", "", clean)
    clean = re.sub(
        r"(?is)(?:^|\n)[^\w\n]{0,24}\s*Thinking\s*\.\.\.\s*.*?\.\.\.\s*done thinking\.?\s*",
        "\n",
        clean,
    )
    clean = re.sub(r"(?im)^\s*(?:thinking|done thinking)\.?\s*$", "", clean)
    clean = re.sub(r"\n{3,}", "\n\n", clean)
    return clean.strip()


def thinking_output_sanitizer_synthetic_check():
    samples = [
        (
            "<think>work Tinman should not see</think>\nFinal answer.",
            ("Final answer.",),
            ("<think>", "work Tinman should not see"),
        ),
        (
            "\x1b[?25lThinking...\nI should reason privately.\n...done thinking.\n\nUse the smoother duct path first.",
            ("Use the smoother duct path first.",),
            ("Thinking", "done thinking", "reason privately", "\x1b"),
        ),
        (
            "\n  Thinking...\ninternal checklist\n...done thinking.\n\nBest answer: 250 C.",
            ("Best answer: 250 C.",),
            ("internal checklist", "Thinking"),
        ),
    ]
    for raw, required_terms, forbidden_terms in samples:
        clean = strip_thinking_markup(raw)
        if not all(term in clean for term in required_terms):
            return False
        if any(term in clean for term in forbidden_terms):
            return False
    return True


def adaptive_answer_composition_profile(messages, route=None):
    route = route or {}
    query = latest_user_text(messages).strip()
    lower = query.lower()
    matched = route.get("matched") if isinstance(route.get("matched"), list) else []
    reasons = []

    def add_reason(reason):
        if reason and reason not in reasons:
            reasons.append(reason)

    if is_agent_preference_question(messages):
        add_reason("agent-preference")
    if is_behavior_guidance_message(messages):
        add_reason("behavior-guidance")
    if is_codex_self_sufficient_help_request(messages):
        add_reason("self-improvement-system")
    if is_codex_ui_direct_interaction_training_request(messages):
        add_reason("direct-interaction-training")
    if is_general_material_property_question(messages):
        add_reason("materials-expert-judgment")
    if is_engineering_tradeoff_question(messages):
        add_reason("engineering-expert-judgment")
    try:
        if understanding_clarification_direct_answer(messages, route):
            add_reason("clarification-needed")
    except Exception:
        pass
    if any(
        item in matched
        for item in (
            "agent-preference",
            "behavior-guidance",
            "codex-self-sufficient-help",
            "codex-ui-direct-interaction-training",
            "same-action-missing-context",
        )
    ):
        add_reason("route-conversational")
    if text_has_any(
        lower,
        (
            "personable",
            "personality",
            "lack of personality",
            "canned",
            "programmed response",
            "boilerplate",
            "same template",
            "subject matter expert",
            "streamlined interaction",
            "thought process",
            "routing of questions",
            "fully understand what i am asking",
            "understand what i am asking",
            "ask questions to clarify",
            "clarifying question",
            "feedback loop",
            "learn from that",
            "learn, grow",
            "fix himself",
            "improve himself",
            "start over",
            "what do we need to do to get him to do this",
        ),
    ):
        add_reason("conversation-quality-request")

    conversational = bool(reasons)
    return {
        "name": "conversational" if conversational else "proof-structured",
        "forceLabeledSections": not conversational,
        "reasons": reasons[:6],
        "questionPolicy": "ask-one-focused-clarification-when-target-is-unclear"
        if conversational
        else "answer-first-with-proof-and-caveats",
    }


def soften_conversational_scaffold(text, messages=None):
    value = str(text or "")
    prior = previous_assistant_text(messages).lower()
    why_label = "The reason is: " if "what matters:" in prior else "What matters: "
    caveat_label = "One practical caveat: " if "keep this boundary in view:" in prior else "Keep this boundary in view: "
    value = re.sub(r"(?i)\bThis is why:\s*", why_label, value)
    value = re.sub(r"(?i)\bYou should also consider:\s*", caveat_label, value)
    value = re.sub(r"\n{3,}", "\n\n", value)
    return value.strip()


def normalize_direct_answer_shape(messages, route, text):
    answer = strip_thinking_markup(text)
    if is_terse_answer_request(messages):
        answer = re.sub(r"(?mi)^#{1,6}\s*", "", answer)
        answer = re.sub(r"\*\*([^*\n]+)\*\*", r"\1", answer)
        answer = re.sub(r"\s+", " ", answer).strip()
        match = re.match(r"(.+?[.!?])(?:\s|$)", answer)
        return (match.group(1) if match else compact(answer, 140)).strip()
    if not answer:
        return answer
    composition = adaptive_answer_composition_profile(messages, route or {})
    if not build_direct_answer_context(messages, route or {}):
        if not composition.get("forceLabeledSections", True):
            answer = re.sub(r"(?mi)^#{1,6}\s*", "", answer)
            answer = re.sub(r"\*\*([^*\n]+)\*\*", r"\1", answer)
            return soften_conversational_scaffold(answer, messages=messages)
        return answer

    if not composition.get("forceLabeledSections", True):
        answer = re.sub(r"(?mi)^#{1,6}\s*", "", answer)
        answer = re.sub(r"\*\*([^*\n]+)\*\*", r"\1", answer)
        return soften_conversational_scaffold(answer, messages=messages)

    answer = re.sub(r"(?mi)^#{1,6}\s*", "", answer)
    answer = re.sub(r"\*\*([^*\n]+)\*\*", r"\1", answer)
    replacements = (
        (r"(?i)\bwhy it fits\s*:", "This is why:"),
        (r"(?i)\bwhy this fits\s*:", "This is why:"),
        (r"(?i)\bwhy this happens\s*:", "This is why:"),
        (r"(?i)\bwhy this matters\s*:", "This is why:"),
        (r"(?i)\bwhy it matters\s*:", "This is why:"),
        (r"(?i)\bwhy it works\s*:", "This is why:"),
        (r"(?i)\bthis is because\s*:?", "This is why:"),
        (r"(?i)(?<!this is )\bwhy\s*:", "This is why:"),
        (r"(?i)(?<!should )\balso consider\s*:", "You should also consider:"),
        (r"(?i)(?<!also )(?<!should )\bconsider\s*:", "You should also consider:"),
        (r"(?i)\bcaveats?\s*:", "You should also consider:"),
        (r"(?i)\bwhat to watch for\s*:", "You should also consider:"),
        (r"(?i)\bwatch outs?\s*:", "You should also consider:"),
        (r"(?i)\bwhat to do next\s*:", "You should also consider:"),
        (r"(?i)\bpractical steps(?: before upgrading)?\s*:", "You should also consider:"),
    )
    for pattern, replacement in replacements:
        answer = re.sub(pattern, replacement, answer)
    answer = re.sub(r"(?i)\bThis is why:(\S)", r"This is why: \1", answer)
    answer = re.sub(r"(?i)\bYou should also consider:(\S)", r"You should also consider: \1", answer)

    if "this is why:" not in answer.lower():
        parts = answer.split("\n\n", 1)
        if len(parts) == 2 and parts[1].strip():
            answer = f"{parts[0].strip()}\n\nThis is why: {parts[1].strip()}"
        else:
            match = re.match(r"(?s)(.+?[.!?])\s+(.+)", answer)
            if match:
                answer = f"{match.group(1).strip()}\n\nThis is why: {match.group(2).strip()}"

    if "you should also consider:" not in answer.lower():
        query = latest_user_text(messages).lower()
        project_id = route.get("projectId", "") if isinstance(route, dict) else ""
        if project_id == "tinmanx-slicer-research" and "filament" in query:
            caveat = "print settings, enclosure or ventilation needs, and enough wall thickness for the real load."
        elif "slow" in query or "debug" in query:
            caveat = "reproducing the slowdown with one baseline measurement so you can tell whether each change helped."
        else:
            caveat = "the real-world load, fit, and environment before committing to the final version."
        answer = answer.rstrip() + f"\n\nYou should also consider: {caveat}"

    query_text = latest_user_text(messages)
    constraint_query_text = re.sub(r"https?://\S+", " ", query_text)
    numeric_constraints = []
    for match in re.finditer(
        r"\b\d+(?:\.\d+)?\s*(?:mm|cm|m|in|inch|inches|mph|rpm|vdc|vac|v|a|amp|amps|w|kw|kg|g|cfm|%|percent|c|°c)?\b",
        constraint_query_text,
        flags=re.I,
    ):
        value = re.sub(r"\s+", " ", match.group(0)).strip()
        if value and value.lower() not in answer.lower() and value not in numeric_constraints:
            numeric_constraints.append(value)
    if numeric_constraints and "this is why:" in answer.lower():
        note = f" This keeps the stated constraint ({', '.join(numeric_constraints[:3])}) in the decision."
        if "you should also consider:" in answer.lower():
            answer = re.sub(r"(?i)\s*(You should also consider:)", note + "\n\n" + r"\1", answer, count=1)
        else:
            answer = answer.rstrip() + note

    return answer.strip()


def normalize_local_open_path(value):
    raw = urllib.parse.unquote(str(value or "").strip().strip("`'\""))
    if raw.startswith("file://"):
        raw = urllib.parse.urlparse(raw).path
    if not raw:
        raise ValueError("No local path was provided.")
    candidate = Path(raw).expanduser()
    if not candidate.exists():
        line_match = re.match(r"^(.+?):\d+(?::\d+)?$", raw)
        if line_match:
            candidate = Path(line_match.group(1)).expanduser()
    if not candidate.is_absolute():
        raise ValueError("Only absolute local paths can be opened.")
    if not candidate.exists():
        raise FileNotFoundError(f"Path does not exist: {raw}")
    return candidate.resolve()


def open_local_path(path_value, mode="reveal", dry_run=False):
    path = normalize_local_open_path(path_value)
    mode = safe_choice(mode, {"reveal", "open"}, "reveal")
    if mode == "open" or path.is_dir():
        args = ["/usr/bin/open", str(path)]
        action = "open"
    else:
        args = ["/usr/bin/open", "-R", str(path)]
        action = "reveal"
    if dry_run:
        return {"ok": True, "path": str(path), "action": action, "dryRun": True, "command": args}
    proc = subprocess.run(
        args,
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
        text=True,
        timeout=8,
    )
    if proc.returncode != 0:
        raise RuntimeError((proc.stderr or proc.stdout or "open command failed").strip())
    return {"ok": True, "path": str(path), "action": action, "dryRun": False}


LOCAL_ANSWER_PATH_RE = re.compile(
    r"(/(?:Users|Applications|Volumes|private/tmp|tmp|var/folders)/[^\n`'\"<>]+?"
    r"(?:\.(?:py|js|sh|command|cpp|c|h|hpp|scad|stl|step|stp|f3d|f3z|3mf|drawio|svg|mmd|dot|kicad_pro|kicad_sch|cfg|ini|json|yaml|yml|toml|plist|gcode|md|txt|pdf|csv|log|inp|frd|dat|img|xz|zip|dmg|png|jpg|jpeg)|/))"
    r"(?=$|[\s\]\),.;:])"
)


