def deliverable_type(path):
    suffix = Path(str(path)).suffix.lower()
    if suffix in {".py", ".js", ".sh", ".command", ".cpp", ".c", ".h", ".hpp"}:
        return "script"
    if suffix in {".stl", ".step", ".stp", ".f3d", ".f3z", ".scad", ".3mf"}:
        return "cad"
    if suffix in {".svg", ".drawio", ".mmd", ".dot", ".kicad_pro", ".kicad_sch"}:
        return "diagram"
    if suffix in {".cfg", ".ini", ".json", ".yaml", ".yml", ".toml", ".plist", ".gcode"}:
        return "config"
    if suffix in {".md", ".txt", ".pdf", ".csv"}:
        return "document"
    if suffix in {".png", ".jpg", ".jpeg"}:
        return "image"
    return "folder" if Path(str(path)).suffix == "" else "file"


def extract_response_deliverables(answer):
    text = str(answer or "")
    deliverables = []
    seen = set()

    def add_item(label, raw_path):
        path = str(raw_path or "").strip().strip("`'\"")
        if not path.startswith("/"):
            return
        allowed_prefixes = ("/Users/", "/Applications/", "/Volumes/", "/private/tmp/", "/tmp/", "/var/folders/")
        if not path.startswith(allowed_prefixes):
            return
        if "\n" in path or "\r" in path or len(path) > 1024:
            return
        path = re.sub(r"[),.;:]+$", "", path)
        if path in seen:
            return
        seen.add(path)
        try:
            exists = Path(path).expanduser().exists()
        except (OSError, ValueError):
            return
        deliverables.append(
            {
                "label": compact(label or Path(path).name or "Output file", 90),
                "path": path,
                "kind": deliverable_type(path),
                "exists": bool(exists),
            }
        )

    for line in text.splitlines():
        stripped = line.strip().lstrip("-* ")
        match = re.match(r"(?P<label>[^:\n]{2,90}):\s*`(?P<path>/[^`]+)`", stripped)
        if match:
            add_item(match.group("label"), match.group("path"))
    for match in re.finditer(r"\[([^\]]+)\]\((/[^)]+)\)", text):
        add_item(match.group(1), match.group(2))
    for match in re.finditer(r"`(/[^`]+)`", text):
        add_item("", match.group(1))
    for match in LOCAL_ANSWER_PATH_RE.finditer(text):
        add_item("", match.group(1))
    return deliverables[:12]


HARD_TASK_KINDS = {
    "CAD/design deliverable",
    "Fusion belt/interference design",
    "Fusion all-designs script handoff",
    "STL/CAD deliverable",
    "Wind turbine CAD/aero design",
    "Generated artifact revision",
    "P51 component CAD handoff",
    "V68 horizontal rotor conversion",
    "Aero/CFD preflight",
    "Aero/CFD solve/revision",
    "Mechanical/structural preflight",
    "Embedded/Linux image port",
    "Engineering diagram",
    "Research + Apply",
    "File/action",
    "Code/config",
    "TinManX white paper design",
    "3D-Fuel PCTG-CF profile pack",
    "RatOS public repo scaffold",
}


def local_path_count(text):
    raw = str(text or "")
    return len(re.findall(r"`/(?:Users|Applications|Volumes|private/tmp|tmp|var/folders)/", raw)) + len(
        LOCAL_ANSWER_PATH_RE.findall(raw)
    )


def paragraph_has_local_path(paragraph):
    return bool(re.search(r"`?/(?:Users|Applications|Volumes|private/tmp|tmp|var/folders)/", str(paragraph or "")))


def hard_task_kind(kind):
    return kind in HARD_TASK_KINDS


def deliverable_priority(contract, deliverable):
    kind = (contract or {}).get("kind", "")
    label = str(deliverable.get("label") or "").lower()
    path = str(deliverable.get("path") or "").lower()
    suffix = Path(path).suffix.lower()
    score = 0
    if deliverable.get("exists"):
        score += 40
    if any(term in label or term in path for term in ("candidate image", "engineering report", "final report", "result preview", "diagram", "fusion 360", "build log")):
        score += 25
    if suffix in {".img", ".step", ".stp", ".f3d", ".f3z", ".stl", ".drawio", ".svg", ".pdf"}:
        score += 20
    if suffix in {".md", ".txt"}:
        score += 12
    if suffix in {".json", ".cfg", ".ini"}:
        score += 4
    if "case setup" in label or "source image" in label or "storage checked" in label:
        score -= 12
    if kind == "Code/config" and suffix in {".py", ".js", ".sh", ".command", ".cpp", ".c", ".h", ".hpp", ".cfg", ".gcode"}:
        score += 18
    if kind == "Engineering diagram" and suffix in {".drawio", ".svg", ".mmd", ".dot", ".pdf"}:
        score += 18
    if kind == "TinManX white paper design" and suffix in {".md", ".pdf", ".txt"}:
        score += 18
    if kind == "3D-Fuel PCTG-CF profile pack" and (suffix in {".md", ".csv", ".json"} or "profiles" in label or "profiles" in path):
        score += 18
    if kind in {"CAD/design deliverable", "STL/CAD deliverable"} and suffix in {".step", ".stp", ".f3d", ".f3z", ".stl", ".scad", ".py"}:
        score += 18
    if kind in {"Aero/CFD preflight", "Aero/CFD solve/revision"}:
        if any(term in label or term in path for term in ("action report", "aero_cfd_action_report", "surface check", "surface_check", "solver stl", "solver_surface", "case setup")):
            score += 26
        if "source geometry" in label:
            score -= 12
    if kind in {"Aero/CFD preflight", "Aero/CFD solve/revision", "Mechanical/structural preflight"} and any(term in label or term in path for term in ("report", "preview", "result")):
        score += 18
    return score


def ranked_response_deliverables(contract, deliverables):
    return sorted(
        deliverables or [],
        key=lambda item: (deliverable_priority(contract, item), str(item.get("label") or ""), str(item.get("path") or "")),
        reverse=True,
    )


def should_compact_hard_task_answer(messages, contract, answer, deliverables):
    if not hard_task_kind((contract or {}).get("kind")):
        return False
    query = latest_user_text(messages).lower()
    if text_has_any(query, ("list every file", "show every file", "all generated files", "return all paths")):
        return False
    return len(deliverables or []) > 3 or local_path_count(answer) > 4


def compact_hard_task_answer(messages, route, answer, contract, deliverables):
    text = str(answer or "").strip()
    if not should_compact_hard_task_answer(messages, contract, text, deliverables):
        return text

    paragraphs = [part.strip() for part in re.split(r"\n\s*\n", text) if part.strip()]
    lines = [line.strip() for line in text.splitlines() if line.strip()]
    plain_lines = [
        line for line in lines
        if not paragraph_has_local_path(line)
        and not line.lower().startswith(("this is why:", "you should also consider:"))
    ]
    first_plain = next(
        (part for part in paragraphs if not paragraph_has_local_path(part) and not part.lower().startswith(("this is why:", "you should also consider:"))),
        plain_lines[0] if plain_lines else (paragraphs[0] if paragraphs else ""),
    )
    why = next((part for part in paragraphs if part.lower().startswith("this is why:")), "")
    if not why:
        why = next((line for line in lines if line.lower().startswith("this is why:")), "")
    consider = next((part for part in paragraphs if part.lower().startswith("you should also consider:")), "")
    if not consider:
        consider = next((line for line in lines if line.lower().startswith("you should also consider:")), "")
    extra_context = ""
    preferred_context_prefixes = (
        "requested speed cases:",
        "i converted the geometry",
        "speed cases staged:",
        "captured constraints:",
    )
    for part in paragraphs[1:]:
        lower = part.lower()
        if (
            not paragraph_has_local_path(part)
            and lower.startswith(preferred_context_prefixes)
            and len(part) <= 480
        ):
            extra_context = part
            break
    for part in paragraphs[1:]:
        if extra_context:
            break
        lower = part.lower()
        if paragraph_has_local_path(part) or lower.startswith(("this is why:", "you should also consider:", "files to open first:")):
            continue
        if len(part) <= 480:
            extra_context = part
            break
    if not extra_context:
        extra_context = next(
            (
                line
                for line in plain_lines[1:]
                if len(line) <= 240 and not line.lower().startswith("files to open first:")
            ),
            "",
        )
    source_context = ""
    for part in paragraphs[1:]:
        lower = part.lower()
        if lower.startswith(("source evidence:", "sources:", "manuals cached locally:")):
            source_context = compact(part, 700)
            break

    ranked = ranked_response_deliverables(contract, deliverables)
    primary = [item for item in ranked if item.get("exists")][:3]
    if not primary:
        primary = ranked[:3]
    output_lines = []
    for item in primary:
        label = compact(item.get("label") or Path(item.get("path") or "").name or "Output file", 60)
        output_lines.append(f"- {label}: `{item.get('path')}`")
    omitted = max(0, len(deliverables or []) - len(primary))
    if omitted:
        file_word = "file is" if omitted == 1 else "files are"
        output_lines.append(f"- {omitted} more supporting {file_word} attached in the file card.")

    parts = [first_plain]
    if output_lines:
        parts.append("Files to open first:\n" + "\n".join(output_lines))
    if extra_context:
        parts.append(extra_context)
    if source_context and source_context not in parts:
        parts.append(source_context)
    if why and why not in parts:
        parts.append(why)
    if consider and consider not in parts:
        parts.append(consider)
    return "\n\n".join(part for part in parts if part).strip()


FINAL_ANSWER_INTERNAL_LABELS = (
    "task contract",
    "done means",
    "must do",
    "required proof",
    "reject if",
    "work receipts",
    "worked through",
    "answer check",
    "recovery plan:",
    "last runtime notes",
    "routed project:",
    "tool recovery:",
)


def answer_bullet_count(text):
    return sum(1 for line in str(text or "").splitlines() if re.match(r"^\s*[-*]\s+", line))


def answer_long_paragraph_count(text, limit=720):
    long_count = 0
    for part in re.split(r"\n\s*\n", str(text or "")):
        stripped = part.strip()
        if not stripped:
            continue
        lines = [line for line in stripped.splitlines() if line.strip()]
        if lines and all(re.match(r"^\s*[-*]\s+", line) for line in lines):
            continue
        if lines and all(line.lstrip().startswith("|") for line in lines):
            continue
        if len(stripped) > limit:
            long_count += 1
    return long_count


def answer_has_noisy_final_labels(text):
    lower = str(text or "").lower()
    return any(label in lower for label in FINAL_ANSWER_INTERNAL_LABELS)


def tinman_etiquette_polish(messages, route, answer, contract=None):
    text = str(answer or "").strip()
    if not text:
        return text
    text = strip_thinking_markup(text)
    text = re.sub(r"(?mi)^#{1,6}\s*", "", text)
    text = re.sub(r"\*\*([^*\n]+)\*\*", r"\1", text)
    drop_line_patterns = (
        r"^\s*Good\s*$",
        r"^\s*Fix this\s*$",
        r"^\s*Steer\s*$",
        r"^\s*Answer check\s*$",
        r"^\s*Work receipts\b.*$",
        r"^\s*Worked through\b.*$",
    )
    kept = []
    for line in text.splitlines():
        if any(re.match(pattern, line, flags=re.IGNORECASE) for pattern in drop_line_patterns):
            continue
        kept.append(line.rstrip())
    text = "\n".join(kept)
    text = re.sub(r"\n\s*(This is why:)", r"\n\n\1", text)
    text = re.sub(r"\n\s*(You should also consider:)", r"\n\n\1", text)
    text = re.sub(r"\n{3,}", "\n\n", text)
    return text.strip()


STALE_EXPLANATION_PHRASES = (
    "he now has a real aero workflow path",
    "she now has a real aero workflow path",
    "the prompt gives dimensions, airflow, clearance, and fusion 360/import requirements",
    "the prompt gives dimensions, airflow, clearance, and fusion 360",
    "the task contract is research and done means",
    "missing: source evidence",
)


def paragraph_has_stale_explanation(paragraph):
    lower = str(paragraph or "").strip().lower()
    if not lower.startswith("this is why:"):
        return False
    return any(phrase in lower for phrase in STALE_EXPLANATION_PHRASES)


def answer_has_stale_explanation(text):
    return any(paragraph_has_stale_explanation(part) for part in re.split(r"\n\s*\n", str(text or "")))


def strip_stale_explanation_paragraphs(text):
    raw = str(text or "").strip()
    if not raw:
        return raw, False
    parts = re.split(r"\n\s*\n", raw)
    kept = []
    removed = False
    for part in parts:
        if paragraph_has_stale_explanation(part):
            removed = True
            continue
        kept.append(part)
    polished = "\n\n".join(part.strip() for part in kept if part.strip()).strip()
    if removed and "this is why:" not in polished.lower():
        first_split = re.split(r"\n\s*\n", polished, maxsplit=1)
        replacement = (
            "This is why: the answer has to stay tied to the current blocker, evidence, and requested deliverable "
            "before claiming the job is complete."
        )
        if first_split and first_split[0].strip():
            polished = first_split[0].strip() + "\n\n" + replacement + (
                "\n\n" + first_split[1].strip() if len(first_split) > 1 and first_split[1].strip() else ""
            )
        else:
            polished = replacement
    return polished, removed


def tinman_etiquette_metrics(messages, route, answer, contract=None):
    text = str(answer or "").strip()
    contract = contract or task_contract(messages, route or {})
    kind = contract.get("kind") or "General help"
    composition = adaptive_answer_composition_profile(messages, route or {})
    direct_like = kind in {"Direct answer", "CAD reference", "Printer status"} or bool(build_direct_answer_context(messages, route or {}))
    hard_like = hard_task_kind(kind)
    bullets = answer_bullet_count(text)
    if is_cad_cnc_question_list_request(messages):
        max_bullets = 120
    else:
        max_bullets = 6 if direct_like else 9 if hard_like else 8
    long_limit = 5000 if is_cad_cnc_question_list_request(messages) else 520 if direct_like else 780
    first = next((part.strip() for part in re.split(r"\n\s*\n", text) if part.strip()), "")
    first_limit = 360 if direct_like else 520
    checks = [
        {
            "label": "starts with outcome",
            "passed": bool(first) and len(first) <= first_limit and not first.lower().startswith(("working notes", "recovery plan", "task contract")),
        },
        {
            "label": "no internal scaffolding",
            "passed": not answer_has_noisy_final_labels(text),
        },
        {
            "label": "clean markdown",
            "passed": "####" not in text and not re.search(r"(?m)^\s*#{1,6}\s+", text) and "**" not in text,
        },
        {
            "label": "current-task explanation",
            "passed": not answer_has_stale_explanation(text),
        },
        {
            "label": "bullet discipline",
            "passed": bullets <= max_bullets,
        },
        {
            "label": "paragraph length",
            "passed": answer_long_paragraph_count(text, long_limit) == 0,
        },
    ]
    if direct_like and composition.get("forceLabeledSections", True):
        lower = text.lower()
        checks.append(
            {
                "label": "direct why/consider",
                "passed": "this is why:" in lower and "you should also consider:" in lower,
            }
        )
    elif direct_like:
        lower = text.lower()
        checks.append(
            {
                "label": "adaptive conversation shape",
                "passed": "this is why:" not in lower and "you should also consider:" not in lower,
            }
        )
    failed = [check for check in checks if not check.get("passed")]
    return {
        "status": "pass" if not failed else "review",
        "checks": checks,
        "failed": failed,
        "bulletCount": bullets,
        "longParagraphCount": answer_long_paragraph_count(text, long_limit),
    }


def extract_assumption_ledger(messages, route, answer, contract=None):
    lower = str(answer or "").lower()
    ledger = []

    def add(kind, text, status="noted"):
        if text and len(ledger) < 8:
            ledger.append({"kind": kind, "text": compact(text, 220), "status": status})

    if "assume" in lower or "assumes" in lower:
        match = re.search(r"(?is)([^.\n]*assum(?:e|es|ed|ption)[^.\n]*(?:[.\n]|$))", str(answer or ""))
        add("Assumption", match.group(1).strip() if match else "The answer includes an explicit assumption.", "assumed")
    if "no full cfd" in lower or "not pretending this is validated" in lower or "not validated" in lower or "not solved cfd" in lower or "not a completed cfd" in lower or "not final validated fea" in lower or "not final strength" in lower:
        add("Validation", "Full validation was not claimed; the answer marks the remaining validation work.", "limited")
    if "offline" in lower or "unreachable" in lower or "blocked" in lower:
        add("Blocker", "The answer identifies a blocker or unreachable dependency.", "blocked")
    if "passed" in lower or "verified" in lower or "validated" in lower:
        add("Verified", "The answer includes a verification or passing-check statement.", "verified")
    if "you should also consider:" in lower:
        caveat = str(answer or "").split("You should also consider:", 1)[-1].strip().split("\n\n", 1)[0]
        add("Caveat", caveat, "caution")
    if text_has_any(lower, ("not yet a boot-tested", "not boot-tested", "not call it bootable", "no removable media was written", "not expand")):
        add("Validation", "Bootable image status is explicitly limited until inspection or boot testing proves it.", "limited")
    if not ledger and (contract or {}).get("kind", "").lower().startswith(("cad", "stl")):
        add("Validation", "Engineering/CAD work should still be fit-checked before final use.", "caution")
    return ledger


