LOCAL_OUTPUT_COMPLETION_CLAIM_RE = re.compile(
    r"\b(?:done|completed|created|generated|saved|wrote|written|updated|changed|modified|staged|exported|produced|cached|downloaded|installed|applied)\b",
    flags=re.IGNORECASE,
)


