def unverified_local_output_claim_paths(answer_text, deliverables=None):
    text = str(answer_text or "")
    if not text:
        return []
    deliverables = deliverables if deliverables is not None else extract_response_deliverables(text)
    missing_paths = []
    seen = set()
    for item in deliverables or []:
        path = str(item.get("path") or "")
        if not path or item.get("exists") or path in seen:
            continue
        seen.add(path)
        missing_paths.append(path)
    if not missing_paths:
        return []

    # Honest blocker reports may name an intended/missing path; the problem is
    # claiming completed local work that cannot be verified on disk.
    global_completion_claim = bool(LOCAL_OUTPUT_COMPLETION_CLAIM_RE.search(text)) and not answer_has_missing_deliverable_blocker(text)
    claims = []
    paragraphs = [part.strip() for part in re.split(r"\n\s*\n", text) if part.strip()]
    lines = [line.strip() for line in text.splitlines() if line.strip()]
    contexts = paragraphs + lines
    for path in missing_paths:
        path_contexts = [ctx for ctx in contexts if path in ctx]
        if not path_contexts:
            path_contexts = [text]
        for context in path_contexts:
            lower_context = context.lower()
            if text_has_any(lower_context, LOCAL_OUTPUT_CLAIM_NEGATIONS):
                continue
            if LOCAL_OUTPUT_COMPLETION_CLAIM_RE.search(context) or global_completion_claim:
                claims.append(path)
                break
    return sorted(set(claims))


def task_contract_gate(messages, route, answer, contract=None, deliverables=None, assumptions=None, web_search="live"):
    text = str(answer or "")
    lower = text.lower()
    contract = contract or task_contract(messages, route or {})
    composition = adaptive_answer_composition_profile(messages, route or {})
    kind = contract.get("kind") or "General help"
    deliverables = deliverables if deliverables is not None else extract_response_deliverables(text)
    assumptions = assumptions if assumptions is not None else extract_assumption_ledger(messages, route or {}, text, contract)
    blocker = answer_has_honest_blocker(text)
    checks = []

    def add(label, passed, detail="", severity="medium"):
        checks.append(
            {
                "label": label,
                "passed": bool(passed),
                "detail": compact(detail, 200),
                "severity": severity,
            }
        )

    first = next((part.strip() for part in re.split(r"\n\s*\n", text) if part.strip()), "")
    hard_kinds = {
        "CAD/design deliverable",
        "Fusion belt/interference design",
        "Fusion all-designs script handoff",
        "STL/CAD deliverable",
        "Wind turbine CAD/aero design",
        "Generated artifact revision",
        "P51 component CAD handoff",
        "V68 horizontal rotor conversion",
        "Aero/CFD preflight",
        "Aero/CFD solve/revision",
        "Mechanical/structural preflight",
        "Embedded/Linux image port",
        "Engineering diagram",
        "Research + Apply",
        "File/action",
        "Code/config",
    }

    add("Objective match", bool(first) and not first.lower().startswith(("recovery plan", "working notes")), "Answer starts with the requested outcome, not internal process.")

    unverified_local_claims = unverified_local_output_claim_paths(text, deliverables)
    add(
        "Verified local path claims",
        not unverified_local_claims,
        "Do not claim saved/created/updated local files unless the path exists or the answer states an honest blocker.",
        "hard" if unverified_local_claims else "medium",
    )

    if kind in {
        "Direct answer",
        "CAD reference",
        "Belt cross-reference",
        "Codex CLI response-time optimization",
        "Orca print-time estimate disparity",
        "Printer status",
        "Slicer model/plate visibility bug",
        "VX-175 printed turbine scaling",
        "Non-continuous fiber strength heatmap",
        "Slice strength visualization",
        "Airflow scenario CFD planning",
        "Numbered option missing context",
        "Recommendation context missing",
        "Full access approval boundary",
        "Professional output labeling",
        "Settings save/no-button guidance",
        "Reasoning level recommendation",
        "Printer Z safety without homing",
        "Z motor board mapping",
        "Klipper fan output controllability",
        "Stable printer hardware spec",
        "Amazon product delta follow-up",
        "Aviation corrosion maintenance quiz",
        "Fusion tube 90-degree bend",
        "Fusion sketch move/copy",
        "Fusion sketch auto-look setting",
        "Fusion API traceback fix",
        "Fine/Draft profile generator",
        "Rocket PC material profile",
        "Propeller tip-sweep research decision",
        "Lay-on-face comparator diagnostic",
        "CC filament runout protocol recall",
        "Bambu printer IP/access-code lookup",
        "Speed setting timeline",
        "Fusion CAM stock/holder collision",
        "Workable app timeline context",
        "Codex improvement next step",
        "Reasoning-level data budget tradeoff",
        "Codex CLI UI self-improvement roadmap",
        "Cross-platform publishable app groundwork",
        "Linux build consideration",
        "Machine-not-available prep work",
        "XY homing sensitivity small-step adjustment",
        "TinmanX Orca Codex slicer-ready build gate",
        "New UI review",
        "P-51 Fusion import process reference",
        "P-51 Fusion lockup recovery",
        "Fusion 360 capability answer",
        "Orca cache cleanup",
        "Rocket emitted shortest path",
        "TinManX wave-overhang readiness",
        "Orca/TinManX profile rename",
        "Orca profile edit/audit",
        "Slicer profile edit/update",
        "Slicer actual-work status",
        "TinManX process-profile edit panel UI",
        "UGS setup walkthrough",
        "Essential-loads subpanel decision",
        "Theory implementation missing context",
        "Online status missing context",
        "Closed-app next-step missing context",
        "Find-one/specs missing context",
        "Label-both missing context",
        "Slow connection cleanup context",
        "No-Ethernet alternate network test",
        "Main broad-footprint refactor",
        "Z tilt code audit",
        "Orca calibration card pack",
        "Rename macro every-print hook",
        "Advanced function roadmap",
        "Orca filament library machine sync",
        "Larger-printer turbine model rerun",
        "NPT tap drill reference",
        "Codex subscription level account status",
        "Deeper code audit context",
        "Dual-Beacon release timing",
        "Qidi Box external-spool false-runout",
        "Speaker enclosure CAD regroup",
        "Speaker enclosure design capability",
        "FibreSeeker RocketSlicer-Orca integration",
        "Nozzle-offset calibration status",
        "Mechanical/structural design pack next step",
        "CAD repair-before-return expectation",
        "Rocket fiber placement verification",
        "CAD source search",
        "Bambu/Orca nozzle warning diagnostic",
        "Orca Codex build strategy",
        "Filament switch state verification",
        "Turbine airflow/endplate comparison",
        "OrcaSlicer Codex backend streamline",
        "Generator search missing specs",
        "Filament price ballpark",
        "Orca active chamber dynamic setting",
        "Orca chamber-before-bed research",
        "FibreSeeker paper calculation update",
        "GitHub push paused with price verification",
        "Wave overhang algorithm comparison",
        "KJV/Hebrew Scripture comparison",
        "Posting missing context",
        "Prusa/Core One L registration code",
        "TinManX average completion-time metric",
        "Rocket/Orca tool-map audit",
        "Rocket backend output compatibility",
        "OrcaSlicer Codex installed-change verification",
        "Core One L profile packaging/share",
        "Shared profile repo machine organization",
        "Flight Ops startup reminder",
        "Compact M5 4mm fitting selection",
        "Context follow-up execution",
        "PDF condensation/package request",
        "Filament box controlled unload",
        "Printer homing pre-move safety",
        "Filament load proceed",
        "Powertrain motor/battery recommendation",
        "Cleanup before nice-to-haves",
        "Status LED pulse upgrade",
        "User-name edit feature context",
        "TinmanX splashscreen rev label",
        "Cleanup target context",
        "Location target missing context",
        "Ambiguous device path comparison",
        "Config support channel decision",
        "Visible progress notes",
        "Output gate comparison",
        "Final nozzle simulator validation",
        "LED strip electrical/design reference",
        "Omnidirectional wind design constraint",
        "Adaptive mesh next-print status",
        "Rotor count follow-up",
        "Wind rotor material/mass tradeoff",
        "Wind turbine RPM/torque estimate",
        "Turbine bucket chord/torque design",
        "Firmware update before Beacon protocols",
        "Flight Ops V2 offline-sync app build",
        "Flight Ops N296SA functionality follow-up",
        "MakersVPN reboot safety",
        "Mac Bluetooth rename",
        "Hotend mount visual reference",
        "CAD duct visual delta",
        "Klipper restart safety",
        "Bambu nozzle status boundary",
        "Chrome screenshot capture",
        "Humidity hook reuse",
        "Qidi filament sensor identification",
        "Filament box comparison boundary",
        "Rat Rig IP lookup",
    }:
        if composition.get("forceLabeledSections", True):
            add(
                "Direct answer shape",
                "this is why:" in lower and "you should also consider:" in lower,
                "Direct questions need answer/why/consider unless the user asked for a terse command output.",
            )
        else:
            add(
                "Adaptive conversation shape",
                "this is why:" not in lower and "you should also consider:" not in lower,
                "Conversational guidance/preferences should stay natural instead of forcing formal why/consider labels.",
            )

    if kind in hard_kinds:
        deliverable_or_blocker = bool(deliverables) or blocker
        add(
            "Required artifact/action proof",
            deliverable_or_blocker,
            "Hard tasks need clickable outputs or an explicit blocker before final.",
            "hard",
        )
        missing_deliverables = [item for item in deliverables if not item.get("exists")]
        add(
            "Referenced deliverables exist",
            not missing_deliverables or answer_has_missing_deliverable_blocker(text),
            "Do not present missing output files as completed deliverables.",
            "hard",
        )

    if kind == "Final nozzle simulator validation":
        has_artifact_boundary = text_has_any(
            lower,
            (
                "current nozzle/build artifact",
                "current artifact",
                "simulator case path",
                "build artifact",
                "case path",
            ),
        )
        has_validation_scope = text_has_any(lower, ("fit/flow/collision/printability", "fit, flow", "collision risk", "printability"))
        has_final_gate = text_has_any(lower, ("simulator/final gate", "final simulator check", "final gate"))
        wrong_status_family = text_has_any(
            lower,
            (
                "moonraker",
                "nozzle temperature",
                "nozzle temp",
                "endpoint/status",
                "printer is offline",
                "configured endpoint",
            ),
        )
        generic_template = text_has_any(lower, ("i staged a first-pass", "cpap cooling duct"))
        add(
            "CAD validation context",
            has_artifact_boundary and has_final_gate,
            "Final-nozzle simulator follow-ups need the actual artifact/case boundary and a simulator/final gate.",
            "hard",
        )
        add(
            "Validation checks named",
            has_validation_scope,
            "Name fit, flow, collision, and printability checks instead of a vague final review.",
            "hard",
        )
        add(
            "No printer-status/template drift",
            not wrong_status_family and not generic_template,
            "Do not answer this CAD validation follow-up as live printer status or a generic CAD template.",
            "hard",
        )

    if kind in {"CAD/design deliverable", "Fusion belt/interference design", "STL/CAD deliverable", "Wind turbine CAD/aero design", "Generated artifact revision", "P51 component CAD handoff", "V68 horizontal rotor conversion", "Aero/CFD preflight", "Aero/CFD solve/revision", "Mechanical/structural preflight", "Engineering diagram"}:
        add(
            "Assumptions and validation",
            bool(assumptions) or blocker,
            "Engineering tasks need assumptions, limits, validation, or a clear blocker.",
            "hard",
        )

    if kind == "STL/CAD deliverable":
        fake_geometry = answer_claims_generated_cad_geometry(text) and text_has_any(
            lower,
            ("did not find a readable stl", "attach the stl", "not attached"),
        )
        add(
            "No fake STL geometry",
            not fake_geometry,
            "Do not generate CAD geometry when the STL is missing.",
            "hard",
        )

    if kind == "Wind turbine CAD/aero design":
        params = wind_turbine_design_parameters(messages)
        wind_token = f"{params.get('windMph', 4):.1f} mph".lower()
        wind_token_short = f"{params.get('windMph', 4):g} mph".lower()
        voltage_token = f"{params.get('voltageVdc', 60):.0f} v".lower()
        wrong_template = text_has_any(
            lower,
            (
                "cpap",
                "cooling duct",
                "cooling-duct",
                "part cooling",
                "nozzle",
                "toolhead",
                "hotend",
                "12-15 cfm",
                "18 mm inlet",
            ),
        )
        has_turbine_domain = text_has_any(lower, ("wind-turbine", "wind turbine", "vertical-axis", "vertical axis", "rotor", "vawt"))
        has_low_wind_math = text_has_any(lower, (wind_token, wind_token_short, "wind energy", "swept area", voltage_token, "generator"))
        native_ext = requested_fusion_native_archive(messages)
        fusion_native_followup = bool(native_ext)
        has_native_correction_focus = (
            fusion_native_followup
            and native_ext in lower
            and text_has_any(lower, ("fusion-native", "fusion 360", "constraints", "joints", "native assembly", "rebuild script"))
        )
        step_or_blocker = any(
            str(item.get("path") or "").lower().endswith((".step", ".stp", ".py", ".md", ".json"))
            for item in deliverables
        ) or blocker
        add(
            "No wrong CAD template",
            not wrong_template,
            "Wind turbine design must not reuse CPAP/nozzle/toolhead/CFM cooling-duct language.",
            "hard",
        )
        add(
            "Wind turbine objective",
            has_turbine_domain and (has_low_wind_math or has_native_correction_focus),
            "Answer must address turbine geometry plus the requested low-wind/generator feasibility, or stay focused on the requested Fusion-native correction.",
            "hard",
        )
        add(
            "CAD/design artifact or blocker",
            step_or_blocker,
            "Wind turbine design needs a labeled STEP/CAD/report path or a concrete local blocker.",
            "hard",
        )
        if native_ext:
            has_native_archive = any(
                str(item.get("path") or "").lower().endswith(native_ext)
                and item.get("exists")
                for item in deliverables
            )
            has_fusion_script = any(
                str(item.get("path") or "").lower().endswith(".py")
                and text_has_any(str(item.get("label") or item.get("path") or "").lower(), ("fusion", "fusion 360", "native"))
                and item.get("exists")
                for item in deliverables
            )
            exact_native_blocker = (
                native_ext in lower
                and text_has_any(
                    lower,
                    (
                        "not generated locally",
                        "cannot safely export",
                        "can't safely export",
                        "must be saved",
                        "must be exported",
                        "inside fusion",
                        "headless",
                        "blocker",
                    ),
                )
            )
            has_step_fallback = any(
                str(item.get("path") or "").lower().endswith((".step", ".stp"))
                for item in deliverables
            )
            step_only_substitute = has_step_fallback and not has_native_archive and not (has_fusion_script and exact_native_blocker)
            add(
                "Requested native Fusion output",
                has_native_archive or (has_fusion_script and exact_native_blocker),
                "A requested .f3d/.f3z needs the real native archive or a Fusion-native script plus exact export blocker.",
                "hard",
            )
            add(
                "No STEP-only substitute",
                not step_only_substitute,
                "STEP can be a backup, but it cannot be the completed output for a requested Fusion-native archive.",
                "hard",
            )

    if kind == "Generated artifact revision":
        prior_context = text_has_any(lower, ("prior outputs", "prior artifact", "previous output", "generated file", "source context"))
        no_runtime_dump = not text_has_any(lower, ("recovery plan:", "local worker returned", "tool recovery:", "last runtime notes:"))
        revised_or_blocked = bool(deliverables) or blocker
        add(
            "Prior artifact context",
            prior_context,
            "Artifact corrections must stay attached to the generated output they are correcting.",
            "hard",
        )
        add(
            "Revision artifact or blocker",
            revised_or_blocked,
            "Artifact corrections need a revised output path or exact blocker.",
            "hard",
        )
        add(
            "No generic runtime dump",
            no_runtime_dump,
            "Do not answer corrective artifact feedback with raw Load failed recovery notes.",
            "hard",
        )

    if kind == "Research" and web_search == "live":
        add(
            "Source evidence",
            answer_has_source_url(text),
            "Research/current/spec/price answers need source URLs.",
            "hard",
        )

    if kind == "Research + Apply":
        has_application_language = text_has_any(
            lower,
            (
                "applied to project",
                "project application",
                "applied output",
                "changed file",
                "created file",
                "updated",
                "blocked because",
            ),
        )
        has_project_proof = bool(deliverables) or answer_has_honest_blocker(text)
        has_verification = text_has_any(
            lower,
            ("verified", "validation", "receipt", "test", "package health", "blocked because"),
        )
        add("Source evidence", answer_has_source_url(text), "Research + Apply needs source URLs.", "hard")
        add(
            "Project application",
            has_application_language and has_project_proof,
            "Research + Apply needs an applied file/path/output or explicit blocker.",
            "hard",
        )
        add(
            "Verification receipt",
            has_verification,
            "Research + Apply needs a verification note, receipt, test, or honest blocker.",
            "hard",
        )
        add(
            "No unverified project/test claims",
            not research_apply_claims_unverified_project_work(text, deliverables),
            "Do not claim a profile/file/test changed unless the path or test proof is present.",
            "hard",
        )

    if kind == "CAD reference":
        has_format_recommendation = (
            text_has_any(
                lower,
                (
                    ".f3d",
                    ".f3z",
                    ".step",
                    ".stp",
                    ".stl",
                    "f3d",
                    "f3z",
                    "stp",
                    "stl",
                    "fusion archive",
                    "native fusion",
                    "file type",
                    "file format",
                    "export format",
                    "import format",
                    "design history",
                    "component names",
                    "body names",
                    "assembly names",
                    "constraints",
                    "joints",
                    "sketches",
                ),
            )
            or (
                bool(re.search(r"\bstep\b", lower))
                and text_has_any(lower, ("export", "import", "file", "format", "fusion", "cad", "component", "body", "assembly"))
            )
        )
        add(
            "Format recommendation present",
            has_format_recommendation or blocker,
            "CAD reference answers must name the actual format/export recommendation.",
            "hard",
        )
        add(
            "No artifact detour",
            not answer_has_cad_artifact(text),
            "Reference questions should not stage CAD files.",
            "hard",
        )

    if kind in {"Aero/CFD preflight", "Aero/CFD solve/revision"}:
        add(
            "No false CFD claim",
            not answer_claims_solved_cfd(text) or bool(deliverables),
            "Only claim solved CFD when solver output/report files are present.",
            "hard",
        )
        nonzero_mesh = not text_has_any(lower, ("mesh read: 0 faces", "0 faces, 0 vertices", "solver stl: ``", "solver stl: `not generated`"))
        has_solver_surface = any(
            str(item.get("path") or "").lower().endswith((".stl", ".obj", ".3mf"))
            for item in deliverables
        )
        add(
            "Solver surface exists",
            (nonzero_mesh and has_solver_surface) or blocker,
            "Aero/CFD answers need a solver surface with nonzero mesh before case setup can count.",
            "hard",
        )
    if kind == "Aero/CFD solve/revision":
        solved_cfd = answer_claims_solved_cfd(text) and any(
            text_has_any(str(item.get("label") or item.get("path") or "").lower(), ("report", "result", "force", "cfd"))
            for item in deliverables
        )
        revised_step_needed = aero_revision_requested(messages)
        revised_step = any(
            str(item.get("path") or "").lower().endswith((".step", ".stp"))
            and text_has_any(str(item.get("label") or item.get("path") or "").lower(), ("revised", "optimized", "improved"))
            for item in deliverables
        )
        add(
            "CFD solved or still blocked",
            solved_cfd or blocker,
            "Requests to run CFD need solver/report proof; preflight-only output must remain blocked.",
            "hard",
        )
        if revised_step_needed:
            add(
                "Revised STEP produced",
                revised_step,
                "Design-improvement requests need a revised STEP/STP file before passing.",
                "hard",
            )

    if kind == "Mechanical/structural preflight":
        has_strength_basis = text_has_any(lower, ("safety factor", "calculix", "load", "constraint", "stress", "deflection", "not final"))
        add(
            "Strength basis",
            (not answer_claims_final_strength(text)) or has_strength_basis,
            "Strength claims need load/material/safety-factor basis.",
            "hard",
        )

    if kind == "Embedded/Linux image port":
        action_requested = embedded_image_action_requested(messages)
        pi5_complete_claim = text_has_any(lower, ("working pi 5 image is ready", "seamless pi 5 image is complete"))
        pi5_complete_claim = pi5_complete_claim or (
            "boot-tested pi 5 image" in lower
            and "not yet a boot-tested pi 5 image" not in lower
            and "not a boot-tested pi 5 image" not in lower
        )
        add(
            "Boot-chain basis",
            text_has_any(lower, ("boot", "kernel", "dtb", "firmware", "cmdline.txt", "config.txt")),
            "OS image porting answers need boot/kernel/firmware checks.",
            "hard",
        )
        add(
            "Storage-aware decision",
            text_has_any(lower, ("storage checked:", "free space:", "disk free", "estimated local work space", "storage ok", "storage is not safely sufficient")),
            "Image-port actions must inspect or state the local disk/storage decision instead of asking Tinman to do visible checks.",
            "hard",
        )
        if action_requested:
            candidate_produced = text_has_any(
                lower,
                (
                    "created an experimental ratos raspberry pi 5 candidate image",
                    "produced a local candidate image",
                    "candidate image:",
                ),
            ) and not text_has_any(lower, ("expected candidate", "not created", "not done yet", "did not produce"))
            build_blocked_or_failed = text_has_any(
                lower,
                (
                    "i am not done yet",
                    "did not produce a candidate image",
                    "build blocker:",
                    "build result: blocked/failed",
                    "build attempted: no",
                    "missing tool:",
                    "candidate image after builder run",
                ),
            )
            test_mode_builder_staged = text_has_any(
                lower,
                (
                    "build has not run in this test pass",
                    "one-shot builder:",
                    "storage is ok",
                    "source image found",
                ),
            )
            add(
                "Candidate action path",
                blocker or text_has_any(lower, ("candidate builder", "candidate-builder", "one-shot runner", "build script", "candidate image")),
                "Create/port requests need a candidate-builder/image path or an explicit blocker.",
                "hard",
            )
            add(
                "Candidate image produced",
                candidate_produced or test_mode_builder_staged,
                "A create/port request is not complete until a candidate image is actually produced; regression test mode may pass only when the source, storage, and one-shot builder path are all explicit.",
                "hard" if build_blocked_or_failed and not test_mode_builder_staged else "medium",
            )
            add(
                "No shallow preflight stop",
                not text_has_any(lower, ("preflight staged only", "status: preflight staged only", "staged only")),
                "Do not pass a create request with preflight-only language when local storage/source can be inspected.",
                "hard",
            )
        add(
            "No fake Pi 5 completion",
            not pi5_complete_claim,
            "Do not claim a finished Pi 5 image without boot/test proof.",
            "hard",
        )

    if kind == "Code/config":
        add(
            "Validation named",
            text_has_any(lower, ("validated", "syntax", "quality-gate", "py_compile", "node --check", "klipper", "not run")),
            "Code/config answers should name validation or why it could not run.",
            "medium",
        )

    failed = [check for check in checks if not check.get("passed")]
    hard_failed = [check for check in failed if check.get("severity") == "hard" or contract.get("hardGate")]
    status = "block" if hard_failed else "review" if failed else "pass"
    return {
        "status": status,
        "checks": checks,
        "failed": failed,
        "requiredProof": contract.get("requiredProof", []),
        "rejectIf": contract.get("rejectIf", []),
    }


def response_scorecard(messages, route, answer, contract=None, deliverables=None, assumptions=None, web_search="live"):
    text = str(answer or "").strip()
    lower = text.lower()
    contract = contract or task_contract(messages, route)
    composition = adaptive_answer_composition_profile(messages, route or {})
    deliverables = deliverables if deliverables is not None else extract_response_deliverables(text)
    assumptions = assumptions if assumptions is not None else extract_assumption_ledger(messages, route, text, contract)
    blocker = answer_has_honest_blocker(text)
    gate = task_contract_gate(messages, route or {}, text, contract, deliverables, assumptions, web_search=web_search)
    first = next((part.strip() for part in re.split(r"\n\s*\n", text) if part.strip()), "")
    checks = []

    def add(label, passed, detail=""):
        checks.append({"label": label, "passed": bool(passed), "detail": compact(detail, 180)})

    def add_gate(check):
        checks.append(
            {
                "label": f"Contract: {check.get('label')}",
                "passed": bool(check.get("passed")),
                "detail": compact(check.get("detail", ""), 180),
            }
        )

    add(
        "Answer first",
        bool(first) and not first.lower().startswith(("working notes", "recovery plan", "fusion 360 script", "openscad model")),
        "The first visible paragraph should tell Tinman the useful answer or action.",
    )
    add(
        "Plain language",
        "####" not in text and "**" not in text and "not acceptable" not in lower,
        "Avoid noisy markdown/report formatting.",
    )
    direct_needed = contract.get("kind") in {
        "Direct answer",
        "CAD reference",
        "Printer status",
        "CAD source search",
        "Bambu/Orca nozzle warning diagnostic",
        "Turbine airflow/endplate comparison",
        "OrcaSlicer Codex backend streamline",
        "Generator search missing specs",
        "Posting missing context",
        "Prusa/Core One L registration code",
        "TinManX average completion-time metric",
        "Rocket/Orca tool-map audit",
        "Slicer profile edit/update",
        "OrcaSlicer Codex installed-change verification",
        "Core One L profile packaging/share",
        "Shared profile repo machine organization",
    } or bool(build_direct_answer_context(messages, route or {}))
    if composition.get("forceLabeledSections", True):
        add(
            "Why/caveat shape",
            (not direct_needed) or ("this is why:" in lower and "you should also consider:" in lower),
            "Direct answers should include why and what to consider.",
        )
    else:
        add(
            "Adaptive conversation shape",
            (not direct_needed) or ("this is why:" not in lower and "you should also consider:" not in lower),
            "Conversational guidance/preferences should stay natural instead of forcing formal why/consider labels.",
        )
    if hard_task_kind(contract.get("kind")):
        add(
            "Deliverables visible",
            bool(deliverables) or blocker,
            "Created or referenced files should be visible and clickable; blocked tasks need the exact blocker.",
        )
    else:
        add("No wrong artifact route", not (contract.get("kind") == "CAD reference" and answer_has_cad_artifact(text)), "Reference questions should not stage artifacts.")
