def conversation_quality_p2_synthetic_check():
    fixture_path = APP_DIR / "tests" / "conversation_quality_p2_cases.json"
    data = read_json(fixture_path, {})
    cases = data.get("cases") if isinstance(data, dict) else []
    if not isinstance(cases, list) or len(cases) < 10:
        return False
    results = []
    for case in cases:
        if not isinstance(case, dict):
            return False
        result = conversation_quality_evaluation(
            case.get("messages") if isinstance(case.get("messages"), list) else [],
            case.get("route") if isinstance(case.get("route"), dict) else {},
            str(case.get("referenceAnswer") or ""),
            contract=case.get("contract") if isinstance(case.get("contract"), dict) else {},
            composition=case.get("composition") if isinstance(case.get("composition"), dict) else {},
            expectations=case.get("expectations") if isinstance(case.get("expectations"), dict) else {},
        )
        results.append(result)
    openings = [re.sub(r"[^a-z0-9]+", " ", result.get("firstSentence", "").lower()).strip() for result in results]
    non_empty_openings = [opening for opening in openings if opening]
    duplicate_openings = len(non_empty_openings) != len(set(non_empty_openings))
    coverage = conversation_quality_p6_coverage_report(data)
    return all(result.get("status") == "pass" for result in results) and not duplicate_openings and coverage.get("status") == "pass"


def evidence_ledger_p3_synthetic_check():
    fixture_path = APP_DIR / "tests" / "evidence_ledger_p3_cases.json"
    data = read_json(fixture_path, {})
    cases = data.get("cases") if isinstance(data, dict) else []
    if not isinstance(cases, list) or len(cases) < 8:
        return False
    for case in cases:
        if not isinstance(case, dict):
            return False
        messages = case.get("messages") if isinstance(case.get("messages"), list) else []
        route = case.get("route") if isinstance(case.get("route"), dict) else {}
        contract = case.get("contract") if isinstance(case.get("contract"), dict) else {}
        answer = str(case.get("answer") or "")
        expectations = case.get("expectations") if isinstance(case.get("expectations"), dict) else {}
        ledger = build_evidence_ledger(
            messages,
            route,
            answer,
            contract=contract,
            evidence=case.get("evidence"),
        )
        policy = ledger.get("policy") if isinstance(ledger.get("policy"), dict) else {}
        entries = ledger.get("entries") if isinstance(ledger.get("entries"), list) else []
        if policy.get("sourceType") != expectations.get("sourceType"):
            return False
        if policy.get("freshness") != expectations.get("freshness"):
            return False
        if bool(policy.get("required")) != bool(expectations.get("required")):
            return False
        if len(entries) > 3 or not entries:
            return False
        statuses = {entry.get("status") for entry in entries if isinstance(entry, dict)}
        source_types = {entry.get("sourceType") for entry in entries if isinstance(entry, dict)}
        for status in expectations.get("statuses") or []:
            if status not in statuses:
                return False
        for source_type in expectations.get("entrySourceTypes") or []:
            if source_type not in source_types:
                return False
        next_evidence = " ".join(str(entry.get("nextEvidence") or "") for entry in entries if isinstance(entry, dict)).lower()
        for term in expectations.get("nextEvidenceTerms") or []:
            if str(term).lower() not in next_evidence:
                return False
        package = response_package(messages, route, answer, web_search="disabled", evidence=case.get("evidence"))
        if not isinstance(package.get("evidenceLedger"), list) or not package.get("evidenceLedger"):
            return False
    return True


