def response_package(messages, route, answer, web_search="live", pre_send_review=None, evidence=None):
    contract = task_contract(messages, route or {})
    composition = adaptive_answer_composition_profile(messages, route or {})
    director = interaction_director_policy(messages, route or {}, contract=contract, composition=composition)
    composer = response_composer_policy(
        messages,
        route or {},
        contract=contract,
        composition=composition,
        director=director,
    )
    objective_plan = (route or {}).get("objectivePlan") or build_interaction_objective_plan(messages, route or {})
    coached = response_coach_answer(messages, route or {}, answer)
    review = pre_send_review if isinstance(pre_send_review, dict) else proactive_pre_send_response_review(
        messages,
        route or {},
        coached,
        contract=contract,
        composition=composition,
        composer=composer,
    )
    coached = str(review.get("text") or coached).strip()
    deliverables = extract_response_deliverables(coached)
    if contract.get("kind") != "Research + Apply":
        coached = compact_hard_task_answer(messages, route or {}, coached, contract, deliverables)
    coached = tinman_etiquette_polish(messages, route or {}, coached, contract)
    coached = apply_response_composer(coached, composer, messages=messages)
    deliverables = extract_response_deliverables(coached)
    assumptions = extract_assumption_ledger(messages, route or {}, coached, contract)
    evidence_ledger = build_evidence_ledger(
        messages,
        route or {},
        coached,
        contract=contract,
        director=director,
        evidence=evidence,
    )
    evidence_claim_review = evidence_claim_gate(messages, coached, evidence_ledger)
    if evidence_claim_review.get("status") == "review":
        coached = apply_evidence_claim_gate(coached, evidence_claim_review)
        deliverables = extract_response_deliverables(coached)
        assumptions = extract_assumption_ledger(messages, route or {}, coached, contract)
        evidence_ledger = build_evidence_ledger(
            messages,
            route or {},
            coached,
            contract=contract,
            director=director,
            evidence=evidence,
        )
    expertise_confidence = expertise_confidence_policy(
        messages,
        route or {},
        evidence_ledger,
        director=director,
        claim_gate=evidence_claim_review,
    )
    scorecard = response_scorecard(messages, route or {}, coached, contract, deliverables, assumptions, web_search=web_search)
    analytical = analytical_answer_score(messages, route or {}, coached, web_search=web_search)
    etiquette = tinman_etiquette_metrics(messages, route or {}, coached, contract)
    gate = scorecard.get("contractGate") or task_contract_gate(messages, route or {}, coached, contract, deliverables, assumptions, web_search=web_search)
    contract = {**contract, "gateStatus": gate.get("status"), "gateFailures": gate.get("failed", [])[:6]}
    feedback_guidance = feedback_guidance_receipt(messages, route or {})
    return {
        "text": coached,
        "displayMode": {
            "answerSurface": "codex-style",
            "showDiagnostics": False,
            "showReceiptsWhenDone": False,
        },
        "taskContract": contract,
        "roleStyle": response_role_style(route or {}),
        "compositionStyle": composition,
        "interactionDirector": director,
        "responseComposer": composer,
        "preSendReview": review,
        "feedbackGuidance": feedback_guidance,
        "workingProfile": working_profile_for_route(route or {}),
        "sessionCompass": normalize_session_compass((route or {}).get("sessionCompass")),
        "sessionCompassProgress": session_compass_progress_update(messages, route or {}, coached),
        "objectivePlan": objective_plan,
        "deliverables": deliverables,
        "assumptions": assumptions,
        "evidenceLedger": evidence_ledger["entries"],
        "evidencePolicy": evidence_ledger["policy"],
        "evidenceClaimGate": evidence_claim_review,
        "expertiseConfidence": expertise_confidence,
        "scorecard": scorecard,
        "contractGate": gate,
        "analyticalCore": analytical,
        "etiquette": etiquette,
    }


