def aero_health_volume_mesh_fixture(target, cases):
    path = Path(target) / "volume_mesh_preflight.json"
    runner = Path(target) / "run_openfoam_body_mesh.sh"
    runner.write_text(
        "\n".join(
            [
                "#!/usr/bin/env bash",
                "set -euo pipefail",
                "echo 'health fixture body mesh runner'",
            ]
        )
        + "\n",
        encoding="utf-8",
    )
    runner.chmod(0o755)
    data = {
        "ok": True,
        "ran": True,
        "caseCount": len(cases),
        "passedCaseCount": len(cases),
        "bodyConformingMeshRan": False,
        "bodyConformingMeshStatus": "runner-ready",
        "bodyConformingMeshRunnerPath": str(runner),
        "bodyConformingMeshCommand": str(runner),
        "bodyConformingMeshNextStep": "Run surfaceFeatureExtract and snappyHexMesh after reviewing the background-mesh checkMesh logs.",
        "cases": [
            {
                "label": case.get("label"),
                "caseDir": case.get("caseDir"),
                "ok": True,
                "blockMesh": {"ok": True, "ran": True, "summary": "blockMesh completed"},
                "checkMesh": {"ok": True, "ran": True, "summary": "Mesh OK."},
                "blockMeshLog": str(Path(case.get("caseDir") or target) / "blockMesh.log"),
                "checkMeshLog": str(Path(case.get("caseDir") or target) / "checkMesh.log"),
            }
            for case in cases
        ],
    }
    path.write_text(json.dumps(data, indent=2, sort_keys=True) + "\n", encoding="utf-8")
    return data, str(path)


