def cad_body_heal_gate_synthetic_check():
    freecad = command_path("FreeCADCmd") or command_path("freecad")
    if not freecad:
        return False
    target = LOCAL_AERO_OUTPUT_DIR / "_health_cad_body_heal_gate"
    target.mkdir(parents=True, exist_ok=True)
    source_step = target / "fixture_source.step"
    generator_code = f"""
import FreeCAD
import Import
import Part

target = {str(source_step)!r}
doc = FreeCAD.newDocument("cad_heal_fixture")
box = doc.addObject("Part::Feature", "fixture_box")
box.Shape = Part.makeBox(12, 8, 5)
doc.recompute()
Import.export([box], target)
print("WROTE_FIXTURE", target)
"""
    proc = subprocess.run(
        [freecad, "-c"],
        input="exec(" + repr(generator_code) + ")\n",
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
        text=True,
        timeout=45,
        env={**os.environ, "PATH": PATH_FOR_CODEX},
    )
    if proc.returncode != 0 or not source_step.exists() or source_step.stat().st_size <= 0:
        return False
    healed_step = target / "fixture_healed.step"
    heal = heal_step_with_freecad(source_step, healed_step)
    solver_stl = target / "fixture_solver.stl"
    conversion = convert_geometry_to_stl(healed_step, solver_stl) if cad_heal_is_usable(heal) else {}
    return (
        cad_heal_is_usable(heal)
        and healed_step.exists()
        and bool(conversion.get("ok"))
        and solver_stl.exists()
        and int(heal.get("objectsImported") or 0) >= 1
        and int(heal.get("objectsExported") or 0) >= 1
    )


