def wind_turbine_output_retention_synthetic_check():
    with tempfile.TemporaryDirectory(prefix="wind-turbine-retention-health-") as tmp_dir:
        root = Path(tmp_dir)
        created = []
        base_time = time.time() - 1000
        for index in range(6):
            case_dir = root / f"20260716-00000{index}-wind-turbine-case"
            case_dir.mkdir(parents=True, exist_ok=True)
            (case_dir / "case_setup.json").write_text("{}", encoding="utf-8")
            (case_dir / "WIND_TURBINE_DESIGN_REPORT.md").write_text("# fixture\n", encoding="utf-8")
            stamp = base_time + index
            os.utime(case_dir, (stamp, stamp))
            created.append(case_dir)
        health_dir = root / "_health_wind_fixture"
        health_dir.mkdir()
        (health_dir / "case_setup.json").write_text("{}", encoding="utf-8")
        retention = cleanup_wind_turbine_output_retention(root=root, keep=3, protect_paths=[created[0]])
        remaining_names = sorted(path.name for path in root.iterdir() if path.is_dir())
        expected_names = sorted([created[0].name] + [path.name for path in created[-3:]] + [health_dir.name])
        return (
            retention.get("removed") == 2
            and retention.get("preserved") == 2
            and remaining_names == expected_names
            and created[0].exists()
            and health_dir.exists()
            and all(not path.exists() for path in created[1:3])
        )


