def live_steering_revision_prompt(messages, route, candidate_answer, notes, friendliness_level=None, humor_level=None):
    clean_messages = []
    for message in (messages or [])[-12:]:
        role = str(message.get("role", "")).strip().lower()
        text = str(message.get("text", "")).strip()
        if role in {"user", "assistant"} and text:
            clean_messages.append((role, text))

    blocks = [
        "You are Tinman's local final-answer editor.",
        build_assistant_style_context(friendliness_level, humor_level, route).strip(),
        build_response_quality_context(messages, route or {}).strip(),
        "Tinman sent live steering while the answer was being generated.",
        "Revise the candidate answer to follow Tinman's steering before final delivery.",
        "Treat the newest live steering as higher priority than older draft wording.",
        "If the steering corrects scope, assumptions, tone, format, or priority, apply it.",
        "If a steering note names Tinman or asks to explicitly mention, say, include, or use wording, keep that requirement visible in the final answer instead of implying it.",
        "Do not paraphrase away named people, exact phrases, file names, part numbers, voltages, IP addresses, or requested labels from Tinman's steering.",
        "Preserve verified facts, file paths, command results, sources, and caveats from the candidate answer.",
        "Do not invent new facts, tests, files, tool results, product specs, prices, or machine access claims.",
        "Return only the final answer for Tinman. Do not mention this editor or hidden reasoning.",
        "",
        format_manager_context(route or {}).strip(),
        "",
    ]
    if clean_messages:
        blocks.append("Conversation context:")
        for role, text in clean_messages:
            label = "User" if role == "user" else "Assistant"
            blocks.append(f"{label}:\n{text}")
            blocks.append("")
    blocks.extend(
        [
            "Live steering notes:",
            "\n".join(f"- {note}" for note in notes),
            "",
            "Candidate answer:",
            str(candidate_answer or "").strip(),
            "",
            "Final answer:",
        ]
    )
    return "\n".join(block for block in blocks if block is not None).strip()


def clean_live_steering_exact_phrase(value):
    phrase = str(value or "").strip()
    phrase = phrase.strip("`\"' ")
    phrase = phrase.strip("\u201c\u201d\u2018\u2019 ")
    while phrase and phrase[-1] in ".!?":
        phrase = phrase[:-1].rstrip()
    if len(phrase) < 2 or len(phrase) > 220:
        return ""
    return phrase


def live_steering_exact_phrase_requirements(notes):
    phrases = []
    seen = set()
    for raw_note in notes or []:
        note = str(raw_note or "").strip()
        if not note:
            continue
        candidates = []
        quoted = re.search(
            r"\b(?:include|mention|say|use|add)\s+(?:the\s+)?(?:exact\s+)?phrase\s+([\"'`])(.{1,220}?)\1",
            note,
            re.I | re.S,
        )
        if quoted:
            candidates.append(quoted.group(2))
        unquoted = re.search(
            r"\b(?:include|mention|say|use|add)\s+(?:the\s+)?(?:exact\s+)?phrase\s+(.{1,220}?)(?:\s+(?:in|inside|within)\s+(?:the\s+)?(?:answer|response)\b|[.!?]?$)",
            note,
            re.I | re.S,
        )
        if unquoted:
            candidates.append(unquoted.group(1))
        for candidate in candidates:
            phrase = clean_live_steering_exact_phrase(candidate)
            key = phrase.lower()
            if phrase and key not in seen:
                phrases.append(phrase)
                seen.add(key)
    return phrases


def enforce_live_steering_exact_phrases(answer, notes):
    revised = str(answer or "").rstrip()
    applied = []
    for phrase in live_steering_exact_phrase_requirements(notes):
        if phrase and phrase not in revised:
            revised = (revised + "\n\n" if revised else "") + phrase
            applied.append(phrase)
    return revised, applied


def live_steering_lifecycle_synthetic_check():
    run_id = f"health-steer-{int(time.time() * 1000)}"
    inactive_rejected = False
    late_rejected = False
    try:
        add_live_steering(run_id, "this should not be accepted before the run starts")
    except ValueError as exc:
        inactive_rejected = "active run" in str(exc).lower() and "steering" in str(exc).lower()
    register_live_run(run_id)
    try:
        count = add_live_steering(run_id, "make the answer shorter")
        notes = live_steering_notes(run_id)
        close_live_steering_window(run_id)
        try:
            add_live_steering(run_id, "this should not be accepted after final answer")
        except ValueError as exc:
            late_rejected = "active run" in str(exc).lower() and "steering" in str(exc).lower()
        return inactive_rejected and late_rejected and count == 1 and notes == ["make the answer shorter"]
    finally:
        unregister_live_run(run_id)


