def preserve_live_steering_critical_fragments(original_answer, revised_answer):
    revised = str(revised_answer or "").rstrip()
    original = str(original_answer or "")
    if not original.strip() or not revised.strip():
        return revised
    line_markers = (
        "blocker:",
        "requested speed cases:",
        "source evidence:",
        "source text used",
        "original left unchanged",
        "original remains unchanged",
        "original file remains unchanged",
        "original preview remains unchanged",
        "originals are still left unchanged",
        "changed:",
    )
    section_markers = (
        "files to open first:",
        "paths checked:",
    )
    revised_lower = revised.lower()
    fragments = []
    seen = set()

    def add_fragment(fragment):
        cleaned = " ".join(str(fragment or "").split()).strip()
        lower = cleaned.lower()
        if lower in revised_lower:
            return
        key = lower
        if key not in seen:
            fragments.append(compact(cleaned, 700))
            seen.add(key)

    all_receipt_markers = tuple(section_markers) + tuple(line_markers)

    def marker_specific_fragment(cleaned, lower, marker):
        start = lower.find(marker)
        if start < 0:
            return ""
        next_positions = [
            lower.find(candidate, start + len(marker))
            for candidate in all_receipt_markers
            if candidate != marker and lower.find(candidate, start + len(marker)) >= 0
        ]
        end = min(next_positions) if next_positions else len(cleaned)
        return cleaned[start:end].strip()

    lines = [str(line or "").rstrip() for line in original.splitlines()]
    idx = 0
    while idx < len(lines):
        cleaned = " ".join(lines[idx].split()).strip()
        lower = cleaned.lower()
        if not cleaned:
            idx += 1
            continue
        for marker in all_receipt_markers:
            if marker in lower:
                add_fragment(marker_specific_fragment(cleaned, lower, marker))
        if any(marker in lower for marker in section_markers):
            section = [cleaned]
            probe = idx + 1
            while probe < len(lines) and len(section) < 5:
                next_cleaned = " ".join(lines[probe].split()).strip()
                if not next_cleaned:
                    break
                if next_cleaned.startswith("-") or next_cleaned.startswith("*") or "`" in next_cleaned:
                    section.append(next_cleaned)
                    probe += 1
                    continue
                break
            add_fragment(" ".join(section))
            idx = probe
            continue
        if any(marker in lower for marker in line_markers):
            add_fragment(cleaned)
        idx += 1

    if not fragments:
        return revised
    return revised + "\n\n" + "\n".join(fragments[:10])


def apply_live_steering_to_answer(messages, route, answer, run_id, emit=None, friendliness_level=None, humor_level=None, generate_fn=None):
    if not str(answer or "").strip():
        return answer, messages
    notes = live_steering_notes(run_id)
    if not notes:
        notes = wait_for_live_steering_notes(run_id)
    if not notes:
        return answer, messages
    steered_messages = messages_with_live_steering(messages, notes)
    if emit:
        emit(f"Tinman's live steering arrived; applying {len(notes)} note{'s' if len(notes) != 1 else ''} before final delivery.")
    direct_exact_phrases = live_steering_exact_phrase_requirements(notes)
    exact_phrase_only = bool(direct_exact_phrases) and all(
        live_steering_exact_phrase_requirements([note]) for note in notes
    )
    if exact_phrase_only:
        revised, applied_directives = enforce_live_steering_exact_phrases(answer, notes)
        if emit:
            if applied_directives:
                emit("An explicit live steering phrase requirement was applied directly before final delivery.")
            emit("Live steering was applied to the final answer.")
        return revised, steered_messages
    try:
        generate = generate_fn or run_ollama_generate
        result = generate(
            live_steering_revision_prompt(
                steered_messages,
                route or {},
                answer,
                notes,
                friendliness_level=friendliness_level,
                humor_level=humor_level,
            ),
            model=MANAGER_POLISH_MODEL,
            timeout=180,
            num_predict=1800,
            num_ctx=12000,
        )
        revised = strip_thinking_markup(result.get("text") or "").strip()
        if revised:
            revised = preserve_live_steering_critical_fragments(answer, revised)
            revised, applied_directives = enforce_live_steering_exact_phrases(revised, notes)
            if emit:
                if applied_directives:
                    emit("An explicit live steering phrase requirement was enforced before final delivery.")
                emit("Live steering was applied to the final answer.")
            return revised, steered_messages
        fallback, applied_directives = enforce_live_steering_exact_phrases(answer, notes)
        if applied_directives:
            if emit:
                emit("An explicit live steering phrase requirement was applied directly after an empty revision pass.")
            return fallback, steered_messages
        if emit:
            emit("Live steering pass returned no usable text, so I kept the best available answer.")
    except Exception as exc:
        fallback, applied_directives = enforce_live_steering_exact_phrases(answer, notes)
        if applied_directives:
            if emit:
                emit(f"An explicit live steering phrase requirement was applied directly after revision failure: {compact(exc, 120)}")
            return fallback, steered_messages
        if emit:
            emit(f"Live steering pass failed, so I kept the best available answer: {compact(exc, 120)}")
    return answer, steered_messages


def emit_assistant_answer(handler, messages, route, admin_topic, text, normalize=True, evidence=None):
    run_id = getattr(handler, "current_run_id", "")
    pre_steering_text = text
    applied_live_steering_notes = []
    live_steering_applied_this_emit = False
    if run_id and not getattr(handler, "current_run_steering_applied", False) and not (admin_topic or {}).get("testRun"):
        def emit_steering_note(note):
            json_line(handler, {"type": "thought", "text": note})

        text, messages = apply_live_steering_to_answer(
            messages,
            route or {},
            text,
            run_id,
            emit=emit_steering_note,
            friendliness_level=getattr(handler, "current_friendliness_level", None),
            humor_level=getattr(handler, "current_humor_level", None),
        )
        applied_live_steering_notes = live_steering_notes(run_id)
        handler.current_run_steering_applied = True
        live_steering_applied_this_emit = True
        close_live_steering_window(run_id)
        finish_live_steering(run_id)
    answer = normalize_direct_answer_shape(messages, route, text) if normalize else strip_thinking_markup(text)
    web_search = safe_choice(getattr(handler, "current_web_search", None), WEB_SEARCH_LEVELS, "live")
    saved_review = (route or {}).get("_preSendReview") if isinstance(route, dict) else None
    package = response_package(
        messages,
        route or {},
        answer,
        web_search=web_search,
        pre_send_review=saved_review,
        evidence=evidence,
    )
    answer = package["text"]
    if live_steering_applied_this_emit:
        answer = preserve_live_steering_critical_fragments(pre_steering_text, answer)
        answer, _ = enforce_live_steering_exact_phrases(answer, applied_live_steering_notes)
    if answer and not (admin_topic or {}).get("testRun"):
        update_admin_activity(messages, route or {}, answer, admin_topic)
    json_line(
        handler,
        {
            "type": "assistant",
            "text": answer,
            "displayMode": package["displayMode"],
            "adminTopic": admin_topic,
            "taskContract": package["taskContract"],
            "roleStyle": package["roleStyle"],
            "compositionStyle": package["compositionStyle"],
            "interactionDirector": package["interactionDirector"],
            "evidenceLedger": package["evidenceLedger"],
            "evidencePolicy": package["evidencePolicy"],
            "evidenceClaimGate": package["evidenceClaimGate"],
            "expertiseConfidence": package["expertiseConfidence"],
            "responseComposer": package["responseComposer"],
            "preSendReview": package["preSendReview"],
            "feedbackGuidance": package["feedbackGuidance"],
            "workingProfile": package["workingProfile"],
            "sessionCompass": package["sessionCompass"],
            "sessionCompassProgress": package["sessionCompassProgress"],
            "objectivePlan": package["objectivePlan"],
            "deliverables": package["deliverables"],
            "assumptions": package["assumptions"],
            "scorecard": package["scorecard"],
            "contractGate": package["contractGate"],
            "analyticalCore": package["analyticalCore"],
            "etiquette": package["etiquette"],
        },
    )
    return answer


def supervise_answer_before_emit(
    messages,
    route,
    admin_topic,
    answer_text,
    cwd="",
    web_search="live",
    emit=None,
    friendliness_level=None,
    humor_level=None,
):
    answer = str(answer_text or "").strip()
    if not answer:
        return answer
    result = autonomy_supervisor_recover_answer(
        messages,
        route or {},
        answer,
        cwd=cwd,
        web_search=web_search,
        emit=emit,
        friendliness_level=friendliness_level,
        humor_level=humor_level,
    )
    recovered = str(result.get("text") or answer).strip()
    if result.get("recovered") and emit:
        emit("Autonomy Supervisor recovered the answer before final delivery.")
    analytical = analytical_answer_score(messages, route or {}, recovered or answer, web_search=web_search)
    if analytical.get("status") != "pass":
        gap_text = "; ".join(gap.get("kind", "gap") for gap in analytical.get("gaps", [])[:4])
        if emit:
            emit(f"Analytical Core caught a weak answer before final delivery: {gap_text}.")
        try:
            coached = run_quality_coach(
                messages,
                route or {},
                recovered or answer,
                review_text="Analytical Core gaps: " + "; ".join(gap.get("reason", gap.get("kind", "gap")) for gap in analytical.get("gaps", [])[:4]),
                emit=emit,
                num_predict=1400,
                friendliness_level=friendliness_level,
                humor_level=humor_level,
            )
            coached_text = str(coached.get("text") or "").strip()
            if coached_text:
                recovered = coached_text
                if emit:
                    emit("Analytical Core correction pass completed.")
        except Exception as exc:
            if emit:
                emit(f"Analytical Core correction pass failed, keeping the best available answer: {compact(exc, 120)}")
    contract = task_contract(messages, route or {})
    composition = adaptive_answer_composition_profile(messages, route or {})
    composer = response_composer_policy(messages, route or {}, contract=contract, composition=composition)
    pre_send_review = proactive_pre_send_response_review(
        messages,
        route or {},
        recovered or answer,
        contract=contract,
        composition=composition,
        composer=composer,
    )
    recovered = str(pre_send_review.get("text") or recovered or answer).strip()
    if isinstance(route, dict):
        route["_preSendReview"] = pre_send_review
    if pre_send_review.get("revisionApplied") and emit:
        flags = ", ".join(pre_send_review.get("flags") or []) or "response polish"
        emit(f"Final-answer review tightened the draft: {flags}.")
    package = response_package(
        messages,
        route or {},
        recovered or answer,
        web_search=web_search,
        pre_send_review=pre_send_review,
    )
    gate = package.get("contractGate") or {}
    if gate.get("status") == "block":
        if emit:
            emit("Task Contract Gate blocked the draft from being marked complete.")
        return format_contract_gate_blocker(messages, route or {}, recovered or answer, contract, gate)
    return package.get("text") or recovered or answer


def local_review_model_for_profile(profile=None):
    if profile == "local-deep-review":
        return LOCAL_DEEP_REVIEW_MODEL
    return LOCAL_REVIEW_MODEL


def run_local_review(
    messages,
    route,
    emit=None,
    num_predict=1800,
    model=None,
    timeout=240,
    friendliness_level=None,
    humor_level=None,
):
    prompt = local_review_prompt(messages, route, friendliness_level, humor_level)
    if not prompt:
        return {"error": "Review needs a user request or answer to inspect."}
    selected_model = model or LOCAL_REVIEW_MODEL
    if emit:
        emit(f"Asking local `{selected_model}` for a second pass.")
    result = run_ollama_generate(
        prompt,
        model=selected_model,
        timeout=timeout,
        num_predict=num_predict,
        num_ctx=12000,
    )
    if result.get("text"):
        return {"text": strip_thinking_markup(result["text"]), "model": selected_model}
    return result


def manager_final_prompt(
    messages,
    route,
    primary_answer,
    review_text,
    friendliness_level=None,
    humor_level=None,
):
    clean_messages = []
    for message in messages[-10:]:
        role = str(message.get("role", "")).strip().lower()
        text = str(message.get("text", "")).strip()
        if role in {"user", "assistant"} and text:
            clean_messages.append((role, text))

    blocks = [
        "You are Tinman's local Manager finalizer.",
        build_assistant_style_context(friendliness_level, humor_level, route).strip(),
        build_autonomy_supervisor_context(messages, route=route, web_search="live").strip(),
        build_response_quality_context(messages, route).strip(),
        "Use the primary worker answer and the local review to produce the final answer for Tinman.",
        "Return only the final answer. Do not mention that a review or finalizer ran.",
        "Keep the answer practical and concise.",
        "For direct questions, preserve a direct-answer shape: answer first, then `This is why`, then `You should also consider` when useful.",
        "Preserve concrete facts, file paths, commands, source URLs, prices, and validation results from the primary answer.",
        "Do not add product names, prices, availability, lifespan claims, or source-like specifics that were not in the primary answer or verified evidence.",
        "If the review identifies a real issue, fix it in the final answer.",
        "If the review only says the answer is basically good, keep the primary answer mostly intact and tighten the wording.",
        "Do not invent facts, sources, command output, test results, or files.",
        "Do not expose hidden reasoning.",
        "Avoid big Markdown headings, bold labels, and noisy report formatting.",
        "",
        format_manager_context(route).strip(),
        "",
    ]
    if clean_messages:
        blocks.append("Conversation context:")
        for role, text in clean_messages:
            label = "User" if role == "user" else "Assistant"
            blocks.append(f"{label}:\n{text}")
            blocks.append("")
    blocks.extend(
        [
            "Primary worker answer:",
            str(primary_answer or "").strip(),
            "",
            "Local review:",
            str(review_text or "").strip(),
            "",
            "Final answer for Tinman:",
        ]
    )
    return "\n".join(blocks).strip()


def run_manager_polish(
    messages,
    route,
    primary_answer,
    review_text,
    emit=None,
    num_predict=2200,
    friendliness_level=None,
    humor_level=None,
):
    if not str(primary_answer or "").strip():
        return {"error": "Manager polish needs a primary answer."}
    if emit:
        emit(f"Polishing the final answer with local `{MANAGER_POLISH_MODEL}`.")
    result = run_ollama_generate(
        manager_final_prompt(
            messages,
            route,
            primary_answer,
            review_text,
            friendliness_level,
            humor_level,
        ),
        model=MANAGER_POLISH_MODEL,
        timeout=240,
        num_predict=num_predict,
        num_ctx=12000,
    )
    if result.get("text"):
        return {"text": strip_thinking_markup(result["text"]), "model": MANAGER_POLISH_MODEL}
    return result


def quality_coach_prompt(
    messages,
    route,
    candidate_answer,
    review_text="",
    friendliness_level=None,
    humor_level=None,
):
    clean_messages = []
    for message in messages[-8:]:
        role = str(message.get("role", "")).strip().lower()
        text = str(message.get("text", "")).strip()
        if role in {"user", "assistant"} and text:
            clean_messages.append((role, text))

    analytical_review = analytical_answer_score(messages, route or {}, candidate_answer, web_search="live")
    analytical_gaps = "; ".join(
        gap.get("reason", gap.get("kind", "gap")) for gap in analytical_review.get("gaps", [])[:5]
    ) or "none"

    blocks = [
        "You are Tinman's final Quality Coach.",
        build_assistant_style_context(friendliness_level, humor_level, route).strip(),
        build_autonomy_supervisor_context(messages, route=route, web_search="live").strip(),
        build_analytical_context(messages, route=route, web_search="live", local_tools=True).strip(),
        build_response_quality_context(messages, route).strip(),
        "Your job is to return the final answer Tinman should see.",
        "If the candidate already passes the rubric, return it with only minor cleanup.",
        "If it misses the question, skips required domain/platform classification, chooses the wrong tool family, buries the answer, uses noisy formatting, invents evidence, sounds canned, or omits a useful reason/caveat, rewrite it.",
        f"Analytical Core score: {analytical_review.get('score')} ({analytical_review.get('status')}). Gaps: {analytical_gaps}.",
        "When rewriting, preserve verified facts but fix the highest-impact analytical gap first: wrong objective, ignored constraints, no decision, no diagnostic path, no validation, or missing evidence.",
        "Do not add unsupported facts, sources, prices, files, tests, command outputs, or machine access claims. You may add the general corrective principles explicitly required by the response-quality context when repairing a causal or safety gap.",
        "Preserve verified specifics from the candidate answer.",
        "Return only the final answer. Do not mention the rubric, coach, review, or scoring.",
        "",
        format_manager_context(route).strip(),
        "",
    ]
    if clean_messages:
        blocks.append("Conversation context:")
        for role, text in clean_messages:
            label = "User" if role == "user" else "Assistant"
            blocks.append(f"{label}:\n{text}")
            blocks.append("")
    if review_text:
        blocks.extend(["Review note:", str(review_text).strip(), ""])
    blocks.extend(
        [
            "Candidate answer:",
            str(candidate_answer or "").strip(),
            "",
            "Final answer for Tinman:",
        ]
    )
    return "\n".join(blocks).strip()


def run_quality_coach(
    messages,
    route,
    candidate_answer,
    review_text="",
    emit=None,
    num_predict=1700,
    friendliness_level=None,
    humor_level=None,
):
    candidate_answer = str(candidate_answer or "").strip()
    if not candidate_answer:
        return {"text": "", "coached": False}
    if emit:
        emit(f"Quality Coach is checking the final answer against Tinman's rubric.")
    result = run_ollama_generate(
        quality_coach_prompt(
            messages,
            route,
            candidate_answer,
            review_text=review_text,
            friendliness_level=friendliness_level,
            humor_level=humor_level,
        ),
        model=MANAGER_POLISH_MODEL,
        timeout=240,
        num_predict=num_predict,
        num_ctx=12000,
    )
    if result.get("text"):
        return {
            "text": strip_thinking_markup(result["text"]),
            "model": MANAGER_POLISH_MODEL,
            "coached": True,
        }
    return {**result, "text": candidate_answer, "coached": False}


def run_manager_review_and_polish(
    messages,
    route,
    primary_answer,
    emit=None,
    manager_depth="balanced",
    friendliness_level=None,
    humor_level=None,
):
    primary_answer = str(primary_answer or "").strip()
    if not primary_answer:
        return {"text": primary_answer, "review": "", "polished": False}
    if manager_depth == "fast":
        if emit:
            emit("Manager speed is Fast; skipping review and polish for this run.")
        return {"text": primary_answer, "review": "", "polished": False}

    review_model = LOCAL_REVIEW_MODEL
    review_timeout = 240
    review_predict = 1100
    if manager_depth == "full":
        review_model = LOCAL_DEEP_REVIEW_MODEL
        review_timeout = 420
        review_predict = 4200
    polish_predict = 1500 if manager_depth == "balanced" else 2200

    review_messages = list(messages) + [{"role": "assistant", "text": primary_answer}]
    if emit:
        escalation_note = auto_deep_review_note((route or {}).get("autoDeepReview") or {})
        if escalation_note:
            emit(escalation_note)
        label = "Balanced" if manager_depth == "balanced" else "Full"
        emit(f"Manager speed is {label}; running a local review pass.")
    try:
        review = run_local_review(
            review_messages,
            route,
            emit=emit,
            num_predict=review_predict,
            model=review_model,
            timeout=review_timeout,
            friendliness_level=friendliness_level,
            humor_level=humor_level,
        )
    except Exception as exc:
        if emit:
            emit("Local review failed, so Manager is returning the primary answer instead of dropping the response.")
        return {"text": primary_answer, "review": f"review failed: {exc}", "polished": False}
    review_text = str(review.get("text") or "").strip()
    if not review_text:
        if emit:
            emit("Local review did not return a usable note, so Manager is keeping the primary answer.")
        return {"text": primary_answer, "review": review.get("error", ""), "polished": False}

    try:
        polish = run_manager_polish(
            messages,
            route,
            primary_answer,
            review_text,
            emit=emit,
            num_predict=polish_predict,
            friendliness_level=friendliness_level,
            humor_level=humor_level,
        )
    except Exception as exc:
        if emit:
            emit("Final polish failed, so Manager is returning the reviewed primary answer.")
        return {"text": primary_answer, "review": f"{review_text}\npolish failed: {exc}".strip(), "polished": False}
    polished_text = str(polish.get("text") or "").strip()
    if polished_text:
        coach_predict = 1400 if manager_depth == "balanced" else 2100
        try:
            coach = run_quality_coach(
                messages,
                route,
                polished_text,
                review_text=review_text,
                emit=emit,
                num_predict=coach_predict,
                friendliness_level=friendliness_level,
                humor_level=humor_level,
            )
        except Exception as exc:
            if emit:
                emit("Quality Coach failed, so Manager is returning the polished answer.")
            return {
                "text": polished_text,
                "review": f"{review_text}\nquality coach failed: {exc}".strip(),
                "polished": True,
                "qualityChecked": False,
            }
        coached_text = str(coach.get("text") or "").strip()
        return {
            "text": coached_text or polished_text,
            "review": review_text,
            "polished": True,
            "qualityChecked": bool(coach.get("coached")),
        }

    if emit:
        emit("Final polish did not return a usable answer, so Manager is keeping the reviewed primary answer.")
    return {"text": primary_answer, "review": review_text, "polished": False}


def ensure_source_links(text, evidence_pack):
    answer = str(text or "").strip()
    if re.search(r"https?://", answer):
        return answer
    lines = ["", "Sources checked"]
    for item in evidence_pack[:6]:
        if item.get("url"):
            lines.append(f"{item.get('id', '')}. {item['url']}")
    return answer + "\n".join(lines)


def ensure_product_shopping_caveats(text, query):
    answer = str(text or "").strip()
    if not answer or not is_current_product_shopping_request([{"role": "user", "text": query}]):
        return answer
    lower = answer.lower()
    additions = []
    if "stock" not in lower:
        additions.append(
            "Stock/availability caveat: treat current stock as unverified unless the seller page itself shows the exact kit available to order now."
        )
    if "price" not in lower and "$" not in answer:
        additions.append(
            "Price caveat: treat price as unverified unless the seller page itself shows the current checkout price."
        )
    if not additions:
        return answer
    return answer.rstrip() + "\n\n" + "\n".join(additions)


def safe_local_research_answer(query, route, evidence_pack):
    def useful_item(item):
        title = str(item.get("title") or "").strip()
        haystack = " ".join([title, str(item.get("excerpt") or ""), str(item.get("snippet") or "")]).lower()
        if not title or title.startswith(("http://", "https://")):
            return False
        if text_has_any(haystack, ("continue shopping", "your account", "spend less. smile more", "free shipping on millions")):
            return False
        return True

    lower = str(query or "").lower()
    asin = ""
    match = re.search(r"(?i)(?:/dp/|/gp/product/|asin[=/:\s-]*)([a-z0-9]{10})", query)
    if match:
        asin = match.group(1).upper()
    usable = [item for item in evidence_pack if useful_item(item)]
    primary = usable[0] if usable else (evidence_pack[0] if evidence_pack else {})
    if asin:
        asin_lower = asin.lower()
        for item in usable:
            parsed = urllib.parse.urlparse(str(item.get("url") or ""))
            if parsed.netloc.lower().endswith("amazon.com") and asin_lower in parsed.path.lower():
                primary = item
                break
    title = compact(primary.get("title") or "the strongest source match", 180)
    excerpt = compact(primary.get("excerpt") or primary.get("snippet") or "", 420)
    urls = [item.get("url") for item in evidence_pack if item.get("url")]
    source_lines = "\n".join(f"{index}. {url}" for index, url in enumerate(urls[:6], start=1))

    if "amazon." in lower or asin:
        lead = f"My recommendation: this is worth considering if you need this class of item; the link appears to be {title}."
        caveat = (
            "I can identify the product from the source snippets, but Amazon did not provide a clean live product page through the local fetch path, "
            "so treat current price, seller, shipping, and stock as unverified until you open the listing."
        )
    else:
        lead = f"My recommendation: use {title} as the best current lead from the checked sources, then verify the final fit before buying or building around it."
        caveat = "verify the newest price, stock, revision, or seller terms before buying or building around it."

    why = excerpt or "the checked sources matched the supplied link/query, but the local model did not return a final synthesis."
    asin_note = f" for ASIN {asin}" if asin else ""
    return "\n\n".join(
        [
            lead,
            f"This is why: the strongest source evidence{asin_note} says {why}",
            f"You should also consider: {caveat}",
            "Sources checked\n" + (source_lines or "No source URLs were captured."),
        ]
    )


def safe_product_shopping_boundary_answer(query, results):
    core = product_shopping_search_core(query) or "that product"
    usable = []
    for item in results or []:
        title = compact(str(item.get("title") or ""), 140)
        url = str(item.get("url") or "").strip()
        haystack = " ".join([title, str(item.get("snippet") or "")]).lower()
        if not title or not url or title.startswith(("http://", "https://")):
            continue
        if text_has_any(haystack, ("continue shopping", "your account", "spend less. smile more", "free shipping on millions")):
            continue
        usable.append({"title": title, "url": url})
        if len(usable) >= 5:
            break

    if usable:
        leads = "\n".join(f"{index}. {item['title']} - {item['url']}" for index, item in enumerate(usable, start=1))
        return "\n\n".join(
            [
                f"I found current web leads for {core}, but I could not verify a clean in-stock, price-confirmed buy link from extractable page text yet.",
                "This is why: product sourcing is volatile, and I should only call something available when the checked source actually shows the exact item, seller, price or stock, and enough page text to prove it.",
                "Best leads to open/check next:\n" + leads,
                "You should also consider: before buying, confirm the listing shows the requested brand/model, includes the exact kit or part rather than only a related accessory, and shows current stock, price, shipping, and return terms.",
            ]
        )

    return "\n\n".join(
        [
            f"I could not verify a current seller for {core} from the free public search path.",
            "This is why: I should not turn a sourcing request into a generic list of marketplaces without source proof.",
            "You should also consider: rerun with Web Access on, a part number, or a manufacturer/distributor link if you have one, and I will verify exact match, stock, price, shipping, and seller risk from the source text.",
        ]
    )


def cad_web_research_evidence(query, limit=4):
    try:
        queries = [
            "3D printer part cooling duct CFD PLA ABS PETG outlet design",
            "CPAP blower 3D printer part cooling duct nozzle design",
        ]
        lower = str(query or "").lower()
        if "fusion" in lower:
            queries.append("Fusion 360 3D printer cooling duct CFD design")
        if "pctg" in lower or "petg" in lower:
            queries.append("3D printer part cooling PETG PCTG fan duct airflow")
        items = []
        seen = set()
        for search_query in queries[:4]:
            for item in search_web_free(search_query, limit=max(limit * 2, 8)):
                url = item.get("url", "")
                if not url or url in seen:
                    continue
                seen.add(url)
                items.append(
                    {
                        "title": item.get("title", ""),
                        "url": url,
                        "snippet": item.get("snippet", ""),
                        "source": item.get("source", ""),
                    }
                )
        def source_score(item):
            haystack = " ".join([item.get("title", ""), item.get("snippet", ""), item.get("url", "")]).lower()
            domain = urllib.parse.urlparse(item.get("url", "")).netloc.lower()
            score = 0
            for term, points in (
                ("cfd", 10),
                ("part cooling", 9),
                ("cooling duct", 9),
                ("fan duct", 7),
                ("airflow", 6),
                ("3d printer", 5),
                ("blower", 4),
                ("pla", 3),
                ("petg", 3),
                ("abs", 3),
            ):
                if term in haystack:
                    score += points
            for domain_term, points in (
                ("sciencedirect.com", 24),
                ("springer.com", 20),
                ("mdpi.com", 18),
                ("researchgate.net", 14),
                ("printables.com", 14),
                ("prusa3d.com", 14),
                ("github.com", 8),
                ("reprap.org", 8),
            ):
                if domain_term in domain:
                    score += points
            if "2026 guide" in haystack or "blog.uavmodel.com" in domain:
                score -= 16
            return score

        items.sort(key=source_score, reverse=True)
        return {"items": items[:limit], "queries": queries[:4]}
    except Exception as exc:
        return {"items": [], "error": str(exc)}


def stable_expert_fallback_prompt(messages, route, friendliness_level=None, humor_level=None):
    query = latest_user_text(messages).strip()
    return "\n".join(
        [
            "You are Tinman's local technical specialist.",
            build_assistant_style_context(friendliness_level, humor_level, route).strip(),
            build_response_quality_context(messages, route).strip(),
            build_3d_printing_expert_context(messages).strip(),
            "The source search did not produce an extractable evidence pack for this stable technical question.",
            "Give the useful answer from broadly stable engineering knowledge instead of reporting a research dead end.",
            "Lead with the practical decision, distinguish a base material from filled or grade-specific behavior, and name the condition that could change the recommendation.",
            "Do not invent source URLs, material-property numbers, current prices, or specific machine settings. Say that grade datasheets or a test coupon are the next evidence when that boundary matters.",
            "Return only the answer for Tinman; do not mention hidden tooling or this fallback.",
            "",
            "Question:",
            query,
        ]
    ).strip()


def stable_expert_fallback_answer(messages, route, friendliness_level=None, humor_level=None, generate_fn=None):
    prompt = stable_expert_fallback_prompt(
        messages,
        route,
        friendliness_level=friendliness_level,
        humor_level=humor_level,
    )
    if not prompt:
        return {"text": ""}
    generate = generate_fn or run_ollama_generate
    result = generate(
        prompt,
        model=LOCAL_RESEARCH_MODEL,
        timeout=180,
        num_predict=1400,
        num_ctx=12000,
    )
    text = strip_thinking_markup(result.get("text") or "").strip()
    return {
        "text": text,
        "model": "stable-expert-fallback" if text else "",
        "warning": result.get("error", "") if not text else "",
    }


def stable_expert_fallback_p32_synthetic_check():
    messages = [
        {
            "role": "user",
            "text": "Compare PEI and PPS-CF for a hot, chemically exposed fixture.",
        }
    ]
    route = route_manager(messages, requested_profile="manager", web_search="live")
    captured = {}

    def fake_generate(prompt, **_kwargs):
        captured["prompt"] = prompt
        return {
            "text": (
                "PPS-CF is usually the better stiffness-first choice when the printer can process it, while PEI can be preferable when toughness, electrical insulation, or a specific grade's certification drives the decision. "
                "Confirm the exact grade datasheet before locking a temperature or chemical-exposure limit."
            )
        }

    result = stable_expert_fallback_answer(messages, route, generate_fn=fake_generate)
    return (
        route.get("projectId") == "tinmanx-slicer-research"
        and result.get("model") == "stable-expert-fallback"
        and "pps-cf" in str(result.get("text") or "").lower()
        and "source search did not produce an extractable evidence pack" in str(captured.get("prompt") or "").lower()
        and "do not invent source urls" in str(captured.get("prompt") or "").lower()
    )


def run_local_research(
    messages,
    route,
    web_search="live",
    emit=None,
    friendliness_level=None,
    humor_level=None,
):
    query = latest_user_text(messages)
    if not query.strip():
        return {"error": "Local Research needs a user question to research."}
    if web_search != "live":
        return {"error": "Local Research needs Web enabled. Turn Web on or use a local Codex mode."}
    if is_named_hardware_spec_lookup_question(messages):
        if emit:
            emit("Named hardware specification detected; checking public manufacturer and component sources directly.")
        return run_named_hardware_spec_retrieval(messages, route, emit=emit)
    if is_external_cad_source_retrieval_question(messages):
        if emit:
            emit("Linked product detected; identifying it before searching public CAD sources.")
        return run_external_cad_source_retrieval(messages, route, emit=emit)

    queries = local_research_queries(query, route)
    if emit:
        emit("Searching free public web sources.")
    results = []
    seen_urls = set()
    for direct_url in extract_http_urls(query):
        seen_urls.add(direct_url)
        results.append(
            {
                "title": direct_url,
                "url": direct_url,
                "snippet": "Direct URL supplied by Tinman.",
            }
        )
    for index, search_query in enumerate(queries, start=1):
        if emit and len(queries) > 1:
            emit(f"Search pass {index}: `{search_query}`.")
        for item in search_web_free(search_query):
            url = item.get("url")
            if not url or url in seen_urls:
                continue
            seen_urls.add(url)
            results.append(item)
    if not results:
        if is_current_product_shopping_request(messages):
            return {
                "text": safe_product_shopping_boundary_answer(query, []),
                "evidence": [],
                "model": "product-shopping-evidence-boundary",
            }
        return {"error": "Local Research could not find free web results for that query."}
    if emit:
        emit(f"Found {len(results)} candidate sources; checking the strongest pages.")
    evidence_pack = build_evidence_pack(query, route, results)
    if not evidence_pack:
        if is_current_product_shopping_request(messages):
            if emit:
                emit("Candidate product pages were found, but source text was weak; returning a verified-boundary sourcing answer.")
            return {
                "text": safe_product_shopping_boundary_answer(query, results),
                "evidence": results[:6],
                "model": "product-shopping-evidence-boundary",
            }
        if is_general_material_property_question(messages) or is_engineering_tradeoff_question(messages):
            if emit:
                emit("Local Research could not extract source text; switching to a bounded stable-expert answer.")
            fallback = stable_expert_fallback_answer(
                messages,
                route,
                friendliness_level=friendliness_level,
                humor_level=humor_level,
            )
            if fallback.get("text"):
                return fallback
        return {"error": "Local Research found results but could not extract useful evidence."}
    if emit:
        emit(f"Built an evidence pack from {len(evidence_pack)} sources.")
        emit(f"Asking local `{LOCAL_RESEARCH_MODEL}` to synthesize a grounded answer.")
    prompt = local_research_prompt(
        query,
        route,
        evidence_pack,
        friendliness_level=friendliness_level,
        humor_level=humor_level,
    )
    result = run_ollama_generate(prompt)
    if result.get("text"):
        answer = ensure_source_links(result["text"], evidence_pack)
        answer = ensure_product_shopping_caveats(answer, query)
        return {
            "text": answer,
            "evidence": evidence_pack,
            "model": LOCAL_RESEARCH_MODEL,
        }
    if emit and result.get("error"):
        emit(f"Local research model did not return a final answer; using evidence fallback: {compact(result.get('error'), 160)}")
    return {
        "text": safe_local_research_answer(query, route, evidence_pack),
        "evidence": evidence_pack,
        "model": "local-research-fallback",
        "warning": result.get("error", "Local research model returned no final answer."),
    }
    return result


def write_research_apply_receipt(messages, route, evidence_pack, answer_text, cwd=""):
    query = latest_user_text(messages)
    stamp = time.strftime("%Y%m%d-%H%M%S")
    target = LOCAL_RESEARCH_APPLY_OUTPUT_DIR / f"{stamp}-{slugify(query, 'research-apply')[:54]}"
    target.mkdir(parents=True, exist_ok=True)
    evidence_path = target / "evidence.json"
    report_path = target / "RESEARCH_APPLY.md"
    payload = {
        "ok": True,
        "createdAt": time.time(),
        "query": query,
        "cwd": cwd or DEFAULT_CWD,
        "route": route or {},
        "evidence": evidence_pack,
    }
    write_json_atomic(evidence_path, payload)
    source_lines = []
    for item in evidence_pack:
        source_lines.append(
            f"- [{item.get('id')}] {item.get('title') or item.get('url')} - {item.get('url')}"
        )
    markdown = "\n".join(
        [
            "# Research + Apply Receipt",
            "",
            f"Created: {stamp}",
            f"Project: {(route or {}).get('project', 'General Helper')}",
            f"Project ID: {(route or {}).get('projectId', 'general')}",
            f"Working directory: {cwd or DEFAULT_CWD}",
            "",
            "## Request",
            "",
            query,
            "",
            "## Applied Answer",
            "",
            strip_thinking_markup(answer_text) or "No answer text was produced.",
            "",
            "## Evidence Pack",
            "",
            "\n".join(source_lines) or "No source evidence captured.",
            "",
            "## Verification",
            "",
            "- Evidence index was written locally.",
            "- Final answer must cite sources and map the learning to a project action or explicit blocker.",
            "- Any real project edit still needs the relevant project-specific test, build, CAD, slicer, or package-health check.",
            "",
            f"Evidence JSON: `{evidence_path}`",
        ]
    ).strip() + "\n"
    report_path.write_text(markdown, encoding="utf-8")
    return {
        "ok": True,
        "outputDir": str(target),
        "reportPath": str(report_path),
        "evidencePath": str(evidence_path),
    }


def normalize_research_apply_answer_text(text):
    return (
        str(text or "")
        .replace("\u2010", "-")
        .replace("\u2011", "-")
        .replace("\u2012", "-")
        .replace("\u2013", "-")
        .replace("\u2014", "-")
        .replace("\u2015", "-")
        .replace("\u2212", "-")
        .replace("\xa0", " ")
    )


def attach_research_apply_receipt(answer_text, receipt):
    text = normalize_research_apply_answer_text(answer_text).strip()
    if not receipt or not receipt.get("ok"):
        return text
    lower = text.lower()
    additions = []
    if "applied to project:" not in lower:
        additions.append(
            "Applied to project: I created a local research/apply receipt that maps the source evidence to this project and keeps the evidence pack available for the next implementation pass."
        )
    if "verification:" not in lower:
        additions.append(
            "Verification: the research/apply receipt and evidence index were written locally."
        )
    report_path = receipt.get("reportPath")
    evidence_path = receipt.get("evidencePath")
    if report_path and ("research + apply receipt" not in lower or report_path not in text):
        additions.append(f"Research + Apply receipt: `{report_path}`")
    if evidence_path and evidence_path not in text:
        additions.append(f"Evidence index: `{evidence_path}`")
    if additions:
        text = text.rstrip() + "\n\n" + "\n".join(additions)
    return text.strip()


def research_apply_claims_unverified_project_work(answer_text, deliverables=None):
    raw = str(answer_text or "")
    lower = raw.lower()
    deliverables = deliverables or []
    non_receipt_deliverables = [
        item for item in deliverables
        if "/generated/research-apply/" not in str(item.get("path") or "")
    ]
    if "~/" in raw:
        return True
    verified_paths = {
        str(item.get("path") or "").rstrip(".,;:")
        for item in deliverables
        if item.get("exists") and item.get("path")
    }
    local_path_claims = [
        path.rstrip(".,;:")
        for path in re.findall(r"/(?:Users|Applications|Volumes)/[^\s`'\"<>)]*", raw)
    ]
    if any(path and path not in verified_paths for path in local_path_claims):
        return True
    if re.search(r"\b(ran|printed|measured|inspected|verified)\b[^.\n]{0,100}\b(flow pass|test print|calibration print|under \d|magnification|top surface)\b", lower):
        return True
    project_change_claim = re.search(
        r"\b(created|wrote|saved|stored|staged|updated|patched|changed|added)\b[^.\n]{0,140}\b(profile|preset|json|cfg|cad|file|project|workflow|receipt)\b",
        lower,
    )
    if project_change_claim and not non_receipt_deliverables:
        claim_text = lower[project_change_claim.start(): project_change_claim.end() + 180]
        if "receipt" not in claim_text and "evidence index" not in claim_text and "research-apply" not in claim_text:
            return True
    return False


def research_apply_material_lessons(query):
    lower = str(query or "").lower()
    if text_has_any(lower, ("pet-cf", "pet cf", "petcf")):
        return (
            "For Orca PET-CF tuning, use the source-backed order as a workflow guard: first-layer and extrusion "
            "consistency first, then nozzle temperature, pressure advance, flow ratio, retraction, cooling/layer-time "
            "behavior, and max volumetric flow. Keep PET-CF separate from PETG-CF assumptions, keep drying and abrasion "
            "control in the loop, and verify the final profile with a real calibration print before trusting production parts."
        )
    if text_has_any(lower, ("pctg", "petg-cf", "petg cf", "petg")):
        return (
            "For Orca PETG/PCTG-family tuning, use the source-backed order as a workflow guard: first-layer and extrusion "
            "consistency first, then nozzle temperature, pressure advance, flow ratio, cooling/layer-time behavior, "
            "retraction, and max volumetric flow. Keep moisture control in the loop before trusting stringing, surface, "
            "or flow results."
        )
    if "filament" in lower or "orca" in lower:
        return (
            "For Orca filament tuning, use the source-backed order as a workflow guard: first-layer and extrusion "
            "consistency first, then nozzle temperature, pressure advance, flow ratio, cooling/layer-time behavior, "
            "retraction, and max volumetric flow. Keep material identity, drying needs, nozzle size, and printer limits "
            "attached to the profile before changing live presets."
        )
    return ""


def safe_research_apply_answer(query, route, evidence_pack):
    urls = [item.get("url") for item in evidence_pack if item.get("url")]
    source_lines = "\n".join(f"{index}. {url}" for index, url in enumerate(urls[:6], start=1))
    lessons = research_apply_material_lessons(query) or (
        "I distilled the checked sources into project-specific rules and kept the source evidence available for the next implementation pass."
    )
    return "\n\n".join(
        [
            "Applied outcome: I created a local Research + Apply receipt for this project pass instead of pretending a live project file, slicer profile, or physical test was changed.",
            f"What I learned: {lessons}",
            (
                "Applied to project: the receipt maps the evidence to the active project workflow and becomes the handoff artifact for the next implementation step. "
                "No Orca profile, CAD file, or machine setting was changed by this smoke-test pass."
            ),
            (
                "Verification: this pass writes the receipt and evidence index locally, then the next pass should make the real project edit and run the matching package, slicer, CAD, or print validation."
            ),
            "Sources checked\n" + (source_lines or "No source URLs were captured."),
        ]
    )


def run_research_apply(
    messages,
    route,
    web_search="live",
    cwd="",
    emit=None,
    friendliness_level=None,
    humor_level=None,
    search_fn=None,
    generate_fn=None,
    receipt_writer=None,
    project_apply_stager=None,
):
    query = latest_user_text(messages)
    if not query.strip():
        return {"error": "Research + Apply needs a user question to research and apply."}
    route = {**(route or {}), "engine": "research-apply", "effectiveProfile": "research-apply"}
    search = search_fn or search_web_free
    generate = generate_fn or run_ollama_generate
    write_receipt = receipt_writer or write_research_apply_receipt
    stage_project_apply = project_apply_stager or stage_project_apply_case
    if web_search == "live":
        queries = local_research_queries(query, route)
        if emit:
            emit("Research + Apply: searching free public web sources.")
        results = []
        seen_urls = set()
        for direct_url in extract_http_urls(query):
            seen_urls.add(direct_url)
            results.append(
                {
                    "title": direct_url,
                    "url": direct_url,
                    "snippet": "Direct URL supplied by Tinman.",
                }
            )
        for index, search_query in enumerate(queries, start=1):
            if emit and len(queries) > 1:
                emit(f"Research + Apply search pass {index}: `{search_query}`.")
            for item in search(search_query):
                url = item.get("url")
                if not url or url in seen_urls:
                    continue
                seen_urls.add(url)
                results.append(item)
        if not results:
            if emit:
                emit("Research + Apply could not find free web results; checking cached source-vault evidence.")
            evidence_pack = build_cached_source_vault_evidence_pack(query, route)
            if not evidence_pack:
                return {"error": "Research + Apply could not find free web results or cached source-vault evidence for that query."}
        else:
            if emit:
                emit(f"Research + Apply found {len(results)} candidate sources; checking the strongest pages.")
            evidence_pack = build_evidence_pack(query, route, results)
            if not evidence_pack:
                if emit:
                    emit("Research + Apply web results did not yield useful evidence; checking cached source-vault evidence.")
                evidence_pack = build_cached_source_vault_evidence_pack(query, route)
    else:
        if emit:
            emit("Research + Apply: Web is off, so I am checking the cached local source vault first.")
        evidence_pack = build_cached_source_vault_evidence_pack(query, route)
        if not evidence_pack:
            return {
                "error": (
                    "Research + Apply needs either Web enabled or a matching cached source-vault entry. "
                    "I checked the local source vault but did not find source evidence for this request."
                )
            }
    if not evidence_pack:
        return {"error": "Research + Apply found results but could not extract useful evidence."}
    if emit:
        emit(f"Research + Apply built an evidence pack from {len(evidence_pack)} sources.")
        emit(f"Asking local `{LOCAL_RESEARCH_MODEL}` to convert research into project action.")
    prompt = research_apply_prompt(
        query,
        route,
        evidence_pack,
        cwd=cwd,
        friendliness_level=friendliness_level,
        humor_level=humor_level,
    )
    result = generate(prompt)
    if result.get("text"):
        answer = ensure_source_links(result["text"], evidence_pack)
        if research_apply_claims_unverified_project_work(answer, []):
            if emit:
                emit("Research + Apply guard removed unverified project/test claims before final delivery.")
            answer = safe_research_apply_answer(query, route, evidence_pack)
        receipt = write_receipt(messages, route, evidence_pack, answer, cwd=cwd)
        answer = attach_research_apply_receipt(answer, receipt)
        project_apply = None
        try:
            if emit:
                emit("Project Apply Executor: staging target inventory, apply plan, and manifest.")
            project_apply = stage_project_apply(messages, route=route, cwd=cwd, research_receipt=receipt)
            answer = attach_project_apply_receipt(answer, project_apply)
        except Exception as exc:
            if emit:
                emit(f"Project Apply Executor could not stage a plan: {compact(exc, 160)}")
        return {
            "text": answer,
            "evidence": evidence_pack,
            "receipt": receipt,
            "projectApply": project_apply,
            "model": LOCAL_RESEARCH_MODEL,
        }
    if emit and result.get("error"):
        emit(f"Research + Apply model did not return a final answer; using evidence fallback: {compact(result.get('error'), 160)}")
    answer = safe_research_apply_answer(query, route, evidence_pack)
    receipt = write_receipt(messages, route, evidence_pack, answer, cwd=cwd)
    answer = attach_research_apply_receipt(answer, receipt)
    project_apply = None
    try:
        if emit:
            emit("Project Apply Executor: staging target inventory, apply plan, and manifest.")
        project_apply = stage_project_apply(messages, route=route, cwd=cwd, research_receipt=receipt)
        answer = attach_project_apply_receipt(answer, project_apply)
    except Exception as exc:
        if emit:
            emit(f"Project Apply Executor could not stage a plan: {compact(exc, 160)}")
    return {
        "text": answer,
        "evidence": evidence_pack,
        "receipt": receipt,
        "projectApply": project_apply,
        "model": "research-apply-fallback",
        "warning": result.get("error", "Research + Apply model returned no final answer."),
    }


class CodexUIHandler(BaseHTTPRequestHandler):
    server_version = "CodexCLIUI/0.1"

    def log_message(self, fmt, *args):
        stamp = time.strftime("%H:%M:%S")
        print(f"[{stamp}] {self.address_string()} {fmt % args}")

    def send_response(self, code, message=None):
        self._response_code_started = True
        return super().send_response(code, message)

    def end_headers(self):
        result = super().end_headers()
        self._response_headers_sent = True
        return result

    def record_post_exception(self, exc):
        log_dir = APP_DIR / "logs"
        log_dir.mkdir(parents=True, exist_ok=True)
        log_path = log_dir / "server-exceptions.log"
        stamp = time.strftime("%Y-%m-%d %H:%M:%S %Z")
        with log_path.open("a", encoding="utf-8") as handle:
            handle.write(f"\n[{stamp}] POST {self.path} from {self.client_address}\n")
            try:
                traceback.print_exc(file=handle)
            except Exception as log_exc:
                handle.write(f"{exc.__class__.__name__}: {exc}\n")
                handle.write(f"Log traceback failed: {log_exc}\n")
        return log_path

    def run_crash_recovery_answer(self, exc, log_path):
        error_name = exc.__class__.__name__
        error_text = compact(str(exc) or error_name, 220)
        return (
            "I hit an internal Codex CLI UI error before this run could finish, "
            "but I did not lose the response.\n\n"
            f"This is why: the server raised `{error_name}` while handling `/api/run`: {error_text}.\n\n"
            "You should also consider: the real exception is now logged locally so the next repair pass can fix "
            "the underlying tool path instead of guessing. Retry once; if it repeats, use Fix this and I will use "
            f"`{log_path}` as the starting evidence."
        )

    def recover_post_exception(self, parsed, exc):
        log_path = self.record_post_exception(exc)
        recovery = {
            "kind": "server-crash",
            "mode": "server-crash-recovery",
            "errorName": exc.__class__.__name__,
            "errorText": compact(str(exc) or exc.__class__.__name__, 300),
            "logPath": str(log_path),
        }
        if parsed.path == "/api/run":
            try:
                if not getattr(self, "_response_headers_sent", False):
                    self._headers_buffer = []
                    self.send_response(200)
                    self.send_header("Content-Type", "application/x-ndjson; charset=utf-8")
                    self.send_header("Cache-Control", "no-cache")
                    self.send_header("X-Accel-Buffering", "no")
                    self.end_headers()
                    json_line(
                        self,
                        {
                            "type": "status",
                            "message": "server-crash-recovery",
                            "mode": "server-crash-recovery",
                            "engine": "local-recovery",
                            "recovery": recovery,
                        },
                    )
                json_line(
                    self,
                    {
                        "type": "thought",
                        "text": f"Server crash shield caught {exc.__class__.__name__}; logging and returning a recovery answer instead of dropping the run.",
                    },
                )
                json_line(
                    self,
                    {
                        "type": "assistant",
                        "text": self.run_crash_recovery_answer(exc, log_path),
                        "recovery": recovery,
                        "displayMode": {
                            "answerSurface": "codex-style",
                            "showDiagnostics": False,
                            "showReceiptsWhenDone": False,
                        },
                    },
                )
                json_line(self, {"type": "done", "returnCode": 1})
            except BrokenPipeError:
                pass
            return

        if not getattr(self, "_response_headers_sent", False):
            self._headers_buffer = []
            self.send_json(
                {
                    "ok": False,
                    "error": f"{exc.__class__.__name__}: {compact(str(exc) or exc.__class__.__name__, 220)}",
                    "log": str(log_path),
                },
                status=500,
            )

    def do_POST(self):
        self._response_code_started = False
        self._response_headers_sent = False
        parsed = urlparse(self.path)
        try:
            return self._do_POST_impl(parsed)
        except BrokenPipeError:
            return
        except Exception as exc:
            return self.recover_post_exception(parsed, exc)

    def finish(self):
        try:
            super().finish()
        finally:
            run_id = getattr(self, "current_run_id", "")
            if run_id:
                unregister_live_run(run_id)

